:root {
    --overlay-color: var(--color-primary);
    --overlay-intensity: 0.1; /* screen-blend faction tint; higher washes out blacks */

    /* Viewport fit (set by viewport-fit.js; fallbacks for first paint) */
    --vw: 100vw;
    --vh: 100dvh;
    /* Slightly wider aspect → fight canvas a bit shorter; room for under-stage. */
    --playfield-aspect: 1.42;
    --planet-view-zoom: 1;
    --design-canvas-w: 480;
    --design-canvas-h: 400;
    --canvas-w: min(864px, calc(72 * var(--sv-w)), calc((calc(100 * var(--sv-h)) - 240px) * 1.2));
    --canvas-h: min(600px, calc(calc(100 * var(--sv-h)) - 240px), calc(calc(72 * var(--sv-w)) / 1.2));
    --side-panel-w: clamp(220px, calc(20 * var(--sv-w)), 300px);
    --ui-pad: clamp(6px, calc(1.2 * var(--sv-w)), 14px);
    --ui-gap: clamp(6px, calc(1 * var(--sv-w)), 14px);
    /* Normal GLXEE shell scale: equivalent to three browser zoom-out steps. */
    --gui-zoom: 0.75;
    --app-scale: 1;
    --game-scale: 1;
    --fill-scale: 1;
    /* Typography: 3 sizes only — lg / md / sm */
    --font-lg: 20px;
    --font-md: 14px;
    --font-sm: 11px;
    --font-base: var(--font-md);
    --font-h1: var(--font-lg);
    --font-h2: var(--font-md);
    --font-text: var(--font-md);
    --font-small: var(--font-sm);
    --font-text-small: var(--font-sm);

    /* Global UI appearance (independent of color themes).
       Contour tokens stay equal within a weight; NORMAL default = 4px. */
    --ui-border-width: 4px;
    --ui-border-width-thin: 4px;
    --ui-border-width-thick: 4px;
    --ui-indicator-width: 4px;
    --ui-font-family: 'Courier New', Courier, monospace;

    /* Retro / arcade FX (driven by uiAppearanceManager) */
    --vf-glow: 0;
    --vf-scan: 0;
    --vf-fx-scale: 1;
    --vf-crt: 0;
    --vf-chroma: 0;
    --vf-vignette: 0;
    --vf-noise: 0;
    --vf-flicker: 0;
    --vf-bloom: 0;
    --vf-bloom-spread: 0;
    --vf-bloom-thr: 0;
    --vf-hdr: 0;

    /* High contrast grayscale palette */
    --gray-100: #ffffff;
    --gray-200: #f8f8f8;
    --gray-300: #e8e8e8;
    --gray-400: #d0d0d0;
    --gray-500: #b0b0b0;
    --gray-600: #888888;
    --gray-700: #606060;
    --gray-800: #404040;
    --gray-900: #202020;
    --gray-1000: #000000;

    /* Game-specific colors with better contrast */
    --game-bg-light: var(--gray-200);
    --game-bg-medium: var(--gray-400);
    --game-bg-dark: var(--gray-900);
    --game-text-light: var(--gray-100);
    --game-text-dark: var(--gray-900);
    --game-border-light: var(--gray-300);
    --game-border-dark: var(--gray-700);

    /* UI colors - affected by theme (updated for new system) */
    --ui-background: var(--color-background);
    --ui-surface: var(--color-surface);
    --ui-border: var(--color-border);
    --ui-text-primary: var(--color-text);
    --ui-text-secondary: var(--color-text-secondary);
    --ui-text-disabled: var(--color-text-muted);
    --ui-hover: var(--color-hover);
    --ui-active: var(--color-active);

    /* Status colors */
    --status-success: var(--status-success);
    --status-warning: var(--status-warning);
    --status-error: var(--status-error);
    --status-info: var(--status-info);

    /* Resource tints (synced from economyConfig); vitals map onto three of them */
    --res-scrap: #b8b0a0;
    --res-ore: #c49a4a;
    --res-crystal: #6ec8e8;
    --res-voltex: #c86ef0;
    --vital-hull: var(--res-scrap);
    --vital-energy: var(--res-voltex);
    --vital-shield: var(--res-crystal);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html, body {
    width: 100%;
    height: 100%;
}

/* The body IS the 4:3 stage (sized by viewport-fit.js), centered in the window.
   transform makes it the containing block for position:fixed children. */
html {
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: hidden;
    background-color: #05060a;
    background-image:
        linear-gradient(to bottom, rgba(0, 0, 0, 0.42) 0%, rgba(0, 0, 0, 0.28) 40%, rgba(0, 0, 0, 0.55) 100%),
        url('../../assets/ui/hs-bg-ingame.png');
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    image-rendering: pixelated;
}
/* In combat: no cockpit art behind the stage, plain dark only. */
html.vf-game-shown,
html.vf-game-shown body {
    background-image: none;
    background-color: #05060a;
}

body {
    font-family: var(--ui-font-family);
    background: var(--color-background);
    color: var(--color-text);
    display: flex;
    align-items: center;
    flex: 0 0 auto;
    position: relative;
    transform: scale(var(--stage-scale, 1));
    transform-origin: center center;
    justify-content: center;
    width: var(--vw, 100vw);
    height: var(--vh, 100dvh);
    min-height: var(--vh, 100dvh);
    max-height: var(--vh, 100dvh);
    /* clip: no scrolling; no letterbox bleed past the stage (parallax used to
       paint purple wings outside the bezel). Crest lives on #vf-bezel inside the stage. */
    overflow: clip;
    overflow-clip-margin: 0;
    font-size: var(--font-text);
    line-height: 1.2;
    letter-spacing: 1px;
    text-rendering: optimizeSpeed;
    -webkit-font-smoothing: none;
    -moz-osx-font-smoothing: unset;
}

/* Soft page-refresh bridge: solid dark while menus boot, so no frame shows
   the bare background art without its menu; the finished menu fades in. */
html.vf-booting .vf-bg-parallax-base,
html.vf-booting .vf-bg-parallax-glow { transition: none !important; }
.vf-boot-veil[class] { background-color: #05060a; }
/* Solid cover only while the progress panel has no destination art class yet */
.vf-boot-veil.vf-boot-veil-loading:not(.vf-boot-veil-start):not(.vf-boot-veil-hs):not(.vf-boot-veil-menu) {
    background-image: none !important;
}

.vf-boot-veil {
    position: fixed;
    left: 0;
    top: 0;
    right: auto;
    bottom: auto;
    z-index: 9980; /* under the bezel (z 9990): the frame is visible during boot */
    pointer-events: none;
    background-color: #000;
    opacity: 1;
    transition: opacity 0.32s ease;
    overflow: hidden;
    isolation: isolate;
    --vf-bg-overscan: 112%;
}
.vf-boot-veil.vf-boot-veil-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: auto;
    inset: 0;
    width: 100% !important;
    height: 100% !important;
}
.vf-boot-veil.is-leaving {
    opacity: 0;
    pointer-events: none;
}
#vf-boot-loader {
    position: relative;
    z-index: 2;
    width: min(420px, 86vw);
    padding: 28px 24px 22px;
    border: 4px solid color-mix(in srgb, var(--color-primary, #3A6EA5) 35%, #2a3340);
    background: color-mix(in srgb, #0a0d12 88%, var(--color-primary, #3A6EA5) 12%);
    box-shadow:
        0 0 0 2px #05060a,
        0 0 0 6px color-mix(in srgb, var(--color-primary, #3A6EA5) 22%, #1a222c),
        0 12px 40px rgba(0, 0, 0, 0.55);
    text-align: center;
    letter-spacing: 0.06em;
    font-family: var(--ui-font-family, 'Silkscreen', ui-monospace, monospace);
    color: var(--color-text, #c8d0d8);
}
#vf-boot-loader .vf-boot-brand {
    font-size: clamp(28px, 6vw, 40px);
    font-weight: 700;
    color: #f2f4f7;
    margin: 0 0 6px;
    text-shadow: 0 0 18px color-mix(in srgb, var(--color-primary, #3A6EA5) 55%, transparent);
}
#vf-boot-loader .vf-boot-channel {
    font-size: var(--font-text);
    color: #6f7f92;
    margin: 0 0 22px;
    text-transform: uppercase;
}
#vf-boot-track {
    position: relative;
    height: 14px;
    border: 3px solid #3a4656;
    background: #05070b;
    padding: 2px;
    box-sizing: border-box;
    margin: 0 0 12px;
    overflow: hidden;
    direction: ltr;
}
#vf-boot-track::after {
    content: '';
    position: absolute;
    inset: 2px auto 2px 0;
    width: 28%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent);
    animation: vf-boot-sweep 1.2s linear infinite;
