/* UI BG mouse-follow parallax (WoodChunk-style, light) */
.vf-bg-parallax-host {
    --vf-bg-overscan: 112%;
    --vf-ptr-glow: 0.55;
    isolation: isolate;
    overflow: hidden;
}

.vf-bg-parallax-host.vf-bg-parallax-ready {
    background-image: none !important;
}

/*
 * First paint = parallax overscan zoom (112%).
 * Boot veil + hosts before JS promote BG into .vf-bg-parallax-base.
 */
.vf-boot-veil-start,
.vf-boot-veil-hs,
.vf-boot-veil-menu,
.start-screen:not(.vf-bg-parallax-ready),
.start-screen-overlay:not(.vf-bg-parallax-ready),
.home-station-overlay:not(.vf-bg-parallax-ready),
.content-viewer-overlay:not(.vf-bg-parallax-ready),
.profile-selection-overlay:not(.is-inline):not(.vf-bg-parallax-ready),
.game-container:not(.vf-bg-parallax-ready),
.victory-screen:not(.vf-bg-parallax-ready),
.game-over:not(.vf-bg-parallax-ready),
.ag-overlay:not(.vf-bg-parallax-ready) {
    --vf-bg-overscan: 112%;
    overflow: hidden;
    isolation: isolate;
    /* Keep background-* for ::before inherit; hide direct paint */
    background-size: 0 0 !important;
}

.vf-boot-veil-start::before,
.vf-boot-veil-hs::before,
.vf-boot-veil-menu::before,
.start-screen:not(.vf-bg-parallax-ready)::before,
.start-screen-overlay:not(.vf-bg-parallax-ready)::before,
.home-station-overlay:not(.vf-bg-parallax-ready)::before,
.content-viewer-overlay:not(.vf-bg-parallax-ready)::before,
.profile-selection-overlay:not(.is-inline):not(.vf-bg-parallax-ready)::before,
.game-container:not(.vf-bg-parallax-ready)::before,
.victory-screen:not(.vf-bg-parallax-ready)::before,
.game-over:not(.vf-bg-parallax-ready)::before,
.ag-overlay:not(.vf-bg-parallax-ready)::before {
    content: "";
    position: absolute;
    left: -6%;
    top: -6%;
    width: var(--vf-bg-overscan, 112%);
    height: var(--vf-bg-overscan, 112%);
    z-index: -1;
    pointer-events: none;
    background-image: inherit;
    background-color: inherit;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}

.vf-bg-parallax-base,
.vf-bg-parallax-glow {
    position: absolute;
    pointer-events: none;
    will-change: transform;
    backface-visibility: hidden;
    z-index: -1;
}

.vf-bg-parallax-base {
    left: -6%;
    top: -6%;
    width: var(--vf-bg-overscan, 112%);
    height: var(--vf-bg-overscan, 112%);
    background-repeat: no-repeat;
    background-position: center;
    background-size: cover;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    transform: translate3d(0, 0, 0);
    opacity: 1;
    transition: opacity 0.42s ease;
    z-index: -2;
}

.vf-bg-parallax-base.is-incoming {
    /* Above stable base so the opacity fade covers the previous frame */
    z-index: -1;
}

.vf-bg-parallax-glow {
    /* The visible part of the 900px radial gradient is ~650px around the centre; a few % of overscan covers the parallax
       shift. (Was -75% / -1200px: a ~3700px layer that software compositors had to keep in memory.) */
    top: -12%;
    right: -12%;
    bottom: -12%;
    left: -12%;
    opacity: var(--vf-ptr-glow, 0.55);
    background-repeat: no-repeat;
    background-image:
        radial-gradient(
            circle 900px at 50% 50%,
            color-mix(in srgb, var(--color-primary) calc(22% * var(--vf-ptr-glow, 0.55)), transparent) 0%,
            color-mix(in srgb, var(--color-primary) calc(10% * var(--vf-ptr-glow, 0.55)), transparent) 35%,
            transparent 72%
        );
    transform: translate3d(0, 0, 0);
}

@media (prefers-reduced-motion: reduce) {
    .vf-bg-parallax-base,
    .vf-bg-parallax-glow {
        transform: none !important;
    }
    /* Keep opacity fade for BG swaps; only kill motion transforms */
    .vf-bg-parallax-base {
        transition: opacity 0.42s ease !important;
    }
    .vf-bg-parallax-glow {
        opacity: 0 !important;
    }
}

html[data-vf-bg-parallax="off"] .vf-bg-parallax-glow {
    opacity: 0 !important;
}

html[data-vf-bg-parallax="off"] .vf-bg-parallax-base {
    transform: none !important;
}

