/* Color overlay for HTML elements */
.color-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
    background: var(--overlay-color);
    opacity: var(--overlay-intensity);
    mix-blend-mode: screen;
}

/* Retro FX stack — scanlines / CRT / chroma (pointer-events none) */
.vf-fx-overlay {
    /* No box of its own: with mix-blend-mode layers inside, a real container becomes an
       isolated group and the layers' backdrop-filters (chroma/bloom/HDR/CRT) see nothing. */
    display: contents;
}

.vf-fx-scanlines,
.vf-fx-scanwarp,
.vf-fx-crt,
.vf-fx-chroma,
.vf-fx-hdr,
.vf-fx-hdr-shadow,
.vf-fx-bloom,
.vf-fx-vignette,
.vf-fx-noise,
.vf-fx-flicker {
    position: fixed;
    inset: 0;
    z-index: 10000;
    pointer-events: none;
    /* Promote each FX plate once; avoids re-layering the full DOM tree every frame. */
    transform: translateZ(0);
    backface-visibility: hidden;
}

.vf-fx-scanlines {
    opacity: min(1, calc(var(--vf-scan, 0) * 2.2));
    background: repeating-linear-gradient(
        to bottom,
        rgba(0, 0, 0, 0) 0px,
        rgba(0, 0, 0, 0) calc(1px * var(--vf-fx-scale, 1) * var(--vf-scan-size, 1)),
        rgba(0, 0, 0, 0.92) calc(2px * var(--vf-fx-scale, 1) * var(--vf-scan-size, 1)),
        rgba(0, 0, 0, 0) calc(3px * var(--vf-fx-scale, 1) * var(--vf-scan-size, 1))
    );
    mix-blend-mode: multiply;
    /* Drift via transform (compositor) instead of background-position (full repaint per frame):
       the layer is 12px taller and slides by 12px = 4 gradient periods, so the loop is seamless. */
    bottom: calc(-12px * var(--vf-fx-scale, 1) * var(--vf-scan-size, 1));
    will-change: transform;
    animation: vf-fx-scan-drift var(--vf-scan-dur, 2s) linear infinite;
}

html[data-vf-scan-drift="off"] .vf-fx-scanlines { animation: none; }

.vf-fx-scanwarp {
    -webkit-backdrop-filter: url(#vfScanWarpFx);
    backdrop-filter: url(#vfScanWarpFx);
}
html[data-vf-scanwarp="off"] .vf-fx-scanwarp,
html[data-vf-perf-heavy="off"] .vf-fx-scanwarp { display: none; }

html[data-vf-scanlines="off"] .vf-fx-scanlines {
    opacity: 0;
    animation: none;
}

.vf-fx-crt {
    /* Tube look without warp/blur: horizontal shadow mask + vignette only.
       The old 90deg RGB phosphor stripes read as weird semi-transparent
       vertical lines across the fight screen. */
    -webkit-backdrop-filter: contrast(calc(1 + 0.18 * var(--vf-crt, 0))) saturate(calc(1 + 0.28 * var(--vf-crt, 0))) brightness(calc(1 + 0.08 * var(--vf-crt, 0)));
    backdrop-filter: contrast(calc(1 + 0.18 * var(--vf-crt, 0))) saturate(calc(1 + 0.28 * var(--vf-crt, 0))) brightness(calc(1 + 0.08 * var(--vf-crt, 0)));
    background:
        repeating-linear-gradient(
            0deg,
            rgba(0, 0, 0, calc(0.08 * var(--vf-crt, 0))) 0px,
            rgba(0, 0, 0, calc(0.08 * var(--vf-crt, 0))) calc(1px * var(--vf-fx-scale, 1)),
            transparent calc(1px * var(--vf-fx-scale, 1)),
            transparent calc(6px * var(--vf-fx-scale, 1))
        ),
        radial-gradient(
            ellipse 70% 65% at 50% 50%,
            rgba(255, 255, 255, calc(0.05 * var(--vf-crt, 0))) 0%,
            transparent 70%
        ),
        radial-gradient(
            ellipse 85% 80% at 50% 50%,
            transparent 55%,
            rgba(0, 0, 0, calc(0.35 * var(--vf-crt, 0))) 100%
        );
    box-shadow: inset 0 0 calc(40px * var(--vf-crt, 0)) calc(4px * var(--vf-crt, 0)) rgba(0, 0, 0, 0.5);
    animation: vf-fx-crt-flicker 4.5s steps(1, end) infinite;
}

@keyframes vf-fx-crt-flicker {
    0%, 100% { opacity: 1; }
    37% { opacity: 0.93; }
    38% { opacity: 1; }
    71% { opacity: 0.95; }
    72% { opacity: 1; }
}

html[data-vf-crt="off"] .vf-fx-crt {
    display: none;
}

.vf-fx-chroma {
    /* Doppler-style channel split: the page behind is re-drawn with red and
       blue pulled apart (filter #vfChromaFx, offsets set from the Chroma value). */
    -webkit-backdrop-filter: url(#vfChromaFx);
    backdrop-filter: url(#vfChromaFx);
}

html[data-vf-chroma="off"] .vf-fx-chroma {
    display: none;
}

/* Bloom = bright-pass glow, built as an SVG filter (#vfBloomFx, values set in apply()):
   threshold -> blur (width) -> gain (strength) -> added on top of the untouched picture. */
.vf-fx-bloom {
    -webkit-backdrop-filter: url(#vfBloomFx);
    backdrop-filter: url(#vfBloomFx);
}
/* HDR is faked with blend layers only (no backdrop-filter, no resampling):
   an overlay-blended warm light lifts mids and highlights but keeps black black,
   a multiply layer pulls the corners down so the centre reads as hot. */
.vf-fx-hdr {
    background: radial-gradient(ellipse 85% 75% at 50% 45%, rgba(255, 244, 222, calc(0.85 * var(--vf-hdr, 0))) 0%, rgba(255, 244, 222, calc(0.45 * var(--vf-hdr, 0))) 100%);
    mix-blend-mode: overlay;
}
.vf-fx-hdr-shadow {
    background: radial-gradient(ellipse 80% 70% at 50% 45%, rgba(255, 255, 255, 1) 40%, rgba(150, 150, 170, calc(1 - 0.5 * var(--vf-hdr, 0))) 100%);
    mix-blend-mode: multiply;
}
html[data-vf-hdr="off"] .vf-fx-hdr-shadow { display: none; }
html[data-vf-hdr="off"] .vf-fx-hdr { display: none; }
html[data-vf-bloom="off"] .vf-fx-bloom { display: none; }

.vf-fx-vignette {
    background: radial-gradient(ellipse 75% 70% at 50% 50%, transparent 35%, rgba(0, 0, 0, calc(0.95 * var(--vf-vignette, 0))) 100%);
}
html[data-vf-vignette="off"] .vf-fx-vignette { display: none; }

.vf-fx-noise {
    opacity: calc(0.5 * var(--vf-noise, 0));
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>");
    background-size: calc(160px * var(--vf-fx-scale, 1)) calc(160px * var(--vf-fx-scale, 1));
    mix-blend-mode: overlay;
    animation: vf-fx-noise-shift 0.5s steps(5, end) infinite;
}
