@keyframes vf-fx-noise-shift {
    0% { background-position: 0 0; }
    20% { background-position: -37px 21px; }
    40% { background-position: 52px -64px; }
    60% { background-position: -81px -12px; }
    80% { background-position: 29px 73px; }
    100% { background-position: 0 0; }
}

.vf-fx-flicker {
    background: #000;
    opacity: 0;
    animation: vf-fx-flicker-pulse 0.18s steps(1, end) infinite;
}
html[data-vf-flicker="off"] .vf-fx-flicker { display: none; }
@keyframes vf-fx-flicker-pulse {
