    50%  { opacity: calc(0.12 * var(--vf-flicker, 0)); }
    75%  { opacity: calc(0.22 * var(--vf-flicker, 0)); }
    100% { opacity: 0; }
}

@keyframes vf-fx-scan-drift {
    from { transform: translateY(calc(-12px * var(--vf-fx-scale, 1) * var(--vf-scan-size, 1))); }
    to { transform: translateY(0); }
}

@keyframes vf-arcade-pulse {
