/* Arcade mode — juice + pulse */
html[data-vf-arcade="on"] .menu-item.selected,
html[data-vf-arcade="on"] .settings-row.selected {
    animation: vf-arcade-pulse 1.1s ease-in-out infinite, vf-arcade-border-pulse 1.1s ease-in-out infinite;
}

html[data-vf-arcade="on"] .settings-cycle-btn {
    transition: transform 0.08s ease, background 0.12s ease, color 0.12s ease, box-shadow 0.12s ease;
}

html[data-vf-arcade="on"] .settings-cycle-btn:active {
    transform: scale(0.88);
}

html[data-vf-arcade="on"] .settings-section-title {
    letter-spacing: 0.22em;
}

html[data-vf-arcade="on"] .settings-row-value {
    letter-spacing: 0.08em;
}

.game-container {
    /* Geometry / GUI scale: shared .vf-glass (part-19). Flex layout only here. */
    display: flex;
    flex-direction: row;
    align-items: stretch;
    justify-content: space-between;
    box-sizing: border-box;
    /* No cockpit art: the faction bezel (screen-frame.css) is the only frame. */
    background-color: #000;
    color: var(--color-text);
    font-family: var(--ui-font-family);
    gap: var(--ui-gap);
    padding: var(--ui-pad);
    text-align: left;
}

/* Left HUD cluster: info panel + compact vitals — glued to playfield, not viewport edge */
.game-left-cluster {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    flex: 0 0 auto;
    width: var(--side-panel-w);
    height: 100%;
    max-height: 100%;
    align-self: stretch;
    gap: clamp(3px, calc(0.5 * var(--sv-h)), 6px);
    z-index: 10;
}

/* Compact Game Info Panel */
.game-info-panel {
    position: relative;
    isolation: isolate;
    width: 100%;
    flex: 1 1 auto;
    min-height: 0;
    max-height: none;
    height: auto;
    overflow: hidden;
    box-sizing: border-box;
    background:
        linear-gradient(165deg,
            color-mix(in srgb, var(--color-primary) 4%, var(--color-background)) 0%,
            var(--color-background) 60%);
    border: var(--ui-border-width) solid var(--color-primary);
    border-radius: 0;
    padding: clamp(4px, calc(0.5 * var(--sv-h)), 8px);
    color: var(--color-text);
    font-size: var(--font-text);
    line-height: 1.2;
    letter-spacing: 0.02em;
    -webkit-font-smoothing: none;
    text-rendering: geometricPrecision;
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary) 25%, transparent);
    display: flex;
    flex-direction: column;
    gap: 4px;
    visibility: visible;
    opacity: 1;
}

.gi-head {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    padding-bottom: 6px;
    border-bottom: var(--ui-border-width-thin) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    flex-shrink: 0;
}

.gi-size-btn {
    flex-shrink: 0;
    margin-left: auto;
    background: var(--ui-surface, #0a0c10);
    color: var(--color-primary);
    border: var(--ui-border-width, 2px) solid var(--color-border, var(--color-primary));
    font-family: var(--ui-font-family);
    font-size: var(--font-small);
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    padding: 4px 8px;
    cursor: pointer;
    line-height: 1.2;
}
.gi-size-btn:hover,
.gi-size-btn:focus-visible,
.gi-size-btn.is-active {
    background: color-mix(in srgb, var(--color-primary) 22%, transparent);
    color: var(--color-text, #fff);
    outline: none;
}

.enemy-size-overlay {
    position: fixed;
    top: 12px;
    left: 12px;
    /* Above home-station (3600) / profile overlays so SIZES works from FLEETS. */
    z-index: 3800;
    pointer-events: none;
    background: transparent;
}
.enemy-size-overlay.hidden { display: none; }
.enemy-size-panel {
    pointer-events: auto;
    min-width: 220px;
    max-width: min(calc(280px * var(--zk)), calc(42 * var(--cw)));
    background: color-mix(in srgb, #05060a 92%, transparent);
    border: var(--ui-border-width, 2px) solid var(--color-border, var(--color-primary));
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--color-primary) 35%, transparent);
    padding: 10px 12px 12px;
    font-family: var(--ui-font-family);
    color: var(--color-text, #e8e8e8);
}
.enemy-size-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-bottom: 4px;
}
.enemy-size-head strong {
    font-size: var(--font-text);
    letter-spacing: 1px;
    color: var(--color-primary);
}
.enemy-size-close {
    background: transparent;
    border: var(--ui-border-width-thin, 2px) solid var(--color-border, var(--color-primary));
    color: var(--color-text);
    font-family: inherit;
    font-size: var(--font-text);
    line-height: 1;
    width: 22px;
    height: 22px;
    cursor: pointer;
    padding: 0;
}
.enemy-size-close:hover { background: color-mix(in srgb, var(--color-primary) 25%, transparent); }
.enemy-size-hint {
    margin: 0 0 8px;
    font-size: var(--font-small);
    letter-spacing: 0.5px;
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    text-transform: uppercase;
}
.enemy-size-list {
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.enemy-size-section {
    margin-top: 6px;
    padding-top: 4px;
    font-size: var(--font-small);
    letter-spacing: 1.5px;
    color: color-mix(in srgb, var(--color-primary) 80%, transparent);
    text-transform: uppercase;
}
.enemy-size-section:first-child { margin-top: 0; padding-top: 0; }
.enemy-size-row {
    display: grid;
    align-items: center;
    gap: 4px 8px;
    padding: 4px 0;
    border-top: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 25%, transparent);
}
.enemy-size-label {
    grid-area: label;
    font-size: var(--font-text);
    letter-spacing: 1px;
    color: var(--color-text);
}
.enemy-size-value {
    text-align: center;
    font-size: var(--font-text);
    font-weight: 700;
    color: var(--color-primary);
}
.enemy-size-step {
    background: var(--ui-surface, #0a0c10);
    border: var(--ui-border-width-thin, 2px) solid var(--color-border, var(--color-primary));
    color: var(--color-text);
    font-family: inherit;
    font-size: var(--font-text);
    height: 24px;
    cursor: pointer;
    padding: 0;
}
.enemy-size-step:hover {
    background: color-mix(in srgb, var(--color-primary) 22%, transparent);
}

/* Planet fills the info panel as atmosphere, not a corner icon. */
.game-info-planet {
    position: absolute;
    inset: 0;
    z-index: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    pointer-events: none;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.42;
}
.game-info-planet svg,
.game-info-planet .game-info-planet-fallback {
    width: 118%;
    height: 118%;
    max-width: none;
    display: block;
    object-fit: cover;
    filter: contrast(1.15) brightness(0.95) saturate(1.1);
}
.game-info-planet-fallback {
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, var(--color-text-secondary), var(--color-primary) 70%, var(--color-border));
}
.game-info-panel > :not(.game-info-planet) {
    position: relative;
    z-index: 1;
}

.gi-head-text {
    min-width: 0;
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
}

.gi-head-text h3,
.game-info-header h3 {
    margin: 0;
    font-size: var(--font-lg);
    color: #fff;
    text-transform: uppercase;
    letter-spacing: 0.04em;
