    position: absolute;
    width: min(78%, 420px);
    aspect-ratio: 1;
    border-radius: 50%;
    border: 2px solid color-mix(in srgb, var(--ms-accent) 35%, transparent);
    box-shadow:
        0 0 0 1px color-mix(in srgb, var(--ms-edge) 80%, transparent),
        0 0 40px color-mix(in srgb, var(--ms-accent) 25%, transparent);
    opacity: 0.55;
    animation: mission-start-aura-pulse 1.4s ease-in-out infinite alternate;
}
.mission-start-overlay.is-count .mission-start-aura {
    width: min(70%, 360px);
    opacity: 0.85;
    animation: mission-start-aura-spin 2.4s linear infinite;
}
.mission-start-overlay.is-go .mission-start-aura {
    width: min(92%, 520px);
    opacity: 1;
    border-color: var(--ms-accent);
    animation: mission-start-aura-burst 0.55s steps(5, end) forwards;
}

.mission-start-frame {
    position: absolute;
    width: min(88%, 560px);
    height: min(52%, 280px);
    pointer-events: none;
}
.mission-start-frame .ms-corner {
    position: absolute;
    width: 28px;
    height: 28px;
    border-color: var(--ms-accent);
    border-style: solid;
    border-width: 0;
    opacity: 0.9;
}
.mission-start-frame .ms-tl { top: 0; left: 0; border-top-width: 3px; border-left-width: 3px; }
.mission-start-frame .ms-tr { top: 0; right: 0; border-top-width: 3px; border-right-width: 3px; }
.mission-start-frame .ms-bl { bottom: 0; left: 0; border-bottom-width: 3px; border-left-width: 3px; }
.mission-start-frame .ms-br { bottom: 0; right: 0; border-bottom-width: 3px; border-right-width: 3px; }
.mission-start-frame .ms-slash { display: none; }

.mission-start-stack {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: clamp(10px, calc(1.6 * var(--sv-w)), 18px);
    max-width: 94%;
}

.mission-start-text {
    position: relative;
    display: grid;
    place-items: center;
    font-family: var(--ui-font-family, monospace);
    font-size: clamp(28px, calc(4.8 * var(--sv-w)), 56px) !important;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--ms-accent, var(--color-primary, #e8e8e8));
    text-align: center;
    min-width: min(92%, 520px);
    min-height: clamp(72px, calc(12 * var(--sv-w)), 110px);
    padding: clamp(18px, calc(2.8 * var(--sv-w)), 28px) clamp(22px, calc(3.5 * var(--sv-w)), 40px);
    border: var(--ui-border-width-thick, 3px) solid var(--ms-accent, var(--color-primary, #b0b0b0));
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--ms-accent) 14%, #05060a) 0%,
            color-mix(in srgb, var(--ms-edge) 55%, #05060a) 100%);
    box-shadow:
        inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--ms-accent) 28%, transparent),
        0 0 28px color-mix(in srgb, var(--ms-accent) 35%, transparent),
        0 4px 0 #000;
    text-shadow:
        0 2px 0 #050508,
        0 0 12px color-mix(in srgb, var(--ms-accent) 55%, transparent);
    -webkit-font-smoothing: none;
    -moz-osx-font-smoothing: unset;
}

.mission-start-sub {
    font-family: var(--ui-font-family, monospace);
    font-size: clamp(12px, calc(1.6 * var(--sv-w)), 18px);
    font-weight: 700;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: color-mix(in srgb, var(--ms-accent) 75%, #fff);
    text-shadow: 0 1px 0 #050508;
    opacity: 0.85;
}
.mission-start-sub[hidden] { display: none !important; }

.mission-start-text.mission-start-count {
    position: relative;
    width: clamp(168px, calc(34 * var(--sv-w)), 260px);
    min-width: 0;
    height: clamp(196px, calc(40 * var(--sv-w)), 300px);
    min-height: 0;
    padding: 0;
    letter-spacing: 0;
    border: 4px solid var(--ms-accent, var(--color-primary, #b0b0b0));
    background:
        repeating-linear-gradient(0deg, transparent 0 4px, color-mix(in srgb, var(--ms-accent) 8%, transparent) 4px 5px),
        color-mix(in srgb, var(--ms-edge) 40%, #05060a);
    box-shadow:
        inset 0 0 0 3px #05060a,
        inset 0 0 0 6px color-mix(in srgb, var(--ms-accent) 40%, transparent),
        0 0 36px color-mix(in srgb, var(--ms-accent) 45%, transparent);
    text-shadow: none;
    image-rendering: pixelated;
}

.mission-start-pixel-canvas {
    position: absolute;
    left: 10%;
    right: 10%;
    top: 8%;
    bottom: 18%;
    width: 80%;
    height: 74%;
    object-fit: contain;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    pointer-events: none;
    filter:
        drop-shadow(3px 0 0 color-mix(in srgb, var(--ms-accent) 45%, transparent))
        drop-shadow(-3px 0 0 color-mix(in srgb, var(--ms-accent) 45%, transparent))
        drop-shadow(0 3px 0 color-mix(in srgb, var(--ms-accent) 45%, transparent))
        drop-shadow(0 -3px 0 color-mix(in srgb, var(--ms-accent) 45%, transparent));
}

/* Stepped progress bar: drains once per countdown second. */
.mission-start-text.mission-start-count::after {
    content: '';
    position: absolute;
    left: 12%;
    right: 12%;
    bottom: 8%;
    height: 8px;
    background: var(--ms-accent, var(--color-primary));
    box-shadow: 0 0 10px color-mix(in srgb, var(--ms-accent) 60%, transparent);
    transform-origin: left center;
    pointer-events: none;
}
.mission-start-text.mission-start-count.mission-start-tick {
    animation: mission-start-count-in 0.22s steps(4, end);
}
.mission-start-text.mission-start-count.mission-start-tick::after {
    animation: mission-start-drain 0.9s steps(12, end) forwards;
}
.mission-start-text.mission-start-go.mission-start-tick {
    animation: mission-start-go-in 0.28s steps(4, end);
}

@keyframes mission-start-drain {
    from { transform: scaleX(1); }
    to { transform: scaleX(0); }
}

.mission-start-text.mission-start-go {
    width: clamp(220px, calc(48 * var(--sv-w)), 380px);
    min-width: 0;
    height: clamp(140px, calc(28 * var(--sv-w)), 220px);
    min-height: 0;
    padding: 0;
    font-size: clamp(64px, calc(11 * var(--sv-w)), 120px) !important;
    letter-spacing: 0.22em;
    color: var(--ms-accent, #c8f0c8);
    border-color: var(--ms-accent, #c8f0c8);
    border-width: 4px;
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--ms-accent) 32%, #05060a) 0%,
            color-mix(in srgb, var(--ms-hull) 45%, #05060a) 100%);
    box-shadow:
        inset 0 0 0 3px #05060a,
        0 0 0 2px var(--ms-accent),
        0 0 48px color-mix(in srgb, var(--ms-accent) 70%, transparent);
}

.mission-start-text.mission-start-pulse,
.mission-start-text.mission-start-fire {
    animation: mission-start-pulse 0.75s ease-in-out infinite alternate;
}

@keyframes mission-start-pulse {
    from {
        opacity: 0.72;
        box-shadow:
            inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--ms-accent) 22%, transparent),
            0 0 18px color-mix(in srgb, var(--ms-accent) 25%, transparent),
            0 4px 0 #000;
    }
    to {
        opacity: 1;
        box-shadow:
            inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--ms-accent) 40%, transparent),
            0 0 36px color-mix(in srgb, var(--ms-accent) 55%, transparent),
            0 4px 0 #000;
    }
}

@keyframes mission-start-count-in {
    from {
        opacity: 0;
        transform: scale(1.28);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

@keyframes mission-start-go-in {
    from {
        opacity: 0;
        transform: scale(1.55);
        filter: brightness(1.6);
    }
    to {
        opacity: 1;
        transform: scale(1);
        filter: brightness(1);
    }
}

@keyframes mission-start-flash {
    0%, 100% { opacity: 1; }
    40% { opacity: 0.55; }
    70% { opacity: 1; }
}

@keyframes mission-start-aura-pulse {
    from { transform: scale(0.92); opacity: 0.35; }
    to { transform: scale(1.06); opacity: 0.7; }
}

@keyframes mission-start-aura-spin {
    to { transform: rotate(360deg) scale(1.05); }
}

@keyframes mission-start-aura-burst {
    from { transform: scale(0.7); opacity: 1; }
    to { transform: scale(1.35); opacity: 0; }
}

@keyframes mission-start-radar {
    to { transform: rotate(360deg); }
}

/* —— Per-faction mission-start identity —— */
/* Terran: clean military double-frame, cyan scanlines */
html[data-faction="terran"] .mission-start-overlay,
.mission-start-overlay[data-faction="terran"] {
    --ms-accent: var(--faction-accent, #7ec8ff);
}
html[data-faction="terran"] .mission-start-text,
.mission-start-overlay[data-faction="terran"] .mission-start-text {
    border-radius: 0;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 5px color-mix(in srgb, var(--ms-accent) 55%, transparent),
        0 0 28px color-mix(in srgb, var(--ms-accent) 35%, transparent),
        0 4px 0 #000;
}
html[data-faction="terran"] .mission-start-text.mission-start-count,
.mission-start-overlay[data-faction="terran"] .mission-start-text.mission-start-count {
    background:
        repeating-linear-gradient(0deg, transparent 0 3px, color-mix(in srgb, var(--ms-accent) 10%, transparent) 3px 4px),
        color-mix(in srgb, var(--ms-edge) 50%, #05060a);
}

/* Kronax: aggressive skew, claw slashes, hot orange */
html[data-faction="kronax"] .mission-start-overlay,
.mission-start-overlay[data-faction="kronax"] {
    --ms-accent: var(--faction-accent, #ff7a4a);
}
html[data-faction="kronax"] .mission-start-stack,
.mission-start-overlay[data-faction="kronax"] .mission-start-stack {
    transform: skewX(-4deg);
}
html[data-faction="kronax"] .mission-start-text,
.mission-start-overlay[data-faction="kronax"] .mission-start-text {
    border-width: 4px;
    clip-path: polygon(0 8%, 8% 0, 100% 0, 100% 92%, 92% 100%, 0 100%);
}
html[data-faction="kronax"] .mission-start-frame .ms-slash,
.mission-start-overlay[data-faction="kronax"] .mission-start-frame .ms-slash {
    display: block;
    position: absolute;
    height: 3px;
    width: 42%;
    background: var(--ms-accent);
    box-shadow: 0 0 10px var(--ms-accent);
    opacity: 0.85;
}
html[data-faction="kronax"] .mission-start-frame .ms-slash-a,
.mission-start-overlay[data-faction="kronax"] .mission-start-frame .ms-slash-a {
    top: 18%; left: -4%; transform: rotate(-18deg);
}
html[data-faction="kronax"] .mission-start-frame .ms-slash-b,
.mission-start-overlay[data-faction="kronax"] .mission-start-frame .ms-slash-b {
    bottom: 18%; right: -4%; transform: rotate(-18deg);
}
html[data-faction="kronax"] .mission-start-text.mission-start-count.mission-start-tick,
.mission-start-overlay[data-faction="kronax"] .mission-start-text.mission-start-count.mission-start-tick {
    animation: mission-start-count-in 0.18s steps(3, end), mission-start-kronax-shake 0.18s steps(3, end);
}
@keyframes mission-start-kronax-shake {
    0% { transform: scale(1.28) translateX(-4px); }
    50% { transform: scale(1.1) translateX(3px); }
    100% { transform: scale(1) translateX(0); }
}

/* Voidborn: soft rings, circular countdown, magenta bloom */
html[data-faction="voidborn"] .mission-start-overlay,
.mission-start-overlay[data-faction="voidborn"] {
    --ms-accent: var(--faction-accent, #f09cff);
}
html[data-faction="voidborn"] .mission-start-text,
.mission-start-overlay[data-faction="voidborn"] .mission-start-text {
    border-radius: 8px;
    box-shadow:
        inset 0 0 24px color-mix(in srgb, var(--ms-accent) 22%, transparent),
        0 0 40px color-mix(in srgb, var(--ms-accent) 45%, transparent);
}
html[data-faction="voidborn"] .mission-start-text.mission-start-count,
.mission-start-overlay[data-faction="voidborn"] .mission-start-text.mission-start-count {
    border-radius: 50%;
    width: clamp(180px, calc(36 * var(--sv-w)), 280px);
    height: clamp(180px, calc(36 * var(--sv-w)), 280px);
    background:
        radial-gradient(circle at 50% 42%,
            color-mix(in srgb, var(--ms-accent) 22%, #120818) 0%,
            #05060a 72%);
}
html[data-faction="voidborn"] .mission-start-aura,
.mission-start-overlay[data-faction="voidborn"] .mission-start-aura {
    border-style: dashed;
    border-width: 3px;
}

/* Pirate: scrap gold, uneven frame, weathered bars */
html[data-faction="pirate"] .mission-start-overlay,
.mission-start-overlay[data-faction="pirate"] {
    --ms-accent: var(--faction-accent, #d4a84a);
}
html[data-faction="pirate"] .mission-start-text,
.mission-start-overlay[data-faction="pirate"] .mission-start-text {
    border-style: solid;
    border-width: 3px 5px 4px 3px;
    box-shadow:
        3px 3px 0 #000,
        -2px 0 0 color-mix(in srgb, var(--ms-accent) 40%, transparent),
        0 0 22px color-mix(in srgb, var(--ms-accent) 30%, transparent);
    background:
        repeating-linear-gradient(90deg, transparent 0 11px, color-mix(in srgb, var(--ms-accent) 8%, transparent) 11px 12px),
        linear-gradient(165deg, color-mix(in srgb, var(--ms-hull) 35%, #05060a), #05060a 70%);
}
html[data-faction="pirate"] .mission-start-frame .ms-corner,
.mission-start-overlay[data-faction="pirate"] .mission-start-frame .ms-corner {
    width: 20px;
    height: 20px;
    border-width: 0;
}
html[data-faction="pirate"] .mission-start-frame .ms-tl,
.mission-start-overlay[data-faction="pirate"] .mission-start-frame .ms-tl { border-top-width: 4px; border-left-width: 2px; }
html[data-faction="pirate"] .mission-start-frame .ms-tr,
.mission-start-overlay[data-faction="pirate"] .mission-start-frame .ms-tr { border-top-width: 2px; border-right-width: 5px; }
html[data-faction="pirate"] .mission-start-frame .ms-bl,
.mission-start-overlay[data-faction="pirate"] .mission-start-frame .ms-bl { border-bottom-width: 5px; border-left-width: 3px; }
html[data-faction="pirate"] .mission-start-frame .ms-br,
.mission-start-overlay[data-faction="pirate"] .mission-start-frame .ms-br { border-bottom-width: 2px; border-right-width: 4px; }

/* Machine: circuit grid, mint green, precise brackets */
html[data-faction="machine"] .mission-start-overlay,
.mission-start-overlay[data-faction="machine"] {
    --ms-accent: var(--faction-accent, #50e0a8);
}
html[data-faction="machine"] .mission-start-text,
.mission-start-overlay[data-faction="machine"] .mission-start-text {
    border-radius: 0;
    background:
        linear-gradient(color-mix(in srgb, var(--ms-accent) 12%, transparent) 1px, transparent 1px) 0 0 / 12px 12px,
        linear-gradient(90deg, color-mix(in srgb, var(--ms-accent) 12%, transparent) 1px, transparent 1px) 0 0 / 12px 12px,
        #05060a;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 4px var(--ms-accent),
        0 0 0 1px color-mix(in srgb, var(--ms-accent) 50%, transparent),
        0 0 30px color-mix(in srgb, var(--ms-accent) 40%, transparent);
}
html[data-faction="machine"] .mission-start-text.mission-start-count::after,
.mission-start-overlay[data-faction="machine"] .mission-start-text.mission-start-count::after {
    height: 4px;
    box-shadow: none;
    background: repeating-linear-gradient(90deg, var(--ms-accent) 0 6px, transparent 6px 10px);
}
html[data-faction="machine"] .mission-start-frame .ms-corner,
.mission-start-overlay[data-faction="machine"] .mission-start-frame .ms-corner {
    width: 32px;
    height: 8px;
    border-width: 0 !important;
    background: var(--ms-accent);
    box-shadow: 0 0 8px var(--ms-accent);
}
html[data-faction="machine"] .mission-start-frame .ms-tl,
.mission-start-overlay[data-faction="machine"] .mission-start-frame .ms-tl { top: 0; left: 0; }
html[data-faction="machine"] .mission-start-frame .ms-tr,
.mission-start-overlay[data-faction="machine"] .mission-start-frame .ms-tr { top: 0; right: 0; }
html[data-faction="machine"] .mission-start-frame .ms-bl,
.mission-start-overlay[data-faction="machine"] .mission-start-frame .ms-bl { bottom: 0; left: 0; }
html[data-faction="machine"] .mission-start-frame .ms-br,
.mission-start-overlay[data-faction="machine"] .mission-start-frame .ms-br { bottom: 0; right: 0; }

@media (prefers-reduced-motion: reduce) {
    .mission-start-aura,
    .mission-start-text.mission-start-pulse,
    .mission-start-text.mission-start-fire,
    .mission-start-text.mission-start-count.mission-start-tick,
    .mission-start-overlay.is-go .mission-start-vignette {
        animation: none !important;
    }
}

.player-vitals-side {
    --vitals-h: clamp(96px, calc(16 * var(--sv-h)), 150px);
    display: flex;
    flex-direction: row;
    align-items: stretch;
    justify-content: space-between;
    gap: 6px;
    flex: 0 0 auto;
    width: 100%;
    height: var(--vitals-h);
    min-height: var(--vitals-h);
    max-height: var(--vitals-h);
    box-sizing: border-box;
    padding: 5px 5px;
    border: var(--ui-border-width) solid var(--color-primary);
    background:
        linear-gradient(165deg,
            color-mix(in srgb, var(--color-primary) 4%, var(--color-background)) 0%,
            var(--color-background) 60%);
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary) 25%, transparent);
}

.player-vitals-side .health-bar {
    flex: 1 1 0;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    width: auto;
    min-width: 0;
    height: 100%;
    padding: 0;
    gap: 4px;
}

.player-vitals-side .health-stat-icon,
.player-vitals-side .health-ship-icon {
    margin-right: 0;
    margin-bottom: 2px;
    flex: 0 0 auto;
    display: block;
    align-self: center;
    object-fit: contain;
    /* All three vitals canvases are native 48×48; keep one shared display size. */
    width: calc(48px * var(--hle-icon-scale, 1));
    height: calc(48px * var(--hle-icon-scale, 1));
    image-rendering: pixelated !important;
    image-rendering: -moz-crisp-edges !important;
    image-rendering: crisp-edges !important;
    -ms-interpolation-mode: nearest-neighbor;
    filter: none !important;
    opacity: 1 !important;
}

.player-vitals-side .health-fill {
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
    align-self: center;
    border-width: max(2px, var(--ui-border-width-thin, 2px));
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--vital-color, var(--color-border)) 35%, transparent);
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}

.player-vitals-side .health-fill::before {
    top: auto;
    bottom: 0;
    left: 0;
    width: 100%;
    height: var(--health-width, 100%);
    transition: height 0.12s steps(8, end);
    /* Hard 2px lattice bands — no soft blend */
    background-image: repeating-linear-gradient(
        to top,
        transparent 0 2px,
        rgba(0, 0, 0, 0.35) 2px 4px
    );
    background-blend-mode: normal;
}

#gameCanvas {
    border: var(--ui-border-width-thick) solid var(--ui-border);
    background: var(--color-background);
    display: block;
    margin: 0 auto;
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--ui-border), 0 0 0 var(--ui-border-width) var(--ui-border);
    width: var(--canvas-w);
    height: var(--canvas-h);
    max-width: 100%;
    max-height: 100%;
    /* Size from --canvas-w/h (aspect-correct); do not flex-stretch */
    flex: 0 0 auto;
    filter: contrast(var(--theme-contrast-filter, 1.15))
        saturate(var(--theme-saturation-filter, 1))
        brightness(var(--theme-brightness-filter, 1));
}
/* VOXEL: the game canvas stays unfiltered; overlay effects still work but never
   blur or warp (no blur() / displacement), so the lattice stays crisp. */
html[data-vf-ship-render="VOXEL"] #gameCanvas {
    filter: none !important;
    image-rendering: pixelated !important;
    image-rendering: -moz-crisp-edges !important;
    image-rendering: crisp-edges !important;
}
/* Firefox/Gecko + Win: CSS filter (and voidborn border-radius) on a canvas that
   lives under body { transform: scale(--stage-scale) } makes WebRender smear
   dirty tiles into horizontal terrain streaks. Drop those; keep nearest-neighbour. */
html[data-vf-engine="gecko"] body .game-container .game-stage #gameCanvas,
html[data-vf-engine="gecko"] body .game-container .game-canvas-container > .game-stage #gameCanvas {
    filter: none !important;
    border-radius: 0 !important;
    image-rendering: -moz-crisp-edges !important;
    image-rendering: pixelated !important;
    image-rendering: crisp-edges !important;
}
/* One-frame compositor poke after a backing-store resize (see render/core.js). */
html[data-vf-engine="gecko"] #gameCanvas.vf-gecko-resize {
    transform: translateZ(0);
}
/* Backdrop-filter FX over the scaled stage: same Gecko corruption class
   (SVG filters and CRT contrast backdrop both smear under transform:scale). */
html[data-vf-engine="gecko"] .vf-fx-chroma,
html[data-vf-engine="gecko"] .vf-fx-bloom,
html[data-vf-engine="gecko"] .vf-fx-scanwarp,
html[data-vf-engine="gecko"] .vf-fx-crt {
    display: none !important;
}
/* VOXEL CRT inherits the shared no-warp CRT stack above. */
html[data-vf-ship-render="VOXEL"] .settings-ship-render-canvas {
    image-rendering: pixelated !important;
    image-rendering: crisp-edges !important;
}

/* Right HUD cluster: loadout top, enemy bars, mission bottom */
.game-right-cluster {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    flex: 0 0 auto;
    width: var(--side-panel-w);
    height: 100%;
    max-height: 100%;
    align-self: stretch;
    gap: clamp(4px, calc(0.7 * var(--sv-h)), 8px);
    z-index: 10;
}

.gi-loadout-side {
    flex: 0 0 auto;
    width: 100%;
    min-width: 0;
    order: -1;
}
.gi-loadout-side[hidden] {
    display: none !important;
}
.gi-loadout-side > .gi-cluster {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    padding: 8px 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}
.gi-loadout-side .gi-cluster-title {
    margin: 0 0 6px;
    padding-bottom: 4px;
    letter-spacing: 0.12em;
}
.gi-loadout-side .gi-cluster-body {
    gap: 0;
}
.gi-loadout-side .gi-row {
    align-items: center;
    padding: 6px 0;
    grid-template-columns: 28px minmax(0, 1fr);
    gap: 4px 8px;
}
.gi-loadout-side .gi-row-text {
    flex-direction: column;
    gap: 1px;
}
.gi-loadout-side .gi-row-value {
    text-align: left;
}
.gi-loadout-side .gi-row-value,
.gi-loadout-side .gi-metric-value {
    font-size: var(--font-md);
    font-weight: bold;
    color: #fff;
}
.gi-loadout-side .gi-cluster-body > .gi-row {
    border-bottom: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 12%, transparent);
}
.gi-loadout-side .gi-cluster-body > .gi-row:last-of-type {
    border-bottom: 0;
}
.gi-loadout-side .gi-weapon-chips {
    margin-top: 6px;
    padding-top: 4px;
    border-top: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 12%, transparent);
}
.gi-loadout-side :is(.gi-row-icon, .gi-icon) {
    width: calc(28px * var(--hle-icon-scale, 1));
    height: calc(28px * var(--hle-icon-scale, 1));
}
.gi-loadout-side .gi-row-icon img {
    width: calc(28px * var(--hle-icon-scale, 1)) !important;
    height: calc(28px * var(--hle-icon-scale, 1)) !important;
}

.gi-transit-map {
    flex: 1 1 auto;
    align-self: center;
    width: 48px;
    min-width: 48px;
    max-width: 48px;
    min-height: 60px;
    box-sizing: border-box;
    padding: 10px 4px 10px 5px;
    border: var(--ui-border-width) solid var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, #05060a);
    display: flex;
    flex-direction: row;
    align-items: stretch;
    gap: 4px;
}
.gi-transit-map[hidden] {
    display: none !important;
}
.gi-transit-track {
    position: relative;
    flex: 0 0 12px;
    width: 12px;
    min-height: 0;
    align-self: stretch;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    background: color-mix(in srgb, var(--color-primary) 10%, #000);
}
.gi-transit-icons {
    position: relative;
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
}
.gi-transit-fill {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: var(--vf-transit-pct, 0%);
    background: var(--color-primary);
    opacity: 0.55;
    transition: height 0.4s linear;
}
.gi-transit-ship {
    position: absolute;
    left: 50%;
    bottom: var(--vf-transit-pct, 0%);
    z-index: 3;
    width: 8px;
    height: 8px;
    transform: translate(-50%, 50%) rotate(45deg);
    background: #fff;
    box-shadow: 0 0 4px 1px var(--color-primary);
    transition: bottom 0.4s linear;
}
.gi-transit-gate {
    position: absolute;
    top: -2px;
    left: 50%;
    z-index: 4;
    transform: translate(-50%, -100%);
    font-size: var(--font-sm);
    letter-spacing: 0.08em;
    color: color-mix(in srgb, var(--color-primary) 60%, #fff);
    opacity: 0;
    white-space: nowrap;
}
.gi-transit-gate.is-visible {
    opacity: 1;
}
.gi-transit-arrived .gi-transit-ship {
    box-shadow: 0 0 8px 2px #fff;
}
.gi-transit-event {
    position: absolute;
    left: 50%;
    z-index: 2;
    width: 5px;
    height: 5px;
    transform: translate(-50%, 50%) rotate(45deg);
    box-sizing: border-box;
    border: 1px solid color-mix(in srgb, var(--evt-accent, #c0c0c0) 70%, #fff);
    background: var(--evt-accent, #c0c0c0);
    box-shadow: 0 0 3px color-mix(in srgb, var(--evt-accent, #c0c0c0) 55%, transparent);
    opacity: 0.35;
    pointer-events: none;
}
.gi-transit-event.is-known {
    opacity: 0.95;
}
.gi-transit-event.is-passed {
    opacity: 0.22;
    box-shadow: none;
    background: color-mix(in srgb, var(--evt-accent, #c0c0c0) 35%, #05060a);
}
.gi-transit-event.is-active {
    opacity: 1;
    width: 6px;
    height: 6px;
    box-shadow: 0 0 5px 1px var(--evt-accent, #c0c0c0);
}
.gi-transit-icon {
    position: absolute;
    left: 50%;
    z-index: 2;
    width: 18px;
    height: 18px;
    margin: 0;
    padding: 1px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--evt-accent, #c0c0c0) 75%, #fff);
    background: color-mix(in srgb, var(--evt-accent, #c0c0c0) 22%, #05060a);
    box-shadow: 0 0 6px color-mix(in srgb, var(--evt-accent, #c0c0c0) 45%, transparent);
    opacity: 0;
    transform: translate(10px, 50%) scale(0.35);
    pointer-events: none;
    overflow: hidden;
}
.gi-transit-icon :is(img, .gi-icon, canvas) {
    width: 14px !important;
    height: 14px !important;
    image-rendering: pixelated;
}
.gi-transit-icon.is-known {
    animation: gi-transit-icon-in 0.45s cubic-bezier(0.2, 1.4, 0.4, 1) forwards;
}
.gi-transit-icon.is-passed {
    opacity: 0.35;
    filter: grayscale(0.55);
    box-shadow: none;
    animation: none;
    transform: translate(-50%, 50%) scale(0.85);
}
.gi-transit-icon.is-active {
    animation: gi-transit-icon-pulse 0.9s ease-in-out infinite alternate;
}
@keyframes gi-transit-icon-in {
    0% {
        opacity: 0;
        transform: translate(12px, 50%) scale(0.3);
    }
    70% {
        opacity: 1;
        transform: translate(-54%, 50%) scale(1.12);
    }
    100% {
        opacity: 1;
        transform: translate(-50%, 50%) scale(1);
    }
}
@keyframes gi-transit-icon-pulse {
    from {
        box-shadow: 0 0 4px color-mix(in srgb, var(--evt-accent, #c0c0c0) 40%, transparent);
        transform: translate(-50%, 50%) scale(1);
    }
    to {
        box-shadow: 0 0 10px 2px var(--evt-accent, #c0c0c0);
        transform: translate(-50%, 50%) scale(1.08);
    }
}

.gi-mission-side {
    flex: 0 0 auto;
    width: 100%;
    min-width: 0;
    margin-top: auto;
}
.gi-mission-side[hidden] {
    display: none !important;
}
.gi-mission-side > .gi-cluster {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    padding: 8px 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}
.gi-mission-side .gi-cluster-title {
    margin: 0 0 6px;
    padding-bottom: 4px;
    letter-spacing: 0.12em;
}
.gi-mission-side .gi-cluster-body {
    gap: 8px;
}
.gi-mission-side .gi-row {
    align-items: start;
}
.gi-mission-side .gi-row-text {
    flex-direction: column;
    gap: 1px;
}
.gi-mission-side .gi-row-value {
    text-align: left;
}
.gi-mission-side .gi-row-value,
.gi-mission-side .gi-metric-value {
    font-size: var(--font-md);
    font-weight: bold;
    color: #fff;
}

/* Once the player has resized a loadout/mission panel tall enough, rows read better icon-on-top
   (bigger icon, centered, label/value underneath) than icon-left — icon-left only exists because
   that's the compact layout these panels are born at. A class toggled by a ResizeObserver (see
   js/ui/hud-layout-editor.js, watchRoomyPanels) drives this rather than a CSS container query —
   @container size-containment support can't be assumed on every engine this ships to, while
   ResizeObserver is effectively universal. */
.gi-loadout-side.gi-roomy .gi-row,
.gi-mission-side.gi-roomy .gi-row {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
    padding: 10px 0;
}
.gi-loadout-side.gi-roomy .gi-row-text,
.gi-mission-side.gi-roomy .gi-row-text {
    align-items: center;
}
.gi-loadout-side.gi-roomy :is(.gi-row-icon, .gi-icon) {
    width: calc(36px * var(--hle-icon-scale, 1));
    height: calc(36px * var(--hle-icon-scale, 1));
}
.gi-loadout-side.gi-roomy .gi-row-icon img {
    width: calc(36px * var(--hle-icon-scale, 1)) !important;
    height: calc(36px * var(--hle-icon-scale, 1)) !important;
}
.gi-mission-side.gi-roomy .gi-mission-card {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
}
.gi-mission-side.gi-roomy .gi-mission-card-icon {
    width: calc(44px * var(--hle-icon-scale, 1));
    height: calc(44px * var(--hle-icon-scale, 1));
}
.gi-mission-side.gi-roomy .gi-mission-card-icon :is(img, .gi-icon, canvas) {
    width: calc(40px * var(--hle-icon-scale, 1)) !important;
    height: calc(40px * var(--hle-icon-scale, 1)) !important;
}
.gi-mission-side.gi-roomy .gi-mission-card-copy {
    align-items: center;
}

/* Mission card: icon | action → target → status (readable, not cramped) */
.gi-mission-card {
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 8px 10px;
    align-items: center;
    min-height: 72px;
    padding: 8px 6px;
    box-sizing: border-box;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    background: color-mix(in srgb, var(--color-primary) 8%, transparent);
}
.gi-mission-card-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: calc(36px * var(--hle-icon-scale, 1));
    height: calc(36px * var(--hle-icon-scale, 1));
    flex-shrink: 0;
}
.gi-mission-card-icon :is(img, .gi-icon, canvas) {
    width: calc(32px * var(--hle-icon-scale, 1)) !important;
    height: calc(32px * var(--hle-icon-scale, 1)) !important;
    display: block;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}
.gi-mission-card-copy {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: center;
    gap: 2px;
    min-width: 0;
}
.gi-mission-card-action {
    font-size: var(--font-sm);
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: color-mix(in srgb, #fff 70%, var(--faction-accent, var(--color-primary)));
    line-height: 1.2;
}
.gi-mission-card-target {
    font-size: var(--font-md);
    font-weight: bold;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #fff;
    line-height: 1.25;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.gi-mission-card-status {
    margin-top: 2px;
    font-size: var(--font-sm);
    font-weight: bold;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--faction-accent, var(--color-primary));
    line-height: 1.2;
}

.enemy-vitals-side {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 6px;
    flex: 1 1 auto;
    width: 100%;
    min-height: 0;
    height: auto;
    box-sizing: border-box;
    padding: 6px 5px;
    overflow-x: hidden;
    overflow-y: auto;
    border: var(--ui-border-width) solid var(--color-primary);
    background:
        linear-gradient(165deg,
            color-mix(in srgb, var(--color-primary) 4%, var(--color-background)) 0%,
            var(--color-background) 60%);
    /* No outer ring glow — multi-spread box-shadows drew semi-transparent
       vertical lines over the playfield beside the sidebar. */
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary) 25%, transparent);
    --enemy-bar-h: 14px;
    --enemy-icon-size: 20px;
}

.enemy-vitals-side .health-bar.enemy-health {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    min-height: 0;
    padding: 6px 4px;
    gap: 5px;
    flex: 0 0 auto;
    border: var(--ui-border-width-thin, 2px) solid color-mix(in srgb, var(--color-primary) 35%, transparent);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

.enemy-vitals-side .enemy-faction {
    font-family: var(--ui-font-family);
    font-size: var(--font-text);
    font-weight: bold;
    color: var(--color-primary);
    text-transform: uppercase;
    letter-spacing: 1px;
    line-height: 1.1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    -webkit-font-smoothing: none;
    -moz-osx-font-smoothing: unset;
}

.enemy-vitals-side .enemy-health-main {
    display: flex;
    align-items: center;
    gap: 5px;
    width: 100%;
    min-width: 0;
}

.enemy-vitals-side .health-fill {
    flex: 1 1 auto;
    width: auto;
    min-width: 0;
    height: var(--enemy-bar-h, 14px);
    border-width: var(--ui-border-width-thin, 2px);
}

.enemy-vitals-side .health-ship-icon {
    width: calc(var(--enemy-icon-size, 20px) * var(--hle-icon-scale, 1));
    height: calc(var(--enemy-icon-size, 20px) * var(--hle-icon-scale, 1));
    margin-right: 0;
    flex-shrink: 0;
}

/* Main/champion enemy: vertical health bar */
.enemy-vitals-side .health-bar.enemy-health.is-champion {
    padding: 10px 4px 12px;
    gap: 8px;
}

.enemy-vitals-side .health-bar.enemy-health.is-champion .enemy-health-main {
    align-items: flex-start;
    min-height: clamp(72px, calc(18 * var(--sv-h)), 120px);
}

.enemy-vitals-side .health-bar.enemy-health.is-champion .health-fill {
    flex: 0 0 auto;
    width: var(--enemy-bar-h, 14px);
    min-width: 0;
    align-self: flex-start;
}

.enemy-vitals-side .health-bar.enemy-health.is-champion .health-fill::before {
    top: auto;
    bottom: 0;
    left: 0;
    width: 100%;
    height: var(--health-width, 100%);
    transition: height 0.3s ease;
}

.game-left-cluster .weapon-selection {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    margin: 0;
    gap: 5px;
    width: 100%;
    box-sizing: border-box;
    overflow: hidden;
    padding: 7px 8px;
    border: var(--ui-border-width) solid var(--color-primary);
    background:
        linear-gradient(165deg,
            color-mix(in srgb, var(--color-primary) 4%, var(--color-background)) 0%,
            var(--color-background) 60%);
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary) 25%, transparent);
    font-family: var(--ui-font-family);
    font-size: var(--font-md);
    color: var(--color-text);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    line-height: 1.2;
    flex: 1 1 auto;
    min-height: clamp(110px, calc(20 * var(--sv-h)), 200px);
    max-height: 42%;
    -webkit-font-smoothing: none;
    -moz-osx-font-smoothing: unset;
}

.game-left-cluster .weapon-list {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: stretch;
    gap: 5px;
    flex: 1 1 auto;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
}

/* One card per weapon: name + side-view weapon art over a left-to-right reload fill; stats on hover */
.game-left-cluster .weapon-card {
    --reload-pct: 100%;
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    padding: 6px 7px;
    border: var(--ui-border-width-thin) solid color-mix(in srgb, var(--color-primary) 30%, transparent);
    background: color-mix(in srgb, var(--color-primary) 7%, #05060a);
    box-sizing: border-box;
    flex: 0 0 auto;
    overflow: hidden;
    transition: opacity 0.12s linear, filter 0.12s linear;
}

.game-left-cluster .weapon-card-reload {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--reload-pct);
    background: linear-gradient(
        90deg,
        color-mix(in srgb, var(--faction-accent, var(--color-primary)) 8%, transparent),
        color-mix(in srgb, var(--faction-accent, var(--color-primary)) 28%, transparent)
    );
    pointer-events: none;
    z-index: 0;
    transition: width 0.05s linear;
}

.game-left-cluster .weapon-card.is-reloading .weapon-card-reload {
    background: linear-gradient(
        90deg,
        color-mix(in srgb, var(--res-ore, #c49a4a) 10%, transparent),
        color-mix(in srgb, var(--res-ore, #c49a4a) 34%, transparent)
    );
}

.game-left-cluster .weapon-card.is-no-energy .weapon-card-reload {
    background: linear-gradient(
        90deg,
        color-mix(in srgb, var(--res-voltex, #c86ef0) 6%, transparent),
        color-mix(in srgb, var(--res-voltex, #c86ef0) 18%, transparent)
    );
}

.game-left-cluster .weapon-card > :not(.weapon-card-reload) {
    position: relative;
    z-index: 1;
}

.game-left-cluster .weapon-card.is-dim {
    opacity: 0.42;
    filter: saturate(0.55);
}

.game-left-cluster .weapon-card.is-dim.is-active {
    opacity: 0.55;
}

.game-left-cluster .weapon-card.is-active {
    border-color: var(--faction-accent, var(--color-primary));
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 18%, #05060a);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
}

.game-left-cluster .weapon-card-icon,
#weaponIcon {
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges;
    image-rendering: crisp-edges;
    width: calc(32px * var(--hle-icon-scale, 1));
    height: calc(32px * var(--hle-icon-scale, 1));
    border: var(--ui-border-width-thin) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    background: var(--ui-surface);
    flex-shrink: 0;
    justify-self: center;
}

.game-left-cluster .weapon-card.is-active .weapon-card-icon {
    border-color: var(--faction-accent, var(--color-primary));
}

.game-left-cluster .weapon-card-body {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}

/* Static so the hover stats overlay the whole card. */
.game-left-cluster .weapon-card > .weapon-card-body { position: static; }

.game-left-cluster .weapon-card-art {
    position: relative;
    z-index: 1;
    display: block;
    width: 100%;
    height: auto;
    aspect-ratio: 3 / 1;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    /* dark outline first, then the glow (same treatment as other glowing icons) */
    filter: drop-shadow(1px 0 0 #05060a) drop-shadow(-1px 0 0 #05060a) drop-shadow(0 1px 0 #05060a) drop-shadow(0 -1px 0 #05060a);
}

/* The weapon always shows in full; only its charge cells (below) show the reload / charge. */
.game-left-cluster .weapon-card-reload { display: none; }
.game-left-cluster .weapon-card-artbox {
    position: relative;
    z-index: 1;
    line-height: 0;
}

/* Charge cells sit on the receiver (art grid: x 5–19, y 7–9) and light up in the weapon's accent. */
.game-left-cluster .weapon-card-pips {
    position: absolute;
    left: 10.4%;
    width: 29.2%;
    top: 43.75%;
    height: 12.5%;
    display: flex;
    gap: 4%;
    z-index: 2;
    pointer-events: none;
}
.game-left-cluster .weapon-card-pips > i {
    flex: 1 1 0;
    background: #05060a;
    opacity: .55;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, #05060a);
}
.game-left-cluster .weapon-card-pips > i.is-on {
    background: var(--faction-accent, var(--color-primary));
    opacity: 1;
    box-shadow: 0 0 0 1px #05060a, 0 0 2px #fff, 0 0 6px var(--faction-accent, var(--color-primary)), 0 0 10px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
}
.game-left-cluster .weapon-card.is-reloading .weapon-card-pips > i.is-on { background: var(--res-ore, #c49a4a); box-shadow: 0 0 0 1px #05060a, 0 0 2px #fff, 0 0 6px var(--res-ore, #c49a4a), 0 0 10px color-mix(in srgb, var(--res-ore, #c49a4a) 60%, transparent); }
.game-left-cluster .weapon-card.is-charging .weapon-card-pips > i.is-on { background: #fff; box-shadow: 0 0 0 1px #05060a, 0 0 3px #fff, 0 0 8px var(--faction-accent, var(--color-primary)), 0 0 12px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, transparent); }
.game-left-cluster .weapon-card.is-no-energy .weapon-card-pips > i.is-on { background: var(--res-voltex, #c86ef0); opacity: 1; box-shadow: 0 0 0 1px #05060a, 0 0 4px var(--res-voltex, #c86ef0); }

