    width: 100%;
    max-height: none;
    align-items: center;
    border-color: var(--color-primary, #e07028);
}
.planet-editor-preview-wrap.pe-preview-fs #pePreview,
.planet-editor-preview-wrap.pe-preview-fs #eePreview,
.planet-editor-preview-wrap.pe-preview-fs #sePreview {
    border-width: var(--ui-border-width-thick);
}
.planet-editor-preview-wrap.pe-preview-fs .pe-preview-label {
    color: var(--color-primary, #e07028);
    letter-spacing: 3px;
}
.pe-layer-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 10px;
}
.pe-layer-card {
    border: var(--ui-border-width) solid var(--ui-border, #4a3820);
    padding: 10px;
    margin-bottom: 10px;
    background: var(--ui-surface, #12100c);
    border-radius: 0;
}
.pe-layer-list .pe-layer-card {
    padding: 0;
    margin-bottom: 0;
}
.pe-layer-header {
    display: flex;
    align-items: stretch;
    width: 100%;
    border-bottom: var(--ui-border-width) solid var(--ui-border, #4a3820);
    background: transparent;
}
.pe-layer-collapsed .pe-layer-header {
    border-bottom: none;
}
.pe-layer-expand {
    display: grid;
    grid-template-columns: 18px auto 1fr;
    gap: 8px;
    align-items: center;
    flex: 1;
    min-width: 0;
    padding: 8px 10px;
    margin: 0;
    background: transparent;
    border: none;
    color: inherit;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
}
.pe-layer-expand:hover {
    background: rgba(224, 112, 40, 0.08);
}
.pe-layer-delete {
    flex-shrink: 0;
    width: 32px;
    margin: 0;
    padding: 0;
    border: none;
    border-left: var(--ui-border-width) solid var(--ui-border, #4a3820);
    background: transparent;
    color: var(--color-primary, #e07028);
    font-family: inherit;
    font-size: var(--font-h2);
    line-height: 1;
    cursor: pointer;
}
.pe-layer-delete:hover {
    background: rgba(224, 112, 40, 0.2);
    color: var(--color-text, #e8e0d0);
}
.pe-layer-toggle {
    color: var(--color-primary, #e07028);
    font-size: var(--font-h2);
    font-weight: bold;
    line-height: 1;
}
.pe-layer-title {
    font-weight: bold;
    margin-bottom: 0;
    letter-spacing: 2px;
    color: var(--color-primary, #e07028);
    font-size: var(--font-text);
}
.pe-layer-summary {
    font-size: var(--font-text);
    color: var(--color-text-secondary, #b09070);
    text-align: right;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.pe-layer-body {
    padding: 10px;
}
.pe-layer-collapsed .pe-layer-body {
    display: none;
}
.pe-ability-group {
    margin-bottom: 14px;
}
.pe-ability-group-title {
    font-size: var(--font-text);
    font-weight: bold;
    letter-spacing: 2px;
    color: var(--color-primary, #e07028);
    margin-bottom: 6px;
    padding-bottom: 4px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #4a3820);
}
.pe-ability-icon {
    display: inline-block;
    width: 1.5em;
    text-align: center;
    margin-right: 6px;
    font-size: var(--font-h2);
    line-height: 1;
    vertical-align: middle;
}
.pe-row {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 6px 10px;
    align-items: center;
    margin-bottom: 8px;
}
.pe-color-row {
    grid-template-columns: 1fr auto auto auto;
}
.pe-color-row input[type="color"] {
    width: 36px;
    height: 28px;
    padding: 0;
    border: var(--ui-border-width-thin, 2px) solid var(--color-border, #4a3820);
    background: transparent;
    cursor: pointer;
}
.pe-color-row input[type="color"]:disabled {
    opacity: 0.35;
    cursor: default;
}
.pe-hex {
    font-size: var(--font-text);
    opacity: 0.8;
    min-width: 64px;
}
.pe-color-clear {
    padding: 4px 8px;
    font-size: var(--font-text);
}
.pe-slider-row { grid-template-columns: 1fr auto; }
.pe-slider-row input[type="range"] { grid-column: 1 / -1; width: 100%; }
.pe-text-row { grid-template-columns: 1fr; }
.pe-text-row input[type="url"],
.pe-text-row input[type="text"] {
    grid-column: 1 / -1;
    width: 100%;
    background: #0a0a0a;
    color: var(--color-text-primary, #e8dcc8);
    border: var(--ui-border-width) solid var(--color-border, #3a3028);
    padding: 6px 8px;
    font-family: inherit;
    font-size: var(--font-text);
}
.pe-row label { font-size: var(--font-text); color: var(--color-text-secondary, #b09070); letter-spacing: 1px; }
.pe-val {
    font-size: var(--font-text);
    min-width: 36px;
    text-align: right;
    color: var(--color-primary, #e07028);
}
.pe-row select {
    grid-column: 1 / -1;
    background: #0a0a0a;
    color: var(--color-text, #e8e0d0);
    border: var(--ui-border-width) solid var(--ui-border, #4a3820);
    padding: 5px 6px;
    border-radius: 0;
    font-family: inherit;
    outline: none;
    appearance: none;
    background-image: linear-gradient(45deg, transparent 50%, var(--color-primary, #e07028) 50%),
                      linear-gradient(135deg, var(--color-primary, #e07028) 50%, transparent 50%);
    background-position: calc(100% - 14px) calc(50% - 2px), calc(100% - 9px) calc(50% - 2px);
    background-size: 5px 5px, 5px 5px;
    background-repeat: no-repeat;
    padding-right: 24px;
}
.pe-row select:focus {
    border-color: var(--color-primary, #e07028);
}
.pe-checklist { display: flex; flex-direction: column; gap: 6px; }
.pe-check, .pe-inline {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: var(--font-text);
    margin-bottom: 6px;
    color: var(--color-text-secondary, #b09070);
}
.planet-editor-overlay input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 14px;
    height: 14px;
    margin: 0;
    border: var(--ui-border-width) solid var(--color-primary, #e07028);
    background: #0a0a0a;
    border-radius: 0;
    cursor: pointer;
    position: relative;
    accent-color: var(--color-primary, #e07028);
}
.planet-editor-overlay input[type="checkbox"]:checked {
    background: var(--color-primary, #e07028);
}
.planet-editor-overlay input[type="checkbox"]:checked::after {
    content: '';
    position: absolute;
    left: 3px;
    top: 0px;
    width: 4px;
    height: 8px;
    border: solid #0a0a0a;
    border-width: 0 var(--ui-border-width) var(--ui-border-width) 0;
    transform: rotate(45deg);
}
.planet-editor-overlay input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    height: 8px;
    background: #1a1510;
    border: var(--ui-border-width) solid var(--ui-border, #4a3820);
    border-radius: 0;
    outline: none;
}
.planet-editor-overlay input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 14px;
    height: 14px;
    background: var(--color-primary, #e07028);
    border: var(--ui-border-width) solid #0a0a0a;
    border-radius: 0;
    cursor: pointer;
    box-shadow: none;
}
.planet-editor-overlay input[type="range"]::-moz-range-thumb {
    width: 14px;
    height: 14px;
    background: var(--color-primary, #e07028);
    border: var(--ui-border-width) solid #0a0a0a;
    border-radius: 0;
    cursor: pointer;
}
.planet-editor-overlay input[type="range"]::-moz-range-progress {
    background: var(--color-primary, #e07028);
    height: 4px;
}


/* --- css/styles/part-05.css --- */
.pe-hint { font-size: var(--font-text); color: var(--color-text-secondary, #b09070); margin: 0 0 10px; }
.pe-pattern-picker {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 10px;
}
.pe-pattern-picker > label {
    font-size: var(--font-text);
    color: var(--color-text-secondary, #b09070);
}
.pe-pattern-current {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 6px;
    margin: 0;
    background: #0d0d0d;
    border: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    color: inherit;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
}
.pe-pattern-current:hover {
    border-color: var(--color-primary, #e07028);
}
.pe-pattern-name {
    flex: 1;
    font-size: var(--font-text);
    letter-spacing: 0.5px;
    color: var(--color-text, #e8dcc8);
    word-break: break-all;
}
.pe-pattern-open-hint {
    color: var(--color-primary, #e07028);
    font-size: var(--font-h2);
    flex-shrink: 0;
}
.pe-pattern-thumb {
    display: block;
    image-rendering: pixelated;
    border: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
    background: #000;
    flex-shrink: 0;
}
.pe-pattern-modal {
    position: absolute;
    inset: 0;
    z-index: 30;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.72);
    padding: 16px;
}
.pe-pattern-modal-dialog {
    width: min(520px, 100%);
    max-height: min(calc(70 * var(--ch)), calc(560px * var(--zk)));
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px;
    background: var(--ui-surface, #12100c);
    border: var(--ui-border-width) solid var(--color-primary, #e07028);
}
.pe-pattern-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}
.pe-pattern-modal-header h3 {
    margin: 0;
    font-size: var(--font-h2);
    letter-spacing: 2px;
    color: var(--color-primary, #e07028);
}
.pe-pattern-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(72px, 1fr));
    gap: 6px;
    max-height: 220px;
    overflow: auto;
    padding: 4px 2px;
}
.pe-pattern-grid-modal {
    max-height: none;
    flex: 1;
    min-height: 0;
}
.pe-pattern-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 4px;
    background: #0d0d0d;
    border: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    color: var(--color-text-secondary, #b09070);
    cursor: pointer;
    font-family: inherit;
    font-size: var(--font-text);
    letter-spacing: 0;
    text-transform: none;
    line-height: 1.15;
    word-break: break-all;
}
.pe-pattern-item:hover {
    border-color: var(--color-text-secondary, #b09070);
}
.pe-pattern-item.active {
    border-color: var(--color-primary, #e07028);
    color: var(--color-text, #e8dcc8);
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--color-primary, #e07028);
}
.pe-pattern-item .pe-pattern-thumb {
    width: 56px;
    height: 84px;
}
.pe-pattern-edit-btn {
    align-self: flex-start;
}
.pe-pattern-item-wrap {
    position: relative;
    display: flex;
    flex-direction: column;
}
.pe-pattern-item-wrap.active .pe-pattern-item {
    border-color: var(--color-primary, #e07028);
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--color-primary, #e07028);
}
.pe-pattern-item-edit {
    position: absolute;
    top: 4px;
    right: 4px;
    min-width: 24px;
    padding: 2px 6px;
    font-size: var(--font-text);
    z-index: 1;
}
.pe-pattern-modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    flex-shrink: 0;
}
.hs-res-buy-modal {
    position: absolute;
    inset: 0;
    z-index: 80;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.78);
    padding: 16px;
}
/* Ship anatomy modal: inside .home-station-content (the station screen), same
   absolute overlay pattern as .hs-res-buy-modal — modal chrome, not a new tab. */
.home-station-content > .hs-anatomy-modal-overlay,
.hs-anatomy-modal-overlay {
    position: absolute;
    inset: 0;
    z-index: 80;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.78);
    padding: 16px;
    box-sizing: border-box;
}
.hs-anatomy-modal {
    width: min(1280px, 100%);
    height: min(900px, 100%);
    max-width: 100%;
    max-height: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 14px 16px;
    background: #050308;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 85%, #fff);
    box-shadow: 4px 4px 0 0 #000, inset 2px 2px 0 0 color-mix(in srgb, var(--color-primary) 30%, transparent);
    box-sizing: border-box;
}
.hs-anatomy-modal-head {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}
.hs-anatomy-modal-title {
    font-weight: bold;
    letter-spacing: 0.1em;
}
.hs-anatomy-modal-close {
    flex: 0 0 auto;
    width: 32px;
    height: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, var(--color-primary) 14%, #05060a);
    color: var(--color-text, #fff);
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 55%, transparent);
    cursor: pointer;
}
.hs-anatomy-modal-close:hover {
    border-color: var(--color-primary);
}
.hs-anatomy-modal .hs-hangar-bay-stage {
    flex: 1 1 auto;
    min-height: 0;
    position: relative;
}
/* Anatomy modal: style panels become full-height side rails. */
.hs-anatomy-modal .hs-floating-area-style {
    top: 8px;
    bottom: 8px;
    left: 8px;
    width: min(280px, calc(100% - 16px));
    height: auto;
    max-height: none;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px;
    overflow-y: auto;
}
.hs-anatomy-modal .hs-floating-area-style.is-right {
    left: auto;
    right: 8px;
}
.hs-anatomy-modal .hs-floating-area-style strong {
    flex: 0 0 auto;
}
.hs-anatomy-modal .hs-floating-wing-preview,
.hs-anatomy-modal .hs-floating-style-carousel,
.hs-anatomy-modal .hs-floating-area-crop {
    flex: 0 0 auto;
}
.hs-anatomy-modal .hs-floating-panel-link {
    margin-top: auto;
}
/* Anatomy modal: pins only — no hangar side-rail cards or link stubs. */
.hs-anatomy-modal .hs-hangar-slot-card,
.hs-anatomy-modal .hs-hangar-link-svg {
    display: none !important;
}
.hs-anatomy-modal .hs-hangar-slot-pin {
    opacity: 1;
}
/* The ship thumb on STATION doubles as the anatomy-modal trigger. */
.hs-ship-thumb[data-open-anatomy-modal] {
    cursor: pointer;
}
.home-station-content > .hs-res-buy-modal {
    position: absolute;
    z-index: 80;
}
.hs-res-buy-dialog {
    width: min(520px, 100%);
    max-height: min(calc(80 * var(--ch)), calc(640px * var(--zk)));
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 14px 16px;
    background: #050308;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 85%, #fff);
    border-radius: 0;
    box-shadow: 4px 4px 0 0 #000, inset 2px 2px 0 0 color-mix(in srgb, var(--color-primary) 30%, transparent);
    overflow: auto;
}
.hs-res-buy-head h3 {
    margin: 0;
    font-size: calc(var(--font-text) + 2px);
    letter-spacing: 2px;
    color: #fff;
    text-transform: uppercase;
}
.hs-res-buy-sub {
    margin: 4px 0 0;
    font-size: var(--font-text);
    letter-spacing: 1px;
    color: color-mix(in srgb, var(--color-primary) 70%, #fff);
}
.hs-res-buy-cost {
    padding: 6px 0;
    border-top: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 35%, transparent);
    border-bottom: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 35%, transparent);
}
.hs-res-buy-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.hs-res-buy-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    gap: 8px;
    align-items: center;
}
.hs-res-buy-name {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}
.hs-res-buy-ok {
    margin: 8px 0;
    letter-spacing: 1px;
}
.hs-res-buy-wallet {
    margin: 0;
    font-size: var(--font-text);
    letter-spacing: 1px;
    color: color-mix(in srgb, var(--color-primary) 55%, #fff);
}
.hs-res-buy-actions {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
    flex-wrap: wrap;
    margin-top: 4px;
}
.hs-res-buy-close {
    opacity: 0.85;
}
.pe-unsaved-dialog {
    width: min(420px, 100%);
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 16px;
    background: var(--ui-surface, #12100c);
    border: var(--ui-border-width) solid var(--color-primary, #e07028);
}
.pe-unsaved-dialog h3 {
    margin: 0;
    font-size: var(--font-h2);
    letter-spacing: 2px;
    color: var(--color-primary, #e07028);
}
.pe-unsaved-actions {
    display: flex;
    gap: 8px;
    justify-content: flex-end;
    flex-wrap: wrap;
}
.pe-pattern-editor-modal {
    position: absolute;
    inset: 0;
    z-index: 40;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.78);
    padding: 16px;
}
.pe-pattern-editor-dialog {
    width: min(420px, 100%);
    max-height: min(calc(88 * var(--ch)), calc(720px * var(--zk)));
    overflow: auto;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px;
    background: var(--ui-surface, #12100c);
    border: var(--ui-border-width) solid var(--color-primary, #e07028);
}
.pe-pattern-editor-canvas-wrap {
    display: flex;
    justify-content: center;
    padding: 8px;
    background: #050505;
    border: var(--ui-border-width) solid var(--ui-border, #3a2a18);
}
.pe-pattern-editor-canvas {
    image-rendering: pixelated;
    cursor: crosshair;
    max-width: 100%;
    touch-action: none;
}
.pe-pattern-editor-tools,
.pe-pattern-editor-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}
.pe-text-input {
    grid-column: 1 / -1;
    width: 100%;
    box-sizing: border-box;
    background: #0a0a0a;
    color: var(--color-text, #e8e0d0);
    border: var(--ui-border-width) solid var(--ui-border, #4a3820);
    padding: 5px 6px;
    border-radius: 0;
    font-family: inherit;
    outline: none;
}
.pe-text-input:focus {
    border-color: var(--color-primary, #e07028);
}
.pe-text-input[readonly] {
    opacity: 0.7;
}
.planet-editor-footer {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: flex-end;
    margin-top: 12px;
    padding-top: 10px;
    border-top: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    flex-shrink: 0;
}

/* Content viewers (Planets / Enemies) */
.content-viewer-overlay {
    position: fixed;
    inset: 0;
    z-index: 1200;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #000;
    background-image:
        linear-gradient(
            to bottom,
            rgba(0, 0, 0, 0.46) 0%,
            rgba(0, 0, 0, 0.30) 40%,
            rgba(0, 0, 0, 0.58) 100%
        ),
        url('../../assets/ui/hs-bg-explorations.png');
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}
.content-viewer-panel {
    width: min(calc(1280px * var(--zk)), calc(98 * var(--cw)));
    height: min(calc(96 * var(--ch)), calc(860px * var(--zk)));
    max-height: calc(96 * var(--sv-h));
    overflow: hidden;
    background: var(--color-background, #1a1208);
    border: var(--ui-border-width-thick) solid var(--ui-border, #c47a2a);
    padding: clamp(14px, calc(2.5 * var(--sv-h)), 24px) clamp(14px, calc(2.5 * var(--sv-w)), 28px) clamp(12px, calc(2 * var(--sv-h)), 18px);
    color: var(--color-text, #e8a040);
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--ui-border, #c47a2a);
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
}
.content-viewer-title {
    margin: 0 0 18px;
    text-align: center;
    letter-spacing: 0.18em;
    font-size: var(--font-h1);
    color: var(--color-text-secondary, #f0b050);
    flex-shrink: 0;
}
.content-viewer-body {
    display: grid;
    grid-template-columns: var(--cv-left-w, 240px) 8px minmax(0, 1fr);
    gap: 4px;
    min-height: 0;
    flex: 1 1 auto;
    overflow: hidden;
    align-items: stretch;
}
.content-viewer-body.has-preview {
    grid-template-columns: var(--cv-left-w, 220px) 8px minmax(0, 1fr) 8px var(--cv-right-w, 260px);
}
.content-viewer-preview {
    min-width: 0;
    min-height: 0;
    height: 100%;
    padding-left: 4px;
    display: flex;
    flex-direction: column;
}
.content-viewer-preview .pe-preview-viewport {
    flex: 1 1 auto;
    min-height: 220px;
}
.content-viewer-preview #pvPreview,
.content-viewer-preview #svPreview,
.content-viewer-preview #evPreview,
.content-viewer-preview #wvPreview,
.content-viewer-preview #avPreview,
.content-viewer-preview #dvPreview {
    width: auto;
    height: auto;
    max-width: 100%;
    max-height: 100%;
    aspect-ratio: 0.8;
    object-fit: contain;
    image-rendering: pixelated;
    border: var(--ui-border-width-thick) solid var(--color-primary, #e07028);
    background: #000;
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--ui-border, #3a2a18);
    flex-shrink: 0;
    transform-origin: center center;
    will-change: transform;
}
.planet-editor-preview-wrap.pe-preview-fs #pvPreview,
.planet-editor-preview-wrap.pe-preview-fs #svPreview,
.planet-editor-preview-wrap.pe-preview-fs #evPreview,
.planet-editor-preview-wrap.pe-preview-fs #wvPreview,
.planet-editor-preview-wrap.pe-preview-fs #avPreview,
.planet-editor-preview-wrap.pe-preview-fs #dvPreview {
    border-width: var(--ui-border-width-thick);
}
.content-viewer-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding-right: 4px;
    min-height: 0;
    height: 100%;
    max-height: none;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary, #808080) var(--color-background, #0a0a0a);
}
.content-viewer-list::-webkit-scrollbar {
    width: 8px;
}
.content-viewer-list::-webkit-scrollbar-track {
    background: var(--color-background, #0a0a0a);
}
.content-viewer-list::-webkit-scrollbar-thumb {
    background: var(--color-primary, #808080);
    border: var(--ui-border-width) solid var(--color-background, #0a0a0a);
}
.content-viewer-item {
    background: transparent;
    border: var(--ui-border-width) solid transparent;
    color: var(--color-text, #e8a040);
    text-align: left;
    padding: 8px 10px;
    cursor: pointer;
    letter-spacing: 0.08em;
    font: inherit;
    text-transform: uppercase;
}
.content-viewer-group {
    font-size: var(--font-text);
    font-weight: bold;
    letter-spacing: 2px;
    color: var(--color-primary, #e07028);
    margin: 8px 4px 2px;
    padding-bottom: 4px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #4a3820);
    flex: 0 0 auto;
    width: 100%;
    box-sizing: border-box;
}
.content-viewer-item:hover {
    border-color: var(--ui-border, #c47a2a);
}
.content-viewer-item.selected {
    background: transparent;
    color: var(--color-text, #e8a040);
    border-color: transparent;
    border-left: var(--ui-indicator-width, var(--ui-border-width, 2px)) solid var(--color-primary, #c47a2a);
    border-right: var(--ui-indicator-width, var(--ui-border-width, 2px)) solid var(--color-primary, #c47a2a);
    font-weight: bold;
}
.content-viewer-item.selected .cv-ability-icon-img,
.content-viewer-item.selected .cv-stat-icon-img {
    filter: none;
    opacity: 1;
}
.content-viewer-detail {
    padding: 4px 4px 4px 8px;
    min-width: 0;
    min-height: 0;
    height: 100%;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary, #808080) var(--color-background, #0a0a0a);
}
.content-viewer-detail::-webkit-scrollbar {
    width: 8px;
}
.content-viewer-detail::-webkit-scrollbar-track {
    background: var(--color-background, #0a0a0a);
}
.content-viewer-detail::-webkit-scrollbar-thumb {
    background: var(--color-primary, #808080);
    border: var(--ui-border-width) solid var(--color-background, #0a0a0a);
}
.content-viewer-name {
    margin: 0 0 8px;
    letter-spacing: 0.12em;
    font-size: var(--font-h1);
    color: var(--color-text-secondary, #f0b050);
}
.content-viewer-desc {
    margin: 0 0 16px;
    opacity: 0.85;
    line-height: 1.4;
}
.fv-lore-block {
    margin-top: 8px;
    padding-top: 4px;
}
.fv-fleet-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 8px;
}
.fv-fleet-chip {
    font-size: var(--font-h2);
    padding: 8px 12px;
    letter-spacing: 0.06em;
}
.fv-lore-text {
    margin: 0;
    max-width: 42em;
    white-space: pre-wrap;
}
.fv-viewer .content-viewer-body.has-preview {
    grid-template-columns: var(--cv-left-w, 280px) 8px minmax(0, 1fr) 8px var(--cv-right-w, 260px);
}
.fv-viewer .content-viewer-item {
    font-size: var(--font-h2);
    padding: 10px 12px;
    gap: 12px;
    position: relative;
    color: color-mix(in srgb, var(--faction-accent) 82%, var(--color-text, #e8a040));
    border-left-color: color-mix(in srgb, var(--faction-accent) 45%, transparent);
}
.fv-viewer .content-viewer-item:hover,
.fv-viewer .content-viewer-item.selected {
    color: var(--faction-accent);
    border-color: color-mix(in srgb, var(--faction-accent) 76%, transparent);
    border-left-color: var(--faction-accent);
    border-right-color: var(--faction-accent);
}
.fv-viewer .content-viewer-item::before {
    content: '';
    width: 3px;
    align-self: stretch;
    background: var(--faction-accent);
    box-shadow: 4px 0 0 color-mix(in srgb, var(--faction-accent) 28%, transparent);
}
.fv-viewer .content-viewer-item.selected::before {
    box-shadow: 4px 0 0 color-mix(in srgb, var(--faction-accent) 55%, transparent);
}
.fv-viewer .cv-item-label {
    font-size: var(--font-h2);
    letter-spacing: 0.1em;
}
.fv-viewer .cv-list-ability-icon {
    width: 40px;
    height: 40px;
    font-size: 40px;
}
.fv-viewer .cv-list-ability-icon .cv-ability-icon-img {
    width: 32px;
    height: 32px;
}
.fv-viewer .cv-faction-emblem {
    position: relative;
    padding: 3px;
    box-sizing: border-box;
    border: var(--ui-border-width, 2px) solid var(--faction-accent);
    background: color-mix(in srgb, var(--faction-accent) 14%, #05060a);
    box-shadow: inset 0 0 0 2px #05060a, 0 0 0 2px color-mix(in srgb, var(--faction-accent) 30%, transparent);
}
.fv-viewer .cv-faction-emblem::before,
.fv-viewer .cv-faction-emblem::after {
    content: '';
    position: absolute;
    width: 5px;
    height: 5px;
    background: var(--faction-accent);
}
.fv-viewer .cv-faction-emblem::before { top: -2px; left: -2px; }
.fv-viewer .cv-faction-emblem::after { right: -2px; bottom: -2px; }
.fv-viewer .cv-faction-emblem .cv-ability-icon-img {
    width: 100%;
    height: 100%;
}
.fv-viewer .fv-faction-hero .content-viewer-name {
    color: var(--faction-accent);
}
.fv-viewer .cv-ability-hero-icon {
    width: 64px;
    height: 64px;
    font-size: 64px;
}
.fv-viewer .cv-ability-hero-icon .cv-ability-icon-img {
    width: 64px;
    height: 64px;
}
.fv-viewer .content-viewer-name {
    font-size: calc(var(--font-h1) + 4px);
}
.fv-viewer .content-viewer-desc,
.fv-viewer .fv-lore-text {
    font-size: var(--font-h2);
    line-height: 1.5;
}
.fv-viewer .cv-stat-cluster-title {
    font-size: var(--font-h2);
    margin-bottom: 6px;
    padding-bottom: 6px;
}
.fv-viewer .content-viewer-stats .stat-row {
    padding: 8px 0;
}
.fv-viewer .content-viewer-stats .stat-label,
.fv-viewer .content-viewer-stats .stat-value {
    font-size: var(--font-h2);
}
.content-viewer-stats .stat-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 16px;
    padding: 5px 0;
    margin: 0;
    background: transparent;
    border: none;
    border-bottom: none;
}
.content-viewer-stats .stat-label {
    opacity: 0.75;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.content-viewer-stats .stat-value {
    font-weight: bold;
    text-align: right;
}
.stat-row-abilities {
    align-items: flex-start;
}
.cv-ability-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    justify-content: flex-end;
    max-width: 70%;
    font-weight: normal;
}
.cv-ability-chip {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 6px;
    border: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
    background: rgba(0, 0, 0, 0.35);
    font-size: var(--font-text);
    letter-spacing: 0.04em;
    white-space: nowrap;
}
.cv-ability-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    line-height: 1;
}
.cv-list-ability-icon {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    font-size: var(--font-h1);
}
.cv-list-group {
    font-size: var(--font-text);
    letter-spacing: 0.14em;
    color: var(--color-primary, #e07028);
    opacity: 0.85;
    padding: 10px 4px 4px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
    margin-top: 4px;
}
.cv-ability-hero-icon {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--font-h1);
    border: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    background: rgba(0, 0, 0, 0.35);
    flex-shrink: 0;
    box-sizing: content-box;
}
.ae-body-single {
    grid-template-columns: 1fr !important;
}
.ae-preview {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    padding: 10px;
    border: var(--ui-border-width) solid var(--ui-border, #4a3820);
    background: var(--ui-surface, #12100c);
}
.ae-preview-icon {
    font-size: var(--font-h1);
    line-height: 1;
}
.ae-preview-name {
    font-size: var(--font-h2);
    letter-spacing: 0.1em;
    color: var(--color-primary, #e07028);
    font-weight: bold;
}
.content-viewer-footer {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 18px;
    padding-top: 12px;
    border-top: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    flex-shrink: 0;
    flex-wrap: wrap;
    align-items: center;
}
.cv-dev-actions {
    display: flex;
    gap: 8px;
    margin-right: auto;
    flex-wrap: wrap;
}
.cv-dev-btn {
    letter-spacing: 0.06em;
    display: inline-flex;
    align-items: center;
}
.cv-dev-badges {
    display: inline-flex;
    gap: 4px;
    margin-left: 6px;
    vertical-align: middle;
}
.cv-dev-badge {
    font-size: var(--font-text);
    letter-spacing: 0.08em;
    padding: 1px 5px;
    border: var(--ui-border-width, 2px) solid var(--ui-border, #3a2a18);
    opacity: 0.55;
}
.cv-dev-badge.on {
    opacity: 1;
    color: var(--color-primary, #e07028);
    border-color: var(--color-primary, #e07028);
}
.content-viewer-hint {
    margin-top: 10px;
    text-align: center;
    font-size: var(--font-text);
    opacity: 0.65;
    letter-spacing: 0.06em;
    flex-shrink: 0;
    line-height: 1.45;
}
.cv-hint-row {
    display: block;
}
.cv-hint-dev {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 6px 14px;
    margin-top: 6px;
    opacity: 1;
    font-size: var(--font-text);
    letter-spacing: 0.04em;
}
.cv-hint-dev-label {
    color: var(--color-primary, #e07028);
    font-weight: bold;
    letter-spacing: 0.1em;
    margin-right: 4px;
}
.cv-hint-dev kbd,
.cv-dev-btn kbd {
    display: inline-block;
    min-width: 1.1em;
    padding: 0 4px;
    margin-right: 4px;
    border: var(--ui-border-width) solid currentColor;
    font-family: inherit;
    font-size: var(--font-text);
    letter-spacing: 0.06em;
    opacity: 0.9;
}
@media (max-width: 900px) {
    .content-viewer-body.has-preview {
        grid-template-columns: var(--cv-left-w, 180px) 8px minmax(0, 1fr);
        grid-template-rows: minmax(0, 1fr) auto;
        overflow: auto;
    }
    .content-viewer-body.has-preview .pe-resize-handle[data-resize="right"],
    .content-viewer-body.has-preview .content-viewer-preview {
        grid-column: 1 / -1;
    }
    .content-viewer-body.has-preview .pe-resize-handle[data-resize="right"] {
        display: none;
    }
    .content-viewer-preview {
        border-top: var(--ui-border-width) solid var(--ui-border, #3a2a18);
        padding-left: 0;
        padding-top: 12px;
        height: auto;
    }
}
@media (max-width: 560px) {
    .content-viewer-body,
    .content-viewer-body.has-preview {
        grid-template-columns: 1fr;
        overflow: auto;
    }
    .content-viewer-body .pe-resize-handle {
        display: none;
    }
    .content-viewer-list {
        border-bottom: var(--ui-border-width) solid var(--ui-border, #3a2a18);
        padding-right: 0;
        padding-bottom: 10px;
        max-height: calc(30 * var(--sv-h));
        height: auto;
        flex-direction: row;
        flex-wrap: wrap;
    }
    .content-viewer-detail {
        height: auto;
    }
    .content-viewer-preview {
        grid-column: auto;
    }
}

/* Viewer icons + galaxy systems */
.content-viewer-item {
    display: flex;
    align-items: center;
    gap: 10px;
}
.cv-icon {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
.cv-planet-icon svg {
    display: block;
    width: 32px;
    height: 32px;
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges;
    image-rendering: crisp-edges;
    shape-rendering: crispEdges;
}
.cv-planet-fallback {
    display: inline-block;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #999, #555 70%, #333);
    border: var(--ui-border-width-thin) solid var(--ui-border, #c47a2a);
}
.cv-planet-fallback[data-planet="mars"] { background: radial-gradient(circle at 30% 30%, #a66, #633 70%, #311); }
.cv-planet-fallback[data-planet="jupiter"] { background: radial-gradient(circle at 30% 30%, #b98, #765 70%, #432); }
.cv-planet-fallback[data-planet="saturn"] { background: radial-gradient(circle at 30% 30%, #ba8, #876 70%, #543); }
.cv-planet-fallback[data-planet="neptune"] { background: radial-gradient(circle at 30% 30%, #68a, #356 70%, #123); }
.cv-planet-fallback[data-planet="pluto"] { background: radial-gradient(circle at 30% 30%, #bbb, #777 70%, #444); }
.cv-ship-icon {
    width: 32px;
    height: 32px;
    background: transparent;
    image-rendering: pixelated;
}
.cv-item-label {
    letter-spacing: 0.08em;
}
.cv-system-group {
    margin-bottom: 12px;
}
.cv-system-label {
    font-size: var(--font-text);
    letter-spacing: 0.14em;
    opacity: 0.7;
    padding: 4px 6px 6px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
    margin-bottom: 6px;
}
.cv-system-empty {
    opacity: 0.4;
    padding: 4px 8px;
}
.content-viewer-hero {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
}
.content-viewer-hero .cv-planet-icon svg {
    width: 48px;
    height: 48px;
    image-rendering: pixelated;
    image-rendering: -moz-crisp-edges;
    image-rendering: crisp-edges;
    shape-rendering: crispEdges;
}
.cv-ship-hero {
    align-items: flex-start;
    gap: 18px;
    margin-bottom: 18px;
    padding-bottom: 14px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
}
.cv-ship-hero-text {
    min-width: 0;
    flex: 1;
    padding-top: 4px;
}
.cv-ship-hero .content-viewer-desc {
    margin-bottom: 0;
}
.cv-ship-preview {
    width: 64px;
    height: 64px;
    background: rgba(0, 0, 0, 0.35);
    border: var(--ui-border-width) solid var(--ui-border, #3a2a18);
    image-rendering: pixelated;
    flex-shrink: 0;
    box-sizing: content-box;
}
.cv-stat-clusters {
    display: flex;
    flex-direction: column;
    gap: 14px;
}
.cv-stat-cluster {
    border: none;
    background: transparent;
    padding: 0;
}
.cv-stat-cluster-title {
    font-size: var(--font-text);
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--color-primary, #e07028);
    opacity: 0.9;
    margin-bottom: 2px;
    padding-bottom: 4px;
    border-bottom: var(--ui-border-width-thin) solid var(--ui-border, #3a2a18);
}
.cv-stat-cluster .stat-row:last-child {
    border-bottom: none;
}
.cv-stat-clusters-plain .cv-stat-cluster + .cv-stat-cluster {
    margin-top: 2px;
}
.cv-stat-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    margin-right: 8px;
    vertical-align: middle;
}
.cv-stat-icon-img {
    display: block;
    width: 16px;
    height: 16px;
    image-rendering: pixelated;
}
.content-viewer-stats .stat-label {
    display: inline-flex;
    align-items: center;
}
.cv-systems-row,
.cv-stages-block {
    margin: 12px 0;
}
.cv-systems-title {
    font-size: var(--font-text);
    letter-spacing: 0.14em;
    opacity: 0.7;
    margin-bottom: 8px;
}
.cv-systems-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}
.cv-system-chip {
    border: var(--ui-border-width-thin) solid var(--ui-border, #c47a2a);
    padding: 4px 8px;
    font-size: var(--font-text);
    letter-spacing: 0.06em;
    opacity: 0.75;
}
.cv-system-chip.active {
    background: var(--color-primary, #c47a2a);
    color: var(--color-background, #1a1208);
    opacity: 1;
}
.ship-belt-item {
    flex-direction: column;
    gap: 6px;
}
.ship-belt-label {
    font-size: var(--font-text);
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--color-text, #e8a040);
    max-width: 80px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.ship-belt-item.selected .ship-belt-label {
    color: var(--color-background, #1a1208);
    font-weight: bold;
}

/* Settings panel — clustered two-column */
.settings-panel {
    width: 100%;
    max-width: 100%;
    flex: 1 1 auto;
    min-height: 0;
    max-height: none;
    overflow-y: auto;
    overflow-x: hidden;
    margin: 0;
    padding: clamp(2px, calc(0.4 * var(--sv-h)), 6px) 0;
    text-align: left;
    box-sizing: border-box;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary) transparent;
}

.settings-panel-clustered {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr);
    gap: clamp(8px, calc(1.6 * var(--sv-w)), 20px);
    align-items: start;
}

.settings-cluster {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: clamp(8px, calc(1.2 * var(--sv-h)), 14px);
}

