}

.settings-section-list {
    display: flex;
    flex-direction: column;
    gap: clamp(2px, calc(0.5 * var(--sv-h)), 6px);
    min-width: 0;
}

/* STYLE section: settings rows left, live ship-render preview on the right. */
.settings-style-body {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: clamp(10px, calc(1.6 * var(--sv-w)), 20px);
    align-items: start;
    min-width: 0;
}
.settings-ship-render-preview {
    display: flex;
