    padding: clamp(3px, calc(0.6 * var(--sv-h)), 6px) clamp(2px, calc(0.8 * var(--sv-w)), 8px) !important;
    text-align: left !important;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
}

.settings-row-theme,
.settings-row-volume {
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: clamp(3px, calc(0.6 * var(--sv-h)), 6px);
}

.settings-second-base-controls {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.settings-second-base-swatch {
