/* In-game color picker overlay (replaces native system picker) */
.vf-color-picker {
    position: fixed;
    z-index: 10050;
    width: 220px;
    padding: 10px;
    box-sizing: border-box;
    background: color-mix(in srgb, var(--color-primary, #c44) 6%, rgba(6, 4, 8, 0.96));
    border: var(--ui-border-width-thin, 2px) solid var(--color-primary, #c44);
    box-shadow: 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary, #c44) 35%, transparent), 0 12px 28px rgba(0, 0, 0, 0.65);
    font-family: var(--ui-font-family, ui-monospace, monospace);
    color: var(--color-text-primary, #9ec8e8);
    user-select: none;
}

.vf-cp-sv {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 0.72;
    border: var(--ui-border-width-thin, 2px) solid var(--color-primary, #c44);
    cursor: crosshair;
    overflow: hidden;
    background: #f00;
}

.vf-cp-sv-white,
.vf-cp-sv-black {
    position: absolute;
    inset: 0;
    pointer-events: none;
}

.vf-cp-sv-white {
    background: linear-gradient(to right, #fff, transparent);
}

.vf-cp-sv-black {
    background: linear-gradient(to top, #000, transparent);
}

.vf-cp-cursor {
    position: absolute;
    width: 12px;
    height: 12px;
    margin: -6px 0 0 -6px;
    border: var(--ui-border-width) solid #fff;
    border-radius: 50%;
    box-shadow: 0 0 0 var(--ui-border-width) #000, 0 0 6px rgba(0, 0, 0, 0.8);
    pointer-events: none;
}

.vf-cp-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 10px;
}

.vf-cp-preview {
    width: 28px;
    height: 28px;
    flex: 0 0 auto;
    border: var(--ui-border-width-thin, 2px) solid var(--color-primary, #c44);
    border-radius: 50%;
    box-shadow: inset 0 0 0 var(--ui-border-width) rgba(0, 0, 0, 0.45);
}

.vf-cp-hue {
    position: relative;
    flex: 1 1 auto;
    height: 14px;
    border: var(--ui-border-width-thin, 2px) solid var(--color-primary, #c44);
    cursor: pointer;
    background: linear-gradient(
        to right,
        #ff0000 0%,
        #ffff00 17%,
        #00ff00 33%,
        #00ffff 50%,
        #0000ff 67%,
        #ff00ff 83%,
        #ff0000 100%
    );
}

.vf-cp-hue-thumb {
    position: absolute;
    top: 50%;
    width: 12px;
    height: 12px;
    margin: -6px 0 0 -6px;
    border: var(--ui-border-width) solid #fff;
    border-radius: 50%;
    box-shadow: 0 0 0 var(--ui-border-width) #000;
    background: transparent;
    pointer-events: none;
}

.vf-cp-rgb {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 6px;
    margin-top: 10px;
}

.vf-cp-channel {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 3px;
    margin: 0;
    font-size: var(--font-text, 11px);
    letter-spacing: 0.08em;
    color: var(--color-text-secondary, var(--color-primary, #c44));
}

.vf-cp-channel span {
    text-align: center;
    opacity: 0.9;
}

.vf-cp-channel input,
.vf-cp-hex {
    width: 100%;
    box-sizing: border-box;
    background: rgba(0, 0, 0, 0.55);
    color: var(--color-text-primary, #9ec8e8);
    border: var(--ui-border-width-thin, 2px) solid var(--color-primary, #c44);
    padding: 4px 2px;
    text-align: center;
    font-family: inherit;
    font-size: var(--font-text, 11px);
    letter-spacing: 0.04em;
    outline: none;
}

.vf-cp-channel input:focus,
.vf-cp-hex:focus {
    border-color: var(--color-text-primary, #9ec8e8);
    box-shadow: 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--color-primary, #c44) 50%, transparent);
}

.vf-cp-channel input::-webkit-outer-spin-button,
.vf-cp-channel input::-webkit-inner-spin-button {
    -webkit-appearance: none;
    margin: 0;
}

.vf-cp-channel input[type="number"] {
