    gap: 8px;
    margin-top: 8px;
}

.vf-cp-hex-label {
    flex: 0 0 auto;
    font-size: var(--font-text, 11px);
    letter-spacing: 0.12em;
    color: var(--color-primary, #c44);
}

.vf-cp-hex {
    flex: 1 1 auto;
    text-align: left;
    padding-left: 6px;
    text-transform: uppercase;
}

.settings-row-youtube {
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
}

.settings-youtube-input {
    width: 100%;
