}

.settings-sound-code-status,
.ss-code-hint {
    font-size: calc(var(--font-text) * 0.85);
    opacity: 0.75;
    letter-spacing: 0.04em;
    margin: 0;
}

.settings-row-action .settings-row-value {
    letter-spacing: 0.06em;
    opacity: 0.9;
}

.settings-asset-status.settings-asset-ready {
    color: var(--color-success, #6ecf6e);
}

.settings-asset-status.settings-asset-warn {
    color: var(--color-warning, #d4a84a);
}

.settings-asset-status.settings-asset-off {
    color: var(--color-error, #c06060);
    opacity: 0.9;
}

.setting-item-assets .toggle-button {
    min-width: 8.5em;
}

.settings-theme-head {
    display: flex;
    align-items: baseline;
