}


/* --- css/styles/part-06.css --- */
.settings-look-slider {
    flex: 1 1 auto;
    min-width: 64px;
    height: clamp(10px, calc(1.5 * var(--sv-h)), 14px);
    margin: 0;
    border: var(--ui-border-width-thin) solid var(--color-border, var(--color-primary));
    border-radius: 0;
    outline: none;
    cursor: pointer;
    -webkit-appearance: none;
