    background: linear-gradient(
        to right,
        var(--color-primary) 0%,
        var(--color-primary) var(--look-fill, 0%),
        color-mix(in srgb, var(--color-primary) 12%, var(--color-background)) var(--look-fill, 0%),
        color-mix(in srgb, var(--color-primary) 12%, var(--color-background)) 100%
    );
}

.settings-look-slider::-webkit-slider-runnable-track {
    height: clamp(10px, calc(1.5 * var(--sv-h)), 14px);
    background: transparent;
    border: none;
}

.settings-look-slider::-moz-range-track {
    height: clamp(10px, calc(1.5 * var(--sv-h)), 14px);
    background: transparent;
    border: none;
}

.settings-look-slider::-moz-range-progress {
    height: clamp(10px, calc(1.5 * var(--sv-h)), 14px);
