    background: var(--color-text, #fff);
    border: var(--ui-border-width-thin) solid var(--color-primary);
    border-radius: 0;
    cursor: pointer;
    box-shadow: none;
}

.settings-look-slider::-moz-range-thumb {
    width: clamp(10px, calc(1.6 * var(--sv-w)), 14px);
    height: clamp(14px, calc(2.2 * var(--sv-h)), 18px);
    background: var(--color-text, #fff);
    border: var(--ui-border-width-thin) solid var(--color-primary);
    border-radius: 0;
    cursor: pointer;
}

.settings-row-look .settings-row-value {
    min-width: clamp(40px, calc(9 * var(--sv-w)), 56px);
    text-align: right;
}

.settings-row-value {
    min-width: clamp(48px, calc(12 * var(--sv-w)), 84px);
