    color: var(--color-primary);
    font-weight: bold;
    font-size: var(--font-text);
}

.settings-cycle-btn {
    width: clamp(22px, calc(4 * var(--sv-w)), 26px);
    height: clamp(22px, calc(4 * var(--sv-w)), 26px);
    border: var(--ui-border-width-thin) solid var(--color-border, var(--color-primary));
    background: color-mix(in srgb, var(--color-primary) 8%, var(--color-surface, #111));
    color: var(--color-primary);
    font-family: inherit;
    font-size: var(--font-h2);
    line-height: 1;
    cursor: pointer;
    padding: 0;
    flex-shrink: 0;
}

.settings-cycle-btn:hover {
    background: var(--color-primary);
    color: var(--color-background);
}

.theme-dropdown-toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    margin: 0;
    padding: 6px 8px;
    border: var(--ui-border-width-thin) solid var(--color-border, var(--color-primary));
