    text-align: left;
    box-sizing: border-box;
}
.theme-dropdown-toggle:hover {
    border-color: color-mix(in srgb, var(--color-primary) 55%, transparent);
}
.settings-row-theme.is-open .theme-dropdown-toggle {
    border-color: var(--color-primary);
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--color-primary);
}
.theme-dropdown-caret {
    flex: 0 0 auto;
    opacity: 0.7;
    transition: transform 0.15s ease;
}
.settings-row-theme.is-open .theme-dropdown-caret {
    transform: rotate(180deg);
}
.theme-dropdown-panel {
    display: none;
    width: 100%;
    margin-top: 4px;
}
.settings-row-theme.is-open .theme-dropdown-panel {
    display: block;
}

.theme-list {
    display: flex;
    flex-direction: column;
    gap: 3px;
    width: 100%;
    max-height: min(calc(42 * var(--ch)), calc(280px * var(--zk)));
    overflow-y: auto;
    overflow-x: hidden;
    padding: 4px;
    border: var(--ui-border-width) solid var(--color-border, var(--color-primary));
