    box-sizing: border-box;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary) transparent;
}

.theme-list-item {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    margin: 0;
    padding: 4px 6px;
    border: var(--ui-border-width-thin) solid transparent;
    background: color-mix(in srgb, var(--color-primary) 4%, transparent);
    color: var(--color-text);
    font-family: inherit;
    font-size: var(--font-text);
    font-weight: bold;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    text-align: left;
    box-sizing: border-box;
}

.theme-list-item:hover {
    border-color: color-mix(in srgb, var(--color-primary) 55%, transparent);
    background: color-mix(in srgb, var(--color-primary) 12%, transparent);
}

.theme-list-item.active {
    border-color: var(--color-primary);
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--color-primary), 0 0 0 2px color-mix(in srgb, color-mix(in srgb, var(--color-primary) 35%, transparent) 72%, transparent), 0 0 0 4px color-mix(in srgb, color-mix(in srgb, var(--color-primary) 35%, transparent) 48%, transparent), 0 0 0 8px color-mix(in srgb, color-mix(in srgb, var(--color-primary) 35%, transparent) 30%, transparent), 0 0 0 10px color-mix(in srgb, color-mix(in srgb, var(--color-primary) 35%, transparent) 16%, transparent);
    background: color-mix(in srgb, var(--color-primary) 18%, transparent);
}

.theme-list-swatch {
    flex: 0 0 auto;
    width: 14px;
    height: 14px;
    border: var(--ui-border-width) solid var(--color-border, #000);
    box-shadow: inset 0 0 0 var(--ui-border-width) rgba(255, 255, 255, 0.15);
}

.theme-list-name {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* legacy horizontal strip kept for safety */
.theme-strip-wrap {
    display: none;
}

.theme-edit-btn {
    display: block;
    width: 100%;
    max-width: 100%;
    margin: 2px 0 0;
    padding: clamp(4px, calc(0.8 * var(--sv-h)), 7px) clamp(8px, calc(1.5 * var(--sv-w)), 12px);
    border: var(--ui-border-width) solid var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 10%, transparent);
    color: var(--color-primary);
    font-family: inherit;
    font-size: var(--font-text);
    letter-spacing: 0.12em;
    cursor: pointer;
    text-transform: uppercase;
    box-sizing: border-box;
}
.theme-edit-btn:hover {
    background: var(--color-primary);
    color: var(--color-background);
}

.settings-panel .volume-controls {
    padding: clamp(4px, calc(0.8 * var(--sv-w)), 8px);
    gap: clamp(3px, calc(0.5 * var(--sv-h)), 6px);
}

.settings-panel .volume-control {
    gap: 6px;
}

.settings-panel .volume-control label {
    min-width: 56px;
    font-size: var(--font-text);
}

@media (max-width: 720px) {
    .settings-panel-clustered {
        grid-template-columns: 1fr;
        gap: clamp(8px, calc(1.4 * var(--sv-h)), 14px);
    }

