    }

    .settings-row-controls {
        width: 100%;
        justify-content: flex-end;
        margin-left: 0;
    }

    .volume-control label {
        min-width: 52px;
        max-width: none;
    }
}

/* Theme Editor overlay */
.theme-editor-overlay {
