/* Combat event announce banner */
.vf-event-announce {
    position: fixed;
    top: 18%;
    left: 50%;
    transform: translateX(-50%);
    z-index: 10000;
    padding: 10px 18px;
    background: rgba(0, 0, 0, 0.82);
    color: #e8c060;
    font-family: monospace;
    font-size: var(--font-text);
    letter-spacing: 0.08em;
    pointer-events: none;
    border: var(--ui-border-width) solid #e8c060;
    text-transform: uppercase;
    opacity: 0;
    transition: opacity 0.2s ease;
}
.vf-event-announce-pulse {
    animation: vf-event-announce-pulse 0.7s ease-in-out infinite alternate;
}
@keyframes vf-event-announce-pulse {
    from { box-shadow: 0 0 0 0 rgba(232, 192, 96, 0.15); }
    to { box-shadow: 0 0 0 calc(2px + 4px) color-mix(in srgb, rgba(232, 192, 96, 0.35) 72%, transparent), 0 0 0 calc(2px + 8px) color-mix(in srgb, rgba(232, 192, 96, 0.35) 48%, transparent), 0 0 0 calc(2px + 12px) color-mix(in srgb, rgba(232, 192, 96, 0.35) 30%, transparent), 0 0 0 calc(2px + 16px) color-mix(in srgb, rgba(232, 192, 96, 0.35) 16%, transparent); }
}

.cv-event-swatch {
    display: inline-block;
    width: 12px;
    height: 12px;
    margin-right: 8px;
    border: var(--ui-border-width) solid rgba(255, 255, 255, 0.35);
    vertical-align: middle;
    flex-shrink: 0;
}
.cv-event-hero-swatch {
    width: 48px;
    height: 48px;
    border: var(--ui-border-width) solid rgba(255, 255, 255, 0.35);
    flex-shrink: 0;
}

/* ——— Component Editor (station tab + overlay) ——— */
.hs-body-components {
    display: flex;
    flex-direction: column;
    min-height: 0;
    flex: 1;
}
.hs-components-root {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    height: 100%;
}
.hs-components-host {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    position: relative;
    z-index: 1000;
}
.hs-components-host select,
.hs-components-host input[type="select"] {
    pointer-events: auto !important;
}
.hs-comp-layout {
    display: grid;
    grid-template-columns: minmax(160px, 220px) minmax(200px, 1fr) minmax(240px, 300px);
    grid-template-rows: auto 1fr;
    gap: 10px;
    flex: 1;
    min-height: 0;
    height: 100%;
    padding: 4px 0 8px;
    box-sizing: border-box;
    transition: grid-template-columns 0.15s ease;
    position: relative;
    z-index: 1000;
}
.hs-comp-topbar {
    grid-column: 1 / -1;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 8px 6px;
    border-bottom: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary, #808080) 35%, transparent);
}
.hs-comp-topbar .hs-comp-type-chips {
    flex: 1 1 auto;
    margin-bottom: 0;
}
.hs-comp-layout.left-collapsed {
    grid-template-columns: 32px minmax(200px, 1fr) minmax(240px, 300px);
}
.hs-comp-layout.right-collapsed {
    grid-template-columns: minmax(160px, 220px) minmax(200px, 1fr) 32px;
}
.hs-comp-layout.left-collapsed.right-collapsed {
    grid-template-columns: 32px minmax(200px, 1fr) 32px;
}
.hs-comp-sidebar,
.hs-comp-center {
    display: flex;
    flex-direction: column;
    min-height: 0;
    background: rgba(0, 0, 0, 0.28);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary, #808080) 45%, transparent);
    padding: 8px;
    box-sizing: border-box;
    overflow: auto;
    position: relative;
}
.hs-comp-sidebar.is-collapsed {
    padding: 6px 2px;
    align-items: center;
    cursor: pointer;
    user-select: none;
    background: rgba(0, 0, 0, 0.45);
}
.hs-comp-sidebar.is-collapsed:hover {
    border-color: var(--color-primary, #e07028);
    background: rgba(0, 0, 0, 0.6);
}
.hs-comp-sidebar-content {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    min-width: 0;
}
.hs-comp-right-col .hs-comp-sidebar-content {
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary, #808080) var(--color-background, #0a0a0a);
    padding-right: 2px;
}
.hs-comp-right-col .hs-comp-sidebar-content::-webkit-scrollbar {
    width: 8px;
}
.hs-comp-right-col .hs-comp-sidebar-content::-webkit-scrollbar-track {
    background: var(--color-background, #0a0a0a);
}
.hs-comp-right-col .hs-comp-sidebar-content::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--color-primary, #808080) 40%, #333);
    border: var(--ui-border-width) solid var(--color-border, #333);
}
.hs-comp-sidebar.is-collapsed .hs-comp-sidebar-content {
    display: none;
}
.hs-comp-collapsed-strip {
    display: none;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    height: 100%;
    width: 100%;
}
.hs-comp-sidebar.is-collapsed .hs-comp-collapsed-strip {
    display: flex;
}
.hs-comp-toggle-btn {
    padding: 2px 6px !important;
    font-size: var(--font-small) !important;
    line-height: 12px;
    min-width: 20px;
    height: 20px;
