    color: #c8c8c8;
    cursor: pointer;
}
.hs-comp-chip.active {
    border-color: var(--color-primary, #a0a0a0);
    color: #fff;
    background: color-mix(in srgb, var(--color-primary, #808080) 25%, rgba(0, 0, 0, 0.5));
}
.hs-comp-list {
    flex: 1;
    min-height: 0;
    overflow: auto;
    display: flex;
    flex-direction: column;
