/* ==========================================================================
   Faction identity — shared shape + surface language
   The document root carries data-faction (factionShipStyles.applyDocumentFactionTheme),
   so the in-game HUD, the station chrome and the menus all reskin from one
   source. Each faction gets its own frame geometry, not just its own colour.
   ========================================================================== */
:root {
    --faction-accent: var(--color-primary);
    --faction-hull: var(--color-primary);
    /* Frame geometry, overridden per faction below. */
    --faction-clip: none;
    --faction-radius: 0;
    --faction-border-width: var(--ui-border-width);
    --faction-surface: none;
    --faction-surface-opacity: 0.16;
}

/* --- In-game HUD panels wear the faction frame ------------------------- */
.game-info-panel,
.player-vitals-side,
.game-left-cluster .weapon-selection,
.game-right-cluster .enemy-vitals-side {
    position: relative;
    clip-path: var(--faction-clip);
    border-radius: var(--faction-radius);
    border-width: var(--faction-border-width);
    border-color: color-mix(in srgb, var(--faction-accent) 60%, var(--color-primary));
}
/* Faction HUD --faction-clip (per-faction gui.css): voidborn top-left stair is 28px,
   kronax 24px. part-16's 5-6px padding left titles shaved. */
html[data-faction] .game-info-panel,
html[data-faction] .player-vitals-side,
html[data-faction] .game-left-cluster .weapon-selection,
html[data-faction] .game-right-cluster .enemy-vitals-side {
    padding-left: 32px !important;
    padding-right: 32px !important;
}

.game-info-panel::after,
.player-vitals-side::after,
.game-left-cluster .weapon-selection::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: var(--faction-surface);
    /* Keep plating quiet so HUD labels stay readable. */
    opacity: calc(var(--faction-surface-opacity, 0.16) * 0.35);
}

/* The HUD's own accents follow the faction, not just the theme primary. */
.player-vitals-side .health-fill::before,
.game-info-panel .gi-diff {
    border-color: color-mix(in srgb, var(--faction-accent) 55%, var(--color-primary));
}

