.hs-hangar-stats.is-row .hs-stat-group .hs-hangar-stat {
    flex: 0 0 auto;
    min-width: 0;
    border: none;
    background: none;
    box-shadow: none;
    padding: 3px 8px 3px 4px;
}
.hs-hangar-stats.is-row .hs-stat-group .hs-hangar-stat::before,
.hs-hangar-stats.is-row .hs-stat-group .hs-hangar-stat::after { content: none; }
.hs-hangar-stats.is-row .hs-hangar-stat.is-slot.is-full .hs-stat-value { color: var(--color-text-secondary); }
/* Stats row: one line, tiles share the width but never shrink below their content. */
.hs-hangar-stats.is-row .hs-hangar-stat {
    flex: 1 1 0;
    min-width: max-content;
    padding: 3px 12px 3px 3px;
    gap: 10px;
}
.hs-hangar-stats.is-row .hs-stat-detail { display: none; }
.hs-stat-chip[style*="--kind-color"] { color: var(--kind-color); }
/* Stats row icons: bare, no box behind them. */
.hs-hangar-stats.is-row .hs-stat-icon {
    background: none;
    border: none;
    padding: 0;
}
/* Label lives in the icon tooltip; value in the plain UI font (the
   Silkscreen pixel font smears below its native size). */
.hs-hangar-stats.is-row .hs-hangar-stat em { display: none; }
.hs-hangar-stats.is-row .hs-stat-value {
    font-family: var(--ui-font-family, monospace);
    font-size: var(--font-h2);
    line-height: 1;
    font-weight: bold;
    letter-spacing: 1px;
    color: var(--color-text);
}
.hs-hangar-stats.is-row .hs-stat-of,
.hs-hangar-stats.is-row .hs-stat-x { font-size: var(--font-text); }
/* Voxel slider in the hangar title bar, left of the sidebar tab buttons. */
.hs-hangar-voxel.is-in-title {
    flex: 0 1 280px;
    grid-template-columns: auto minmax(80px, 1fr) 44px;
    margin-right: 8px;
}
.hs-hangar-voxel input[type="range"] {
    width: 100%;
    min-width: 0;
    accent-color: var(--color-primary);
}
.hs-hangar-voxel output {
    text-align: right;
    color: var(--color-text);
    font-variant-numeric: tabular-nums;
}
.hs-hangar-head-bar .hs-hangar-frame-up {
    flex: 0 1 auto;
    justify-content: flex-end;
}

/* New-profile faction picker: emblems, live faction palette, ship preview. */
.profile-faction-swatch-emblem {
    display: inline-flex;
    flex-shrink: 0;
}
.profile-faction-swatch-emblem img,
.profile-faction-preview-emblem img {
    width: 100%;
    height: 100%;
    image-rendering: pixelated;
}
.profile-faction-preview {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    margin: 4px auto 14px;
    padding: 8px 12px;
    width: min(360px, 92%);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    background:
        radial-gradient(circle at 35% 50%, color-mix(in srgb, var(--color-primary) 16%, transparent), transparent 70%),
        #050508;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.profile-faction-ship {
    width: 150px;
    height: 105px;
    image-rendering: pixelated;
}
.profile-faction-preview-text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    min-width: 0;
    text-align: left;
}
.profile-faction-preview-emblem {
    display: inline-flex;
    width: 32px;
    height: 32px;
}
.profile-faction-preview-name {
    color: var(--color-primary);
    letter-spacing: 2px;
}
.profile-faction-preview-trait {
    color: var(--color-text-secondary);
    font-size: var(--font-text-small, 11px);
    letter-spacing: 1px;
}
.profile-selection-name-mode {
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

/* Faction emblem beside each profile (list + detail header). */
.profile-list-emblem {
    display: inline-flex;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    margin-right: 10px;
}
.profile-list-item .profile-list-name {
    flex: 1 1 auto;
    min-width: 0;
}
.profile-list-emblem img,
.profile-details-emblem img {
    width: 100%;
    height: 100%;
    image-rendering: pixelated;
}
.profile-details-header {
    display: flex;
    align-items: center;
    gap: 12px;
}
.profile-details-emblem {
    display: inline-flex;
    width: 32px;
    height: 32px;
    flex-shrink: 0;
}
.profile-details-title {
    display: flex;
    flex-direction: column;
    line-height: 1.1;
}
.profile-details-title small {
    font-size: var(--font-text-small, 11px);
    font-weight: normal;
    letter-spacing: 2px;
    color: var(--color-text-secondary);
}

/* ——— Faction frame shapes for the profile dialogs ———
   The box itself stays unclipped (so its drop-shadow glow survives); two
   pseudo layers draw the frame: ::before = faction-coloured outline shape,
   ::after = the dark fill inset by the frame width. Each faction defines
   --pf-shape (outer) and --pf-shape-in (inner) so the outline follows the
   same silhouette. Controls inside follow the faction's cut too. */
.profile-selection-content[data-faction] {
    position: relative;
    isolation: isolate;
    border: none;
    background: transparent;
    box-shadow: none;
    filter: drop-shadow(6px 0 0 color-mix(in srgb, color-mix(in srgb, var(--ui-border) 70%, transparent) 55%, transparent)) drop-shadow(-6px 0 0 color-mix(in srgb, color-mix(in srgb, var(--ui-border) 70%, transparent) 55%, transparent)) drop-shadow(0 6px 0 color-mix(in srgb, color-mix(in srgb, var(--ui-border) 70%, transparent) 55%, transparent)) drop-shadow(0 -6px 0 color-mix(in srgb, color-mix(in srgb, var(--ui-border) 70%, transparent) 55%, transparent));
    --pf-frame: 4px;
}
.profile-selection-content[data-faction]::before,
.profile-selection-content[data-faction]::after {
    content: '';
    position: absolute;
    z-index: -1;
    pointer-events: none;
}
.profile-selection-content[data-faction]::before {
    inset: 0;
    background: var(--ui-border);
    clip-path: var(--pf-shape);
    border-radius: var(--pf-radius, 0);
}
.profile-selection-content[data-faction]::after {
    inset: var(--pf-frame);
    background: var(--color-background, #000);
    clip-path: var(--pf-shape-in, var(--pf-shape));
    border-radius: var(--pf-radius-in, 0);
}
/* Controls inherit the faction cut. Outlines drawn as inset shadows so a
   clipped diagonal still shows an edge colour behind it. */
.profile-selection-content[data-faction] .action-button,
.profile-selection-content[data-faction] .profile-faction-swatch,
.profile-selection-content[data-faction] .profile-name-input,
.profile-selection-content[data-faction] .profile-faction-preview,
.profile-selection-content[data-faction] .profile-list,
.profile-selection-content[data-faction] .profile-details {
    clip-path: var(--pf-ctl, none);
    border-radius: var(--pf-ctl-radius, 0);
}
.profile-faction-preview-hero {
    color: var(--color-primary);
    font-size: var(--font-text-small, 11px);
    letter-spacing: 1px;
    opacity: 0.9;
    cursor: help;
}

/* ==========================================================================
   Shared modal dialog (uiDialog) — replaces native confirm/alert/prompt.
   Frame follows the active faction (html[data-faction] --faction-clip),
   drawn as ::before outline + ::after fill so the stepped edge keeps a border.
   ========================================================================== */
.ui-dialog-backdrop {
    position: fixed;
    inset: 0;
    z-index: 100000;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: color-mix(in srgb, #000 62%, transparent);
    image-rendering: pixelated;
}
.ui-dialog {
    position: relative;
    isolation: isolate;
    min-width: min(320px, 100%);
    max-width: min(460px, 100%);
    padding: 22px 24px 18px;
    font-family: var(--ui-font-family);
    color: var(--color-text);
    text-align: center;
    filter: drop-shadow(0 0 14px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent));
}
.ui-dialog::before,
.ui-dialog::after {
    content: '';
    position: absolute;
    z-index: -1;
    pointer-events: none;
    clip-path: var(--faction-clip, none);
}
.ui-dialog::before {
    inset: 0;
    background: var(--faction-accent, var(--color-primary));
}
.ui-dialog::after {
    inset: 3px;
    background:
        var(--faction-surface, none),
        var(--color-background, #000);
    background-blend-mode: normal;
}
.ui-dialog-title {
    margin: 0 0 10px;
    font-size: var(--font-text, 14px);
    letter-spacing: 2px;
    color: var(--faction-accent, var(--color-primary));
}
.ui-dialog-message {
    margin: 0 0 16px;
    font-size: var(--font-text, 14px);
    letter-spacing: 1px;
    line-height: 1.4;
    text-transform: uppercase;
    white-space: pre-wrap;
}
.ui-dialog-input {
    display: block;
    width: 100%;
    box-sizing: border-box;
    margin: 0 0 16px;
    padding: 8px 10px;
    font: inherit;
    letter-spacing: 1px;
    color: var(--color-text);
    background: #000;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
    border-radius: 0;
}
.ui-dialog-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
}
.ui-dialog-actions .action-button {
    min-width: 100px;
    clip-path: polygon(0 4px, 4px 4px, 4px 0, calc(100% - 4px) 0, calc(100% - 4px) 4px, 100% 4px, 100% calc(100% - 4px), calc(100% - 4px) calc(100% - 4px), calc(100% - 4px) 100%, 4px 100%, 4px calc(100% - 4px), 0 calc(100% - 4px));
    border-radius: 0;
}
.ui-dialog-actions .action-button.danger {
    color: #ff8a8a;
    border-color: #ff5a5a;
}

/* ==========================================================================
   Interactables — lighter than the base colour so clickable things read as
   clickable. Mixes the base (primary) with the light 2nd base (which, for the
   faction palette, is the base colour lightened).
   Re-declared on [data-faction] boxes so a locally re-coloured box (profile
   dialog previewing another faction) recomputes instead of inheriting the
   root's already-resolved value.
   ========================================================================== */
:root,
[data-faction] {
    --color-interactive: color-mix(in srgb, var(--color-primary) 45%, var(--color-second-basecolor, #ffffff));
    --color-interactive-border: color-mix(in srgb, var(--color-primary) 60%, var(--color-second-basecolor, #ffffff));
}
.settings-row-value,
.settings-cycle-btn,
.theme-edit-btn,
.hs-connection-step,
.hs-style-carousel-step,
.hs-tree-wing-symmetry,
.hs-floating-panel-link,
.profile-selection-actions .action-button,
.galaxy-selection-actions .action-button,
.galaxy-map-actions .action-button,
.ui-dialog-actions .action-button {
    color: var(--color-interactive);
}
.settings-cycle-btn,
.theme-edit-btn,
.hs-connection-step,
.hs-style-carousel-step,
.hs-tree-wing-symmetry,
.profile-selection-actions .action-button,
.galaxy-selection-actions .action-button,
.galaxy-map-actions .action-button,
.ui-dialog-actions .action-button {
    border-color: var(--color-interactive-border);
}
.settings-cycle-btn:hover,
.theme-edit-btn:hover,
.hs-connection-step:hover,
.hs-style-carousel-step:hover {
    background: var(--color-interactive);
    color: var(--color-background);
}
.volume-slider::-webkit-slider-thumb,
.settings-look-slider::-webkit-slider-thumb,
.hs-floating-area-style input[type="range"]::-webkit-slider-thumb {
    background: var(--color-interactive);
}
.volume-slider::-moz-range-thumb,
.settings-look-slider::-moz-range-thumb,
.hs-floating-area-style input[type="range"]::-moz-range-thumb {
    background: var(--color-interactive);
}

/* Embedded PROFILES tab — pilot list shown directly. */
.hs-menu-profile-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin: 4px 0 14px;
}
.hs-menu-profile-row {
    display: grid;
    /* emblem | name | faction | active badge | actions */
    grid-template-columns: 32px minmax(0, 1fr) auto auto auto;
    align-items: center;
    column-gap: 16px;
    padding: 8px 12px;
    font: inherit;
    font-size: var(--font-text);
    letter-spacing: 1px;
    text-align: left;
    color: var(--color-text);
    background: color-mix(in srgb, var(--row-accent, var(--color-primary)) 8%, transparent);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--row-accent, var(--color-primary)) 45%, transparent);
    clip-path: var(--faction-ctl-clip, none);
}
.hs-menu-profile-row:hover {
    background: color-mix(in srgb, var(--row-accent, var(--color-primary)) 20%, transparent);
}
.hs-menu-profile-row.is-active {
    border-color: var(--row-accent, var(--color-primary));
    background: color-mix(in srgb, var(--row-accent, var(--color-primary)) 18%, transparent);
}
.hs-menu-profile-emblem,
.hs-menu-profile-emblem .ui-icon-tip {
    display: grid;
    place-items: center;
    width: 32px;
    height: 32px;
    line-height: 0;
}
.hs-menu-profile-emblem img {
    display: block;
    image-rendering: pixelated;
    filter: none;
    opacity: 1;
}
.hs-menu-profile-name {
    font-size: var(--font-h2);
    font-weight: bold;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.hs-menu-profile-faction {
    color: var(--row-accent, var(--color-text-secondary));
    font-size: var(--font-text-small, 11px);
    letter-spacing: 2px;
}
.hs-menu-profile-badge {
    padding: 1px 6px;
    font-size: var(--font-text-small, 11px);
    letter-spacing: 1px;
    color: var(--color-background);
    background: var(--row-accent, var(--color-primary));
}

/* ==========================================================================
   Faction frames with a visible stepped outline.
   A plain clip-path only nibbled tiny corners off a 1px, low-contrast border,
   so panels still read as rectangles. Here every framed box gets:
     ::before  accent-coloured slab over the whole box, cut to the faction
               shape → the outline, steps included
     ::after   the box's own fill (background: inherit), inset by the frame
               width and cut to the same shape → the inside
   Independent of the element's own border (some panels zero it).
   Same polygon on both, offset by the border width, gives an exact 2px
   stepped frame along every staircase edge.
   ========================================================================== */
.home-station-overlay :is(.hs-panel, .hs-section):not(.hs-hangar-root, .hs-hangar-bay, .hs-shop-root),
.home-station-overlay .hs-hangar-bay-stage {
    --frame-w: 2px;
    --frame-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 75%, transparent);
    position: relative;
    isolation: isolate;
    border: var(--frame-w) solid transparent;
    box-shadow: none;
}
.home-station-overlay :is(.hs-panel, .hs-section):not(.hs-hangar-root, .hs-hangar-bay, .hs-shop-root)::before,
.home-station-overlay .hs-hangar-bay-stage::before {
    content: '';
    position: absolute;
    inset: 0;
    top: 0;
    left: 0;
    right: 0;
    height: auto;
    z-index: -1;
    opacity: 1;
    pointer-events: none;
    background: var(--frame-color);
    clip-path: var(--faction-panel-clip, none);
}
.home-station-overlay :is(.hs-panel, .hs-section):not(.hs-hangar-root, .hs-hangar-bay, .hs-shop-root, .hs-faction-card) {
    padding-left: 16px;
    padding-right: 16px;
}
.home-station-overlay :is(.hs-panel, .hs-section):not(.hs-hangar-root, .hs-hangar-bay, .hs-shop-root)::after,
.home-station-overlay .hs-hangar-bay-stage::after {
    content: '';
    position: absolute;
    inset: var(--frame-w);
    z-index: -1;
    pointer-events: none;
    background: inherit;
    background-color: var(--color-background, #050508);
    clip-path: var(--faction-panel-clip, none);
}

/* Station buttons & tabs: same frame with the smaller control shape. */
.home-station-overlay :is(.hs-tab, .hs-home-btn, .hs-menu-tab-btn, .hs-menu-btn, .hs-logout-btn,
    .hs-shop-ctrl, .hs-shop-cat, .hs-play, .action-button) {
    --frame-w: 2px;
    --frame-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
    position: relative;
    isolation: isolate;
    border-color: transparent;
    border-width: var(--frame-w);
    border-style: solid;
}
.home-station-overlay :is(.hs-tab, .hs-home-btn, .hs-menu-tab-btn, .hs-menu-btn, .hs-logout-btn,
    .hs-shop-ctrl, .hs-shop-cat, .hs-play, .action-button)::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background: var(--frame-color);
    clip-path: var(--faction-ctl-clip, none);
}
.home-station-overlay :is(.hs-tab, .hs-home-btn, .hs-menu-tab-btn, .hs-menu-btn, .hs-logout-btn,
    .hs-shop-ctrl, .hs-shop-cat, .hs-play, .action-button)::after {
    content: '';
    position: absolute;
    inset: var(--frame-w);
    z-index: -1;
    pointer-events: none;
    background: inherit;
    clip-path: var(--faction-ctl-clip, none);
}
.home-station-overlay :is(.hs-tab, .hs-home-btn, .hs-menu-tab-btn, .hs-menu-btn, .hs-logout-btn,
    .hs-shop-ctrl, .hs-shop-cat, .hs-play, .action-button):is(:hover, .active, .nav-focused) {
    --frame-color: var(--faction-accent, var(--color-primary));
}

/* Logout focus/hover: dark red fill + bright text so it stays readable
   (generic nav-focused fills would otherwise turn it light purple). */
.home-station-overlay .hs-logout-btn:is(:hover, :focus-visible, .nav-focused) {
    --frame-color: #ff5a5a;
    background: color-mix(in srgb, #ff3b3b 22%, var(--color-surface, #0a0a12));
    color: #ffe0e0;
    text-shadow: none;
}
.home-station-overlay .hs-logout-btn.nav-focused {
    outline-color: #ff5a5a;
}

/* Active tabs: faction-colour fill, light outline, black text/icons. */
html .home-station-overlay :is(.hs-menu-tab-btn, .hs-tab, .hs-home-btn).active {
    --frame-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, #fff);
    background: var(--faction-accent, var(--color-primary));
    color: #000;
}
html .home-station-overlay :is(.hs-menu-tab-btn, .hs-tab, .hs-home-btn).active :is(.hs-menu-tab-label, .hs-tab-label, .hs-home-text) {
    color: #000;
    font-family: 'Silkscreen', var(--ui-font-family, monospace);
    font-weight: 700;
    /* Silkscreen is an 8px grid font: whole multiples keep glyphs crisp. */
    font-size: var(--font-h2);
    line-height: 16px;
    letter-spacing: 0;
    -webkit-font-smoothing: none;
    -moz-osx-font-smoothing: unset;
    font-smooth: never;
    text-shadow: none;
}
html .home-station-overlay :is(.hs-menu-tab-btn, .hs-tab, .hs-home-btn).active :is(.hs-menu-tab-icon, .hs-tab-icon, .hs-home-icon) {
    filter: brightness(0);
    opacity: 1;
}

/* Upgrade sub-tabs (ships / modules): scroll the list instead of squashing
   panels; the station tree keeps its own inner scroller. */
.hs-upgrade-root .hs-tab-fill {
    overflow-x: hidden;
    overflow-y: auto;
    scroll-padding: 12px 0;
}
.hs-upgrade-root .hs-tab-fill > :is(.hs-panel, .hs-line, .hs-empty-slot) {
    flex: 0 0 auto;
}
/* Affordability hint on still-focusable upgrade buttons. */
:is(.hs-upgrade-root, .hs-shop-root) .action-button[data-short] {
    opacity: 0.65;
}
:is(.hs-upgrade-root, .hs-shop-root) .action-button[data-short]:is(:hover, .nav-focused) {
    opacity: 1;
}

/* Locked cosmetic styles: visible preview, not selectable (unlock in shop). */
.hs-style-thumb.is-locked {
    position: relative;
    cursor: not-allowed;
}
.hs-style-thumb.is-locked canvas {
    opacity: 0.35;
    filter: grayscale(1);
}
.hs-style-thumb.is-locked::after {
    content: 'LOCK';
    position: absolute;
    inset: auto 0 2px 0;
    text-align: center;
    font-size: var(--font-small);
    font-weight: bold;
    letter-spacing: 0.08em;
    color: var(--color-text);
    text-shadow: 0 0 3px #000, 0 0 3px #000;
    pointer-events: none;
}
.hs-style-shop-thumb {
    flex: 0 0 auto;
    display: inline-flex;
    margin-right: 10px;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 50%, transparent);
    image-rendering: pixelated;
}
.hs-style-shop-thumb canvas {
    display: block;
    width: 64px;
    height: 48px;
    image-rendering: pixelated;
}
.hs-style-shop-line.is-owned .hs-style-shop-thumb {
    opacity: 0.6;
}

/* Station tab: panels keep their natural height and the body scrolls,
   instead of squashing the bottom row (ships / parts) into the leftover. */

.hs-station-grid {
    grid-template-rows: minmax(110px, auto) minmax(min-content, 1fr);
}
.hs-panel-stack {
    height: auto;
}

/* Shop: the item list is the scroller, so its column header (and style
   group headings) can stay pinned at the top while rows scroll under it. */
.hs-body:has(> .hs-shop-root) {
    overflow: hidden;
}
.hs-body > .hs-shop-root {
    min-height: 0;
}
.hs-shop-root .hs-shop-list {
    flex: 1 1 auto;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    scroll-padding-top: 40px;
}
.hs-shop-list > .hs-shop-line {
    flex: 0 0 auto;
}
.hs-shop-list > .hs-shop-line.hs-shop-head {
    position: sticky;
    top: 0;
    z-index: 4;
    margin-bottom: 0;
    background: color-mix(in srgb, var(--color-surface) 92%, var(--color-background));
    border-bottom: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
}

/* Style shop clusters: section (hull / components / connections) and a
   per-part heading that pins under the column header while scrolling. */
.hs-style-shop-section {
    flex: 0 0 auto;
    margin: 14px 0 4px;
    padding: 2px 8px;
    font-size: var(--font-text);
    font-weight: bold;
    letter-spacing: 3px;
    color: var(--faction-accent, var(--color-primary));
    border-left: var(--ui-border-width-thick) solid var(--faction-accent, var(--color-primary));
}
.hs-style-shop-section:first-of-type {
    margin-top: 6px;
}
.hs-style-shop-group {
    position: sticky;
    top: 30px;
    z-index: 3;
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 6px;
    padding: 4px 8px;
    letter-spacing: 2px;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 18%, var(--color-surface));
    border-bottom: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
}
.hs-style-shop-count {
    margin-left: auto;
    font-size: var(--font-text);
    color: var(--color-text-secondary);
}

/* Mission cargo panel removed: cargo auto-transfers to the station. */
.hs-station-grid {
    grid-template-rows: minmax(110px, auto) minmax(min-content, 1fr);
}

/* Galaxy map: standalone trading post node. */
.gm-post-node { cursor: pointer; }
.gm-post-node.closed { cursor: not-allowed; }
.gm-post-node:hover .gm-post-badge-bg { stroke-width: 3; }
.gm-post-label {
    font-size: var(--font-small);
    letter-spacing: 1px;
    text-anchor: middle;
    fill: var(--faction-accent, var(--color-primary));
}
.gm-post-node.closed .gm-post-label {
    fill: var(--color-text-secondary);
    opacity: 0.6;
}
.gm-post-badge-bg {
    fill: var(--color-background, #050508);
    stroke: var(--faction-accent, var(--color-primary));
    stroke-width: 2;
}
.gm-post-badge-mark {
    fill: var(--faction-accent, var(--color-primary));
}
.gm-post-node.closed .gm-post-badge-bg {
    stroke: var(--color-text-secondary);
    stroke-dasharray: 3 2;
}
.gm-post-node.closed .gm-post-badge-mark {
    fill: var(--color-text-secondary);
    opacity: 0.6;
}
.gm-dock-btn {
    border-color: var(--faction-accent, var(--color-primary));
}
/* Trading post shop: origin faction per part. */
.hs-part-faction {
    color: var(--faction-accent, var(--color-primary));
    letter-spacing: 1px;
}

/* Faction chip on shop rows; items without a faction read NEUTRAL. */
.hs-part-faction {
    display: inline-block;
    padding: 0 4px;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
    color: var(--faction-accent, var(--color-primary));
    font-weight: bold;
}
.hs-part-faction.is-neutral {
    border-color: color-mix(in srgb, var(--color-text-secondary) 50%, transparent);
    color: var(--color-text-secondary);
}
/* Shop SELL mode: credit payout column. */
.hs-sell-value {
    justify-self: end;
    font-weight: bold;
    letter-spacing: 1px;
    color: var(--status-success, #7fdc7f);
}

/* Hangar ship list: the open ship's component tree fills the column height. */
.hs-hangar-ship-tree {
    flex: 0 0 auto;
}
.hs-hangar-ship-tree[open] {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    min-height: 0;
}
.hs-hangar-ship-tree[open] > .hs-component-tree-container {
    flex: 1 1 auto;
    max-height: none;
}
.hs-tree-items > .hs-tree-connection {
    margin-top: 4px;
}

/* Slot entry flashed when a slot on the ship is clicked with the tree open. */
.hs-tree-item.is-focused > .hs-tree-item-label {
    outline: var(--ui-border-width) solid var(--faction-accent, var(--color-primary));
    outline-offset: -2px;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 22%, transparent);
}

/* Play tab keeps the same fixed window height as every other tab; the
   map shell fills the body instead of the window hugging the map. */
.home-station-content .hs-body-play > .hs-play-shell {
    flex: 1 1 auto;
}

/* Trading post selection frame (reuses planet corners). */
.gm-post-node .gm-selection-frame { opacity: 0; }

/* Trading posts drawn as pixel space stations (map node + sector card). */
.gm-station-outline { fill: #05060a; }
.gm-station-hull { fill: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, #d8d8e0); }
.gm-station-dark { fill: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 30%, #1a1a24); }
.gm-station-panel { fill: #2d5fa8; stroke: #7fb2ff; stroke-width: 0.3; }
.gm-station-light { fill: #fff6c8; }
.gm-post-node.open .gm-station-light { animation: gm-station-blink 1.6s steps(2, end) infinite; }
/* Card-size station detail layers (see stationPixelsSvg detail). */
.gm-station-glint { fill: #ffffff; opacity: 0.28; }
.gm-station-shade { fill: #000000; opacity: 0.32; }
.gm-station-deep { fill: #000000; opacity: 0.5; }
.gm-station-window { fill: #fff6c8; opacity: 0.85; }
.gm-station-card .gm-station-panel { stroke: none; }
@keyframes gm-station-blink { 50% { fill: var(--faction-accent, var(--color-primary)); } }
.gm-post-node.closed .gm-station { filter: grayscale(1) brightness(0.55); }
.gm-post-node:hover .gm-station { filter: brightness(1.25); }
.gm-post-node.closed:hover .gm-station { filter: grayscale(1) brightness(0.7); }
.gm-station-card { width: 100%; height: 100%; image-rendering: pixelated; }
/* Shop parts + lamps (stationPixelsSvg). */
.gm-station-crate { fill: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, #8a6a3a); }
.gm-station-sign { fill: #10131c; }
.gm-station-sign-glyph { fill: var(--faction-accent, var(--color-primary)); }
.gm-station-lamp { pointer-events: none; }
.gm-lamp-red { fill: #ff3b3b; }
.gm-lamp-green { fill: #3bff7a; }
/* Owner faction (stationFactionStyle): hull / trim / glow in its colours. */
.gm-station.is-faction .gm-station-hull { fill: color-mix(in srgb, var(--st-hull) 62%, #6c727e); }
.gm-station.is-faction .gm-station-dark { fill: color-mix(in srgb, var(--st-edge) 70%, #20232b); }
.gm-station.is-faction .gm-station-crate { fill: color-mix(in srgb, var(--st-hull) 45%, #4a4840); }
.gm-station.is-faction .gm-station-panel { fill: color-mix(in srgb, var(--st-accent) 45%, #141a28); stroke: none; }
.gm-station.is-faction :is(.gm-station-light, .gm-station-window) { fill: color-mix(in srgb, var(--st-accent) 75%, #ffffff); }
.gm-station.is-faction .gm-station-sign-glyph { fill: var(--st-accent); }
.gm-lamp-strobe { fill: #ffffff; }
.gm-lamp-amber { fill: #ffb43b; }
:is(.gm-post-node, .gm-station-card).open .gm-station-lamp { animation: gm-lamp-pulse 1.2s steps(2, end) infinite; }
:is(.gm-post-node, .gm-station-card).open .gm-lamp-strobe { animation: gm-lamp-strobe 2.4s steps(1, end) infinite; }
:is(.gm-post-node, .gm-station-card).open .gm-lamp-amber { animation-duration: 0.8s; }
:is(.gm-post-node, .gm-station-card).closed .gm-station-lamp { opacity: 0; }
@keyframes gm-lamp-pulse { 50% { opacity: 0.25; } }
@keyframes gm-lamp-strobe { 0%, 88% { opacity: 0.1; } 90%, 100% { opacity: 1; } }

/* Player ship marker on the galaxy map. */
.gm-ship-marker { pointer-events: none; }
.gm-ship-marker-body {
    fill: var(--color-primary);
    stroke: var(--color-background, #050508);
    stroke-width: 1.5;
    filter: drop-shadow(2px 0 0 color-mix(in srgb, var(--color-primary) 55%, transparent)) drop-shadow(-2px 0 0 color-mix(in srgb, var(--color-primary) 55%, transparent)) drop-shadow(0 2px 0 color-mix(in srgb, var(--color-primary) 55%, transparent)) drop-shadow(0 -2px 0 color-mix(in srgb, var(--color-primary) 55%, transparent));
}
.gm-ship-location-label {
    fill: var(--color-primary, #ff9b54);
    font: bold 9px monospace;
    letter-spacing: 1px;
    paint-order: stroke;
    stroke: #050508;
    stroke-width: 3px;
    text-anchor: middle;
}

/* Explorations: every entry listed with its discovered count; empty dimmed. */
.hs-explore-item .hs-explore-count {
    margin-left: auto;
    padding-left: 12px;
    font-weight: bold;
    letter-spacing: 1px;
    color: var(--faction-accent, var(--color-primary));
}
.hs-explore-item.is-empty {
    cursor: default;
}
.hs-explore-item.is-empty .hs-explore-count {
    color: var(--color-text-secondary);
}

/* Explorations: panel fills the body height and the entry buttons share it. */
.hs-body > .hs-explore-root {
    flex: 1 1 auto;
    min-height: 100%;
    box-sizing: border-box;
}
.hs-explore-root > .hs-explore-grid {
    flex: 1 1 auto;
    align-content: stretch;
    grid-template-rows: 1fr;
}
.hs-explore-cluster {
    display: flex;
    flex-direction: column;
    min-height: 0;
}
.hs-explore-cluster-items {
    flex: 1 1 auto;
}
.hs-explore-cluster-items > .hs-explore-item {
    flex: 1 1 0;
    min-height: 48px;
}
.home-station-content .hs-body-play > .hs-play-shell > .galaxy-map-embedded {
    flex: 1 1 auto;
}
/* The map area takes the height left over by the panels below it. */
.home-station-content .hs-body-play .galaxy-map-embedded .galaxy-map-area {
    flex: 1 1 auto;
    height: auto;
    min-height: 160px;
}

/* Galaxy map cursor: per-faction look (see selectionFrameSvg). */
.gm-selection-frame { color: var(--faction-accent, var(--color-primary)); }
.gm-selection-frame .gm-corner { fill: currentColor; vector-effect: non-scaling-stroke; shape-rendering: crispEdges; }
.gm-corner-stroke,
.gm-corner-organic {
    fill: none;
    stroke: currentColor;
    stroke-width: max(3px, var(--cursor-t, 3px));
    opacity: 1;
    stroke-linecap: round;
    stroke-linejoin: round;
    vector-effect: non-scaling-stroke;
}
.gm-corner-stroke { stroke-linecap: square; stroke-linejoin: miter; }
/* Global Pixel Size: corners are lattice-cell rects — no non-scaling stroke (that kept them UI-fine). */
html[data-vf-pixel-size="on"] .gm-selection-frame .gm-corner {
    vector-effect: none;
    shape-rendering: crispEdges;
}
html[data-vf-pixel-size="on"] .gm-corner-stroke,
html[data-vf-pixel-size="on"] .gm-corner-organic {
    vector-effect: none;
    stroke-width: var(--cursor-t, 1);
    stroke-linecap: square;
    stroke-linejoin: miter;
}
html[data-vf-pixel-size="on"] .gm-stage-progress-px .gm-pixel-text,
html[data-vf-pixel-size="on"] .gm-stage-progress-px .gm-pixel-text-o {
    shape-rendering: crispEdges;
}
/* Voidborn: organic, softly glowing and breathing instead of snapping. */
.gm-cursor-voidborn { filter: none; }
.galaxy-map-overlay .gm-node.selected .gm-cursor-voidborn,
.galaxy-map-overlay .gm-node.hovered .gm-cursor-voidborn,
.galaxy-map-embedded.is-input-active .gm-node.selected .gm-cursor-voidborn,
.galaxy-map-embedded.is-input-active .gm-node.hovered .gm-cursor-voidborn,
.gm-post-node.selected .gm-cursor-voidborn {
    animation: gm-void-breathe 2.4s steps(8, end) infinite;
}
@keyframes gm-void-breathe {
    0%   { transform: scale(0.94) rotate(0deg); }
    35%  { transform: scale(1.08, 1.02) rotate(3deg); }
    70%  { transform: scale(1.0, 1.1) rotate(-2deg); }
    100% { transform: scale(0.94) rotate(0deg); }
}
/* Machine: hard stepped blink instead of a smooth pulse. */
.galaxy-map-embedded.is-input-active .gm-node.selected .gm-cursor-machine,
.galaxy-map-overlay .gm-node.selected .gm-cursor-machine {
    animation: gm-machine-blink 0.8s steps(2, end) infinite;
}
@keyframes gm-machine-blink {
    from { opacity: 1; }
    to { opacity: 0.45; }
}

/* Ship orbiting its current map location. */
.gm-ship-orbit-ring {
    fill: none;
    stroke: var(--color-primary);
    stroke-width: 1;
    stroke-dasharray: 2 4;
    opacity: 0.35;
}
.gm-ship-marker-img {
    image-rendering: pixelated;
    /* The dark outline is baked into the icon pixels. */
}

/* --- Victory screen follows the faction frame language ----------------- */
html[data-faction] .victory-content {
    position: relative;
    border-radius: 0;
    border-color: var(--faction-accent, var(--color-primary));
    clip-path: var(--faction-panel-clip, none);
    box-shadow:
        inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, transparent),
        0 0 18px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
}
html[data-faction] .victory-content::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: var(--faction-surface);
    opacity: var(--faction-surface-opacity);
}
html[data-faction] .victory-content > * { position: relative; z-index: 1; }
html[data-faction] :is(.victory-stats, .victory-loot) {
