/* --- Death screen follows the faction frame language ------------------- */
html[data-faction] .game-over-content {
    position: relative;
    border-radius: 0;
    border-color: var(--faction-accent, var(--color-primary));
    clip-path: var(--faction-panel-clip, none);
}
html[data-faction] .game-over-content::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: var(--faction-surface);
    opacity: var(--faction-surface-opacity);
}
html[data-faction] .game-over-content > * { position: relative; z-index: 1; }
html[data-faction] .game-over {
    filter: drop-shadow(0 0 14px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent));
}
