    color: var(--faction-accent, var(--color-primary));
    text-shadow: 1px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 78%, transparent), -1px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 78%, transparent), 0 1px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 78%, transparent), 0 -1px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 78%, transparent), 4px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 42%, transparent), -4px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 42%, transparent), 0 4px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 42%, transparent), 0 -4px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 42%, transparent), 8px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 18%, transparent), -8px 0 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 18%, transparent), 0 8px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 18%, transparent), 0 -8px 0 color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent) 18%, transparent);
}
html[data-faction] .game-over-button {
    border-radius: 0;
    clip-path: var(--faction-ctl-clip, none);
}
.game-over-loss {
    margin: 0 auto 18px;
    max-width: 320px;
    text-align: left;
}
html[data-faction] .game-over-loss {
    border-radius: 0;
    clip-path: var(--faction-ctl-clip, none);
}
.game-over-loss .victory-loot-amount { color: var(--color-error, #ff5a4a); }

/* --- Pause screen follows the faction frame language ------------------- */
html[data-faction] .pause-menu {
    position: relative;
    border-radius: 0;
    border-color: var(--faction-accent, var(--color-primary));
    clip-path: var(--faction-panel-clip, none);
}
html[data-faction] .pause-menu::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: var(--faction-surface);
    opacity: var(--faction-surface-opacity);
}
html[data-faction] .pause-menu > * { position: relative; z-index: 1; }
/* The clip-path would cut an outer glow, so the glow sits inside the frame. */
html[data-faction] .pause-overlay {
    --pause-glow: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
}
html[data-faction] .pause-overlay .pause-menu {
    border-color: var(--faction-accent, var(--color-primary));
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, transparent), inset 0 0 26px var(--pause-glow);
}
html[data-faction] .pause-button {
    border-radius: 0;
    clip-path: var(--faction-ctl-clip, none);
}
html[data-faction] .pause-overlay h2 {
    color: var(--faction-accent, var(--color-primary));
    text-shadow: 0 0 12px var(--pause-glow);
}

/* ===== In-game HUD contrast ============================================
   Sidebars get a near-black, opaque panel so labels and bars read against
   the busy playfield-coloured page, with bright text and accent values. */
.game-info-panel,
.player-vitals-side,
.game-left-cluster .weapon-selection,
.game-right-cluster .enemy-vitals-side {
    background: color-mix(in srgb, #050508 82%, var(--color-background, #000)) !important;
    color: #f2f4f8;
}
:is(.game-info-panel, .gi-loadout-side, .gi-mission-side) :is(.gi-label, .info-label, .stat-label, small, .label, .gi-row-label, .gi-metric-label, .gi-cluster-title, .gi-chip-row-label),
.game-left-cluster .weapon-info {
    color: color-mix(in srgb, #fff 72%, var(--faction-accent, var(--color-primary)));
    opacity: 1;
    text-shadow: 0 1px 0 #050508, 0 0 4px #050508;
}
:is(.game-info-panel, .gi-loadout-side, .gi-mission-side) :is(.gi-value, .info-value, .stat-value, strong, .gi-row-value, .gi-metric-value),
.gi-head-text h3 {
    color: #fff;
    text-shadow: 0 1px 0 #050508, 0 0 3px #050508;
}

/* Right sidebar: one row per enemy — framed portrait, faction + name, and
   a horizontal health bar with the HP readout (champion row is larger). */

.enemy-vitals-side .health-bar.enemy-health.is-champion {
    border-color: var(--faction-accent, var(--color-primary));
    box-shadow: inset 0 0 0 var(--ui-border-width) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
}
.enemy-vitals-side .enemy-head {
    display: flex;
    align-items: center;
    min-width: 0;
}
.enemy-vitals-side .health-ship-icon {
    flex: 0 0 auto;
    box-sizing: content-box;
    image-rendering: pixelated;
}
.enemy-vitals-side .enemy-text {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}
.enemy-vitals-side .enemy-faction {
    color: var(--faction-accent, var(--color-primary));
    text-shadow: none;
}
.enemy-vitals-side .enemy-name {
    font-family: var(--ui-font-family);
    font-size: var(--font-small);
    letter-spacing: 1px;
    color: #fff;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.enemy-vitals-side .health-bar.enemy-health .enemy-health-main,
.enemy-vitals-side .health-bar.enemy-health.is-champion .enemy-health-main {
    align-items: stretch;
