    opacity: 0.7;
}
.hs-hangar-part-ghost.is-removing::after {
    content: '✕';
    position: absolute;
    right: -10px;
    top: -10px;
    font-size: var(--font-text);
    font-weight: bold;
    color: #ff4a4a;
}

/* --- Filled slot grab frame spans the installed part (easy to grab). */
.hs-hangar-slot-layer .hs-hangar-slot:not(.is-empty) .hs-hangar-slot-pin {
    width: var(--pin-w, 28px);
    height: var(--pin-h, 28px);
    margin: calc(var(--pin-h, 28px) / -2) 0 0 calc(var(--pin-w, 28px) / -2);
}
@keyframes hs-slot-filled-breathe {
    0%, 100% { box-shadow: 0 0 0 2px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 72%, transparent), 0 0 0 2px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 48%, transparent), 0 0 0 4px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 30%, transparent), 0 0 0 6px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 16%, transparent); opacity: 0.75; }
    50% { box-shadow: 0 0 0 4px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 72%, transparent), 0 0 0 8px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 48%, transparent), 0 0 0 14px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 30%, transparent), 0 0 0 18px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 16%, transparent); opacity: 1; }
}
.hs-hangar-slot-layer .hs-hangar-slot:not(.is-empty).is-area-hover .hs-hangar-slot-pin,
.home-station-content:not(.hs-pointer-mode) .hs-hangar-slot-layer .hs-hangar-slot:not(.is-empty) .hs-hangar-slot-pin {
    /* Big frames breathe instead of spinning, so they stay on the part. */
    animation: hs-slot-filled-breathe 1.4s ease-in-out infinite;
}

/* --- Slot pins take the shape of their purpose:
   weapon = forward arrowhead, defense = shield, ability = circle,
   energy = diamond cell. Empty slots show the shape as an outline (the
   pin box itself goes invisible); filled slots keep their grab frame and
   carry the shape as a badge in the top-left corner. */
:is(.hs-hangar-slot, .hs-slot-glyph)[data-slot-kind="weapon"]  { --slot-shape: polygon(50% 0, 100% 100%, 50% 72%, 0 100%); }
:is(.hs-hangar-slot, .hs-slot-glyph)[data-slot-kind="defense"] { --slot-shape: polygon(0 0, 100% 0, 100% 55%, 50% 100%, 0 55%); }
:is(.hs-hangar-slot, .hs-slot-glyph)[data-slot-kind="ability"] { --slot-shape: circle(50% at 50% 50%); }
:is(.hs-hangar-slot, .hs-slot-glyph)[data-slot-kind="energy"]  { --slot-shape: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); }
.hs-hangar-slot[data-slot-kind] {
    --slot-shape-color: var(--faction-accent, var(--color-primary));
}

.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin {
    border: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    filter: drop-shadow(2px 0 0 color-mix(in srgb, var(--slot-shape-color) 55%, transparent)) drop-shadow(-2px 0 0 color-mix(in srgb, var(--slot-shape-color) 55%, transparent)) drop-shadow(0 2px 0 color-mix(in srgb, var(--slot-shape-color) 55%, transparent)) drop-shadow(0 -2px 0 color-mix(in srgb, var(--slot-shape-color) 55%, transparent));
}
.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin::before,
.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin::after {
    content: '';
    position: absolute;
    clip-path: var(--slot-shape);
    pointer-events: none;
}
/* Outer shape = outline colour, inner shape = dark fill → a shaped outline. */
.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin::before {
    inset: 0;
    background: var(--slot-shape-color);
}
.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin::after {
    inset: 3px;
    background: color-mix(in srgb, var(--slot-shape-color) 22%, var(--color-background));
}
.hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-dot {
    position: relative;
    z-index: 1;
    margin: 0;
    position: absolute;
    left: 50%;
    top: 50%;
    width: 4px;
    height: 4px;
    transform: translate(-50%, -50%);
    background: var(--slot-shape-color);
}
/* Arrowhead and shield read better a little taller than wide. */
.hs-hangar-slot.is-empty[data-slot-kind="weapon"] .hs-hangar-slot-dot { top: 62%; }
.hs-hangar-slot.is-empty[data-slot-kind="defense"] .hs-hangar-slot-dot { top: 42%; }
/* Drop target: the whole shape fills solid. */
.hs-hangar-slot.is-empty.is-drop-target[data-slot-kind] .hs-hangar-slot-pin::after {
    background: var(--slot-shape-color);
}

/* Filled slot: shape badge on the grab frame's corner. */
.hs-hangar-slot:not(.is-empty)[data-slot-kind] .hs-hangar-slot-pin::before {
    content: '';
    position: absolute;
    left: -8px;
    top: -8px;
    width: 14px;
    height: 14px;
    background: var(--slot-shape-color);
    clip-path: var(--slot-shape);
    pointer-events: none;
}
.hs-hangar-slot:not(.is-empty)[data-slot-kind] .hs-hangar-slot-pin::after {
    content: '';
    position: absolute;
    left: -5px;
    top: -5px;
    width: 8px;
    height: 8px;
    background: var(--color-background);
    clip-path: var(--slot-shape);
    pointer-events: none;
}
/* Empty shapes a bit larger than the old square so the outline reads. */
.hs-hangar-slot-layer .hs-hangar-slot.is-empty[data-slot-kind] .hs-hangar-slot-pin {
    width: 22px;
    height: 22px;
    margin: -11px 0 0 -11px;
}

/* --- Hull areas: slot/part size badges (S / M / L). */
.hs-slot-size {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.4em;
    padding: 0 3px;
    font-size: 0.85em;
    font-weight: bold;
    line-height: 1.3;
    color: var(--color-background);
    background: var(--faction-accent, var(--color-primary));
}
.hs-slot-size.is-M { outline: var(--ui-border-width) solid var(--faction-accent, var(--color-primary)); outline-offset: 1px; }
.hs-slot-size.is-L { outline: var(--ui-border-width) double var(--faction-accent, var(--color-primary)); outline-offset: 1px; }

/* Slot pins grow with slot size: S small, M medium, L large. */
.hs-hangar-slot-layer .hs-hangar-slot.is-empty[data-slot-size="M"] .hs-hangar-slot-pin {
    width: 28px;
    height: 28px;
    margin: -14px 0 0 -14px;
}
.hs-hangar-slot-layer .hs-hangar-slot.is-empty[data-slot-size="L"] .hs-hangar-slot-pin {
    width: 36px;
    height: 36px;
    margin: -18px 0 0 -18px;
}

/* Dragging a part too big for this ship's slots: no pulse, red dashed. */
.hs-hangar-bay-stage.is-part-too-big .hs-hangar-slot .hs-hangar-slot-pin {
    animation: none !important;
    opacity: 0.6 !important;
    --slot-shape-color: #ff5a5a;
}

/* Parts grid: size badge in the corner, oversized parts dimmed. */
.hs-hangar-part {
    position: relative;
}
.hs-hangar-part > .hs-slot-size {
    top: 2px;
    left: 2px;
    font-size: var(--font-small);
    z-index: 1;
}
.hs-hangar-part.is-too-big {
    opacity: 0.45;
}
.hs-hangar-part.is-too-big > .hs-slot-size {
    background: #ff5a5a;
}

/* Hangar: four area tiles in one row under the head bar. */
.hs-hangar-areas {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 6px;
    margin-top: 6px;
}
.hs-area-tile {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas: "name btn" "cost btn";
    align-items: center;
    min-width: 0;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 6%, transparent);
}
.hs-area-tile .hs-area-name { grid-area: name; display: inline-flex; align-items: center; min-width: 0;}
.hs-area-tile .hs-area-costs { grid-area: cost; display: inline-flex; flex-wrap: wrap; gap: 0 5px; min-width: 0; }
.hs-area-tile .hs-area-btn,
.hs-area-tile .hs-area-max { grid-area: btn; }
.hs-area-tile .hs-area-btn {
    font-size: var(--font-text);
    white-space: nowrap;
}
.hs-area-cost {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-size: var(--font-text);
    color: var(--color-text-secondary);
}
.hs-area-cost img { width: 12px; height: 12px; }
.hs-area-cost.is-short { color: #ff7a7a; }

/* Upgrade tab rows. */
.hs-area-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 6px;
    min-width: 0;
}
.hs-area-row .hs-area-name {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
    white-space: nowrap;
}
.hs-area-row .hs-area-name small {
    color: var(--color-text-secondary);
    overflow: hidden;
    text-overflow: ellipsis;
}
.hs-area-row.is-compact .hs-line-action {
    padding: 2px 8px;
    font-size: var(--font-text);
}
.hs-area-ship {
    margin-bottom: 12px;
}
.hs-area-ship > .hs-area-row {
    padding: 4px 8px 4px 48px;
}

/* Native slot dropdown list: the browser draws it on a light default
   background, which washed out the light UI text. Force dark rows. */
.hs-hangar-slot-select,
.hs-tree-slot-select {
    color-scheme: dark;
}
.hs-hangar-slot-select option,
.hs-tree-slot-select option {
    background: #0b0d14;
    color: #e8ecf4;
}
.hs-hangar-slot-select option:checked,
.hs-tree-slot-select option:checked {
    background: var(--faction-accent, var(--color-primary));
    color: #050508;
}
.hs-hangar-slot-select option:disabled,
.hs-tree-slot-select option:disabled {
    color: #7a8190;
}

/* Slot-type glyph (same shape as the pin on the ship) for list headers,
   part cells and slot cards: outlined shape in the faction accent. */
.hs-slot-glyph {
    position: relative;
    display: inline-block;
    flex: 0 0 auto;
    width: 14px;
    height: 14px;
    margin-right: 8px;
    vertical-align: -2px;
    background: var(--faction-accent, var(--color-primary));
    clip-path: var(--slot-shape);
}
.hs-slot-glyph::after {
    content: '';
    position: absolute;
    inset: 3px;
    background: var(--color-background);
    clip-path: var(--slot-shape);
}

.hs-hangar-part > .hs-hangar-part-glyph {
    top: 3px;
    right: 3px;
    width: 10px;
    height: 10px;
    margin: 0;
}
.hs-hangar-part > .hs-hangar-part-glyph::after {
    inset: 2px;
}

/* --- Only weapon slots live on the ship; other part types are switched
   on/off in the PARTS sidebar. */

.hs-hangar-part.is-toggle {
    cursor: pointer;
}
.hs-hangar-part-state {
    font-size: var(--font-small);
    font-weight: bold;
    letter-spacing: 1px;
    padding: 0 4px;
    color: var(--color-text-secondary);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 35%, transparent);
}
.hs-hangar-part.is-equipped .hs-hangar-part-state {
    color: var(--color-background);
    background: var(--color-primary);
    border-color: var(--color-primary);
}

/* --- Wing weapon slot = mirrored pair: the second marker on the right wing
   follows the first one's look but is display-only. */
.hs-hangar-slot-pin.is-mirror {
    left: calc(var(--bay-ship-left) + (var(--bay-ship-w) * var(--pin-mx, 0.5)));
    top: calc(var(--bay-ship-top) + (var(--bay-ship-h) * var(--pin-my, 0.5)));
    pointer-events: none !important;
    display: block;
}

/* Component tree: ON/OFF switch for toggleable hull areas (nose, aft). */
.hs-tree-branch > summary .hs-area-switch {
    margin-left: auto;
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    cursor: pointer;
}
.hs-tree-branch > summary:has(.hs-area-switch) {
    display: flex;
    align-items: center;
    gap: 4px;
    min-width: 0;
}
.hs-tree-branch > summary:has(.hs-area-switch) .hs-tree-text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.hs-area-switch input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}
.hs-area-switch-track {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 28px;
    padding: 1px 3px;
    font-size: var(--font-small);
    font-weight: bold;
    letter-spacing: 1px;
    border: var(--ui-border-width) solid var(--faction-accent, var(--color-primary));
    background: var(--faction-accent, var(--color-primary));
    color: var(--color-background);
}
.hs-area-switch input:not(:checked) + .hs-area-switch-track {
    background: transparent;
    color: var(--color-text-secondary);
    border-color: var(--color-border);
}
.hs-area-switch input:focus-visible + .hs-area-switch-track {
    outline: var(--ui-border-width) solid var(--faction-accent, var(--color-primary));
    outline-offset: 2px;
}
.hs-tree-branch.is-area-off > summary .hs-tree-text,
.hs-tree-branch.is-area-off > summary .hs-tree-icon,
.hs-tree-branch.is-area-off > summary .hs-tree-toggle {
    opacity: 0.4;
    text-decoration: line-through;
}
.hs-tree-branch.is-area-off > .hs-tree-items {
    display: none;
}
.hs-area-tile.is-off {
    border-style: dashed;
}

/* --- Only weapon slots are shown on the ship; other parts live in the sidebar. */
.hs-hangar-slot-layer .hs-hangar-slot:not([data-slot-kind="weapon"]) {
    display: none !important;
}
/* Area tiles: the ON/OFF switch sits at the end of the name row; an off
   tile stays clickable (only its content is dimmed). */
.hs-area-tile .hs-area-name .hs-area-switch {
    cursor: pointer;
}
.hs-area-tile.is-off {
    opacity: 1;
}
.hs-area-tile.is-off .hs-area-name strong {
    opacity: 0.45;
}
.hs-area-tile.is-off .hs-area-name {
    grid-column: 1 / -1;
}

/* --- RESET ANATOMY + SET AS DEFAULT side by side. */
.hs-hangar-bay-tools {
    display: flex;
    gap: 6px;
}
.hs-hangar-bay-tools > .action-button {
    flex: 1 1 0;
    min-width: 0;
}

/* Area upgrade confirm modal (reuses the resource-buy dialog look). */
.hs-area-modal-list {
    margin: 0;
    padding: 0 0 0 18px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-size: var(--font-text);
    letter-spacing: 1px;
    line-height: 1.4;
}
.hs-area-modal-list strong {
    color: var(--faction-accent, var(--color-primary));
}
.hs-area-modal-short {
    margin: 0;
    font-size: var(--font-text);
    letter-spacing: 1px;
    color: #ff7a7a;
}

/* --- PLAY has no resource row, so the map toolbar is the second row: it
   starts right of the hanging faction crest instead of running under it. */
.home-station-content.hs-mode-play .galaxy-map-toolbar {
    margin-left: var(--hs-tabs-offset, 0px);
}

/* --- The hanging faction crest always stays on top: the header sits above
   the body (whose frames/panels would otherwise paint over the crest). */
.home-station-content > .hs-header {
    position: relative;
    z-index: 30;
}
.hs-topbar-emblem > .hs-crest {
    z-index: 31;
}

/* --- Pixel look: UI lines sit on a 2px grid. The hangar connector lines
   are drawn with hard edges and a 2px stroke instead of anti-aliased
   hairlines (planet art SVGs keep their smooth curves). */
.hs-hangar-link-svg,
.hs-hangar-link-svg * {
    shape-rendering: crispEdges;
}
.hs-hangar-link-svg path,
.hs-hangar-link-svg line,
.hs-hangar-link-svg polyline {
    stroke-width: 2px;
}

/* Top bar areas: HANGAR | HOME STATION | FACTIONS | EXPLORATIONS.
   Area buttons and sub navbar tabs are .hs-tab buttons with visible labels. */
.home-station-overlay .hs-tabs .hs-area-btn .hs-tab-label,
.home-station-overlay .hs-subnav .hs-tab-label {
    display: inline;
}
.hs-subnav {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 4px 0 2px;
    overflow-x: auto;
    scrollbar-width: thin;
}
.home-station-overlay .hs-subnav .hs-tab {
    padding: 4px 8px;
}
.home-station-overlay .hs-subnav .hs-tab-icon,
.home-station-overlay .hs-subnav .hs-tab-pixel {
    width: 24px;
    height: 24px;
}

/* Faction relations dashboard */
.hs-factions { display: flex; flex-direction: column; gap: 10px; }
.hs-faction-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
}
.hs-faction-card { display: flex; flex-direction: column; gap: 8px; }
.hs-faction-head { display: flex; align-items: center; gap: 8px; }
.hs-faction-crest { width: 48px; height: 48px; flex-shrink: 0; }
.hs-faction-crest img { width: 48px; height: 48px; image-rendering: pixelated; }
.hs-faction-name { flex: 1; font-weight: bold; letter-spacing: 1px; }
.hs-faction-status {
    font-size: 0.8em;
    padding: 2px 6px;
    border: var(--ui-border-width) solid var(--color-border);
    color: var(--color-text-secondary);
}
.hs-faction-meter {
    border: var(--ui-border-width) solid var(--color-border);
}
.hs-faction-meter span { display: block; height: 100%; background: var(--color-text-secondary); }
.hs-faction-card.is-ally .hs-faction-meter span,
.hs-faction-card.is-friend .hs-faction-meter span { background: var(--color-primary); }
.hs-faction-card.is-hostile .hs-faction-meter span { background: #d04848; }
.hs-faction-card.is-ally .hs-faction-status { border-color: var(--color-primary); color: var(--color-text); }
.hs-faction-card.is-hostile .hs-faction-status { border-color: #d04848; color: #ff8080; }
.hs-faction-stats { display: flex; justify-content: space-between; font-size: 0.85em; color: var(--color-text-secondary); }
.hs-faction-goal { margin: 0; font-size: 0.85em; color: var(--color-text-secondary); line-height: 1.4; }
.hs-faction-pact { align-self: flex-start; }

/* --- AREAS/PARTS switch gets its own row under the sidebar heading so it
   never covers the label in the narrow sidebar. */
.hs-hangar-list > .hs-panel-title {
    flex-wrap: wrap;
}
.hs-hangar-list > .hs-panel-title > .hs-hangar-view-toggle {
    order: 10;
    flex: 1 0 100%;
    margin: 4px 0 0;
}
.hs-hangar-list > .hs-panel-title > .hs-hangar-view-toggle > .hs-hangar-view-btn {
    flex: 1 1 0;
}

/* --- Station header: pilot card in the top-left corner (crest, name,
   resources) next to the area navbar + sub navbar. */
.hs-header-split {
    display: flex;
    align-items: stretch;
    gap: 8px;
    margin-bottom: 4px;
}
.hs-crest-card { --crest-size: 64px; }
.hs-pilot-card {
    flex: 0 0 auto;
    display: flex;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
    background: color-mix(in srgb, var(--color-background, #050508) 70%, transparent);
    clip-path: var(--faction-ctl-clip, none);
    max-width: 46%;
}
.hs-pilot-crest {
    flex: 0 0 auto;
    display: inline-flex;
    filter: drop-shadow(0 0 6px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent));
}
.hs-pilot-info {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}
.hs-pilot-card .hs-profile {
    margin: 0;
    color: var(--color-text);
}
.hs-pilot-res {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 10px;
    align-items: center;
}
.hs-header-main {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    min-width: 0;
}
.hs-header-main .hs-topbar {
    margin-bottom: 0;
}

/* --- Mission board (hangar area, before CRAFT). */
.hs-mission-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.hs-mission {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 12px;
}
.hs-mission .hs-line-name {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}
.hs-mission-type {
    font-size: var(--font-small);
    font-weight: bold;
    letter-spacing: 2px;
    color: var(--color-primary);
}
.hs-mission.is-patrol .hs-mission-type {
    color: var(--color-text-secondary);
}
.hs-mission-meta {
    font-size: var(--font-small);
    letter-spacing: 1px;
    color: var(--color-text-secondary);
}
.hs-mission-actions {
    display: flex;
    gap: 6px;
}
.hs-mission.is-locked {
    opacity: 0.45;
}
.hs-mission.is-active {
    border-color: var(--faction-accent, var(--color-primary));
    box-shadow: inset 0 0 0 var(--ui-border-width) var(--faction-accent, var(--color-primary));
}
.hs-mission .hs-line-name {
    align-items: flex-start;
    text-align: left;
}
.hs-mission .hs-line-action {
    white-space: nowrap;
}
.hs-mission.is-locked .hs-mission-reward {
    min-width: 0;
}

