/* Faction holdings on the galaxy map: base planet + faction stations. */
/* Base fortress (baseFortressSvg): outline + five depths of the faction
   colour, lit windows, glowing gate, blinking mast lamps. */
.gm-base-marker .gm-base-graphic rect { stroke: none; }
.gm-base-marker .gm-base-o { fill: #07080c; }
.gm-base-marker .gm-base-k { fill: color-mix(in srgb, var(--fac) 15%, #0a0a0e); }
.gm-base-marker .gm-base-d { fill: color-mix(in srgb, var(--fac) 35%, #1a1a22); }
.gm-base-marker .gm-base-m { fill: color-mix(in srgb, var(--fac) 55%, #454552); }
.gm-base-marker .gm-base-l { fill: color-mix(in srgb, var(--fac) 70%, #d8d9e2); }
.gm-base-marker .gm-base-w { fill: color-mix(in srgb, var(--fac) 55%, #fff); }
.gm-base-marker .gm-base-c { fill: color-mix(in srgb, var(--fac) 80%, #fff); animation: gm-base-core 2.4s steps(4, end) infinite; }
.gm-base-marker .gm-base-a { fill: #ffb43b; animation: gm-lamp-pulse 1.2s steps(2, end) infinite; }
@keyframes gm-base-core { 50% { fill: var(--fac); } }
.gm-base-marker .gm-base-label {
    fill: var(--fac);
    font-size: var(--font-small);
    font-weight: bold;
    letter-spacing: 2px;
    text-anchor: middle;
}
.gm-post-node.is-built .gm-faction-station-ring {
    display: none;
}
.galaxy-map-ruler-holdings {
    font-size: var(--font-small);
    letter-spacing: 1px;
    color: #fff;
    opacity: 0.85;
}

/* Galaxy map without focus: no planet / post selection frame — only the
   player ship marker shows where you are. */
.galaxy-map-embedded:not(.is-input-active):not(.is-picked) .gm-selection-frame {
    display: none;
}

/* Selection frame: snaps onto the picked planet / post, then breathes. */
.gm-node.selected .gm-frame-slot,
.gm-post-node.selected .gm-frame-slot,
.gm-border-station.selected .gm-frame-slot {
    /* On the slot, not the frame: updateSelectionFrames rebuilds the frame on every
       zoom step, which restarted the animation each time and distorted it. */
    transform-box: fill-box;
    transform-origin: center;
    animation:
        gm-frame-snap 0.28s cubic-bezier(0.2, 0.9, 0.3, 1.2) both,
        gm-frame-breathe 1.8s ease-in-out 0.28s infinite;
}
@keyframes gm-frame-snap {
    from { transform: scale(1.45); opacity: 0; }
    to   { transform: scale(1);    opacity: 1; }
}
@keyframes gm-frame-breathe {
    0%, 100% { transform: scale(1);    opacity: 1; }
    50%      { transform: scale(1.06); opacity: 0.75; }
}
@media (prefers-reduced-motion: reduce) {
    .gm-node.selected .gm-frame-slot,
    .gm-post-node.selected .gm-frame-slot { animation: none; }
}

