    padding: 8px;
    background: color-mix(in srgb, #000 70%, transparent);
    border: var(--ui-border-width) solid var(--faction-accent, var(--color-primary));
    box-shadow: 0 0 0 4px color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent) 72%, transparent), 0 0 0 8px color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent) 48%, transparent), 0 0 0 14px color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent) 30%, transparent), 0 0 0 18px color-mix(in srgb, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent) 16%, transparent);
    z-index: 2;
    pointer-events: none;
}
.gm-lock-badge .gm-lock-shackle,
.gm-lock-badge .gm-lock-body { fill: var(--faction-accent, var(--color-primary)); }
.gm-lock-badge .gm-lock-hole { fill: #000; }

/* ===== Area tree: calmer containers ======================================
   Nested boxes each drew a full bright outline. Now: soft tinted panels,
