/* --- Faction picker, large: fill the screen, bigger type and icons. */
.profile-selection-content.profile-selection-floating.profile-selection-name-mode:has(.profile-faction-info-row) {
    max-width: min(calc(1320px * var(--zk)), calc(96 * var(--cw)));
    width: min(calc(1320px * var(--zk)), calc(96 * var(--cw)));
    max-height: calc(96 * var(--sv-h));
    overflow-y: auto;
    padding: 28px 32px;
}
.profile-selection-name-mode:has(.profile-faction-info-row) h2 { font-size: 34px; }
.profile-selection-name-mode:has(.profile-faction-info-row) .profile-faction-swatches { gap: 12px; }
.profile-selection-name-mode:has(.profile-faction-info-row) .profile-faction-swatch { padding: 18px 6px 14px; }

.profile-selection-name-mode:has(.profile-faction-info-row) .profile-faction-swatch-label { font-size: var(--font-h2); letter-spacing: 1px; }
.profile-selection-name-mode .profile-faction-info-row { gap: 16px; margin: 16px 0; }
/* Horizontal padding must clear the 32px pixel-art border-image frame the per-faction
   ::before ornament paints on this same card (assets/factions/<faction>/gui.css) — this rule's
   extra .profile-faction-info-row class outranks part-19.css's attempt at the same fix,
   so the narrower 20px here was still the one winning and letting the frame eat into
   the first/last characters of the centered trait text. */
.profile-selection-name-mode .profile-faction-info-row .profile-faction-preview { padding: 16px 36px; gap: 24px; }
.profile-selection-name-mode .profile-faction-info-row .profile-faction-ship { width: 260px; height: 182px; }
.profile-selection-name-mode .profile-faction-preview-emblem { width: 48px; height: 48px; }
.profile-selection-name-mode .profile-faction-preview-name { font-size: 22px; }
.profile-selection-name-mode .profile-faction-preview-trait,
.profile-selection-name-mode .profile-faction-preview-hero { font-size: var(--font-h2); line-height: 1.5; }
.profile-selection-name-mode .profile-faction-info-row .profile-faction-lore { padding: 16px 20px; }
.profile-selection-name-mode .profile-faction-lore-label { font-size: var(--font-text); margin-bottom: 8px; }
.profile-selection-name-mode .profile-faction-info-row .profile-faction-lore-text {
    font-size: var(--font-h2);
    line-height: 1.6;
    max-height: none;
}
.profile-selection-name-mode .profile-faction-facts { gap: 16px; margin-bottom: 20px; }
.profile-selection-name-mode .profile-faction-fact {
    text-align: left;
}

.profile-selection-name-mode .profile-faction-fact-label { font-size: var(--font-text); margin-bottom: 6px; }
.profile-selection-name-mode .profile-faction-fact-value { font-size: var(--font-h2);}
.profile-selection-name-mode .profile-faction-fact-note { font-size: var(--font-text); margin-top: 4px;}
.profile-selection-name-mode:has(.profile-faction-info-row) .profile-selection-actions button {
    font-size: var(--font-h2);
    padding: 10px 28px;
}

/* --- Profiles overlay: fill the bezel glass host; body scrolls inside. */
.profile-selection-content.profile-selection-floating:not(.profile-selection-name-mode) {
    width: 100%;
    max-width: none;
    height: 100%;
    max-height: none;
    box-sizing: border-box;
    padding: 28px 32px;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-title {
    flex: 0 0 auto;
    font-size: 34px;
    margin-bottom: 20px;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-body {
    grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.6fr);
    gap: 18px;
    flex: 1 1 0;
    min-height: 0;
    height: auto;
    max-height: none;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-actions,
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-instructions {
    flex: 0 0 auto;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-list-item {
    padding: 14px 16px;
    font-size: var(--font-h2);
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-list-emblem { width: 28px; height: 28px; }
.profile-selection-floating:not(.profile-selection-name-mode) .profile-list-emblem img { width: 28px !important; height: 28px !important; }
.profile-selection-floating:not(.profile-selection-name-mode) .profile-list-empty,
.profile-selection-floating:not(.profile-selection-name-mode) .profile-details-empty { font-size: var(--font-h2); }
.profile-selection-floating:not(.profile-selection-name-mode) .profile-details {
    padding: 20px 24px;
    font-size: var(--font-h2);
    gap: 14px;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-actions button {
    font-size: var(--font-h2);
    padding: 10px 28px;
}
.profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-instructions { font-size: var(--font-text); }
@media (max-width: 560px) {
    .profile-selection-floating:not(.profile-selection-name-mode) .profile-selection-body {
        grid-template-columns: 1fr;
        height: auto;
    }
}

/* --- Start menu, wide: pilot card + a one-line hint under each entry. */
.start-screen-content:has(> .start-screen-menu-clustered) {
    width: min(calc(560px * var(--zk)), calc(94 * var(--cw)));
    padding: 28px 36px 18px;
    gap: 10px;
}
.start-screen-content:has(> .start-screen-menu-clustered) .start-screen-title {
    font-size: 48px;
    letter-spacing: 0.18em;
    margin: 0;
}
.start-screen-content:has(> .start-screen-menu-clustered) .start-screen-subtitle {
    font-size: var(--font-h2);
    letter-spacing: 0.3em;
    margin: 0 0 6px;
}
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered {
    width: 100%;
    max-width: none;
}
.start-screen-content > .start-screen-profile {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 4px 0 6px;
    padding: 12px 16px;
    text-align: left;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 55%, transparent);
    background: color-mix(in srgb, var(--color-primary) 8%, transparent);
}
.start-screen-content > .start-screen-profile.no-profile {
    justify-content: center;
    font-size: var(--font-text);
    letter-spacing: 0.12em;
    opacity: 0.75;
    border-style: dashed;
}
.start-profile-emblem { display: inline-flex; width: 40px; height: 40px; flex: 0 0 auto; }
.start-profile-emblem .menu-pixel-icon { width: 40px; height: 40px; }
.start-profile-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.start-profile-label { font-size: var(--font-text); letter-spacing: 0.2em; color: var(--color-primary); }
.start-profile-name { font-size: 20px; letter-spacing: 0.08em; color: var(--color-text); }
.start-profile-meta { font-size: var(--font-text); letter-spacing: 0.1em; color: var(--color-text-secondary); }
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered .menu-item {
    gap: 14px;
    padding: 8px 12px;
}
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered .menu-item.menu-item-primary { padding: 14px 18px; }
.menu-item-text { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 0; }
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered .menu-item-label { font-size: var(--font-h2); letter-spacing: 0.08em; }
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered .menu-item-primary .menu-item-label { font-size: 22px; }
.menu-item-desc {
    font-size: var(--font-text);
    letter-spacing: 0.04em;
    color: var(--color-text-secondary);
    opacity: 0.8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.menu-item.selected .menu-item-desc { opacity: 1; }
:is(.start-screen-content, .start-menu-row) > .start-screen-menu-clustered .menu-cluster-title { font-size: var(--font-text); }

/* --- Faction picker: same box heights for every faction; lore in blocks. */
.profile-selection-name-mode .profile-faction-info-row { height: 300px; }
.profile-selection-name-mode .profile-faction-info-row > * { min-height: 0; overflow: hidden; }
.profile-selection-name-mode .profile-faction-info-row .profile-faction-lore-text {
    overflow-y: auto;
    padding-right: 6px;
}
.profile-faction-lore-text p { margin: 0 0 10px; }
.profile-faction-lore-text p:last-child { margin-bottom: 0; }
.profile-faction-lore-lead {
    color: var(--color-primary);
    font-weight: bold;
    padding-bottom: 8px;
    border-bottom: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 35%, transparent);
}
.profile-faction-lore-hero {
    font-size: 0.85em;
    letter-spacing: 1px;
    color: var(--color-primary);
    opacity: 0.8;
    text-transform: uppercase;
}

.profile-selection-name-mode .profile-faction-fact { box-sizing: border-box;}
@media (max-width: 640px) {
    .profile-selection-name-mode .profile-faction-info-row { height: auto; }
    .profile-selection-name-mode .profile-faction-facts { grid-auto-rows: auto; }
}

/* --- Faction picker: fourth card (allies). */
.profile-selection-name-mode .profile-faction-facts { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.profile-faction-ally {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-right: 12px;
    font-weight: bold;
    letter-spacing: 1px;
}
.profile-faction-ally img { width: 24px !important; height: 24px !important; }
@media (max-width: 1000px) {
    .profile-selection-name-mode .profile-faction-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
    .profile-selection-name-mode .profile-faction-facts { grid-template-columns: 1fr; }
}

/* Faction fact cards: grow with their text instead of clipping it. */
/* Fixed row height so switching factions doesn't resize the modal;
   long texts are clamped instead of clipped mid-line. */
.profile-selection-name-mode .profile-faction-facts { align-items: stretch;}
.profile-selection-name-mode .profile-faction-fact {
    height: 100%;
    overflow: hidden;
    gap: 14px;
}
.profile-selection-name-mode .profile-faction-fact-icon { width: 48px; height: 48px; }
.profile-selection-name-mode .profile-faction-fact-value { font-size: var(--font-h2); overflow-wrap: anywhere;}
.profile-selection-name-mode .profile-faction-fact-note { font-size: var(--font-text);}
.profile-selection-name-mode .profile-faction-fact-value,
.profile-selection-name-mode .profile-faction-fact-note {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

/* Settings modal: wide, three columns, collapsible sections. */
.start-screen-content:has(> .settings-panel-3col) {
    width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
    max-width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
}
.settings-panel-clustered.settings-panel-3col {
    /* Sections stacked, each the full modal width. */
    grid-template-columns: 1fr;
    gap: clamp(8px, calc(1.2 * var(--sv-h)), 14px);
}
.settings-panel-3col .settings-cluster {
    width: 100%;
}
details.settings-section > summary.settings-section-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    list-style: none;
    user-select: none;
}
details.settings-section > summary.settings-section-title::-webkit-details-marker { display: none; }
details.settings-section > summary.settings-section-title::after {
    content: "▾";
    font-size: 1.1em;
    transition: transform 0.12s;
}
details.settings-section:not([open]) > summary.settings-section-title {
    margin-bottom: 0;
    border-bottom-color: transparent;
}
details.settings-section:not([open]) > summary.settings-section-title::after {
    transform: rotate(-90deg);
}
details.settings-section > summary.settings-section-title:hover {
    opacity: 1;
    text-shadow: 1px 0 0 color-mix(in srgb, var(--color-primary) 78%, transparent), -1px 0 0 color-mix(in srgb, var(--color-primary) 78%, transparent), 0 1px 0 color-mix(in srgb, var(--color-primary) 78%, transparent), 0 -1px 0 color-mix(in srgb, var(--color-primary) 78%, transparent), 2px 0 0 color-mix(in srgb, var(--color-primary) 42%, transparent), -2px 0 0 color-mix(in srgb, var(--color-primary) 42%, transparent), 0 2px 0 color-mix(in srgb, var(--color-primary) 42%, transparent), 0 -2px 0 color-mix(in srgb, var(--color-primary) 42%, transparent), 4px 0 0 color-mix(in srgb, var(--color-primary) 18%, transparent), -4px 0 0 color-mix(in srgb, var(--color-primary) 18%, transparent), 0 4px 0 color-mix(in srgb, var(--color-primary) 18%, transparent), 0 -4px 0 color-mix(in srgb, var(--color-primary) 18%, transparent);
}
details.settings-section > summary.settings-section-title .settings-section-name {
    flex: 1 1 auto;
    text-align: left;
}
.settings-section-icon {
    width: 18px;
    height: 18px;
    flex: 0 0 auto;
    margin-right: 10px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: square;
    stroke-linejoin: miter;
}
/* Settings modal: only the modal is outlined, sections are borderless. */
.settings-panel-clustered details.settings-section,
html[data-vf-glow]:not([data-vf-glow="off"]) .settings-panel-clustered details.settings-section {
    border: none !important;
    outline: none;
    box-shadow: none !important;
    background: transparent !important;
    clip-path: none;
    padding-left: 0;
    padding-right: 0;
}
.settings-panel-clustered details.settings-section:not([open]) > summary.settings-section-title {
    border-bottom-color: color-mix(in srgb, var(--color-primary) 25%, transparent);
}
/* Fixed modal height, whichever section is open; the panel scrolls inside. */
.start-screen-content:has(> .settings-panel-3col) {
    height: min(calc(86 * var(--ch)), calc(860px * var(--zk)));
}
.start-screen-content > .settings-panel-3col {
    overflow-y: auto;
    align-content: start;
}

/* Credits: plain upward roll, large and flat (the 3D fly-in read oddly and
   spent most of its time tiny in the distance). */
.hs-credits-crawl-stage { perspective: none; }
.hs-credits-crawl-stage-fullscreen {
    width: min(calc(900px * var(--zk)), calc(92 * var(--cw)));
    height: min(calc(64 * var(--ch)), calc(560px * var(--zk)));
}
.hs-credits-crawl { transform: none; }
.hs-credits-crawl-text {
    position: absolute;
    top: 0;
    width: min(760px, 92%);
    animation: hs-credits-roll 14s linear infinite;
}
.hs-credits-crawl-line {
    font-size: clamp(1.4rem, calc(3.6 * var(--sv-h)), 2.2rem);
    margin: 0.7em 0;
}
.hs-credits-crawl-role {
    font-size: clamp(1rem, calc(2.4 * var(--sv-h)), 1.4rem);
    color: var(--color-primary);
}
@keyframes hs-credits-roll {
    from { transform: translateY(var(--credits-roll-from, 480px)); }
    to { transform: translateY(-100%); }
}
.hs-credits-crawl-stage-fullscreen .hs-credits-crawl-text { --credits-roll-from: min(calc(64 * var(--sv-h)), 560px); }
.start-screen-content:has(> .hs-credits-crawl-stage-fullscreen) {
    width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
    max-width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
    height: min(calc(88 * var(--ch)), calc(820px * var(--zk)));
}
.start-screen-content > .hs-credits-crawl-stage-fullscreen {
    width: 100%;
    height: auto;
    flex: 1 1 auto;
}
.hs-credits-crawl-stage-fullscreen .hs-credits-crawl-text { --credits-roll-from: min(calc(70 * var(--sv-h)), 660px); }
.hs-credits-crawl-line.hs-credits-crawl-title {
    font-size: clamp(2.6rem, calc(7 * var(--sv-h)), 4.4rem);
    font-weight: bold;
    color: var(--color-primary);
    letter-spacing: 0.2em;
    margin: 0.5em 0 0.2em;
}

/* Modal switch (menu ↔ settings ↔ credits …): short pop-in of the new panel. */
.start-screen-content:not(.start-screen-content-embedded) {
    animation: vf-modal-in 180ms steps(6, end) both;
}
@keyframes vf-modal-in {
    from { opacity: 0; transform: scale(0.96) translateY(6px); }
    to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
    .start-screen-content:not(.start-screen-content-embedded) { animation: none; }
}

/* Settings accordion: the opened section's rows slide in. */
details.settings-section[open] > .settings-section-list,
details.settings-section[open] > .settings-style-body {
    animation: vf-section-in 200ms steps(5, end) both;
    transform-origin: top center;
}
@keyframes vf-section-in {
    from { opacity: 0; transform: translateY(-8px) scaleY(0.92); }
    to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
    details.settings-section[open] > .settings-section-list,
    details.settings-section[open] > .settings-style-body { animation: none; }
}

/* Pilot creation: start options (galaxy / difficulty / starter kit). */
.profile-start-options {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 12px auto 4px;
    max-width: 960px;
    width: 100%;
}
.profile-start-row {
    display: grid;
    grid-template-columns: 130px minmax(0, 1fr);
    align-items: center;
    gap: 10px;
}
.profile-start-label {
    font-size: var(--font-text);
    letter-spacing: 2px;
    color: var(--faction-accent, var(--color-primary));
}
.profile-start-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}
.profile-start-chip {
    font: inherit;
    font-size: var(--font-text);
    letter-spacing: 1px;
    padding: 5px 10px;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 6%, #000);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    cursor: pointer;
}
.profile-start-chip:hover {
    border-color: var(--faction-accent, var(--color-primary));
    color: #fff;
}
.profile-start-chip.selected {
    color: #000;
    background: var(--faction-accent, var(--color-primary));
    border-color: var(--faction-accent, var(--color-primary));
}

/* Pilot creation: start galaxy card (‹ mini map · info ›). */
.profile-start-galaxy {
    align-items: center;
    gap: 12px;
    padding: 8px 10px;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 6%, #000);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
}
.profile-start-galaxy-nav {
    font: inherit;
    font-size: 20px;
    line-height: 1;
    width: 28px;
    height: 84px;
    color: var(--faction-accent, var(--color-primary));
    background: transparent;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    cursor: pointer;
}
.profile-start-galaxy-nav:hover {
    color: #000;
    background: var(--faction-accent, var(--color-primary));
}
.profile-start-galaxy-map {
    flex: 0 0 auto;
    background: #000;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--galaxy-color) 45%, transparent);
}
.profile-start-galaxy-map .edges line {
    stroke: color-mix(in srgb, var(--galaxy-color) 55%, transparent);
    stroke-width: 1;
}
.profile-start-galaxy-map .dots rect { fill: var(--galaxy-color); }
.profile-start-galaxy-map .dots rect.is-start { fill: #fff; }
.profile-start-galaxy-info {
    display: flex;
    flex-direction: column;
    gap: 5px;
    flex: 1 1 auto;
    min-width: 0;
}
.profile-start-galaxy-name {
    font-size: var(--font-h2);
    letter-spacing: 2px;
    color: #fff;
}
.profile-start-galaxy-home {
    font-size: var(--font-small);
    letter-spacing: 1px;
    color: var(--faction-accent, var(--color-primary));
    margin-left: 6px;
}
.profile-start-galaxy-ruler {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: var(--font-text);
    letter-spacing: 1px;
}
.profile-start-galaxy-ruler > span:first-child,
.profile-start-galaxy-ruler > svg,
.profile-start-galaxy-ruler > img {
    width: 20px;
    height: 20px;
}
.profile-start-galaxy-meta {
    font-size: var(--font-small);
    letter-spacing: 1px;
}

/* Pilot name step: only ship + start galaxy, both larger. */
.profile-selection-name-mode.is-name-step .profile-faction-lore,
.profile-selection-name-mode.is-name-step .profile-faction-facts {
    display: none;
}
.profile-selection-name-mode.is-name-step .profile-faction-info-row {
    display: flex;
    justify-content: center;
}
.profile-selection-name-mode.is-name-step .profile-faction-preview {
    flex: 1 1 auto;
}
.profile-selection-name-mode.is-name-step .profile-faction-ship {
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}
.profile-selection-name-mode.is-name-step .profile-start-galaxy-nav {
    width: 34px;
    font-size: 24px;
}

