}
/* Stage stepper in the planet card (1..3 + boss), between stats and buttons. */
.gm-stage-stepper {
    display: flex;
    align-items: center;
    padding: 30px 8px 22px;
}
.gm-stage-stepper:empty { display: none; }
.gm-stage-stepper .gm-sector-stage {
    position: relative;
    flex: 0 0 34px;
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    padding: 5px;
    background: #05060a;
    border: var(--ui-border-width, 2px) solid #6b7690;
    color: #cfd6e6;
    image-rendering: pixelated;
    /* Dark outline so the tiles read on top of the planet. */
    box-shadow: 0 0 0 2px #05060a;
}
.gm-stage-stepper .gm-sector-stage svg {
    width: 100%;
    height: 100%;
}
.gm-stage-stepper .gm-stage-open { fill: currentColor; }
.gm-stage-link {
    flex: 1 1 auto;
    height: 0;
    border-top: var(--ui-border-width, 2px) dashed #3a4256;
}
.gm-stage-link.is-walked { border-top: var(--ui-border-width, 2px) solid #5fd37a; }
.gm-stage-tag {
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translate(-50%, 4px);
    color: inherit;
    font-size: var(--font-text);
    line-height: 13px;
    letter-spacing: 0.08em;
    white-space: nowrap;
}
