.gm-stage-stepper .gm-sector-stage.is-done svg { outline: var(--ui-border-width, 2px) solid #05060a; }
.gm-stage-stepper .gm-stage-done-bg { fill: #5fd37a; }
.gm-stage-stepper .gm-stage-check { fill: #05060a; }
.gm-stage-stepper .gm-sector-stage.is-boss:not(.is-done) {
    border-color: #ff5a3c;
    color: #ff5a3c;
}
