    filter:
        drop-shadow(4px 0 0 #05060a) drop-shadow(-4px 0 0 #05060a)
        drop-shadow(0 4px 0 #05060a) drop-shadow(0 -4px 0 #05060a) !important;
}
html .start-screen-menu-clustered .menu-item-icon { overflow: visible; }

/* Main menu focus: glow only around the icon; the label stays crisp
   (accent colour, no text glow — the pixel text glow made it unreadable). */
html .start-screen-menu-clustered .menu-item,
html .start-screen-menu-clustered .menu-item.selected,
html .start-screen-menu-clustered .menu-item.selected .menu-item-label,
html .start-screen-menu-clustered .menu-item.selected .menu-item-desc {
