}

/* Top-bar resources: own frame on a black background (all layouts). */
html .home-station-overlay .hs-topbar .hs-topbar-res,
html .home-station-overlay .hs-topbar.is-res-stacked .hs-topbar-res {
    padding: 6px 12px;
    background: #000;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, transparent);
    box-shadow: none;
    box-sizing: border-box;
}
html .home-station-overlay .hs-topbar.is-res-grid .hs-topbar-res { padding: 4px 10px; }

/* Top-bar resource icons: exact 2× of their 16 px grid (30 px scaling made
   the pixels uneven and blurry), crisp nearest-neighbour, full strength. */
html .home-station-overlay .hs-topbar .hs-topbar-res .hs-credit-icon,
html .home-station-overlay .hs-topbar .hs-topbar-res .hs-credit-icon img,
html .home-station-overlay .hs-topbar .hs-topbar-res .hs-credit-icon canvas {
    width: 32px !important;
    height: 32px !important;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    /* Stronger colours on the black strip. */
    filter: saturate(1.9) contrast(1.2) brightness(1.15) !important;
    opacity: 1;
}
/* Empty resources: dim only the number, not the icon. */
html .home-station-overlay .hs-topbar .hs-topbar-res .hs-res-empty { opacity: 1; }
html .home-station-overlay .hs-topbar .hs-topbar-res .hs-res-empty .hs-credit-amount { opacity: 0.5; }
/* Compact grid: exact 1× (16 px) instead of 18 px. */
html .home-station-overlay .hs-topbar.is-res-grid .hs-topbar-res .hs-credit-icon,
html .home-station-overlay .hs-topbar.is-res-grid .hs-topbar-res .hs-credit-icon img,
html .home-station-overlay .hs-topbar.is-res-grid .hs-topbar-res .hs-credit-icon canvas {
    width: 16px !important;
    height: 16px !important;
}

/* Hangar parts: on/off parts get a switch, single-slot kinds a radio button. */
.hs-hangar-part-switch {
    position: relative;
    flex: 0 0 auto;
    width: 34px;
    height: 18px;
    margin-left: auto;
    box-sizing: border-box;
    background: #05060a;
    border: var(--ui-border-width, 2px) solid #4a5268;
}
.hs-hangar-part-switch > span {
    position: absolute;
    top: 2px;
    left: 2px;
    width: 10px;
    height: 10px;
    background: #6b7690;
    transition: left 0.12s steps(3, end), background 0.12s;
}
.hs-hangar-part-switch.is-on {
    border-color: var(--faction-accent, var(--color-primary));
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, #05060a);
}
.hs-hangar-part-switch.is-on > span {
    left: 18px;
    background: var(--faction-accent, var(--color-primary));
}
.hs-hangar-part-radio {
    position: relative;
    flex: 0 0 auto;
    width: 18px;
    height: 18px;
    margin-left: auto;
    box-sizing: border-box;
    border: var(--ui-border-width, 2px) solid #4a5268;
    background: #05060a;
    /* Pixel "circle": corners cut. */
    clip-path: polygon(4px 0, calc(100% - 4px) 0, calc(100% - 4px) 2px, calc(100% - 2px) 2px, calc(100% - 2px) 4px, 100% 4px, 100% calc(100% - 4px), calc(100% - 2px) calc(100% - 4px), calc(100% - 2px) calc(100% - 2px), calc(100% - 4px) calc(100% - 2px), calc(100% - 4px) 100%, 4px 100%, 4px calc(100% - 2px), 2px calc(100% - 2px), 2px calc(100% - 4px), 0 calc(100% - 4px), 0 4px, 2px 4px, 2px 2px, 4px 2px);
}
.hs-hangar-part-radio.is-on { border-color: var(--faction-accent, var(--color-primary)); }
.hs-hangar-part-radio.is-on::after {
    content: '';
    position: absolute;
    inset: 3px;
    background: var(--faction-accent, var(--color-primary));
}

/* Tooltips: multi-line info (name, what it does, stats). */
.ui-tooltip {
    white-space: pre-line;
    max-width: min(420px, calc(100vw - 16px));
    text-align: left;
}
/* Rich tooltip: heading + label/value rows + note. */
.ui-tooltip.ui-tooltip-rich {
    white-space: normal;
    min-width: 320px;
    max-width: min(460px, calc(calc(100 * var(--sv-w)) - 16px));
    max-height: calc(calc(100 * var(--sv-h)) - 16px);
    overflow: visible;
    display: grid;
    gap: 8px;
    padding: 14px 18px;
    font-size: calc(var(--font-text) + 3px);
    line-height: 1.35;
}
.ui-tooltip.ui-tooltip-rich .ui-tooltip-head { font-size: calc(var(--font-text) + 5px); }
.ui-tooltip-head {
    color: var(--faction-accent, var(--color-primary));
    letter-spacing: 0.08em;
    padding-bottom: 4px;
    margin-bottom: 2px;
    border-bottom: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
}
/* Blueprint tooltips: a small schematic badge before the title, same grid-line
   motif as the blueprint storage cells, instead of a "BP" text prefix. */
.ui-tooltip-bp-badge {
    display: inline-block;
    flex-shrink: 0;
    width: 18px;
    height: 18px;
    margin-right: 6px;
    vertical-align: middle;
    border: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, transparent);
    background:
        repeating-linear-gradient(0deg, transparent 0 3px, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent) 3px 4px),
        repeating-linear-gradient(90deg, transparent 0 3px, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent) 3px 4px),
        #05060a;
}
.ui-tooltip-head.has-bp { display: flex; align-items: center; }
/* Item-preview tooltips (hover over a storage/inventory cell): icon left, title to its right —
   without this the icon span and title span, both plain block-flow children, stack vertically. */
.ui-tooltip-head.has-item { display: flex; align-items: center; gap: 8px; }

/* Slot/part size schematic (SIZE_FIT tooltip row, see ui-tooltip.js): the slot's own footprint
   as an outlined box, the part's footprint nested inside it as a filled box — shows how much of
   the slot the part actually uses at a glance, instead of two "SLOT SIZE: S" text rows. */
.ui-tooltip-sizefit { display: flex; align-items: center; gap: 10px; }
.ui-tooltip-sizefit-schema { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; }
.ui-tooltip-sizefit-slot {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    border: var(--ui-border-width, 2px) solid var(--faction-accent, var(--color-primary));
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 10%, transparent);
}
.ui-tooltip-sizefit-part { background: var(--faction-accent, var(--color-primary)); }
/* With an actual part icon (has-icon), the box just frames it — no flat fill color underneath. */
.ui-tooltip-sizefit-part.has-icon {
    background-color: transparent;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    image-rendering: pixelated;
}
.ui-tooltip-sizefit-schema.is-slot-S .ui-tooltip-sizefit-slot { width: 24px; height: 24px; }
.ui-tooltip-sizefit-schema.is-slot-M .ui-tooltip-sizefit-slot { width: 32px; height: 32px; }
.ui-tooltip-sizefit-schema.is-slot-L .ui-tooltip-sizefit-slot { width: 40px; height: 40px; }
.ui-tooltip-sizefit-schema.is-part-S .ui-tooltip-sizefit-part { width: 14px; height: 14px; }
.ui-tooltip-sizefit-schema.is-part-M .ui-tooltip-sizefit-part { width: 22px; height: 22px; }
.ui-tooltip-sizefit-schema.is-part-L .ui-tooltip-sizefit-part { width: 32px; height: 32px; }
.ui-tooltip-sizefit-label { font-size: 0.85em; opacity: 0.85; letter-spacing: 0.04em; }
.ui-tooltip-row { display: flex; justify-content: space-between; gap: 12px; }
.ui-tooltip-key { opacity: 0.6; }
.ui-tooltip-val { text-align: right; }
.ui-tooltip-note { opacity: 0.7; font-size: 0.9em; margin-top: 2px; text-transform: none; }
.ui-tooltip-html { display: grid; gap: 8px; }
.ui-tooltip-html .ui-tooltip-stats {
    display: flex;
    gap: 10px;
    align-items: center;
    flex-wrap: wrap;
}
.ui-tooltip-html .ui-tip-chip {
    display: inline-flex;
    gap: 6px;
    align-items: center;
}
.ui-tooltip-html .ui-tip-chip img {
    width: 16px;
    height: 16px;
    image-rendering: pixelated;
    flex: 0 0 auto;
}
.ui-tooltip-html .ui-tooltip-affordance {
    margin-left: auto;
    letter-spacing: 1px;
    font-weight: bold;
}
.ui-tooltip-stats.is-ok .ui-tooltip-affordance { color: var(--faction-accent, var(--color-primary)); }
.ui-tooltip-stats.is-short .ui-tooltip-affordance { color: color-mix(in srgb, #ff6a4a 80%, #fff); }

/* Weapon rows: the icon is the drag handle. The row is a <button>, so the
   row itself switches cursor while the icon is hovered. */
.hs-hangar-part-icon.is-drag-handle { cursor: grab; touch-action: none; }
.hs-hangar-part:has(.hs-hangar-part-icon.is-drag-handle:hover),
.hs-hangar-part .hs-hangar-part-icon.is-drag-handle * { cursor: grab; }
body.hs-part-grabbing .hs-hangar-part-icon.is-drag-handle { cursor: grabbing; }

/* No idle animation on equipped sidebar icons: anything animating inside
   their 12-layer drop-shadow glow re-renders that filter every frame and
   made the whole hangar stutter. */

/* Live preview: right-drag pans. */
#hsHangarPreviewViewport.is-panning, #hsHangarPreviewViewport.is-panning * { cursor: grabbing !important; }

/* Ability effects: penalties in red; hover preview change on the SPEED tile. */
.hs-hangar-weapon-stat.is-bad { color: var(--color-danger, #ff4d4d); }
.hs-stat-delta { margin-left: 6px; font-size: var(--font-text); }
.hs-stat-delta.is-up { color: #6dff8a; }
.hs-stat-delta.is-down { color: var(--color-danger, #ff4d4d); }
.hs-hangar-weapon-stats.is-desc {
    font-size: var(--font-text);
    opacity: 0.6;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
}

/* Parts sections: collapsible header with a slot strip (filled = assigned). */
.hs-hangar-parts-title[data-part-section-toggle] { cursor: pointer; user-select: none; }
/* flex:1 1 auto + min-width:0 so the label truncates instead of overflowing/overlapping the
   fixed-size icon, slot strip and caret that share this row — a long section label used to run
   under the slot-strip icons since nothing here could shrink first. */
.hs-hangar-parts-label { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.hs-hangar-parts-caret { font-size: var(--font-small); color: var(--color-text-secondary);}
.hs-hangar-parts-section.is-collapsed > .hs-hangar-parts-grid { display: none; }
.hs-section-slots {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-left: auto;
    letter-spacing: 0;
}
.hs-section-slot {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    border: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--kind-color, var(--color-primary)) 45%, transparent);
    background: #05060a;
}
.hs-section-slot.is-filled {
    border-style: solid;
    border-color: var(--kind-color, var(--color-primary));
    background: color-mix(in srgb, var(--kind-color, var(--color-primary)) 18%, #05060a);
    cursor: grab;
}
.hs-section-slot.is-filled:hover { background: color-mix(in srgb, var(--color-danger, #ff4d4d) 30%, #05060a); }
.hs-section-slot.is-filled.is-pulling { opacity: .35; }
.hs-section-slot img { display: block; }
.hs-section-slot-count { margin-left: 4px; font-size: var(--font-text); color: var(--kind-color, var(--color-text-secondary)); }
.hs-section-slot-count.is-full { color: var(--color-text-secondary); }
.hs-section-slots.is-denied { animation: hs-slots-denied 0.35s steps(2, end); }
@keyframes hs-slots-denied {
    0%, 100% { transform: translateX(0); }
    25% { transform: translateX(-3px); }
    75% { transform: translateX(3px); }
}

/* Hangar head: slots · areas · stats in one row. Area tiles are compact:
   pixel-ship icon (label in tooltip), switch, level, upgrade button. */
/* All areas in one frame (like the slot / stat groups); tiles frameless. */
.hs-hangar-stats.is-row .hs-hangar-areas {
    display: flex;
    align-items: center;
    gap: 14px;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 6%, transparent);
}
.hs-hangar-stats.is-row .hs-area-tile {
    display: flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
    border: none;
    background: none;
}
.hs-area-lv { font: inherit; font-size: 0.85em; font-weight: bold; border: none; cursor: pointer; display: inline-flex; align-items: center; gap: 3px; }
.hs-area-lv.is-max { cursor: default; }
.hs-area-lv[disabled] { cursor: not-allowed; opacity: 0.55; }
.hs-area-lv-up { font-size: var(--font-small); }
button.hs-area-lv:not([disabled]):hover { filter: brightness(1.3); }
.hs-hangar-stats.is-row .hs-area-tile .hs-area-name { gap: 5px; }
.hs-hangar-stats.is-row .hs-area-tile .hs-area-btn { padding: 3px 7px; font-size: var(--font-text); }
.hs-hangar-stats.is-row .hs-area-tile .hs-area-costs { display: none; }
.hs-area-icon { display: inline-flex; line-height: 0; }
.hs-area-icon svg { display: block; }
.hs-area-icon .is-dim { fill: color-mix(in srgb, var(--color-text-secondary) 45%, transparent); }
.hs-area-icon .is-lit { fill: var(--faction-accent, var(--color-primary)); }
.hs-area-tile.is-off .hs-area-icon .is-lit { fill: var(--color-text-secondary); }

/* Parts section headers: bigger label, type glyph and slot boxes. */
.hs-hangar-parts-title { font-size: var(--font-h2); padding-bottom: 5px; }
.hs-hangar-parts-title .hs-slot-glyph { width: 22px; height: 22px; }
/* Same footprint as the section's own kind icon (.hs-hangar-parts-icon, forced to 24px in
   part-21.css) — it was 36px here, visibly bigger than everything else on this row. */
.hs-section-slot { width: 24px; height: 24px; overflow: hidden; flex: 0 0 auto; }
.hs-section-slot img,
.hs-section-slot .hs-pixel { width: 16px; height: 16px; max-width: 100%; max-height: 100%; image-rendering: pixelated; }
.hs-section-slot-count { font-size: var(--font-text); }
.hs-hangar-parts-caret { font-size: var(--font-h2); line-height: 1; margin-left: 8px; color: var(--kind-color, var(--color-primary)); }

/* Parts section headers: pixel sprite + label in the section's colour. */
.hs-hangar-parts-icon { display: inline-flex; flex: 0 0 auto; line-height: 0; }
.hs-hangar-parts-icon img { display: block; }
.hs-hangar-parts-section .hs-hangar-parts-title {
    color: var(--kind-color, var(--color-primary));
    border-bottom-color: color-mix(in srgb, var(--kind-color, var(--color-primary)) 45%, transparent);
    font-family: 'Silkscreen', var(--ui-font-family, monospace);
    font-size: var(--font-h2);
    letter-spacing: 2px;
    text-shadow: 2px 2px 0 #05060a;
}

/* Part stat lines: each value coloured by its stat type (icon tinted to match). */
.hs-hangar-weapon-stat[data-stat="damage"]    { color: #ff6a4a; }
.hs-hangar-weapon-stat[data-stat="shotspeed"] { color: #4ad8ff; }
.hs-hangar-weapon-stat[data-stat="firerate"]  { color: #ffa04a; }
.hs-hangar-weapon-stat[data-stat="speed"]     { color: #6dff8a; }
.hs-hangar-weapon-stat[data-stat="armor"]     { color: #7aa8ff; }
.hs-hangar-weapon-stat[data-stat="energy"]    { color: #ffd24a; }
.hs-hangar-weapon-stat.is-bad { color: var(--color-danger, #ff4d4d); }
.hs-hangar-weapon-stat.is-good { color: #6dff8a; }
/* Downgrade / upgrade vs equipped: number itself lights up, not only the row. */
.hs-hangar-weapon-stat.is-bad .hs-stat-num {
    color: #ff6a5d;
    text-shadow: 0 0 0 1px #05060a, 0 0 8px color-mix(in srgb, #ff4d4d 70%, transparent);
    font-weight: 700;
}
.hs-hangar-weapon-stat.is-good .hs-stat-num {
    color: #6dff8a;
    text-shadow: 0 0 0 1px #05060a, 0 0 8px color-mix(in srgb, #6dff8a 70%, transparent);
    font-weight: 700;
}
.hs-hangar-weapon-stat .hs-stat-worse {
    margin-left: 3px;
    color: #ff6a5d;
    font-size: 0.85em;
}
.hs-hangar-weapon-stat .hs-stat-better {
    margin-left: 3px;
    color: #6dff8a;
    font-size: 0.85em;
}
/* Compact tooltips: same up/down punch on compared weapon numbers. */
.ui-tooltip-stat.is-bad .hs-stat-num {
    color: #ff6a5d;
    text-shadow: 0 0 6px color-mix(in srgb, #ff4d4d 70%, transparent);
    font-weight: 700;
}
.ui-tooltip-stat.is-good .hs-stat-num {
    color: #6dff8a;
    text-shadow: 0 0 6px color-mix(in srgb, #6dff8a 70%, transparent);
    font-weight: 700;
}
.ui-tooltip-stat .hs-stat-worse { margin-left: 2px; color: #ff6a5d; font-size: 0.85em; }
.ui-tooltip-stat .hs-stat-better { margin-left: 2px; color: #6dff8a; font-size: 0.85em; }
.hs-equip-compare-stats { display: block; margin-top: 6px; }
.hs-line-desc {
    display: block;
    margin-top: 2px;
    opacity: 0.75;
    font-size: var(--font-text);
}
/* Stat raised by the ship class / faction: bright, glowing, boxed, ▲ marker. */
.hs-hangar-weapon-stat.is-boosted {
    color: #fff3c4;
    font-weight: 700;
    padding: 1px 4px 1px 2px;
    border: var(--ui-border-width, 2px) solid #ffd24a;
    background: rgba(255, 210, 74, 0.14);
    text-shadow: 0 0 1px #05060a, 0 0 6px rgba(255, 210, 74, 0.8);
}
.hs-stat-boost { color: #ffd24a; font-size: 0.8em; margin-left: 1px; }

/* Galaxy map: node labels, badges and icons are never text-selectable
   (dragging / double-clicking the map selected them). Inputs stay editable. */
.galaxy-map-overlay,
.galaxy-map-overlay *,
.galaxy-map-embedded,
.galaxy-map-embedded *,
.galaxy-map-svg,
.galaxy-map-svg * {
    -webkit-user-select: none;
    user-select: none;
    -webkit-user-drag: none;
}
:is(.galaxy-map-overlay, .galaxy-map-embedded) :is(input, textarea, [contenteditable="true"]) {
    -webkit-user-select: text;
    user-select: text;
}

/* Hangar parts list: bigger part name (stats line keeps its own size). */
.hs-hangar-part .hs-hangar-part-title {
    font-size: var(--font-h2);
}

/* Parts section headers: reserve icon + row height so nothing jumps while
   the pixel sprites / Silkscreen font load on refresh. */
.hs-hangar-parts-icon { width: 32px; height: 32px; }
.hs-hangar-parts-icon img { width: 32px; height: 32px; }
.hs-hangar-parts-section .hs-hangar-parts-title { min-height: 38px; box-sizing: border-box; }
/* More vertical air between the collapsible sections and their content. */
.hs-hangar-parts-section { margin-top: 14px; }
.hs-hangar-parts-section:first-child { margin-top: 4px; }
.hs-hangar-parts-section .hs-hangar-parts-title { margin-bottom: 8px; }
.hs-hangar-parts-section > .hs-hangar-parts-grid { padding-bottom: 6px; }

/* Replay boot intro from the main menu footer */
.ui-intro-btn {
    font-family: var(--ui-font-family);
    font-size: var(--font-text);
    letter-spacing: 0.12em;
    color: var(--color-text-secondary);
    background: color-mix(in srgb, var(--color-background) 70%, transparent);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 45%, transparent);
    padding: 2px 8px;
    cursor: pointer;
    line-height: 1.2;
}
.ui-intro-btn:hover,
.ui-intro-btn:focus-visible {
    color: var(--color-primary);
    border-color: var(--color-primary);
}
/* ? + INTRO side by side; hidden until hovered/focused (space stays reserved) */
.ui-menu-util-row {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    min-height: 22px;
    margin: 4px auto 6px;
    opacity: 0;
    transition: opacity 150ms ease;
}
.ui-menu-util-row:hover,
.ui-menu-util-row:focus-within {
    opacity: 1;
}
.ui-menu-util-row > .ui-controls-show-btn {
    margin: 0;
}
/* Dev hint on its own line under the hover buttons */
.ui-menu-util-row > .start-screen-footer {
    flex-basis: 100%;
    margin: 0;
}

/* ── Retro skin for the main start menu ─────────────────────────────── */
.start-screen-content.start-screen-retro {
    --retro-ink: var(--color-primary, #ff5a1f);
    --retro-dim: color-mix(in srgb, var(--retro-ink) 35%, #000);
    font-family: 'Silkscreen', var(--ui-font-family);
    border: 0;
    padding: 22px 30px 14px;
    backdrop-filter: none;
    /* Chunky double pixel frame with notched corners */
    box-shadow:
        0 0 0 4px var(--retro-ink),
        0 0 0 8px #05060a,
        0 0 0 12px var(--retro-dim),
        12px 12px 0 12px rgba(0, 0, 0, 0.7) !important;
    image-rendering: pixelated;
}
.start-screen-content.start-screen-retro::after {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 5;
}
.start-screen-retro .start-screen-title {
    font-family: 'Silkscreen', var(--ui-font-family);
    font-weight: 700;
    font-size: clamp(52px, calc(7.8 * var(--sv-w)), 86px);
    letter-spacing: 0.08em;
    color: var(--retro-ink);
    text-shadow: 4px 4px 0 var(--retro-dim), 8px 8px 0 #000;
    filter: none;
    margin-top: clamp(12px, calc(2.4 * var(--sv-h)), 32px);
    margin-bottom: 2px;
}
.start-screen-retro .start-screen-subtitle {
    font-family: 'Silkscreen', var(--ui-font-family);
    font-size: clamp(16px, calc(1.9 * var(--sv-w)), 23px);
    letter-spacing: 0.3em;
    color: var(--color-text-secondary);
}
.start-screen-retro .start-screen-subtitle::after {
    content: '_';
    animation: vf-retro-blink 1s steps(1) infinite;
}
.start-screen-retro .start-screen-profile {
    font-family: 'Silkscreen', var(--ui-font-family);
    border-style: solid;
    border-radius: 0;
}
.start-screen-retro .menu-item {
    position: relative;
    border-radius: 0;
    transition: none;
}
.start-screen-retro .menu-item-label {
    font-family: 'Silkscreen', var(--ui-font-family);
    font-size: clamp(16px, calc(2 * var(--sv-w)), 22px);
    letter-spacing: 0.12em;
}
.start-screen-retro .menu-item .menu-pixel-icon {
    filter: none !important;
    image-rendering: pixelated;
}
/* Selected entry: hard inverted bar + blinking ▶ caret, no soft glow */
.start-screen-retro .menu-item.selected {
    background: color-mix(in srgb, var(--retro-ink) 18%, transparent) !important;
    box-shadow: inset 4px 0 0 var(--retro-ink) !important;
    text-shadow: none !important;
}
.start-screen-retro .menu-item.selected .menu-item-label {
    color: var(--retro-ink);
    text-shadow: 2px 2px 0 #000;
}
.start-screen-retro .menu-item .menu-item-label::before {
    content: '\25B6\00a0';
    color: var(--retro-ink);
    visibility: hidden;
}
.start-screen-retro .menu-item.selected .menu-item-label::before {
    visibility: visible;
    animation: vf-retro-blink 0.6s steps(1) infinite;
}
.start-screen-retro .ui-intro-btn,
.start-screen-retro .ui-controls-show-btn,
.start-screen-retro .dev-mode-hint,
.start-screen-retro .start-screen-instructions {
    font-family: 'Silkscreen', var(--ui-font-family);
}
@keyframes vf-retro-blink { 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
    .start-screen-retro .menu-item.selected .menu-item-label::before,
    .start-screen-retro .start-screen-subtitle::after { animation: none; }
}
/* Retro menu: no zoom-in or label size tweening — nothing may shift on refresh */
.start-screen-content.start-screen-retro {
    animation: none !important;
    transform: none !important;
}
.start-screen-retro .menu-item-label,
.start-screen-retro .menu-item.selected .menu-item-label {
    transition: none !important;
    font-size: clamp(16px, calc(2 * var(--sv-w)), 22px) !important;
}

/* ── Start screen: recent pilots scoreboard (right of the menu) ─────── */
.start-menu-row {
    display: flex;
    align-items: flex-start;
    justify-content: center;
    gap: clamp(16px, calc(3 * var(--sv-w)), 40px);
}
.start-menu-row > .start-screen-menu-clustered {
    margin-left: 0;
    margin-right: 0;
}
.start-scoreboard {
    width: min(420px, 100%);
    min-width: 360px;
    flex-shrink: 0;
    margin-top: clamp(2px, calc(0.6 * var(--sv-h)), 8px);
    padding: 10px 16px;
    background: #05060a;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary, #ff5a1f) 70%, #000);
    font-family: 'Silkscreen', var(--ui-font-family);
    text-transform: uppercase;
}
.start-scoreboard-title {
    color: var(--color-primary, #ff5a1f);
    letter-spacing: 0.2em;
    font-size: var(--font-h2);
    text-align: center;
    text-shadow: 2px 2px 0 #000;
    padding-bottom: 6px;
    border-bottom: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--color-primary, #ff5a1f) 40%, transparent);
}
.start-scoreboard-head,
.start-scoreboard-row {
    display: grid;
    grid-template-columns: 22px 28px minmax(0, 1fr) max-content;
    align-items: center;
    gap: 10px;
}
.start-scoreboard-head {
    padding: 6px 4px 2px;
    font-size: var(--font-small);
    letter-spacing: 0.15em;
    color: var(--color-text-secondary);
}
.start-scoreboard-head span:last-child { text-align: right; }
.start-scoreboard-list {
    list-style: none;
    margin: 0;
    padding: 0;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--color-primary, #ff5a1f) transparent;
}
.start-scoreboard-row {
    padding: 5px 4px;
    font-size: var(--font-text);
    letter-spacing: 0.08em;
    color: var(--color-text, #eee);
}
.start-scoreboard-row:nth-child(odd) { background: rgba(255, 255, 255, 0.03); }
.start-scoreboard-row.is-active {
    background: color-mix(in srgb, var(--color-primary, #ff5a1f) 18%, transparent);
    box-shadow: inset 3px 0 0 var(--color-primary, #ff5a1f);
}
.start-scoreboard-rank { color: var(--color-text-secondary); text-align: right; }
.start-scoreboard-row:nth-child(1) .start-scoreboard-rank { color: #ffd23f; }
.start-scoreboard-row:nth-child(2) .start-scoreboard-rank { color: #c8d0dc; }
.start-scoreboard-row:nth-child(3) .start-scoreboard-rank { color: #d08a4a; }
.start-scoreboard-emblem { display: flex; }
.start-scoreboard-emblem img { width: 24px; height: 24px; image-rendering: pixelated; }
.start-scoreboard-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.start-scoreboard-score {
    text-align: right;
    color: var(--color-primary, #ff5a1f);
    font-variant-numeric: tabular-nums;
}
.start-scoreboard-empty {
    padding: 14px 4px;
    text-align: center;
    font-size: var(--font-text);
    color: var(--color-text-secondary);
}
@media (max-width: 800px) {
    .start-scoreboard { min-width: 0; }
}
/* Menu keeps its full width next to the scoreboard; labels never clip. */
.start-menu-row > .start-screen-menu-clustered { flex: 0 0 auto; width: max-content; min-width: 280px; }
.start-menu-row .menu-item-label { white-space: nowrap; overflow: visible; text-overflow: clip; }

.start-screen-content.start-screen-retro {
    width: min(calc(96 * var(--cw)), calc(980px * var(--zk))) !important;
    max-width: min(calc(96 * var(--cw)), calc(980px * var(--zk))) !important;
    padding-left: clamp(24px, calc(4 * var(--sv-w)), 48px);
    padding-right: clamp(24px, calc(4 * var(--sv-w)), 48px);
}
.start-screen-retro .start-menu-row {
    gap: clamp(24px, calc(4 * var(--sv-w)), 56px);
}
.start-screen-retro .start-scoreboard { flex: 1 1 380px; min-width: 0;}
.start-scoreboard-name { text-align: left; }
.start-scoreboard-head span:nth-child(3) { text-align: left; }
.start-scoreboard-row.is-empty { color: var(--color-text-secondary); opacity: 0.45; }
.start-scoreboard-row.is-empty .start-scoreboard-rank { color: inherit; }
.start-scoreboard-row .start-scoreboard-emblem { min-height: 24px; }
.start-scoreboard-list { max-height: none; }
.start-scoreboard-row.is-pickable { cursor: pointer; }
.start-scoreboard-row.is-pickable:not(.is-active):hover,
.start-scoreboard-row.is-pickable:not(.is-active):focus-visible {
    background: color-mix(in srgb, var(--color-primary, #ff5a1f) 10%, transparent);
    box-shadow: inset 3px 0 0 color-mix(in srgb, var(--color-primary, #ff5a1f) 50%, transparent);
    outline: none;
}
.start-scoreboard-row.is-active .start-scoreboard-name { color: var(--color-primary, #ff5a1f); }

/* ── Start screen as a machine terminal: pixel housing around a screen ─
   GLXEE look: flat colors, hard pixel shadows, notched corners, no blur. */
.start-screen-content.start-screen-retro {
    --bezel: 32px;
    --hull: #1c1f26;
    --hull-lit: #2c313b;
    --hull-dark: #0c0e12;
    overflow: visible !important;
    isolation: isolate;
    border-radius: 0;
    background: #05060a !important;
    /* Screen glass: hard inner pixel bevel + orange trim line */
    box-shadow:
        inset 0 0 0 2px var(--retro-ink),
        inset 0 0 0 6px #05060a,
        inset 0 0 0 8px var(--retro-dim),
        inset 0 0 60px color-mix(in srgb, var(--retro-ink) 8%, transparent) !important;
}
.start-screen-content.start-screen-retro::after {
    border-radius: 0;
    background: repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.28) 0 1px, transparent 1px 3px);
}
.start-screen-content.start-screen-retro::before,
.home-station-overlay::after {
    content: 'GLX-OS \25AA  NAV TERMINAL \25AA  MK-II';
    position: absolute;
    inset: calc(var(--bezel) * -1);
    z-index: -1;
    pointer-events: none;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    font-family: 'Silkscreen', var(--ui-font-family);
    font-size: var(--font-text);
    font-weight: 700;
    letter-spacing: 0.3em;
    line-height: var(--bezel);
    color: var(--retro-ink);
    text-shadow: 2px 2px 0 #000;
    image-rendering: pixelated;
    /* Notched 8-bit corners */
    clip-path: polygon(
        16px 0, calc(100% - 16px) 0, calc(100% - 16px) 8px, calc(100% - 8px) 8px, calc(100% - 8px) 16px, 100% 16px,
        100% calc(100% - 16px), calc(100% - 8px) calc(100% - 16px), calc(100% - 8px) calc(100% - 8px), calc(100% - 16px) calc(100% - 8px), calc(100% - 16px) 100%,
        16px 100%, 16px calc(100% - 8px), 8px calc(100% - 8px), 8px calc(100% - 16px), 0 calc(100% - 16px),
        0 16px, 8px 16px, 8px 8px, 16px 8px);
    background:
        /* square pixel bolts */
        linear-gradient(var(--retro-ink) 0 0) 20px 20px / 6px 6px no-repeat,
        linear-gradient(var(--retro-ink) 0 0) calc(100% - 20px) 20px / 6px 6px no-repeat,
        linear-gradient(var(--retro-ink) 0 0) 20px calc(100% - 20px) / 6px 6px no-repeat,
        linear-gradient(var(--retro-ink) 0 0) calc(100% - 20px) calc(100% - 20px) / 6px 6px no-repeat,
        /* status lights, top right */
        linear-gradient(var(--retro-ink) 0 0) calc(100% - 48px) 12px / 8px 8px no-repeat,
        linear-gradient(#3dff6a 0 0) calc(100% - 62px) 12px / 8px 8px no-repeat,
        linear-gradient(var(--hull-dark) 0 0) calc(100% - 76px) 12px / 8px 8px no-repeat,
        /* vent slots, top left */
        repeating-linear-gradient(90deg, var(--hull-dark) 0 4px, transparent 4px 8px) 40px 12px / 96px 8px no-repeat,
        /* orange hazard strips along the bottom */
        repeating-linear-gradient(90deg, var(--retro-ink) 0 8px, var(--hull-dark) 8px 16px) 40px calc(100% - 12px) / 96px 8px no-repeat,
        repeating-linear-gradient(90deg, var(--retro-ink) 0 8px, var(--hull-dark) 8px 16px) calc(100% - 40px) calc(100% - 12px) / 96px 8px no-repeat,
        /* flat panel with hard light/dark pixel bevel */
        linear-gradient(var(--hull-lit) 0 0) 0 0 / 100% 4px no-repeat,
        linear-gradient(var(--hull-lit) 0 0) 0 0 / 4px 100% no-repeat,
        linear-gradient(var(--hull-dark) 0 0) 0 100% / 100% 4px no-repeat,
        linear-gradient(var(--hull-dark) 0 0) 100% 0 / 4px 100% no-repeat,
        var(--hull);
    /* Only the frame paints; the screen stays visible through the hole. */
    --hole: linear-gradient(#000 0 0) var(--bezel) var(--bezel) / calc(100% - 2 * var(--bezel)) calc(100% - 2 * var(--bezel)) no-repeat;
    -webkit-mask: var(--hole), linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask: var(--hole) exclude, linear-gradient(#000 0 0);
}

/* Profiles page inside the terminal screen */
.start-screen-retro .start-screen-profiles-body {
    width: 100%;
    max-height: min(calc(56 * var(--ch)), calc(520px * var(--zk)));
    overflow-y: auto;
    text-align: left;
}
/* Profiles page in the terminal: compact one-line filter tabs, tidy rows. */
.start-screen-profiles-body { font-family: 'Silkscreen', var(--ui-font-family); padding: 0 4px; }
.start-screen-profiles-body .hs-menu-panel-copy { display: none; }
.start-screen-profiles-body .hs-menu-profile-filters {
    flex-wrap: nowrap;
    gap: 4px;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--retro-ink) 35%, transparent);
