/* PLAY launch: strong outline drawn inside the box (inset shadows), so the
   button keeps its size; the play triangle sits on a lit disc. */
/* Same look at rest and on hover; only the planets' colour changes. */
html body .home-station-overlay .home-station-content .hs-play-launch,
html body .home-station-overlay .home-station-content .hs-play-launch:is(:hover, .nav-focused, .active) {
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 38%, #05060a) 0%, color-mix(in srgb, var(--color-primary) 12%, #020203) 80%);
    filter: none;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 5px var(--color-primary),
        inset 0 0 22px color-mix(in srgb, var(--color-primary) 80%, transparent);
}
/* Planets: tinted in the GUI's faction colour at rest (a colour-blend layer
   masked to each planet's own shape), their real colours on hover / focus. */
.hs-play-launch-planets { opacity: 1; }
/* #hsPlayTint: SVG filter rendered by renderPlayLaunch from --color-primary. */
.hs-play-launch-filter { position: absolute; width: 0; height: 0; }
.hs-play-launch-planet {
    filter: url(#hsPlayTint) brightness(1);
    /* At rest: small, out at the edges; hover pulls them in and grows them. */
    transform: translate(calc(var(--pdx, 0px) * -1), calc(var(--pdy, 0px) * -1)) scale(0.9);
    transition: filter 0.2s, transform 0.2s;
}
.hs-play-launch-planet-0 { --pdx: 10px; --pdy: 8px; }
.hs-play-launch-planet-1 { --pdx: -10px; --pdy: 8px; }
.hs-play-launch-planet-2 { --pdx: 10px; --pdy: -8px; }
.hs-play-launch-planet-3 { --pdx: -8px; --pdy: -8px; }
.hs-play-launch-planet-4 { --pdx: 0px; --pdy: 6px; }
.hs-play-launch:is(:hover, .nav-focused) .hs-play-launch-planet { filter: none; transform: scale(1.05); }
.hs-play-launch::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 44%;
    transform: translate(-50%, -50%);
    border-radius: 50%;
    background: color-mix(in srgb, #05060a 70%, transparent);
    box-shadow: 0 0 0 3px var(--color-primary), 0 0 0 5px #05060a, 0 0 14px var(--color-primary);
    pointer-events: none;
}
.hs-play-launch-icon { border-width: 14px 0 14px 23px;}
.hs-play-launch-label { z-index: 1; font-weight: bold; }

/* Pixel look: stepped disc ring (14x14 grid, 4px cells) + stepped triangle
   (6x11 grid, 3px cells) instead of smooth circle / border triangle. */
.hs-play-launch::before,
.hs-play-launch::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 44%;
    transform: translate(-50%, -50%);
    border-radius: 0;
    box-shadow: none;
    pointer-events: none;
    clip-path: polygon(71.429% 0%, 71.429% 7.143%, 78.571% 7.143%, 78.571% 14.286%, 85.714% 14.286%, 85.714% 21.429%, 92.857% 21.429%, 92.857% 28.571%, 100% 28.571%, 100% 71.429%, 92.857% 71.429%, 92.857% 78.571%, 85.714% 78.571%, 85.714% 85.714%, 78.571% 85.714%, 78.571% 92.857%, 71.429% 92.857%, 71.429% 100%, 28.571% 100%, 28.571% 92.857%, 21.429% 92.857%, 21.429% 85.714%, 14.286% 85.714%, 14.286% 78.571%, 7.143% 78.571%, 7.143% 71.429%, 0% 71.429%, 0% 28.571%, 7.143% 28.571%, 7.143% 21.429%, 14.286% 21.429%, 14.286% 14.286%, 21.429% 14.286%, 21.429% 7.143%, 28.571% 7.143%, 28.571% 0%);
}
.hs-play-launch::before { width: 56px; height: 56px; background: var(--color-primary); }
.hs-play-launch::after { width: 48px; height: 48px; background: #05060a; }
.hs-play-launch-icon {
    width: 18px;
    height: 33px;
    border: 0;
    background: var(--color-primary);
    transform: translate(-35%, -50%);
    clip-path: polygon(0% 0%, 16.667% 0%, 16.667% 9.091%, 33.333% 9.091%, 33.333% 18.182%, 50% 18.182%, 50% 27.273%, 66.667% 27.273%, 66.667% 36.364%, 83.333% 36.364%, 83.333% 45.455%, 100% 45.455%, 100% 54.545%, 83.333% 54.545%, 83.333% 63.636%, 66.667% 63.636%, 66.667% 72.727%, 50% 72.727%, 50% 81.818%, 33.333% 81.818%, 33.333% 90.909%, 16.667% 90.909%, 16.667% 100%, 0% 100%);
    filter: none;
    z-index: 2;
}

/* Fleet: model list on the left, live in-game preview on the right. */
.hs-body:has(.hs-faction-fleets) {
