.hs-fd-fleet-stage { cursor: grab; touch-action: none; }
.hs-fd-fleet-stage.is-panning { cursor: grabbing; }
.hs-fd-fleet-stage.is-panning canvas { transition: none; }

/* Galaxy map ship panel: fill the width responsively — the ship art grows
   with the panel, and the stats become tiles in an auto-fitting grid
   (side by side when wide, wrapping when narrow) instead of long rows
   with a gulf between label and value. */
.galaxy-map-panel-ship { container-type: inline-size; }
.galaxy-map-panel-ship .gm-ship-panel-body { align-items: center; gap: 16px; }
.galaxy-map-panel-ship .gm-ship-mini-canvas {
    width: clamp(84px, 20cqi, 180px);
    height: auto;
    aspect-ratio: 84 / 120;
}
.galaxy-map-panel-ship .gm-ship-detail {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
    gap: 8px;
}
.galaxy-map-panel-ship .gm-ship-detail .stat-row {
    flex-direction: column;
    justify-content: center;
    align-items: flex-start;
    gap: 4px;
    padding: 8px 10px;
    border: var(--ui-border-width) solid var(--color-border);
    background: color-mix(in srgb, var(--color-surface) 55%, transparent);
    min-width: 0;
}
.galaxy-map-panel-ship .gm-ship-detail .stat-row:last-child {
    border-bottom: var(--ui-border-width) solid var(--color-border);
}
.galaxy-map-panel-ship .gm-ship-detail .stat-label {
    font-size: var(--font-text);
    opacity: 0.7;
    letter-spacing: 1px;
}
.galaxy-map-panel-ship .gm-ship-detail .stat-value {
    text-align: left;
    overflow-wrap: anywhere;
}
.galaxy-map-panel-ship .gm-ship-loadout { justify-content: flex-start; }
/* Narrow panel: ship art above the stats. */
@container (max-width: 420px) {
    .galaxy-map-panel-ship .gm-ship-panel-body { flex-direction: column; align-items: stretch; }
    .galaxy-map-panel-ship .gm-ship-mini-canvas { align-self: center; width: clamp(72px, 30cqi, 120px); }
}

/* Explore controls live in the map toolbar, left of TELEPORT. */
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-explore {
    grid-column: 1;
    justify-self: end;
    align-self: center;
    margin: 0;
    flex-wrap: nowrap;
    min-width: 0;
}
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-explore .gm-explore-meta {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
}
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-explore #gmExplore {
    white-space: nowrap;
}

/* Galaxy travel as a modal over the planet map (mount-play-tab.js). */
.hs-travel-modal {
    position: absolute;
    inset: 0;
    z-index: 90;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background: rgba(0, 0, 0, 0.72);
}
.hs-travel-dialog {
    position: relative;
    width: min(1400px, 100%);
    max-height: 100%;
    overflow: auto;
    box-shadow: 6px 6px 0 0 #000;
}
.hs-travel-dialog > .hs-panel { margin: 0; }
.hs-travel-close {
    position: absolute;
    top: 8px;
    right: 8px;
    z-index: 2;
    min-width: 28px;
    padding: 2px 8px;
}

/* Map fills the stage; bottom bar sits under it (map ends above the bar). */
.galaxy-map-embedded .gm-map-stage {
    position: relative;
    flex: 1 1 auto;
    min-height: 160px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.home-station-content .hs-body-play .galaxy-map-embedded .gm-map-stage > .galaxy-map-area {
    flex: 1 1 auto;
    min-height: 0;
    height: auto;
}
.galaxy-map-embedded .gm-map-stage > .galaxy-map-panels {
    position: static;
    left: auto;
    right: auto;
    bottom: auto;
    width: 100%;
    flex: 0 0 auto;
    display: block;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    overflow: visible;
    pointer-events: auto;
    z-index: 30;
}
.galaxy-map-embedded .gm-map-stage > .galaxy-map-panels > .galaxy-map-ruler.is-bar {
    pointer-events: auto;
}
.galaxy-map-embedded .gm-map-stage .galaxy-map-panel-select {
    background: transparent;
    border: 0;
    box-shadow: none;
    min-width: 0;
}
.galaxy-map-embedded .gm-map-stage .galaxy-map-panel-ship {
    width: 100%;
}

/* Nebula layers: slow breathing + a few map units of drift, per layer offset. */
/* No nebula animation: inside the SVG it repainted the whole map every frame. */
@media (prefers-reduced-motion: reduce) {
    .gm-nebula .gm-neb-layer { animation: none; }
}
/* Fine patch fades over the coarse field — reads as sharpening, not a rebuild pop. */
.gm-nebula .gm-neb-fine image {
    transition: opacity 0.28s ease-out;
}

/* Ship hover card: art left, name/status + compact stat grid right. */
.galaxy-map-panel-ship.gm-ship-card {
    display: grid;
    grid-template-columns: 76px minmax(0, 1fr);
    gap: 10px;
    align-items: center;
    padding: 8px 10px;
}
.gm-ship-card-art {
