    background: color-mix(in srgb, var(--color-primary) 8%, #000);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 30%, transparent);
}
.gm-ship-card .gm-ship-mini-canvas {
    width: 64px !important;
    height: 92px !important;
    image-rendering: pixelated;
}
.gm-ship-card-main { min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.gm-ship-card-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
}
.gm-ship-card-head .gm-panel-value {
    font-size: var(--font-text);
    letter-spacing: 1px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.gm-ship-card-status {
    flex: 0 0 auto;
    font-size: calc(var(--font-text) - 2px);
    letter-spacing: 1px;
    padding: 1px 5px;
    color: #05060a;
    background: var(--color-primary);
}
.gm-ship-card-class {
    font-size: calc(var(--font-text) - 2px);
    letter-spacing: 1px;
    color: var(--color-text-secondary);
}
.gm-ship-card-stats {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3px 10px;
    margin: 2px 0 0;
}
.gm-ship-card-stats > div {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    min-width: 0;
    padding: 2px 0;
    border-bottom: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 18%, transparent);
}
.gm-ship-card-stats .gm-ship-card-wide { grid-column: 1 / -1; }
.gm-ship-card-stats dt {
    font-size: calc(var(--font-text) - 2px);
    color: var(--color-text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
}
.gm-ship-card-stats dd {
    margin: 0;
    display: flex;
    align-items: center;
    gap: 4px;
    flex-wrap: wrap;
    justify-content: flex-end;
    font-size: var(--font-text);
    color: #fff;
}
.gm-ship-card-stats .gm-stat-chip img { width: 24px !important; height: 24px !important; }
.gm-muted { color: var(--color-text-secondary); }

/* Map planets as images (galaxy-map planetIconHtml asImage). */
.gm-planet-icon.gm-planet-icon-img { position: relative; overflow: visible; }
.gm-planet-icon-img .gm-planet-img {
    position: absolute;
    max-width: none;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    pointer-events: none;
}

/* Planet card buttons: bigger, glowing faction accent, animated on hover. */
.galaxy-map-panel-select .gm-card-actions {
    gap: 8px;
    margin-top: 8px;
}
.galaxy-map-panel-select .gm-card-actions .action-button {
    position: relative;
    overflow: hidden;
    padding: 11px 16px;
    font-size: var(--font-h2);
    letter-spacing: 2px;
    font-weight: bold;
    color: #fff;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 38%, #05060a);
    border: var(--ui-border-width, 2px) solid var(--faction-accent, var(--color-primary));
    box-shadow:
        3px 3px 0 0 #000,
        0 0 0 var(--ui-border-width, 2px) #000,
        0 0 12px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    text-shadow: 1px 1px 0 #000;
    transition: transform 0.12s steps(2, end), box-shadow 0.12s steps(2, end), background-color 0.12s steps(2, end);
}
.galaxy-map-panel-select .gm-card-actions .action-button.secondary {
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 14%, #05060a);
    opacity: 1;
}
/* Pixel shine sweeping across on hover. */
.galaxy-map-panel-select .gm-card-actions .action-button::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: -40%;
    width: 24%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
    transform: skewX(-20deg);
    pointer-events: none;
    opacity: 0;
}
.galaxy-map-panel-select .gm-card-actions .action-button:not(:disabled):is(:hover, :focus-visible, .nav-focused) {
    transform: translate(-2px, -2px);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 62%, #05060a);
    box-shadow:
        5px 5px 0 0 #000,
        0 0 0 var(--ui-border-width, 2px) #000,
        0 0 20px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 75%, transparent);
    animation: gm-card-btn-pulse 1.2s ease-in-out infinite;
}
.galaxy-map-panel-select .gm-card-actions .action-button:not(:disabled):is(:hover, :focus-visible, .nav-focused)::after {
    animation: gm-card-btn-shine 0.9s ease-out;
    opacity: 1;
}
.galaxy-map-panel-select .gm-card-actions .action-button:not(:disabled):active {
    transform: translate(1px, 1px);
    box-shadow: 1px 1px 0 0 #000, 0 0 0 var(--ui-border-width, 2px) #000;
    animation: none;
}
.galaxy-map-panel-select .gm-card-actions .action-button:disabled {
    opacity: 0.45;
    box-shadow: 2px 2px 0 0 #000;
}
@keyframes gm-card-btn-shine {
    from { left: -40%; }
    to   { left: 130%; }
}
@keyframes gm-card-btn-pulse {
    0%, 100% { filter: brightness(1); }
    50%      { filter: brightness(1.18); }
}
@media (prefers-reduced-motion: reduce) {
    .galaxy-map-panel-select .gm-card-actions .action-button { transition: none; }
    .galaxy-map-panel-select .gm-card-actions .action-button:is(:hover, :focus-visible, .nav-focused),
    .galaxy-map-panel-select .gm-card-actions .action-button::after { animation: none; }
}

/* ==========================================================================
   Pilot creation / profile section: responsive pass.
   Fluid sizes instead of fixed px, and stacking breakpoints at 900 / 640 px.
   ========================================================================== */
.profile-selection-content.profile-selection-floating.profile-selection-name-mode:has(.profile-faction-info-row) {
    width: min(calc(1320px * var(--zk)), calc(96 * var(--cw)));
    max-width: min(calc(1320px * var(--zk)), calc(96 * var(--cw)));
    padding: clamp(14px, calc(2.4 * var(--sv-w)), 32px) clamp(12px, calc(2.6 * var(--sv-w)), 32px);
    box-sizing: border-box;
}
.profile-selection-name-mode:has(.profile-faction-info-row) h2 { font-size: clamp(20px, calc(3.2 * var(--sv-w)), 34px); }
.profile-selection-name-mode .profile-faction-preview-name { font-size: clamp(16px, calc(2 * var(--sv-w)), 22px); }
.profile-selection-name-mode .profile-faction-preview-trait,
.profile-selection-name-mode .profile-faction-preview-hero { font-size: clamp(12px, calc(1.3 * var(--sv-w)), 14px); }
.profile-selection-name-mode .profile-faction-info-row .profile-faction-ship,
.profile-selection-name-mode.is-name-step .profile-faction-ship {
    width: clamp(150px, calc(24 * var(--sv-w)), 260px) !important;
    height: auto !important;
    aspect-ratio: 10 / 7;
    max-width: 100%;
