/* Start options: label column shrinks, content always gets the room. */
.profile-start-options,
.profile-selection-name-mode.is-name-step .profile-start-options {
    max-width: min(1040px, 100%);
    box-sizing: border-box;
}

.profile-start-chip { min-height: 30px; }

/* Galaxy card: ‹ map info › — the map is fluid (keeps its 56:22 ratio),
   the info column wraps, the arrows stretch to the card height. */
.profile-start-galaxy {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) minmax(150px, 0.45fr) auto;
    grid-template-areas: "prev map info next";
    align-items: stretch;
    gap: clamp(6px, calc(1.2 * var(--sv-w)), 12px);
    min-width: 0;
}
.profile-start-galaxy > .profile-start-galaxy-nav:first-child { grid-area: prev; }
.profile-start-galaxy > .profile-start-galaxy-nav:last-child { grid-area: next; }
.profile-start-galaxy > .profile-start-galaxy-map { grid-area: map; }
.profile-start-galaxy > .profile-start-galaxy-info { grid-area: info; align-self: center; }
.profile-start-galaxy-map,
.profile-selection-name-mode.is-name-step .profile-start-galaxy-map {
    width: 100%;
    max-width: 100%;
    height: auto;
    aspect-ratio: 560 / 220;
    min-width: 0;
}
.profile-start-galaxy-nav,
.profile-selection-name-mode.is-name-step .profile-start-galaxy-nav {
    height: auto;
    min-height: 44px;
    width: clamp(28px, calc(3 * var(--sv-w)), 34px);
}
.profile-start-galaxy-name,
.profile-selection-name-mode.is-name-step .profile-start-galaxy-name {
    font-size: clamp(15px, calc(1.9 * var(--sv-w)), 22px);
    overflow-wrap: anywhere;
}
.profile-start-galaxy-meta { overflow-wrap: anywhere; }

/* Wizard card with the start-galaxy list: ‹ list map info › (the list is scrollable, the map keeps its ratio). */
.profile-start-galaxy.has-side {
    grid-template-columns: auto minmax(160px, 0.62fr) minmax(0, 1.4fr) minmax(150px, 0.5fr) auto;
    grid-template-areas: "prev side map info next";
}
.profile-start-galaxy > .profile-start-galaxy-side { grid-area: side; }
.profile-start-galaxy-side {
    list-style: none;
    margin: 0;
    padding: 4px;
    min-height: 0;
    overflow-y: auto;
