}
.profile-start-galaxy-side li:hover { background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 14%, #05060a); color: #fff; }
.profile-start-galaxy-side li.selected { background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 28%, #05060a); color: #fff; }
.profile-start-galaxy-side .ruler { display: inline-flex; width: 20px; height: 20px; flex: none; }
.profile-start-galaxy-side .name { flex: 1 1 calc(100% - 30px); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.profile-start-galaxy-side .rivals { margin-left: 28px; }
.profile-start-galaxy-side .rivals { display: inline-flex; gap: 2px; opacity: 0.8; flex: none; }
.profile-start-galaxy-side .tag { flex: none; font-size: var(--font-small); line-height: 8px; padding: 2px 3px; color: #000; background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, #fff); }
.profile-start-galaxy-side .tag.is-home { background: var(--faction-accent, var(--color-primary)); }

@media (max-width: 900px) {
    .profile-faction-info-row { grid-template-columns: 1fr; }
    /* Info goes under the map; arrows keep flanking the map. */
    .profile-start-galaxy {
        grid-template-columns: auto minmax(0, 1fr) auto;
        grid-template-areas:
            "prev map next"
            "prev info next";
    }
    .profile-start-galaxy.has-side {
        grid-template-columns: auto minmax(0, 1fr) auto;
        grid-template-areas:
            "prev side next"
            "prev map next"
            "prev info next";
    }
    .profile-start-galaxy-side { max-height: 130px; }
    .profile-start-galaxy > .profile-start-galaxy-info { text-align: center; align-items: center; }
}
@media (max-width: 640px) {
    /* Label above its content. */
    .profile-start-row,
    .profile-selection-name-mode.is-name-step .profile-start-row[data-start-row="galaxy"] {
        grid-template-columns: 1fr;
        gap: 4px;
    }
    .profile-start-label { text-align: left; }
    /* Chips share the row evenly and are easy to tap. */
    .profile-start-chips {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
    }
    .profile-start-chip { min-height: 40px; }
    .profile-selection-name-mode.is-name-step .profile-faction-preview { gap: 12px; padding: 10px; }
    .profile-selection-name-mode .profile-modal-crest { width: 40px; height: 40px; top: 10px; left: 10px; }
}

