html body .home-station-overlay .home-station-content .hs-play-launch:is(:hover, :focus-visible, .nav-focused) {
    outline: none;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 5px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, #fff),
        inset 0 0 28px var(--faction-accent, var(--color-primary));
}

/* Enemy rows: shield bar under the HP bar (cyan), pulsing while it recharges. */
.enemy-vitals-side .health-bar.enemy-health .enemy-health-main,
.enemy-vitals-side .health-bar.enemy-health.is-champion .enemy-health-main {
    flex-direction: column;
    gap: 3px;
}
.enemy-vitals-side .health-bar.enemy-health .health-fill {
    width: 100%;
    flex: 0 0 auto;
}
.enemy-vitals-side .enemy-shield-fill {
    position: relative;
    width: 100%;
    height: 10px;
    background: #000;
    border: var(--ui-border-width-thin, 2px) solid color-mix(in srgb, #4fd8ff 55%, transparent);
    box-sizing: border-box;
}
.enemy-vitals-side .health-bar.enemy-health.is-champion .enemy-shield-fill { height: 12px; }
.enemy-vitals-side .enemy-shield-fill::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    height: 100%;
    width: var(--shield-width, 100%);
    background: #4fd8ff;
    transition: width 0.25s linear;
}
.enemy-vitals-side .enemy-shield-fill.is-charging::before {
    animation: enemy-shield-charge 0.6s steps(2) infinite;
}
.enemy-vitals-side .enemy-shield-fill.is-down { border-color: #ff4f4f; }
@keyframes enemy-shield-charge {
    50% { background: color-mix(in srgb, #4fd8ff 45%, #fff); }
}
.enemy-vitals-side .enemy-shield-text {
    position: relative;
    z-index: 1;
    display: block;
    text-align: center;
    font-family: var(--ui-font-family);
    font-size: var(--font-small);
    line-height: 8px;
    font-weight: bold;
    color: #fff;
    text-shadow: 1px 0 0 #000, -1px 0 0 #000, 0 1px 0 #000, 0 -1px 0 #000;
}
.enemy-vitals-side .enemy-shield-fill.is-down .enemy-shield-text { color: #ff8080; }
.enemy-vitals-side .enemy-shield-fill.is-none { border-color: color-mix(in srgb, #4fd8ff 22%, transparent); }
.enemy-vitals-side .enemy-shield-fill.is-none .enemy-shield-text { color: #6f8a96; }

