/* FIELD → LOOT: label above the chips; larger, resource-coloured icons. */
:is(.game-info-panel, .gi-under-stage) .gi-chip-row {
    grid-template-columns: minmax(0, 1fr);
    gap: 4px;
}
:is(.game-info-panel, .gi-under-stage) .gi-chips { gap: 5px; }
:is(.game-info-panel, .gi-under-stage) .gi-chip.gi-chip-loot {
    border-color: color-mix(in srgb, var(--loot-color) 60%, transparent);
