/* LOOT: more headroom above the label; chips share the row evenly,
   icon and count centred in each column. */
:is(.game-info-panel, .gi-under-stage) .gi-cluster-field .gi-chip-row {
    padding-top: 8px;
}
:is(.game-info-panel, .gi-under-stage) .gi-chip-row-label {
    margin-bottom: 2px;
    text-align: left;
    justify-self: start;
}
:is(.game-info-panel, .gi-under-stage) .gi-chip-row .gi-chips {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(0, 1fr));
    justify-items: start;
    width: 100%;
}
.game-info-panel .gi-chip.gi-chip-loot {
    width: 100%;
    max-width: 56px;
    align-items: center;
    justify-content: center;
    gap: 3px;
}
.game-info-panel .gi-chip.gi-chip-loot .gi-chip-count {
    text-align: center;
    width: 100%;
}

/* SHIP stats: improved values light up green with their delta, lowered
   ones dim red; the weapon box glows while shots are boosted. */
:is(.game-info-panel, .gi-under-stage) .gi-stat .gi-stat-delta {
    margin-left: 5px;
    font-size: 0.7em;
    vertical-align: middle;
}
:is(.game-info-panel, .gi-under-stage) .gi-stat.gi-stat-up {
    border-color: #5dff9a !important;
    background: color-mix(in srgb, #5dff9a 18%, #05060a) !important;
    box-shadow: 0 0 0 2px color-mix(in srgb, #5dff9a 35%, transparent), 0 0 12px color-mix(in srgb, #5dff9a 45%, transparent);
    animation: gi-stat-pulse 0.5s steps(2) 4;
}
:is(.game-info-panel, .gi-under-stage) .gi-stat.gi-stat-up :is(.gi-metric-label, .gi-metric-value) { color: #5dff9a !important; }
:is(.game-info-panel, .gi-under-stage) .gi-stat.gi-stat-down {
    border-color: color-mix(in srgb, #ff6a5d 60%, transparent) !important;
}
:is(.game-info-panel, .gi-under-stage) .gi-stat.gi-stat-down .gi-metric-value { color: #ff8a80 !important; }
@keyframes gi-stat-pulse { 50% { background: color-mix(in srgb, #5dff9a 40%, #05060a); } }

.gi-weapon-boosted {
    border-color: #ffcf3a !important;
    box-shadow: 0 0 0 2px color-mix(in srgb, #ffcf3a 35%, transparent), 0 0 14px color-mix(in srgb, #ffcf3a 45%, transparent) !important;
}
.gi-weapon-boosted .weapon-card.is-active {
    border-color: #ffcf3a;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, #ffcf3a 45%, transparent);
}
.gi-weapon-boosted .weapon-card.is-active .weapon-card-name::after {
    content: ' ▲';
    color: #ffcf3a;
    font-weight: bold;
}
.gi-weapon-flash { animation: gi-stat-pulse 0.5s steps(2) 4; }

/* LOADOUT → all slotted weapons; breathing glow during temporary boosts (power shot). */
:is(.game-info-panel, .gi-loadout-side) .gi-weapon-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    padding-top: 4px;
}
:is(.game-info-panel, .gi-loadout-side) .gi-chip.gi-chip-weapon :is(.gi-icon, img) {
    filter: drop-shadow(0 0 1px #05060a);
}
:is(.game-info-panel, .gi-loadout-side) .gi-chip.gi-chip-weapon.gi-chip-boosted {
    border-color: #ffcf3a;
    animation: gi-weapon-breath 1.6s ease-in-out var(--gi-breath-delay, 0s) infinite;
}
:is(.game-info-panel, .gi-loadout-side) .gi-chip.gi-chip-weapon.gi-chip-boosted :is(.gi-icon, img) {
    animation: gi-weapon-breath-icon 1.6s ease-in-out var(--gi-breath-delay, 0s) infinite;
}
@keyframes gi-weapon-breath {
    0%, 100% { background: color-mix(in srgb, #ffcf3a 8%, transparent); }
    50% { background: color-mix(in srgb, #ffcf3a 30%, transparent); }
}
@keyframes gi-weapon-breath-icon {
    0%, 100% { filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 1px #ffcf3a); }
    50% { filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 5px #ffcf3a) brightness(1.3); }
}


/* --- css/styles/part-17.css --- */
