/* Galaxy map start buttons: black fill + double outline (accent border,
   dark gap, inner accent line). The mission button is the primary: brighter
   lines and text. No colour-fill pulse on focus. */
.galaxy-map-panel-select .gm-card-actions .action-button,
.action-button#gmConfirmStart,
.action-button.gm-mission-btn {
    --gm-btn-line: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, #05060a);
    background: #05060a !important;
    color: #d8d8de !important;
    border: var(--ui-border-width, 2px) solid var(--gm-btn-line) !important;
    box-shadow:
        inset 0 0 0 var(--ui-border-width, 2px) #05060a,
        inset 0 0 0 calc(var(--ui-border-width, 2px) * 2) var(--gm-btn-line),
        2px 2px 0 0 #000 !important;
    text-shadow: 1px 1px 0 #000;
    opacity: 1;
    animation: none !important;
}
.action-button.gm-mission-btn {
    --gm-btn-line: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 85%, #fff);
    color: #fff !important;
    font-weight: bold;
}
.galaxy-map-panel-select .gm-card-actions .action-button:not(:disabled):is(:hover, :focus-visible, .nav-focused),
.action-button#gmConfirmStart:is(:hover, :focus-visible, .nav-focused),
.action-button.gm-mission-btn:is(:hover, :focus-visible, .nav-focused) {
    --gm-btn-line: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, #fff);
    background: #05060a !important;
    color: #fff !important;
    box-shadow:
        inset 0 0 0 var(--ui-border-width, 2px) #05060a,
        inset 0 0 0 calc(var(--ui-border-width, 2px) * 2) var(--gm-btn-line),
        3px 3px 0 0 #000 !important;
