}
.home-station-overlay :is(#gmConfirmStart, .gm-mission-btn, .gm-card-actions .action-button)::after {
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.25), transparent) !important;
    clip-path: none !important;
}

/* Sector card: settling factions as coloured chips. */
.gm-faction-value { display: inline-flex; flex-wrap: wrap; gap: 6px; justify-content: flex-end; }
.gm-faction-chip { display: inline-flex; align-items: center; gap: 4px; color: var(--chip); text-shadow: 1px 1px 0 #05060a; }
.gm-faction-dot { width: 7px; height: 7px; background: var(--chip); box-shadow: 0 0 0 var(--ui-border-width, 2px) #05060a; }

