    box-shadow:
        inset 2px 0 0 var(--color-primary),
        inset -2px 0 0 var(--color-primary),
        inset 0 -2px 0 var(--color-primary) !important;
    background:
        linear-gradient(to right,
            var(--color-primary) 0 var(--hs-gap-l, 0px),
            transparent var(--hs-gap-l, 0px) var(--hs-gap-r, 0px),
