html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn:is(:hover, :focus-visible, .nav-focused) {
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 5px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, #fff),
        inset 0 0 28px var(--faction-accent, var(--color-primary)) !important;
