    text-shadow: 2px 2px 0 #000 !important;
}
html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn:is(:hover, :focus-visible, .nav-focused) .hs-tab-label {
    color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, #fff) !important;
}
html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn.active {
    z-index: 3;
    background: var(--hs-tabpanel) !important;
    box-shadow:
        inset 0 2px 0 var(--color-primary),
        inset 2px 0 0 var(--color-primary),
        inset -2px 0 0 var(--color-primary) !important;
}
html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-label {
    color: var(--faction-accent, var(--color-primary)) !important;
}
/* Background icons: like PLAY's planets — big, half out of the card, dim
