}
.hs-area-btn .hs-area-deco-0 { left: 0; top: 0; }
.hs-area-btn .hs-area-deco-1 { right: 0; top: 0; }
.hs-area-btn .hs-area-deco-2 { left: 0; bottom: 0; }
.hs-area-btn .hs-area-deco-3 { right: 0; bottom: 0; }
html body .home-station-overlay .home-station-content .hs-area-btn:is(:hover, :focus-visible, .nav-focused) .hs-area-deco-item {
    filter: url(#hsPlayTint) brightness(1.15);
}

html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn.active {
    margin-bottom: -3px !important;
}
html body .home-station-overlay .home-station-content .hs-area-btn:is(:hover, :focus-visible, .nav-focused) .hs-area-deco-item {
