.launch-cutscene {
    position: fixed;
    left: calc(var(--stage-x, 0px) + var(--fr-open-side));
    top: calc(var(--stage-y, 0px) + var(--fr-open-top));
    width: var(--fr-open-w);
    height: var(--fr-open-h);
    right: auto;
    bottom: auto;
    z-index: 9990;
    background: #02040a;
    overflow: hidden;
}
.launch-cutscene-canvas { position: absolute; inset: 0; width: 100%; height: 100%; image-rendering: pixelated; z-index: 1; }
.launch-cutscene-planet.hero-planet-canvas {
    position: absolute !important;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 0; /* was -1: painted under the host background, invisible */
}
.launch-cutscene-skip {
    position: absolute;
    right: 20px;
    bottom: 20px;
    z-index: 2;
    padding: 8px 16px;
    background: color-mix(in srgb, var(--color-surface, #0b0b10) 85%, transparent);
    border: var(--ui-border-width) solid var(--color-primary);
    color: var(--color-primary);
    font-family: var(--ui-font-family, inherit);
    text-transform: uppercase;
    letter-spacing: 0.1em;
    cursor: pointer;
}
.launch-cutscene-skip:hover { filter: brightness(1.25); }
.launch-cutscene-card {
    position: absolute;
    left: 50%;
    top: 10%;
    transform: translateX(-50%);
    z-index: 5;
    width: min(520px, 86%);
    padding: 14px 18px 16px;
    text-align: center;
    pointer-events: none;
    opacity: 0;
    color: #f4f0e4;
    background: rgba(2, 4, 10, 0.72);
    border: 1px solid rgba(244, 240, 228, 0.35);
    box-shadow: 0 0 0 1px #000, 0 8px 24px rgba(0, 0, 0, 0.55);
    text-shadow:
        0 0 2px #000,
        0 2px 0 #000,
        2px 0 0 #000,
        -2px 0 0 #000,
        0 -2px 0 #000;
    font-family: "Courier New", Courier, monospace;
    text-transform: uppercase;
}
.launch-cutscene-kicker {
    font-size: 12px;
    letter-spacing: 0.28em;
    opacity: 0.9;
    margin-bottom: 6px;
    color: var(--color-primary, #e8c56a);
}
.launch-cutscene-title {
    font-size: clamp(22px, 4vw, 36px);
    letter-spacing: 0.12em;
    line-height: 1.1;
    margin-bottom: 8px;
    color: #f4f0e4;
    font-weight: 700;
}
.launch-cutscene-blurb {
    font-size: clamp(12px, 1.6vw, 15px);
    letter-spacing: 0.04em;
    line-height: 1.35;
    opacity: 1;
    color: #d8d2c4;
    text-transform: none;
}
.launch-cutscene-speaker {
    font-size: clamp(11px, 1.4vw, 13px);
    letter-spacing: 0.22em;
    color: var(--color-primary, #e8c56a);
    margin-bottom: 8px;
}
.launch-cutscene-line {
    font-size: clamp(14px, 2vw, 18px);
    letter-spacing: 0.03em;
    line-height: 1.4;
    color: #f4f0e4;
    text-transform: none;
    min-height: 2.8em;
}
.launch-cutscene-title-mini {
    margin-top: 12px;
    font-size: 11px;
    letter-spacing: 0.18em;
    opacity: 0.55;
    color: #d8d2c4;
}
.launch-cutscene-hint {
    position: absolute;
    left: 20px;
    bottom: 22px;
    z-index: 2;
    font-size: 11px;
    letter-spacing: 0.16em;
    color: color-mix(in srgb, var(--color-primary, #e8c56a) 70%, transparent);
    font-family: "Courier New", Courier, monospace;
    text-transform: uppercase;
    pointer-events: none;
    opacity: 0.35;
    transition: opacity 200ms ease;
}

/* STORY wizard step: full-width story tiles + mission strip. Type = stepper 18px. */
.profile-story-step {
    --story-font: 18px;
    --story-font-sub: 16px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    width: 100%;
    max-width: none;
    margin: 0;
    min-height: 0;
    flex: 1 1 auto;
    font-size: var(--story-font);
    box-sizing: border-box;
}
.profile-story-head {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    text-align: center;
}
.profile-story-profile {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 14px 16px;
    align-items: center;
    text-align: left;
    max-width: 640px;
    width: 100%;
    padding: 12px 16px;
    box-sizing: border-box;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 50%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 12%, #05060a);
}
.profile-story-profile-art {
    width: 80px;
    height: 80px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 10%, #05060a);
}
.profile-story-profile-art .profile-story-ico { width: 60px; height: 60px; }
.profile-story-profile-text {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
}
.profile-story-profile-label {
    font-size: var(--story-font-sub);
    letter-spacing: 0.16em;
    opacity: 0.8;
    color: var(--faction-accent, var(--color-primary));
}
.profile-story-profile-name {
    font-size: calc(var(--story-font) * 1.2);
    letter-spacing: 0.14em;
    font-weight: bold;
    color: var(--color-primary);
}
.profile-story-profile-blurb {
    font-size: var(--story-font-sub);
    line-height: 1.35;
    opacity: 0.9;
    text-transform: none;
    letter-spacing: 0.02em;
}
.profile-story-step .profile-selection-title {
    font-size: calc(var(--story-font) * 1.35) !important;
    letter-spacing: 0.12em;
    margin: 0;
}
.profile-story-layout {
    display: flex;
    flex-direction: column;
    gap: 14px;
    min-height: 0;
    flex: 1 1 auto;
    width: 100%;
}
.profile-story-list {
    display: grid;
    grid-template-columns: repeat(var(--story-count, 2), minmax(0, 1fr));
    gap: 12px;
    width: 100%;
    min-height: 0;
}
.profile-story-card {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: auto;
    align-items: center;
    gap: 14px 16px;
    padding: 16px 18px;
    text-align: left;
    min-height: 132px;
    background: color-mix(in srgb, var(--color-surface, #0b0b10) 88%, transparent);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 40%, transparent);
    color: var(--color-primary);
    font-family: var(--ui-font-family, inherit);
    text-transform: uppercase;
    cursor: pointer;
    transition: border-color 0.15s ease, transform 0.15s ease;
}
.profile-story-card:hover { transform: translateY(-1px); }
.profile-story-card.selected,
.profile-story-step.nav-row-active .profile-story-card.selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--color-primary) 35%, transparent);
}
.profile-story-card-art {
    flex: 0 0 auto;
    width: 96px;
    height: 96px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 10%, #05060a);
}
.profile-story-ico {
    display: block;
    width: 72px;
    height: 72px;
    background: var(--faction-accent, var(--color-primary));
    -webkit-mask: var(--pk-img) center / contain no-repeat;
    mask: var(--pk-img) center / contain no-repeat;
    image-rendering: pixelated;
    filter: drop-shadow(1px 1px 0 #05060a);
}
.profile-story-detail-art .profile-story-ico { width: 56px; height: 56px; }
.profile-story-card-text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
    min-width: 0;
}
.profile-story-card-title { font-weight: bold; letter-spacing: 0.12em; font-size: var(--story-font); }
.profile-story-card-meta { font-size: var(--story-font-sub); opacity: 0.8; letter-spacing: 0.1em; }
.profile-story-card-blurb {
    font-size: var(--story-font-sub);
    opacity: 0.9;
    line-height: 1.4;
    text-transform: none;
    letter-spacing: 0.02em;
}
.profile-story-detail {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 16px 18px;
    width: 100%;
    box-sizing: border-box;
    background: color-mix(in srgb, var(--color-surface, #0b0b10) 88%, transparent);
    border: var(--ui-border-width) solid color-mix(in srgb, var(--color-primary) 28%, transparent);
    min-height: 0;
    overflow: auto;
}
.profile-story-detail-head {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 14px 16px;
    align-items: center;
}
.profile-story-detail-art {
    width: 72px;
    height: 72px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 10%, #05060a);
}
.profile-story-detail-copy { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.profile-story-detail-title {
    margin: 0;
    font-size: var(--story-font);
    letter-spacing: 0.14em;
    color: var(--faction-accent, var(--color-primary));
}
.profile-story-detail-blurb {
    margin: 0;
    font-size: var(--story-font-sub);
    line-height: 1.45;
    opacity: 0.9;
    text-transform: none;
}
.profile-story-missions {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 8px;
}
.profile-story-mission {
    display: grid;
    grid-template-columns: 32px 1fr auto;
    gap: 12px;
    align-items: center;
    padding: 10px 12px;
    border: 1px solid color-mix(in srgb, var(--color-primary) 22%, transparent);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}
.profile-story-mission.is-first {
    border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 12%, transparent);
}
.profile-story-mission-idx {
    width: 28px;
    height: 28px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--story-font-sub);
    font-weight: bold;
    border: 1px solid color-mix(in srgb, var(--color-primary) 45%, transparent);
}
.profile-story-mission-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.profile-story-mission-body b { font-size: var(--story-font); letter-spacing: 0.1em; }
.profile-story-mission-body small { font-size: var(--story-font-sub); opacity: 0.8; letter-spacing: 0.08em; }
.profile-story-mission-diff { font-size: var(--story-font-sub); opacity: 0.85; letter-spacing: 0.1em; }
.profile-story-mission.is-empty { opacity: 0.6; grid-template-columns: 1fr; font-size: var(--story-font-sub); }
.profile-mission-empty {
    text-align: center;
    opacity: 0.7;
    padding: 24px;
}
@media (max-width: 720px) {
    .profile-story-list { grid-template-columns: 1fr; }
    .profile-story-card { grid-template-columns: 72px 1fr; min-height: 0; }
    .profile-story-card-art { width: 72px; height: 72px; }
    .profile-story-card-art .profile-story-ico { width: 52px; height: 52px; }
}
/* Story step: use the full wizard content width. */
html body .profile-selection-content:has(> .profile-story-step) {
    width: 100%;
    max-width: none;
    align-self: stretch;
    box-sizing: border-box;
}

/* Dev mode: every stage in the planet stepper is clickable. */
.gm-sector-stage.is-dev-pick { cursor: pointer; }
.gm-sector-stage.is-dev-pick:hover { filter: brightness(1.3); }

/* HUD mission count rows: enemy ship icon + count only. */
.gi-enemy-icon { width: 24px; height: 24px; object-fit: contain; image-rendering: pixelated; }
.gi-row-count .gi-row-text { justify-content: flex-start; }

/* --- Game-over wreck backdrop (js/ui/game-over-wreck.js) ---------------- */
.game-over-wreck {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    pointer-events: none;
    image-rendering: pixelated;
    /* Soft atmosphere behind the card — must not compete with the panel. */
    opacity: 0.42;
    filter: saturate(0.85) brightness(0.75);
}
.game-over::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background: radial-gradient(ellipse at 50% 42%, transparent 20%, rgba(0, 0, 0, 0.82) 88%),
        radial-gradient(ellipse at 50% 45%, color-mix(in srgb, #ff5a2a 8%, transparent), transparent 42%);
}
.game-over-content { position: relative; z-index: 1; margin: 0; backdrop-filter: blur(2px); }
.game-over-epitaph {
    margin: 0 0 4px;
    font-size: var(--font-small, 11px);
    letter-spacing: 0.25em;
    color: var(--color-error, #ff5a4a);
    opacity: 0.85;
}
/* Defeat card: compact planet so title / stepper / loot / buttons all fit. */
html body .game-over .outcome-progress {
    margin: 0 auto;
    gap: 10px;
    width: 100%;
    min-height: 0;
    padding-top: 108px;
}
html body .game-over .outcome-progress > .outcome-planet-icon {
    width: 168px;
    height: 168px;
}
html body .game-over .outcome-planet-text strong {
    font-size: var(--font-h2);
}
html body .game-over .outcome-planet-text span {
    font-size: var(--font-small);
}
html body .game-over .outcome-step {
    width: 44px;
}
html body .game-over .game-over-loss {
    margin: 4px auto 8px;
    max-width: 100%;
}
html body .game-over .game-over-buttons {
    margin-top: 4px;
    width: 100%;
}
html body .game-over .game-over-content h2 {
    margin-bottom: 4px;
}
html body .game-over .game-over-content p {
    margin-bottom: 2px;
}

/* === Faction picker: strong per-faction frame language ====================
   P = big panels (preview / lore / fact cards), C = controls. */
.profile-selection-content[data-faction] {
    --fp-accent: var(--ui-border, var(--color-primary));
}
.profile-selection-content[data-faction] :is(.profile-faction-preview, .profile-faction-lore, .profile-faction-fact)::after {
    opacity: var(--fp-surface-opacity, 0.3);
}
.profile-selection-content[data-faction] :is(.profile-faction-preview, .profile-faction-lore, .profile-faction-fact)::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background: var(--fp-ornament, none);
}
@keyframes fp-void-pulse {
    50% { box-shadow: 0 0 30px color-mix(in srgb, var(--fp-accent) 80%, transparent),
        inset 0 0 40px color-mix(in srgb, var(--fp-accent) 50%, transparent); }
}
@keyframes fp-machine-scan { from { --fp-scan: -40%; } to { --fp-scan: 140%; } }
@property --fp-scan { syntax: '<percentage>'; inherits: true; initial-value: -40%; }

@media (prefers-reduced-motion: reduce) {
    .profile-selection-content[data-faction] * { animation: none !important; }
}

/* Faction contract goal line (faction-relations.js FACTION_CONTRACT_KINDS). */
.hs-mission-goal { color: var(--color-text, #e8e4d8); font-weight: bold; }
.hs-mission.is-renegade .hs-mission-type,
.hs-mission.is-bounty .hs-mission-type { color: #ff5a3c; }
.hs-mission.is-conquer .hs-mission-type { color: #ffcf3a; }
.hs-mission.is-defend .hs-mission-type { color: #5cff7a; }

/* Faction preview card: emblem left of the faction name; trait / hero lines
   run underneath, spanning the full width. */
.profile-faction-preview .profile-faction-preview-text {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: 12px;
    align-items: center;
    justify-items: start;
    text-align: left;
}
.profile-faction-preview .profile-faction-preview-text > .profile-faction-preview-emblem {
    grid-column: 1;
    grid-row: 1;
    margin: 0;
}
.profile-faction-preview .profile-faction-preview-text > .profile-faction-preview-name {
    grid-column: 2;
    grid-row: 1;
    margin: 0;
}
.profile-faction-preview .profile-faction-preview-text > :not(.profile-faction-preview-emblem):not(.profile-faction-preview-name) {
    grid-column: 1 / -1;
}

/* Invaded planet: single planet pixels flare up where the factions clash. */
.gm-battle { pointer-events: none; }
.gm-battle-px { opacity: 0; fill: #fff3c0; animation: gm-battle-px 3.2s steps(1, end) infinite; animation-delay: var(--bd, 0s); }
@keyframes gm-battle-px {
    0%  { opacity: 1; fill: #fff3c0; }
    3%  { opacity: 0.9; fill: #ffb347; }
    7%  { opacity: 0.6; fill: #c8461e; }
    12% { opacity: 0.3; fill: #5a2418; }
    16% { opacity: 0; }
}
@media (prefers-reduced-motion: reduce) { .gm-battle-px { animation: none; opacity: 0.6; fill: #ffb347; } }

/* Raid/hunt mission: minimal chevron fleet in space around the planet. */
.gm-fleet { pointer-events: none; }
.gm-fleet-ship { opacity: 0.55; }
.gm-fleet-ship path { fill: var(--fac, var(--color-primary)); }
.gm-fleet-ship {
    animation: gm-fleet-blink 2.8s steps(2, end) infinite;
    animation-delay: var(--bd, 0s);
}
@keyframes gm-fleet-blink {
    0%, 100% { opacity: 0.95; }
    50%      { opacity: 0.35; }
}
@media (prefers-reduced-motion: reduce) {
    .gm-fleet-ship { animation: none; opacity: 0.75; }
}

/* Start galaxy card: real planet sprites on a star field, readable text. */
.profile-start-galaxy-map .stars rect { fill: #cfe4ff; }
.profile-start-galaxy-map .dust rect { fill: var(--galaxy-color); }
.profile-start-galaxy-map .edges path { fill: color-mix(in srgb, var(--galaxy-color) 70%, #fff); opacity: 0.7; }
.profile-start-galaxy-map .start-bracket { fill: #fff; }
.profile-start-galaxy-map .planet-label {
    font-family: var(--ui-font-family);
    font-size: var(--font-small);
    letter-spacing: 1px;
    text-anchor: middle;
    fill: color-mix(in srgb, #fff 80%, var(--galaxy-color));
    paint-order: stroke;
    stroke: #05060a;
    stroke-width: 3px;
}
.profile-start-galaxy-map .planet-label.is-start { fill: #fff; }
.profile-start-planet { width: 100%; height: 100%; }
.profile-start-label,
.profile-selection-name-mode .profile-start-label {
    font-size: var(--font-text);
    color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, #fff);
    text-shadow: none;
    filter: none;
}
.profile-start-galaxy-ruler { font-size: var(--font-text); color: #fff; }
.profile-start-galaxy-meta { font-size: var(--font-text); opacity: 1; color: color-mix(in srgb, #fff 82%, var(--faction-accent, var(--color-primary))); }
.profile-start-galaxy-home { font-size: var(--font-text); }
.profile-start-chip { font-size: var(--font-text); color: #fff; }
.profile-start-galaxy-info, .profile-start-label, .profile-start-chip:not(.selected) {
    text-shadow: 1px 0 0 #05060a, -1px 0 0 #05060a, 0 1px 0 #05060a, 0 -1px 0 #05060a;
}

/* Profile dialog buttons: pixel glyph before the label. */
.profile-selection-actions .action-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.ps-btn-icon { flex: none; filter: drop-shadow(1px 1px 0 #05060a); }
.profile-start-galaxy-new {
    align-self: flex-start;
    margin-top: 8px;
    padding: 4px 10px;
    font: inherit;
    font-size: var(--font-small);
    letter-spacing: 2px;
    color: var(--faction-accent, var(--color-primary));
    background: transparent;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    cursor: pointer;
}
.profile-start-galaxy-new:hover { color: #000; background: var(--faction-accent, var(--color-primary)); }
@media (max-width: 900px) { .profile-start-galaxy-new { align-self: center; } }

/* Starter kit: chips + live effect readout in one card. */
.profile-start-kit-card {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 7%, #05060a);
    clip-path: var(--faction-ctl-clip, none);
}
.profile-start-kit-card .profile-start-chips {
    padding: 6px;
    flex-wrap: nowrap;
}
.profile-start-kit-card .profile-start-chip { flex: 1 1 0; min-width: 0; text-align: center; }
.profile-start-kit-effect {
    padding: 7px 12px;
    border-top: var(--ui-border-width) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 14%, #000);
    color: var(--color-text, #fff);
    font-size: var(--font-text);
    letter-spacing: 1.5px;
    text-align: left;
}
.profile-start-kit-effect::before {
    content: '▸ ';
    color: var(--faction-accent, var(--color-primary));
}

/* NEW GALAXY modal (pilot creation). */
.profile-galaxy-modal {
    position: fixed;
    inset: 0;
    z-index: 10050;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: rgba(0, 0, 0, 0.72);
}
.profile-galaxy-modal-box {
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: min(620px, 100%);
    max-height: 100%;
    overflow-y: auto;
