/* Victory / defeat: planet + stage stepper (stage-stepper.js). */
.outcome-progress {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    margin: 12px auto 4px;
    font-family: 'Silkscreen', var(--ui-font-family, monospace);
    text-shadow: none;
    --outcome-accent: var(--faction-accent, var(--color-primary));
}
.outcome-progress[hidden] { display: none; }
.outcome-planet { display: flex; align-items: center;}
.outcome-planet-icon { display: inline-flex; flex: none;}
.outcome-planet-text { display: flex; flex-direction: column;}
.outcome-planet-text strong { font-size: var(--font-h2); letter-spacing: 2px; color: #fff;}
.outcome-planet-text span { font-size: var(--font-small); color: #a8adb8;}
.outcome-stepper {
    display: flex;
    align-items: center;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
}
.outcome-step {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
}
/* Center-to-center connector behind the dots — thin 2px, not --ui-border-width. */
.outcome-step + .outcome-step::before {
    content: "";
    position: absolute;
    z-index: 0;
    top: 50%;
    right: 50%;
    width: 100%;
    height: 0;
    border-top: 2px solid #3a3f4a;
    transform: translateY(-50%);
    pointer-events: none;
}
.outcome-step.is-done::before,
.outcome-step.is-won::before { border-top-color: var(--outcome-accent); }
.outcome-step-dot {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    box-sizing: border-box;
    font-size: var(--font-h2);
    line-height: 16px;
    color: #6a7080;
    background: #0a0c12;
    border: var(--ui-border-width, 2px) solid #3a3f4a;
}
.outcome-step-label { font-size: var(--font-small); line-height: 8px; letter-spacing: 1px; color: #6a7080; white-space: nowrap; }
.outcome-step.is-done .outcome-step-dot { color: #000; background: color-mix(in srgb, var(--outcome-accent) 70%, #000); border-color: var(--outcome-accent); }
.outcome-step.is-done .outcome-step-label { color: #c8ccd6; }
.outcome-step.is-won .outcome-step-dot { color: #000; background: var(--outcome-accent); border-color: #fff; box-shadow: 0 0 0 3px color-mix(in srgb, var(--outcome-accent) 40%, transparent); }
.outcome-step.is-won .outcome-step-label { color: #fff; }
.outcome-step.is-lost .outcome-step-dot { color: #fff; background: #8a1f1f; border-color: #ff6a6a; box-shadow: 0 0 0 3px rgba(255, 90, 90, 0.35); }
.outcome-step.is-lost .outcome-step-label { color: #ff8a8a; }
.outcome-step.is-boss .outcome-step-dot { width: 32px; height: 32px; }

/* Planet card buttons side by side (FROM START left, mission right). */
