html body .home-station-overlay .home-station-content .hs-play-launch .hs-play-launch-icon::before { content: none; }
html body .home-station-overlay .home-station-content .hs-play-launch .hs-play-launch-icon {
    filter: none !important;
}

/* Background deco icons only on PLAY (its planets); area cards stay clean. */
.hs-area-btn .hs-area-deco { display: none !important; }

/* PLAY a bit wider than the area cards. */
html body .home-station-overlay .home-station-content .hs-header-split > .hs-play-launch {
    flex: 0 0 230px;
    width: 230px;
    min-width: 230px;
}
@media (min-width: 1101px) and (max-width: 1650px) {
    html body .home-station-overlay .home-station-content .hs-header-split > .hs-play-launch {
        flex: 0 0 clamp(112px, calc(10.5 * var(--sv-w)), 172px) !important;
        width: clamp(112px, calc(10.5 * var(--sv-w)), 172px) !important;
        min-width: 112px !important;
    }
}

/* Nav labels a size up. */
html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn .hs-tab-label,
html body .home-station-overlay .home-station-content .hs-play-launch .hs-play-launch-label {
    font-size: var(--font-h2) !important;
    letter-spacing: 0.06em;
}
@media (min-width: 1101px) and (max-width: 1650px) {
    html body .home-station-overlay .home-station-content .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn .hs-tab-label,
    html body .home-station-overlay .home-station-content .hs-play-launch .hs-play-launch-label {
        font-size: clamp(13px, calc(1.25 * var(--sv-w)), 17px) !important;
    }
}

/* Profile list: no separators between pilots, no doubled side lines — the
   selected pilot is marked by a tinted row instead of left/right borders. */
html body .profile-list .profile-list-item,
html body .profile-list .profile-list-item.selected {
    border: 0;
}
html body .profile-list .profile-list-item.selected {
    background: color-mix(in srgb, var(--color-primary) 16%, transparent);
}
/* The inline profile dialog carried a faction drop-shadow filter on the whole
   box, which put a halo (and a ghost second line) around every text, emblem
   and border. Off; the list keeps one crisp frame. */
html body .profile-selection-overlay.is-inline .profile-selection-content { filter: none !important; }

/* ==== Profile details: coarse tile layout, big type, icons ==== */
.profile-details { padding: 16px !important; gap: 16px; text-align: left; }
.pd-hero { display: flex; align-items: center; gap: 16px; padding-bottom: 16px; border-bottom: var(--ui-border-width, 2px) solid var(--color-border); }
.pd-hero-actions { margin-left: auto; display: inline-flex; flex: 0 0 auto; align-items: center; gap: 8px; }
.pd-hero-btn {
    appearance: none; display: inline-flex; align-items: center; gap: 6px; cursor: pointer;
    font: inherit; font-size: var(--font-text); letter-spacing: 1px; padding: 8px 12px;
    color: var(--faction-accent, var(--color-primary)); background: transparent;
    border: var(--ui-border-width, 2px) solid var(--faction-accent, var(--color-primary));
}
.pd-hero-btn:hover, .pd-hero-btn:focus-visible {
    color: #05060a; background: var(--faction-accent, var(--color-primary)); outline: none;
}
.pd-hero-btn.is-danger { color: var(--status-error, #ff5a3c); border-color: var(--status-error, #ff5a3c); }
.pd-hero-btn.is-danger:hover, .pd-hero-btn.is-danger:focus-visible, .pd-hero-btn.is-danger.is-armed { color: #05060a; background: var(--status-error, #ff5a3c); }
.pd-hero-btn:disabled { opacity: .35; cursor: default; pointer-events: none; }
.pd-hero-btn .ps-btn-icon { width: 16px; height: 16px; flex: none; }
.pd-hero-face { position: relative; display: inline-flex; flex: none; align-items: center; justify-content: center; }
.pd-hero-face.has-portrait .pd-hero-emblem {
    position: absolute; right: -3px; bottom: -3px; z-index: 1;
    width: 28px; height: 28px;
    filter: drop-shadow(0 0 0 #05060a) drop-shadow(1px 1px 0 #05060a);
}
.pd-hero-emblem, .pd-hero-emblem img { width: 28px; height: 28px; flex: none; display: block; }
.pd-hero-face:not(.has-portrait) .pd-hero-emblem,
.pd-hero-face:not(.has-portrait) .pd-hero-emblem img { width: 56px; height: 56px; }
.pd-hero-text { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.pd-hero-name { font-size: 26px; letter-spacing: 3px; color: var(--color-text); overflow-wrap: anywhere; }
.pd-hero-faction { font-style: normal; font-size: var(--font-h2); letter-spacing: 3px; color: var(--faction-accent, var(--color-primary)); }
.pd-tiles { display: flex; flex-wrap: nowrap; align-items: center; gap: 0; background: color-mix(in srgb, var(--color-primary) 10%, #05060a); border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 55%, transparent); }
.pd-tile { display: flex; align-items: center; gap: 12px; padding: 12px; min-width: 0; }
.pd-tile.is-wide { flex: 1 1 auto; }
.pd-tile:not(.is-wide) { flex: 0 0 auto; }
.pd-tile-icon, .pd-tile-icon img { width: 32px; height: 32px; flex: none; }
.pd-tile-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pd-tile-value { font-size: 20px; letter-spacing: 1px; color: var(--color-text); overflow-wrap: anywhere; }
.pd-tile-cap { font-style: normal; font-size: var(--font-text); letter-spacing: 2px; color: var(--color-text-secondary); }
.pd-block-title { font-size: var(--font-h2); letter-spacing: 3px; color: var(--faction-accent, var(--color-primary));}
.pd-block-title img { width: 20px; height: 20px; }
.pd-galaxies { flex-direction: column;}
.pd-galaxy { display: grid; grid-template-columns: minmax(0, 1fr) auto 56px; align-items: center; gap: 12px; padding: 8px 12px; background: color-mix(in srgb, var(--color-primary) 6%, #05060a); font-size: var(--font-h2); letter-spacing: 1px; color: var(--color-text-secondary); }
.pd-galaxy.is-station { color: var(--faction-accent, var(--color-primary)); background: color-mix(in srgb, var(--color-primary) 16%, #05060a); }
.pd-galaxy-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pd-galaxy-count { text-align: right; color: var(--color-text); }
.pd-bar { display: inline-flex; gap: 2px; }
.pd-bar i { width: 8px; height: 12px; background: color-mix(in srgb, var(--color-text) 18%, transparent); }
.pd-bar i.on { background: var(--faction-accent, var(--color-primary)); }
.pd-res { display: grid; grid-template-columns: repeat(auto-fill, minmax(104px, 1fr)); gap: 8px; }
.pd-res-item { display: flex; align-items: center; gap: 8px; padding: 8px 12px; background: color-mix(in srgb, var(--color-primary) 8%, #05060a); border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 35%, transparent); }
.pd-res-icon, .pd-res-icon img { width: 28px; height: 28px; flex: none; }
.pd-res-value { font-size: var(--font-h2); letter-spacing: 1px; color: var(--color-text); }
.pd-ships { display: flex; flex-wrap: wrap; gap: 8px; }
.pd-ship { display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; font-size: var(--font-h2); letter-spacing: 1px; background: color-mix(in srgb, var(--color-primary) 8%, #05060a); border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 35%, transparent); color: var(--color-text); }
.pd-ship.is-active { border-color: var(--faction-accent, var(--color-primary)); color: var(--faction-accent, var(--color-primary)); }
.pd-ship img { width: 20px; height: 20px; }
/* Galaxies: two columns of chunky tiles (name + count on top, cell bar below). */
.pd-galaxies { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.pd-galaxy { grid-template-columns: minmax(0, 1fr) auto;}
.pd-galaxy-name { grid-area: name; }
.pd-galaxy-count { grid-area: count; }
.pd-bar { grid-area: bar; }
.pd-bar i { flex: 1 1 0; max-width: 14px; }

/* Galaxy tile: current planet as the galaxy's icon on the left. */
.pd-galaxy { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "planet name count" "planet bar bar"; column-gap: 12px; row-gap: 8px; }
.pd-galaxy-planet { grid-area: planet; width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; align-self: center; }
.pd-galaxy-planet > *, .pd-galaxy-planet img { width: 40px; height: 40px; }
.pd-galaxy-count { display: inline-flex; align-items: center; gap: 4px; }
.pd-galaxy-count img { width: 20px; height: 20px; }
.pd-galaxy.is-station { box-shadow: inset 0 0 0 2px var(--faction-accent, var(--color-primary)); }

/* UNIVERSE LOADER modal (galaxies page). */
.galaxy-viewer-head { flex-wrap: wrap; min-width: 0; }
.galaxy-viewer-head-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; justify-content: flex-end; min-width: 0; }
.galaxy-viewer { position: relative; }
.galaxy-viewer-modal-backdrop { position: absolute; inset: 0; z-index: 20; display: flex; align-items: center; justify-content: center; background: rgba(2, 2, 3, 0.78); }
.galaxy-viewer-modal { width: min(420px, 90%); box-sizing: border-box; padding: 16px; display: flex; flex-direction: column; gap: 16px; background: #05060a; border: var(--ui-border-width, 2px) solid var(--color-primary); text-align: left; }
.galaxy-viewer-modal h3 { margin: 0; font-size: var(--font-h2); letter-spacing: 3px; color: var(--color-primary); }
.galaxy-viewer-modal p { margin: 0; font-size: var(--font-text); line-height: 1.5; letter-spacing: 1px; color: var(--color-text-secondary); }
.galaxy-viewer-modal-actions { display: flex; gap: 8px; justify-content: flex-end; }
.galaxy-viewer-modal-actions .galaxy-viewer-btn:first-child { margin-right: auto; }
.galaxy-viewer-modal-actions .is-primary { border-color: var(--color-primary); color: var(--color-primary); }

/* Galaxy list runs down to the bottom of its column. */
.galaxy-viewer-side { height: 100%; }
.galaxy-viewer-list { flex: 1 1 0; min-height: 0; max-height: none; }

.galaxy-viewer-btn { display: inline-flex; align-items: center; gap: 8px; }
.galaxy-viewer-btn .ps-btn-icon, .galaxy-viewer-btn .gv-btn-ico, .galaxy-viewer-btn .gv-btn-ico img { width: 16px; height: 16px; flex: none; }

/* UNIVERSE LOADER: drop area + app-style action buttons. */
.galaxy-viewer-modal-actions .action-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.gv-drop { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 24px 16px; text-align: center; cursor: pointer; color: var(--color-text-secondary); background: color-mix(in srgb, var(--color-primary) 6%, #05060a); border: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--color-primary) 55%, transparent); }
.gv-drop:hover, .gv-drop:focus-visible, .gv-drop.is-over { color: var(--color-primary); border-color: var(--color-primary); background: color-mix(in srgb, var(--color-primary) 16%, #05060a); outline: none; }
.gv-drop-icon { display: inline-flex; filter: drop-shadow(2px 0 0 #05060a) drop-shadow(-2px 0 0 #05060a) drop-shadow(0 2px 0 #05060a) drop-shadow(0 -2px 0 #05060a); }
.gv-drop-title { font-size: var(--font-h2); letter-spacing: 3px; color: var(--color-text); }
.gv-drop-sub { font-size: var(--font-text); letter-spacing: 1px; }
.galaxy-viewer-modal .action-button {
    font-family: 'Silkscreen', var(--ui-font-family);
    font-size: var(--font-h2);
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 10px 16px;
    color: var(--color-text);
    background: #05060a;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 55%, transparent);
    border-radius: 0;
    cursor: pointer;
    box-shadow: none;
}
.galaxy-viewer-modal .action-button:not(.secondary) {
    color: var(--color-primary);
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 14%, #05060a);
}
.galaxy-viewer-modal .action-button:hover,
.galaxy-viewer-modal .action-button:focus-visible {
    color: #05060a;
    background: var(--color-primary);
    border-color: var(--color-primary);
    outline: none;
}
.galaxy-viewer-modal .action-button .ps-btn-icon { width: 20px; height: 20px; }
.galaxy-viewer-modal-actions .action-button:first-child { margin-right: auto; }

/* DELETE GALAXY modal: target galaxy list. */
.gv-target-list { max-height: 200px; }
.gv-target-list li { cursor: pointer; }
.galaxy-viewer-modal .gv-target-list { flex: none; height: auto; min-height: 0; max-height: 200px; overflow-y: auto; }

/* Main nav icons: full crisp pixels — no brightness/saturate filters (blur under glass scale). */
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn .hs-tab-icon,
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn .hs-tab-icon :is(img, canvas, .hs-tab-pixel, .ui-icon-tip) {
    image-rendering: -moz-crisp-edges !important;
    image-rendering: pixelated !important;
    image-rendering: crisp-edges !important;
    -ms-interpolation-mode: nearest-neighbor;
}
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn .hs-tab-icon,
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn .hs-tab-icon :is(img, canvas, .hs-tab-pixel, .ui-icon-tip) {
    filter: none !important;
    opacity: 1 !important;
}
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active .hs-tab-icon {
    position: relative;
    background: none !important;
    box-shadow: none !important;
    animation: none;
}
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active .hs-tab-icon::after {
    content: none !important;
    display: none !important;
}
@keyframes hs-holo-on {
    /* Only a slight dimming, no blackout. */
    0%   { opacity: 0.82; }
    35%  { opacity: 1; }
    55%  { opacity: 0.9; }
    100% { opacity: 1; }
}
@keyframes hs-holo-flicker {
    0%, 100% { opacity: 1; }
    6% { opacity: 0.8; }
    8% { opacity: 1; }
    41% { opacity: 0.9; }
    43% { opacity: 1; }
    72% { opacity: 0.7; transform: translateX(1px); }
    74% { opacity: 1; transform: none; }
    90% { opacity: 0.92; }
}
@keyframes hs-holo-scan {
    from { background-position: 0 0; }
    to { background-position: 0 12px; }
}
@media (prefers-reduced-motion: reduce) {
    html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active .hs-tab-icon,
    html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active .hs-tab-icon::after { animation: none; }
}

/* MENU: calmer flicker (its wide bar icon made the full flicker too harsh). */
@keyframes hs-holo-flicker-soft {
    0%, 100% { opacity: 1; }
    41% { opacity: 0.94; }
    43% { opacity: 1; }
    72% { opacity: 0.88; }
    74% { opacity: 1; }
}
html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn[data-open-menu].active .hs-tab-icon {
    animation: none;
}

/* PLAY: crisp icon at full strength. */
html body .home-station-overlay .home-station-content .hs-play-launch .hs-play-launch-icon {
    image-rendering: -moz-crisp-edges !important;
    image-rendering: pixelated !important;
    image-rendering: crisp-edges !important;
    opacity: 1 !important;
}
html body .home-station-overlay .home-station-content .hs-play-launch:not(.active) .hs-play-launch-planets {
    filter: none;
    opacity: 1;
}
html body .home-station-overlay .home-station-content .hs-play-launch.active :is(.hs-play-launch-planets, .hs-play-launch-icon) {
    animation: none;
}
@media (prefers-reduced-motion: reduce) {
    html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn[data-open-menu].active .hs-tab-icon,
    html body .home-station-overlay .home-station-content .hs-play-launch.active :is(.hs-play-launch-planets, .hs-play-launch-icon) { animation: none; }
}

html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active.holo-on .hs-tab-icon,
html body .home-station-overlay .home-station-content .hs-play-launch.active.holo-on :is(.hs-play-launch-planets, .hs-play-launch-icon) {
    animation: hs-holo-on 0.3s steps(1, end) 1;
}
@media (prefers-reduced-motion: reduce) {
    html body .home-station-overlay .home-station-content .hs-tab.hs-area-btn.active.holo-on .hs-tab-icon,
    html body .home-station-overlay .home-station-content .hs-play-launch.active.holo-on :is(.hs-play-launch-planets, .hs-play-launch-icon) { animation: none; }
}

/* Settings: text and controls scale with the panel's own width (container
   queries), so the page fills whatever box it sits in. */
.settings-panel {
    container: sp / inline-size;
    --sp-font: clamp(14px, 1.7cqw, 20px);
}
.settings-panel :is(.settings-row-label, .settings-row-value, .settings-hint, .settings-section-name, .volume-control label, .theme-dropdown-toggle) {
    font-size: var(--sp-font);
}
.settings-panel .settings-section-title {
    font-size: calc(var(--sp-font) * 1.1);
}
.settings-panel .settings-section-icon {
    width: calc(var(--sp-font) * 1.4);
    height: calc(var(--sp-font) * 1.4);
}
.settings-panel .settings-row {
    padding-block: calc(var(--sp-font) * 0.4) !important;
}
.settings-panel .settings-cycle-btn {
    width: calc(var(--sp-font) * 2);
    height: calc(var(--sp-font) * 2);
    font-size: var(--sp-font);
}
.settings-panel .settings-row-value {
    min-width: calc(var(--sp-font) * 5);
}
@container sp (max-width: 640px) {
    .settings-panel-clustered:not(.settings-panel-3col) {
        grid-template-columns: 1fr;
    }
    .settings-panel .settings-row:not(.settings-row-theme):not(.settings-row-volume):not(.settings-row-youtube):not(.settings-row-sound-code) {
        flex-wrap: wrap;
    }
}

/* Bottom bar under the map: planet segment keeps a readable min width. */
.galaxy-map-embedded .gm-map-stage > .galaxy-map-panels {
    justify-content: flex-start;
}
.galaxy-map-embedded .gm-map-stage .galaxy-map-panel-select {
    width: max(calc(20 * var(--sv-w)), 380px) !important;
    min-height: 0 !important;
    height: auto !important;
    max-width: calc(50 * var(--sv-w));
    box-sizing: border-box;
    flex: 0 0 auto;
    overflow: hidden;
}

/* Layout space under CSS zoom. Reference: 75% GUI scale.
   --zk / --cw / --ch size elements in the zoomed layout coordinates.
   Use the bezel screen opening (not the full stage) so modals fit the glass. */
:root {
    --zk: calc(0.75 / var(--gui-zoom, 0.75));
    --cw: calc(var(--fr-open-w, var(--vw, 1280px)) / var(--gui-zoom-eff, var(--gui-zoom, 0.75)) / 100);
    --ch: calc(var(--fr-open-h, var(--vh, 960px)) / var(--gui-zoom-eff, var(--gui-zoom, 0.75)) / 100);
}
.galaxy-map-embedded .gm-map-stage .galaxy-map-panel-select {
    width: calc(420px * var(--zk)) !important;
    max-width: calc(50 * var(--cw));
}
.start-screen-content {
    max-width: min(calc(94 * var(--cw)), calc(860px * var(--zk)));
    max-height: calc(94 * var(--ch));
}
.start-screen-content:has(> .settings-panel) {
    width: min(calc(94 * var(--cw)), calc(860px * var(--zk)));
}
.start-screen-content:has(> .settings-panel-3col) {
    width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
    max-width: min(calc(96 * var(--cw)), calc(1100px * var(--zk)));
    height: min(calc(86 * var(--ch)), calc(860px * var(--zk)));
}

/* Planet map container: fills the space under the header (the whole station
   is one fixed-proportion stage, so that share is the same at every size). */
.home-station-content .hs-body-play .galaxy-map-embedded .gm-map-stage {
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
}

/* Station overlay: full stage for BG/parallax/::after. GUI scale lives on
   .vf-glass / .vf-browser-shell (part-19), not here. */
.home-station-overlay {
    --u: min(calc(var(--vw, calc(100 * var(--sv-w))) / 1640), calc(var(--vh, calc(100 * var(--sv-h))) / 1110));
    --bezel: calc(38 * var(--u));
    --hs-frame-gap: calc(6 * var(--u));
    inset: 0 !important;
    left: 0 !important;
    top: 0 !important;
    width: auto !important;
    height: auto !important;
    transform: none !important;
    transition: none !important;
    box-shadow: none;
    /* Overlay spans the stage for BG/parallax; glass host clips the GUI. */
    overflow: visible !important;
}
.home-station-overlay .home-station-content {
    --hs-pad-y: 0px;
}
/* Legacy station hull frame retired — #vf-bezel owns the rim. Keep ::after
   inert so it cannot paint over / under the glass edge. */
.home-station-overlay::after {
    content: none !important;
    display: none !important;
    background: none !important;
}
.hs-frame-ui-scale {
    position: fixed !important;
    right: calc(var(--bezel) + 224 * var(--u));
    bottom: calc(var(--hs-frame-gap) + 6 * var(--u));
    font-size: calc(12 * var(--u));
}
.hs-frame-ui-scale input {
    width: calc(180 * var(--u));
}

/* Settings sliders: much wider, they take most of the row. */

.settings-panel .settings-look-slider {
    min-width: 160px;
    height: calc(var(--sp-font, 14px) * 1);
}

/* All settings sliders share one width (set by the longest label's row). */
.settings-panel .settings-look-controls {
    flex: 0 0 auto;
    width: 52%;
    max-width: none;
}

