/* Station overlay: stage offset tokens (glass host uses these via :root). */
.home-station-overlay {
    --stage-x: 0px;
    --stage-y: 0px;
}

/* vw/vh replacements: 1% of the 4:3 stage. Not zoomed contexts: real stage px.
   Zoomed contexts (below) use layout px so sizes keep their proportions. */
:root {
    --sv-w: calc(var(--vw, 1000px) / 100);
    --sv-h: calc(var(--vh, 750px) / 100);
}
.game-container,
.home-station-overlay .home-station-content {
    --sv-w: calc(var(--vw, 1000px) / var(--gui-zoom-eff, var(--gui-zoom, 0.75)) / 100);
    --sv-h: calc(var(--vh, 750px) / var(--gui-zoom-eff, var(--gui-zoom, 0.75)) / 100);
}

/* Global bezel around the 4:3 stage (all screens) + resolution slider */
:root {
    --stage-x: 0px;
    --stage-y: 0px;
    --bz-u: min(calc(var(--vw, calc(100 * var(--sv-w))) / 1640), calc(var(--vh, calc(100 * var(--sv-h))) / 1110));
    --bz: max(34px, calc(44 * var(--bz-u)));
    /* Screen glass opening inside the bezel (matches .vf-fr-hole / ::before).
       Side/bottom/top 56u: metal + tooth art ate the outer glass px when the
       hole was flush with a thinner rim. Top --bz-extra was 50 (open 94u) and
       left a hull gutter under the rim art before BG/glass — keep 12 → 56u. */
    --bz-extra: 12;
    --fr-open-side: calc(56 * var(--bz-u));
    --fr-open-bottom: calc(56 * var(--bz-u));
    --fr-open-top: calc((44 + var(--bz-extra, 12)) * var(--bz-u));
    --fr-open-w: calc(var(--vw, 1280px) - 2 * var(--fr-open-side));
    --fr-open-h: calc(var(--vh, 960px) - var(--fr-open-top) - var(--fr-open-bottom));
    /* Single glass-host zoom token (station / menus / fight). */
    --vf-glass-z: var(--gui-zoom-eff, var(--gui-zoom, 0.75));
    /* Pull glass just inside the rim. Metal factions use slice-16 (fully
       opaque band) with --_art-th ≈ --fr-ol + 2u — no deep tooth, so inset
       is only a thin gutter. (Old +14u tooth + 16u inset bloated 9-slice
       corners and made the frame read as disconnected blocks.) */
    --vf-glass-inset: calc(4 * var(--bz-u));
}

/* One bezel-opening glass host. Body keeps stage-scale; this host is the only
   GUI scale. Recipe: undivided top/left (+ inset), size = (open - 2*inset) / z,
   transform:scale(z). Never CSS zoom on this host.
   Selectors cover markup with .vf-glass and the known hosts before class lands. */
.vf-glass,
.home-station-overlay > .vf-browser-shell,
.home-station-overlay > .home-station-content,
.start-screen,
.start-screen-overlay,
.profile-selection-overlay:not(.home-station-overlay):not(.is-inline),
.player-selection-overlay,
.ag-overlay,
#vf-in-stage-shop.vf-iss,
#vf-trading-post-shop.hs-tps.vf-iss,
html body .game-container {
    --_z: var(--vf-glass-z, var(--gui-zoom-eff, var(--gui-zoom, 0.75)));
    --_gi: var(--vf-glass-inset, 0px);
    zoom: 1 !important;
    position: fixed;
    top: calc(var(--stage-y, 0px) + var(--fr-open-top) + var(--_gi));
    left: calc(var(--stage-x, 0px) + var(--fr-open-side) + var(--_gi));
    right: auto;
    bottom: auto;
    width: calc((var(--fr-open-w) - 2 * var(--_gi)) / var(--_z));
    height: calc((var(--fr-open-h) - 2 * var(--_gi)) / var(--_z));
    max-width: none;
    max-height: none;
    margin: 0;
    box-sizing: border-box;
    transform: scale(var(--_z));
    transform-origin: 0 0;
    overflow: hidden;
    /* Contain paint to the glass box — no chrome/crest past the rim. */
    contain: paint;
    /* Nearest-neighbor when the compositor scales this layer — without it,
       pixel icons (and Silkscreen) go mushy under fractional --_z. */
    image-rendering: -moz-crisp-edges;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}
/* Start / station: starfield must meet the inner rim. Default glass inset
   left a black/hull gutter under the bezel top strip (faction ::before ends
   at --fr-ot; glass began at --fr-ot + --_gi). Keep side/bottom inset. */
.start-screen,
.start-screen-overlay,
.home-station-overlay > .vf-browser-shell,
.home-station-overlay > .home-station-content {
    top: calc(var(--stage-y, 0px) + var(--fr-open-top));
    height: calc((var(--fr-open-h) - var(--_gi)) / var(--_z));
}
.vf-bezel {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    /* Above every glass host (station/fight/menus). translateZ keeps this layer
       above transform:scale glass in the compositor so rim art always covers
       screen edges — screen must never paint over the bezel band. */
    z-index: 9993;
    transform: translateZ(0);
    isolation: isolate;
    pointer-events: none;
    --u: var(--bz-u);
    --bezel: calc(38 * var(--u));
    --hs-frame-gap: calc(6 * var(--u));
    --retro-ink: var(--color-primary, #3dff6a);
    --hull: #1c1f26;
    --hull-lit: #2c313b;
    --hull-dark: #0c0e12;
}
.vf-bezel::after {
    content: '' !important; /* the slider takes the label's place */
    position: absolute !important;
    inset: 0 !important;
    left: 0 !important;
    top: 0 !important;
    width: auto !important;
    height: auto !important;
    z-index: 1;
    display: flex !important;
}
