    .vf-glass,
    .home-station-overlay > .vf-browser-shell,
    .home-station-overlay > .home-station-content,
    .start-screen,
    .start-screen-overlay,
    .profile-selection-overlay:not(.home-station-overlay):not(.is-inline),
    .player-selection-overlay,
    .ag-overlay,
    #vf-in-stage-shop.vf-iss,
    #vf-trading-post-shop.hs-tps.vf-iss
