        calc(24 * var(--bz-u)) 0,
        calc(100% - 24 * var(--bz-u)) 0,
        100% calc(24 * var(--bz-u)),
        100% calc(100% - 24 * var(--bz-u)),
        calc(100% - 24 * var(--bz-u)) 100%,
        calc(24 * var(--bz-u)) 100%,
        0 calc(100% - 24 * var(--bz-u)),
        0 calc(24 * var(--bz-u))
