    border: var(--ui-border-width, 2px) solid var(--color-border);
    color: var(--color-text-secondary);
    cursor: pointer;
}
.pd-known-toggle.is-on { color: var(--color-primary); border-color: var(--color-primary); }
.pd-known-toggle:hover, .pd-known-toggle:focus-visible { color: #fff; outline: none; }

/* empty screen: static noise + label */
.vf-pilot-empty {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    color: color-mix(in srgb, var(--ph-accent, var(--color-text, #fff)) 70%, transparent);
    letter-spacing: 0.22em;
    font-size: calc(14 * var(--bz-u));
}
.vf-pilot-empty i {
    position: absolute;
    inset: calc(var(--ph-rim-top, 8) * var(--bz-u)) calc(var(--ph-rim-side, 4) * var(--bz-u)) calc(var(--ph-rim-side, 4) * var(--bz-u));
    background:
        repeating-linear-gradient(90deg, #ffffff10 0 calc(3 * var(--bz-u)), transparent calc(3 * var(--bz-u)) calc(7 * var(--bz-u))),
        repeating-linear-gradient(0deg, #ffffff0c 0 calc(2 * var(--bz-u)), transparent calc(2 * var(--bz-u)) calc(5 * var(--bz-u)));
    animation: vf-pilot-noise 0.4s steps(3) infinite;
    pointer-events: none;
}
.vf-pilot-empty b { position: relative; z-index: 1; font-weight: normal; }
@keyframes vf-pilot-noise { 0% { background-position: 0 0, 0 0; } 33% { background-position: 5px 3px, -3px 2px; } 66% { background-position: -4px 6px, 2px -4px; } }
@media (prefers-reduced-motion: reduce) { .vf-pilot-empty i { animation: none; } }

/* Top strip = side rim (56u); --bz-extra 12 on top of base 44. */
.vf-bezel {
    --bz-extra: 12;
    --hole: linear-gradient(#000 0 0) var(--bezel) calc(var(--bezel) + var(--bz-extra) * var(--u)) / calc(100% - 2 * var(--bezel)) calc(100% - 2 * var(--bezel) - var(--bz-extra) * var(--u)) no-repeat;
