.vf-bezel::after {
    --hole: linear-gradient(#000 0 0) var(--bezel) calc(var(--bezel) + var(--bz-extra) * var(--u)) / calc(100% - 2 * var(--bezel)) calc(100% - 2 * var(--bezel) - var(--bz-extra) * var(--u)) no-repeat;
}

/* Pilot card + wallet now live in the bezel's top strip */
html body .home-station-overlay .home-station-content .hs-header-split > :is(.hs-pilot-card, .hs-wallet-card) { display: none !important; }

/* ── Sci-fi bezel, styled per faction (data-faction on #vf-bezel, from the active pilot) ── */
.vf-bezel-deco {
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    -webkit-mask: var(--hole), linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask: var(--hole) exclude, linear-gradient(#000 0 0);
    background:
        /* light strips along the outer edge (top / bottom) */
        linear-gradient(90deg, transparent, var(--retro-ink) 20%, var(--retro-ink) 80%, transparent) 50% calc(5 * var(--u)) / 60% calc(2 * var(--u)) no-repeat,
        linear-gradient(90deg, transparent, var(--retro-ink) 20%, var(--retro-ink) 80%, transparent) 50% calc(100% - 5 * var(--u)) / 60% calc(2 * var(--u)) no-repeat,
        /* side service panels with slots */
        repeating-linear-gradient(0deg, var(--hull-dark) 0 calc(3 * var(--u)), transparent calc(3 * var(--u)) calc(10 * var(--u))) calc(14 * var(--u)) 30% / calc(8 * var(--u)) 40% no-repeat,
        repeating-linear-gradient(0deg, var(--hull-dark) 0 calc(3 * var(--u)), transparent calc(3 * var(--u)) calc(10 * var(--u))) calc(100% - 22 * var(--u)) 30% / calc(8 * var(--u)) 40% no-repeat;
}
