/* Name step: icons on kit chips + use the whole screen */
.profile-start-chips .profile-start-chip { display: inline-flex; flex-direction: column; align-items: center; gap: 6px; }
.profile-kit-icon { display: inline-flex; width: 28px; height: 28px; }
.profile-kit-icon img { width: 100% !important; height: 100% !important; image-rendering: pixelated; }
html body .profile-selection-content.profile-selection-name-mode.is-name-step {
    zoom: 1;
    width: calc(100% - 140 * var(--bz-u)) !important;
    max-width: none !important;
    height: calc(100% - 100 * var(--bz-u)) !important;
    max-height: none !important;
    justify-content: space-between;
    gap: 14px;
    overflow: hidden !important;
}
html body .profile-selection-name-mode.is-name-step .profile-selection-title { font-size: 40px !important; }
html body .profile-selection-name-mode.is-name-step .profile-name-input { font-size: 30px; padding: 14px 20px; width: 100%; box-sizing: border-box; }
html body .profile-selection-name-mode.is-name-step .profile-start-options { display: flex; flex-direction: column; gap: 14px; min-height: 0;}
html body .profile-selection-name-mode.is-name-step .profile-start-row { display: flex; flex-direction: column; gap: 8px; }
html body .profile-selection-name-mode.is-name-step .profile-start-label { font-size: var(--font-h2) !important; letter-spacing: 3px; }
html body .profile-selection-name-mode.is-name-step .profile-start-chips { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
html body .profile-selection-name-mode.is-name-step .profile-start-chip { font-size: var(--font-h2) !important; padding: 14px 8px; }
html body .profile-selection-name-mode.is-name-step .profile-kit-icon { width: 40px; height: 40px; }
html body .profile-selection-name-mode.is-name-step .profile-start-kit-effect { font-size: var(--font-h2) !important; margin-top: 8px; }
html body .profile-selection-name-mode.is-name-step :is(.profile-start-galaxy-home, .profile-start-galaxy-meta, .profile-start-galaxy-new, .profile-start-galaxy-caret) { font-size: var(--font-h2) !important; }
html body .profile-selection-name-mode.is-name-step .profile-start-galaxy { font-size: 20px; }

html body .profile-selection-name-mode.is-name-step .profile-selection-actions .action-button { font-size: var(--font-h2) !important; padding: 12px 30px !important; }
