.vf-bezel[data-faction="terran"] { --fr-band-fill: #05080e; }
.vf-bezel[data-faction="kronax"] { --fr-band-fill: #060202; }
.vf-bezel[data-faction="pirate"] { --fr-band-fill: #040503; }
.vf-bezel[data-faction="machine"] { --fr-band-fill: #020706; }
.vf-bezel[data-faction="voidborn"] {
    /* Flat #14041c read as an empty hole under the thin vine line — give the
       band the same pixel-dither checker as the pilot-hud frame (pilot-hud.css)
       instead of a solid fill, so it reads as hull texture, not empty space. */
    --fr-band-fill: conic-gradient(#1c0a2a 25%, #0e0314 0 50%, #1c0a2a 0 75%, #0e0314 0) 0 0 / calc(6 * var(--bz-u)) calc(6 * var(--bz-u));
}
.vf-bezel-back {
    --_gi: var(--vf-glass-inset, 0px);
    --_hl: calc(var(--fr-ol, var(--fr-open-side, calc(44 * var(--u)))) + var(--_gi));
    --_hr: calc(var(--fr-or, var(--fr-open-side, calc(44 * var(--u)))) + var(--_gi));
    --_ht: calc(var(--fr-ot, var(--fr-open-top, calc((44 + var(--bz-extra, 12)) * var(--u)))) + var(--_gi));
    --_hb: calc(var(--fr-ob, var(--fr-open-bottom, calc(44 * var(--u)))) + var(--_gi));
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background: var(--fr-band-fill, #000);
    clip-path: var(--fr-shape);
    /* Punch the glass opening; composite keeps the band fill. */
    -webkit-mask:
        linear-gradient(#000 0 0),
        linear-gradient(#000 0 0);
    -webkit-mask-clip: border-box, content-box;
    -webkit-mask-composite: destination-out;
    mask:
        linear-gradient(#000 0 0),
        linear-gradient(#000 0 0);
    mask-clip: border-box, content-box;
    mask-composite: exclude;
    padding: var(--_ht) var(--_hr) var(--_hb) var(--_hl);
    box-sizing: border-box;
}

