}
.vf-bezel-fx .vf-fx-row { display: flex; align-items: center; gap: 8px; }

.vf-bezel-fx input[type="range"] { flex: 1;}
.vf-bezel-fx output { min-width: 3.5em; text-align: right; color: var(--color-text, #fff); }
.vf-bezel-fx .vf-fx-seg { display: flex; flex: 1; gap: 4px; }
.vf-bezel-fx .vf-fx-seg button {
    flex: 1;
    padding: 4px 6px;
    background: #0c0e12;
    border: 2px solid #2c313b;
    border-radius: 0;
    color: inherit;
