    cursor: pointer;
}
.vf-bezel-fx .vf-fx-seg button.on { border-color: var(--color-primary, #3dff6a); background: color-mix(in srgb, var(--color-primary, #3dff6a) 18%, #0c0e12); color: #fff; }

.vf-bezel-fx { overflow-y: auto;}
.vf-bezel-fx .vf-fx-title { margin-top: 4px; padding-top: 6px; border-top: 2px solid #2c313b; color: var(--color-text, #fff); }
.vf-bezel-fx .vf-fx-wrap { flex-wrap: wrap; }
.vf-bezel-fx .vf-fx-wrap button { flex: 0 0 auto; min-width: 2.2em; }
.vf-bezel-fx .vf-fx-colors { display: flex; gap: 10px; flex: 1; }
.vf-bezel-fx .vf-fx-colors label { display: flex; align-items: center; gap: 4px; }
.vf-bezel-fx input[type="color"] { padding: 0; background: none; border-radius: 0; cursor: pointer;}
.vf-bezel-fx .vf-fx-reset { flex: 1; padding: 4px 6px; background: #0c0e12; border: 2px solid #2c313b; border-radius: 0; color: inherit; font: inherit; letter-spacing: inherit; cursor: pointer; }
.vf-bezel-fx .vf-fx-reset:hover { border-color: var(--color-primary, #3dff6a); }
.vf-bezel .vf-bezel-deco { opacity: var(--fr-deco, 1); }

/* Visual-settings sidebar: docked to the right window edge, scrolls inside. */
.vf-bezel-fx { left: auto; min-width: 0; max-height: none; max-width: 100vw;
    z-index: 10001;
    box-shadow: inset 0 0 0 2px #2c313b, -6px 0 0 rgba(0, 0, 0, 0.45);
}
.vf-bezel-fx .vf-fx-head { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #2c313b; color: var(--color-text, #fff);}
.vf-bezel-fx .vf-fx-head button { background: #0c0e12; border-radius: 0; font: inherit; padding: 2px 8px; cursor: pointer;}
.vf-bezel-fx .vf-fx-tabs { display: flex; border-bottom: 2px solid #2c313b; }
.vf-bezel-fx .vf-fx-tabs button { background: #0c0e12; border-right: 2px solid #2c313b; border-radius: 0; color: inherit; font: inherit; cursor: pointer;}
.vf-bezel-fx .vf-fx-tabs button.on { opacity: 1; background: color-mix(in srgb, var(--color-primary, #3dff6a) 18%, #0c0e12); box-shadow: inset 0 -2px 0 var(--color-primary, #3dff6a);}
.vf-bezel-fx .vf-fx-body { flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 8px;}
.vf-bezel-fx .vf-fx-body .vf-fx-title { border-top: 0; margin-top: 4px; padding-top: 0; }

/* FRAME PIXEL: bevel sizing / clip rules stay; SVG #vfFramePx filter removed (app-wide ~3 FPS). */
html[data-vf-frame-px="on"] #vf-bezel .vf-fr {
    clip-path: none;
    filter: none;
    image-rendering: pixelated;
}
html[data-vf-frame-px="on"] #vf-bezel .vf-bezel-deco { image-rendering: pixelated; }

/* ── Visual settings sidebar styled as a REMOTE CONTROL ───────────────────
   Chamfered hull body, IR window on top, LCD readout, chunky keys with LEDs,
   recessed fader slots and a speaker grill at the bottom. */
.vf-bezel-fx {
    --rc-hull: #1a1d26;
    --rc-lit: #3a4152;
    --rc-dark: #07080c;
    --rc-acc: var(--color-primary, #3dff6a);
    top: 12px; right: 12px; bottom: 12px;
    width: 304px;
    padding: 18px 12px 10px;
    gap: 10px;
    background: linear-gradient(90deg, var(--rc-hull), color-mix(in srgb, var(--rc-hull) 80%, #000));
    box-shadow:
        inset 4px 4px 0 var(--rc-lit),
        inset -4px -4px 0 var(--rc-dark),
        inset 0 0 0 8px var(--rc-hull),
        -8px 8px 0 rgba(0, 0, 0, 0.5);
    clip-path: polygon(12px 0, calc(100% - 12px) 0, 100% 12px, 100% calc(100% - 12px), calc(100% - 12px) 100%, 12px 100%, 0 calc(100% - 12px), 0 12px);
    overflow: hidden;
}
/* IR window */
.vf-bezel-fx::before {
    content: "";
    position: absolute;
    top: 6px; left: 50%;
    width: 64px; height: 6px;
    transform: translateX(-50%);
    background: color-mix(in srgb, #ff2a2a 40%, #200);
    box-shadow: inset 0 0 0 2px #000, 0 0 0 2px var(--rc-dark);
}
/* speaker grill */
.vf-bezel-fx::after {
    content: "";
    flex: 0 0 14px;
    background: repeating-linear-gradient(90deg, var(--rc-dark) 0 4px, transparent 4px 8px);
    box-shadow: inset 0 0 0 2px var(--rc-dark);
    opacity: 0.8;
}
/* LCD readout */
.vf-bezel-fx .vf-fx-head {
    flex: 0 0 auto;
    padding: 8px 10px;
    border: 0;
    background:
        repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.28) 0 1px, transparent 1px 3px),
        color-mix(in srgb, var(--rc-acc) 12%, #02070a);
    box-shadow: inset 3px 3px 0 #000, inset -3px -3px 0 color-mix(in srgb, var(--rc-acc) 25%, #000);
    color: var(--rc-acc);
    text-shadow: 0 0 6px color-mix(in srgb, var(--rc-acc) 70%, transparent);
}
.vf-bezel-fx .vf-fx-head button { background: var(--rc-hull); box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark); border: 0; color: #fff; text-shadow: none; }
.vf-bezel-fx .vf-fx-head button:active { box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit); }
/* tab keys */
.vf-bezel-fx .vf-fx-tabs { flex: 0 0 auto; border: 0;}
.vf-bezel-fx .vf-fx-tabs button {
    border: 0; opacity: 1;
    background: var(--rc-hull);
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark), 0 3px 0 var(--rc-dark);
    position: relative;
}
.vf-bezel-fx .vf-fx-tabs button::before { content: ""; position: absolute; top: 3px; left: 50%; width: 6px; height: 2px; transform: translateX(-50%); background: #000; }
.vf-bezel-fx .vf-fx-tabs button.on {
    background: color-mix(in srgb, var(--rc-acc) 14%, var(--rc-hull));
    box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit), 0 1px 0 var(--rc-dark);
    color: #fff;
}

/* ---- Gamepad menu cursor (js/core/gamepad/cursor.js) -------------------- */
.vf-gp-cursor {
    position: fixed;
    left: 0;
    top: 0;
    z-index: 100050;
    box-sizing: border-box;
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    will-change: transform, width, height;
    transition: none;
}
.vf-gp-cursor.is-on {
    opacity: 1;
    visibility: visible;
}
.vf-gp-cursor.is-out {
    opacity: 0 !important;
    visibility: hidden !important;
    transition: none !important;
}
.vf-gp-cursor > i {
    position: absolute;
    width: 10px;
    height: 10px;
    border: 2px solid var(--color-primary, #3dff6a);
    box-shadow: 0 0 8px color-mix(in srgb, var(--color-primary, #3dff6a) 55%, transparent);
    pointer-events: none;
}
.vf-gp-cursor > i:nth-child(1) { left: 0; top: 0; border-right: 0; border-bottom: 0; }
.vf-gp-cursor > i:nth-child(2) { right: 0; top: 0; border-left: 0; border-bottom: 0; }
.vf-gp-cursor > i:nth-child(3) { left: 0; bottom: 0; border-right: 0; border-top: 0; }
.vf-gp-cursor > i:nth-child(4) { right: 0; bottom: 0; border-left: 0; border-top: 0; }
.vf-gp-cursor.is-jump > i {
    animation: vf-gp-cursor-pulse 0.22s steps(2) 1;
}
.vf-gp-cursor.is-out > i,
.vf-gp-cursor:not(.is-on) > i {
    animation: none !important;
    box-shadow: none;
    opacity: 0;
}
.vf-gp-cursor::after {
    content: '';
    position: absolute;
    inset: 0;
    border: 1px solid color-mix(in srgb, var(--color-primary, #3dff6a) 35%, transparent);
    background: color-mix(in srgb, var(--color-primary, #3dff6a) 8%, transparent);
    pointer-events: none;
}
.vf-gp-cursor.is-out::after,
.vf-gp-cursor:not(.is-on)::after {
    opacity: 0;
    border-color: transparent;
    background: transparent;
}
@keyframes vf-gp-cursor-pulse {
    0% { transform: scale(1.15); opacity: 0.55; }
    100% { transform: scale(1); opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
    .vf-gp-cursor.is-jump > i { animation: none; }
    .vf-gp-cursor { transition: none; }
}



/* --- css/styles/part-20.css --- */
.vf-bezel-fx .vf-fx-tabs button.on::before { background: var(--rc-acc); box-shadow: 0 0 6px var(--rc-acc); }
