}
.vf-bezel-fx .vf-fx-seg button.on::before { background: var(--rc-acc); box-shadow: 0 0 5px var(--rc-acc); }
.vf-bezel-fx .vf-fx-reset:active { transform: translateY(1px); }
/* fader slots */
.vf-bezel-fx input[type="range"]::-webkit-slider-runnable-track { border: 0;}
.vf-bezel-fx input[type="range"]::-moz-range-track { border: 0;}
.vf-bezel-fx input[type="range"] { background: linear-gradient(90deg, var(--rc-acc) var(--look-fill, 0%), transparent 0) center / 100% 4px no-repeat; }
.vf-bezel-fx .vf-fx-row:hover { background: none; }
.vf-bezel-fx .vf-fx-body .vf-fx-row { background: none; }

.vf-bezel-fx .vf-fx-preview { padding: 8px; background: color-mix(in srgb, var(--rc-acc) 8%, #02070a); box-shadow: inset 2px 2px 0 #000; color: var(--rc-acc); display: flex; flex-direction: column; gap: 4px; letter-spacing: normal; }
.vf-bezel-fx .vf-fx-tabs button { font-size: var(--font-small); }

.vf-bezel-fx .vf-fx-body { overflow-x: hidden; }
/* AUDIO: settings | Music Editor (wide = side-by-side, narrow = stacked) */
.vf-bezel-fx .vf-fx-body.is-audio-split {
