}
/* Collapsed: border becomes the expand strip with a › affordance */
.vf-bezel-fx .vf-fx-audio-split.is-settings-collapsed > .vf-fx-audio-resize {
    flex: 0 0 18px;
    width: 18px;
    cursor: pointer;
    background: color-mix(in srgb, var(--rc-hull) 75%, #000);
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark);
}
.vf-bezel-fx .vf-fx-audio-split.is-settings-collapsed > .vf-fx-audio-resize::before {
    left: 50%;
    width: 2px;
