}
.vf-bezel-fx .vf-fx-row { min-width: 0; }
.vf-bezel-fx .vf-fx-row input[type="range"] { min-width: 48px; }
.vf-bezel-fx .vf-fx-head { cursor: move; user-select: none; touch-action: none; }
.vf-bezel-fx .vf-fx-grip {
    position: absolute; right: 14px; bottom: 2px; width: 16px; height: 12px; cursor: nwse-resize; z-index: 2;
    background: repeating-linear-gradient(135deg, transparent 0 3px, var(--rc-lit) 3px 5px);
    touch-action: none;
}

/* Remote layout: steppers, key grid, cards */
.vf-bezel-fx .vf-fx-row { flex-wrap: nowrap; }
.vf-bezel-fx .vf-fx-row > span:first-child { flex: 0 0 82px; }
.vf-bezel-fx .vf-fx-step { flex: 1; min-width: 0; display: flex; align-items: stretch; gap: 4px; }
.vf-bezel-fx .vf-fx-step button {
    flex: 0 0 28px; padding: 4px 0; border: 0; border-radius: 0; background: var(--rc-hull);
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark), 0 2px 0 var(--rc-dark);
    color: inherit; font: inherit; cursor: pointer;
}
.vf-bezel-fx .vf-fx-step button:active { transform: translateY(1px); box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit); }
.vf-bezel-fx .vf-fx-step output {
    flex: 1; min-width: 0; display: flex; align-items: center; justify-content: center; text-align: center;
    background: color-mix(in srgb, var(--rc-acc) 8%, #02070a); box-shadow: inset 2px 2px 0 #000;
    color: var(--rc-acc); padding: 4px 2px; white-space: nowrap; overflow: hidden;
}
.vf-bezel-fx .vf-fx-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; }
.vf-bezel-fx .vf-fx-key {
    padding: 8px 4px 6px; border: 0; border-radius: 0; background: var(--rc-hull); color: inherit; font: inherit; letter-spacing: inherit; cursor: pointer; position: relative;
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark), 0 2px 0 var(--rc-dark);
}
.vf-bezel-fx .vf-fx-key::before { content: ""; position: absolute; top: 2px; left: 50%; width: 4px; height: 2px; transform: translateX(-50%); background: #000; }
.vf-bezel-fx .vf-fx-key.on { transform: translateY(1px); color: #fff; background: color-mix(in srgb, var(--rc-acc) 14%, var(--rc-hull)); box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit); }
.vf-bezel-fx .vf-fx-key.on::before { background: var(--rc-acc); box-shadow: 0 0 5px var(--rc-acc); }
.vf-bezel-fx .vf-fx-card { display: flex; flex-direction: column; gap: 6px; padding: 8px; background: color-mix(in srgb, var(--rc-hull) 55%, #000); box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit); }
.vf-bezel-fx .vf-fx-card .vf-fx-title { margin: 0; }
.vf-bezel-fx .vf-fx-tabs { flex-wrap: wrap; }
.vf-bezel-fx .vf-fx-tabs button { min-width: 0; flex: 1 1 0; padding-left: 0; padding-right: 0; overflow: hidden; }

/* Faction picker keys in the FRAME tab: one row, each in its faction's silhouette + surface. */
.vf-bezel-fx .vf-fx-facs { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
.vf-bezel-fx .vf-fx-fac {
    --faction-color: var(--rc-acc);
    position: relative; isolation: isolate; min-width: 0; padding: 12px 2px 8px; border: 0; border-radius: 0;
    background: color-mix(in srgb, var(--faction-color) 16%, var(--rc-hull)); color: var(--faction-color);
    font: inherit; font-size: var(--font-small); letter-spacing: 0; cursor: pointer; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--faction-color) 55%, #000);
    transition: background-color .35s ease, color .35s ease, box-shadow .35s ease;
}
.vf-bezel-fx .vf-fx-fac::before { content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none; opacity: 0.55; }
.vf-bezel-fx .vf-fx-fac.on { color: #fff; background: color-mix(in srgb, var(--faction-color) 38%, #000); box-shadow: inset 0 0 0 2px var(--faction-color), inset 0 0 8px var(--faction-color); }
.vf-bezel-fx .vf-fx-fac.on::before { opacity: 0.25; }

/* Tabs as rubber remote keys: icon over label, domed face, chamfered pill. */
.vf-bezel-fx .vf-fx-tabs { gap: 5px; padding: 2px 0 4px; }
.vf-bezel-fx .vf-fx-tabs button {
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px;
    padding: 8px 0 6px; min-height: 52px; font-size: var(--font-small); letter-spacing: 0.04em;
    background:
        radial-gradient(ellipse at 50% 18%, color-mix(in srgb, var(--rc-lit) 70%, transparent) 0, transparent 62%),
        linear-gradient(180deg, var(--rc-hull), color-mix(in srgb, var(--rc-hull) 70%, #000));
    clip-path: polygon(0 6px, 2px 6px, 2px 4px, 4px 4px, 4px 2px, 6px 2px, 6px 0, calc(100% - 6px) 0, calc(100% - 6px) 2px, calc(100% - 4px) 2px, calc(100% - 4px) 4px, calc(100% - 2px) 4px, calc(100% - 2px) 6px, 100% 6px, 100% calc(100% - 6px), calc(100% - 2px) calc(100% - 6px), calc(100% - 2px) calc(100% - 4px), calc(100% - 4px) calc(100% - 4px), calc(100% - 4px) calc(100% - 2px), calc(100% - 6px) calc(100% - 2px), calc(100% - 6px) 100%, 6px 100%, 6px calc(100% - 2px), 4px calc(100% - 2px), 4px calc(100% - 4px), 2px calc(100% - 4px), 2px calc(100% - 6px), 0 calc(100% - 6px));
    box-shadow: inset 0 0 0 2px var(--rc-dark), inset 3px 3px 0 var(--rc-lit), inset -3px -3px 0 var(--rc-dark);
}
.vf-bezel-fx .vf-fx-tabs button::before { display: none; }
.vf-bezel-fx .vf-fx-tabs button svg { width: 26px; height: 26px; flex: none; color: color-mix(in srgb, currentColor 80%, #fff); }
.vf-bezel-fx .vf-fx-tabs button span { display: none; }
.vf-bezel-fx .vf-fx-tabs button { min-height: 52px; }
.vf-bezel-fx .vf-fx-tabs button.on {
    transform: translateY(1px);
    background:
        radial-gradient(ellipse at 50% 80%, color-mix(in srgb, var(--rc-acc) 45%, transparent) 0, transparent 70%),
        color-mix(in srgb, var(--rc-acc) 12%, var(--rc-hull));
    box-shadow: inset 0 0 0 2px var(--rc-dark), inset 3px 3px 0 var(--rc-dark), inset -3px -3px 0 var(--rc-lit), inset 0 0 8px var(--rc-acc);
}
.vf-bezel-fx .vf-fx-tabs button.on svg { color: #fff; filter: drop-shadow(0 0 3px var(--rc-acc)); }

/* Held in the hand: a slight, slow sway; hover (or dragging) holds it still. */
@keyframes vf-rc-hold {
    0%   { transform: translate(0, 0) rotate(0deg); }
    22%  { transform: translate(-1.5px, 1px) rotate(-0.45deg); }
    48%  { transform: translate(1px, -1.5px) rotate(0.3deg); }
    73%  { transform: translate(1.5px, 0.5px) rotate(0.5deg); }
    100% { transform: translate(0, 0) rotate(0deg); }
}
.vf-bezel-fx { animation: vf-rc-hold 7s ease-in-out infinite;}
.vf-bezel-fx:hover, .vf-bezel-fx.is-dragging { animation: none; }
@media (prefers-reduced-motion: reduce) { .vf-bezel-fx { animation: none; } }

/* Remote faders: tall, easy to grab. The whole bar is the hit area; no row highlight. */
.vf-bezel-fx input[type="range"] {
    height: 24px;
    min-width: 90px;
    border: 0;
    box-shadow: inset 2px 2px 0 #000, inset -2px -2px 0 var(--rc-lit);
    background:
        linear-gradient(90deg, color-mix(in srgb, var(--rc-acc) 70%, #000) var(--look-fill, 0%), transparent 0) 0 0 / 100% 100% no-repeat,
        color-mix(in srgb, var(--rc-acc) 8%, #02070a);
    touch-action: none;
    cursor: ew-resize;
}
/* STYLE preferred MUSIC BPM mark (snap target). */
.vf-bezel-fx input[type="range"].has-bpm-mark {
    background:
        linear-gradient(90deg,
            transparent calc(var(--bpm-mark, 0%) - 1px),
            #fff calc(var(--bpm-mark, 0%) - 1px),
            #fff calc(var(--bpm-mark, 0%) + 1px),
            transparent calc(var(--bpm-mark, 0%) + 1px)) 0 0 / 100% 100% no-repeat,
        linear-gradient(90deg, color-mix(in srgb, var(--rc-acc) 70%, #000) var(--look-fill, 0%), transparent 0) 0 0 / 100% 100% no-repeat,
        color-mix(in srgb, var(--rc-acc) 8%, #02070a);
}
.vf-bezel-fx input[type="range"]::-webkit-slider-runnable-track { height: 24px; background: transparent; box-shadow: none; }
.vf-bezel-fx input[type="range"]::-moz-range-track { height: 24px; background: transparent; box-shadow: none; }
.vf-bezel-fx input[type="range"]::-webkit-slider-thumb {
    width: 14px; height: 24px; margin-top: 0; border: 0; background: var(--rc-hull);
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark), inset 0 0 0 2px #000, inset -6px 0 0 -4px var(--rc-acc), inset 6px 0 0 -4px var(--rc-acc);
}
.vf-bezel-fx input[type="range"]::-moz-range-thumb {
    width: 10px; height: 20px; border: 0; border-radius: 0; background: var(--rc-hull);
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark), 0 0 0 2px #000;
}
.vf-bezel-fx input[type="range"]:hover { filter: brightness(1.2); }
.vf-bezel-fx input[type="range"]:focus-visible { outline: 2px solid var(--rc-acc); outline-offset: 1px; }
.vf-bezel-fx label.vf-fx-row, .vf-bezel-fx label.vf-fx-row:hover, .vf-bezel-fx label.vf-fx-row:focus-within {
    background: none !important; box-shadow: none !important; outline: none; cursor: default;
}
/* Override the bezel default width:140px so row sliders can flex-shrink. */
.vf-bezel-fx .vf-fx-row input[type="range"] {
    width: 0;
    flex: 1 1 0;
    min-width: 48px;
}
.vf-bezel-fx input[type="color"] { width: 32px; height: 24px; border: 0; box-shadow: inset 0 0 0 2px #000; }

/* Held into view: slides up from below the window edge, tilted, and back out. */
.vf-bezel-fx {
    transition: translate 0.4s cubic-bezier(0.2, 0.9, 0.25, 1.05), rotate 0.4s cubic-bezier(0.2, 0.9, 0.25, 1.05);
}

.vf-bezel-fx:not(.is-in) { animation: none; pointer-events: none; }
@media (prefers-reduced-motion: reduce) { .vf-bezel-fx { transition: none; } }

/* Slide in from the right window edge (travels the full viewport width, so it also
   leaves the screen when the remote was dragged elsewhere). */
.vf-bezel-fx { translate: 100vw 0; rotate: 5deg; transform-origin: 100% 100%; }
.vf-bezel-fx.is-in { translate: 0 0; rotate: 0deg; }

/* Sway is driven from JS (eased on hover); no CSS keyframes. */
.vf-bezel-fx, .vf-bezel-fx:hover, .vf-bezel-fx.is-dragging { animation: none !important; }

/* Bezel tool keys: physical hardware keys sitting in a recessed tray in the frame. */
.vf-bezel .vf-bezel-tools {
    padding: calc(4 * var(--bz-u));
    gap: calc(6 * var(--bz-u));
    border-radius: calc(8 * var(--bz-u));
    clip-path: inset(0 round calc(8 * var(--bz-u)));
    background: var(--hull-dark, #05080e);
    box-shadow:
        inset calc(2 * var(--bz-u)) calc(2 * var(--bz-u)) 0 rgba(0, 0, 0, 0.85),
        inset calc(-2 * var(--bz-u)) calc(-2 * var(--bz-u)) 0 var(--hull-lit, #2a3a52),
        0 calc(1 * var(--bz-u)) 0 var(--hull-lit, #2a3a52);
}
.vf-bezel .vf-bezel-tools button {
    position: relative;
    border: 0;
    border-radius: calc(6 * var(--bz-u));
    clip-path: inset(0 round calc(6 * var(--bz-u)));
    background:
        linear-gradient(180deg, color-mix(in srgb, var(--hull-lit, #2a3a52) 75%, #fff 0%) 0, var(--hull, #131a26) 55%, color-mix(in srgb, var(--hull, #131a26) 70%, #000) 100%);
    box-shadow:
        inset calc(2 * var(--bz-u)) calc(2 * var(--bz-u)) 0 color-mix(in srgb, var(--hull-lit, #2a3a52) 60%, #fff),
        inset calc(-2 * var(--bz-u)) calc(-2 * var(--bz-u)) 0 var(--hull-dark, #05080e),
        0 calc(3 * var(--bz-u)) 0 #000;
    transform: translateY(calc(-1 * var(--bz-u)));
    transition: transform 0.08s steps(2, end), box-shadow 0.08s steps(2, end), filter 0.1s;
}
/* Settings remote handset: taller key, rounded ends, deeper bevel. */
.vf-bezel .vf-bezel-tools button[data-tool="fx"] {
    width: calc(52 * var(--bz-u));
    height: calc(68 * var(--bz-u));
    border-radius: calc(10 * var(--bz-u));
    background:
        linear-gradient(180deg,
            color-mix(in srgb, var(--hull-lit, #2a3a52) 85%, #fff) 0,
            var(--hull, #131a26) 40%,
            color-mix(in srgb, var(--hull, #131a26) 55%, #000) 100%);
    box-shadow:
        inset calc(2 * var(--bz-u)) calc(2 * var(--bz-u)) 0 color-mix(in srgb, var(--hull-lit, #2a3a52) 70%, #fff),
        inset calc(-2 * var(--bz-u)) calc(-3 * var(--bz-u)) 0 var(--hull-dark, #05080e),
        0 calc(4 * var(--bz-u)) 0 #000;
}
.vf-bezel .vf-bezel-tools button[data-tool="fx"]::after {
    top: calc(5 * var(--bz-u));
    width: calc(8 * var(--bz-u));
    height: calc(3 * var(--bz-u));
    border-radius: calc(1 * var(--bz-u));
}
.vf-bezel .vf-bezel-tools button::after {
    /* key LED */
    content: "";
    position: absolute;
    top: calc(3 * var(--bz-u));
    left: 50%;
    width: calc(6 * var(--bz-u));
    height: calc(2 * var(--bz-u));
    transform: translateX(-50%);
    background: #000;
}
.vf-bezel .vf-bezel-tools button:hover,
.vf-bezel .vf-bezel-tools button:focus-visible { filter: brightness(1.25); border: 0; color: #fff; }
.vf-bezel .vf-bezel-tools button:active,
.vf-bezel .vf-bezel-tools button.is-open {
    transform: translateY(calc(2 * var(--bz-u)));
    background: color-mix(in srgb, var(--color-primary, #3dff6a) 12%, var(--hull, #131a26));
    box-shadow:
        inset calc(2 * var(--bz-u)) calc(2 * var(--bz-u)) 0 var(--hull-dark, #05080e),
        inset calc(-2 * var(--bz-u)) calc(-2 * var(--bz-u)) 0 var(--hull-lit, #2a3a52),
        0 calc(1 * var(--bz-u)) 0 #000;
}
.vf-bezel .vf-bezel-tools button.is-open::after { background: var(--color-primary, #3dff6a); box-shadow: 0 0 calc(6 * var(--bz-u)) var(--color-primary, #3dff6a); }
.vf-bezel .vf-bezel-tools button > svg { filter: drop-shadow(0 calc(1 * var(--bz-u)) 0 #000); }

/* Unavailable key: an empty dark socket (the slot stays, so nothing shifts or pops in). */
.vf-bezel .vf-bezel-tools button.is-off {
    background: var(--hull-dark, #05080e);
    box-shadow: inset calc(2 * var(--bz-u)) calc(2 * var(--bz-u)) 0 #000, inset calc(-2 * var(--bz-u)) calc(-2 * var(--bz-u)) 0 var(--hull-lit, #2a3a52);
    transform: none;
    filter: none;
    pointer-events: none;
    cursor: default;
}
.vf-bezel .vf-bezel-tools button.is-off > svg, .vf-bezel .vf-bezel-tools button.is-off::after { opacity: 0; }

/* Resolution key is hidden (the slider plate stays in code, just unreachable from the strip). */
.vf-bezel .vf-bezel-tools button[data-tool="res"] { display: none !important; }

/* Logout key: fully invisible until a pilot is logged in, but still occupies its slot
   (visibility, not display, so the fullscreen key to its left never shifts into its place). */
html:not([data-vf-logged]) .vf-bezel .vf-bezel-tools button[data-tool="logout"] {
    visibility: hidden;
    pointer-events: none;
}

/* Square screen opening whenever corners are pixel/voxel: the opening, the glass bevel and the
   backing all read the same radius tokens, so the frame never disagrees with the picture. */
html[data-vf-gui-voxel="on"][data-vf-gv-corners="on"]:not([data-vf-frame-px="on"]) .vf-bezel,
html[data-vf-gui-voxel="on"][data-vf-gv-corners="on"]:not([data-vf-frame-px="on"]) .vf-bezel[data-faction] {
    --fr-hole-r: 0;
    --glass-r: 0;
}

/* Pixel frame: the stage is no longer cut to the smooth faction outline — that cut would
   shear off the stepped pixel edge of the frame. The pixelated plates define the silhouette. */
html[data-vf-frame-px="on"] #vf-bezel .vf-fr-p { clip-path: var(--fr-shape); }

/* Pixel frame, no cutting at all: every frame layer is rasterised by the same filter on one
   shared grid (equal square cells) and none of them keeps a smooth clip-path. The plates are
   shaped by their own (pre-filter) clips, so corners and rounded openings step like voxels. */
html[data-vf-frame-px="on"] #vf-bezel .vf-fr,
html[data-vf-frame-px="on"] #vf-bezel .vf-bezel-deco,
html[data-vf-frame-px="on"] #vf-bezel::before,
html[data-vf-frame-px="on"] #vf-bezel::after {
    clip-path: none !important;
    /* Runtime (1e456a): filter:url(#vfFramePx) on the bezel dropped app-wide RAF
       from ~59 FPS to ~2.7 FPS with FRAME PIXEL on. Keep pixel look without the SVG filter. */
    filter: none;
    image-rendering: pixelated;
}
html[data-vf-frame-px="on"] #vf-bezel .vf-bezel-back { clip-path: none; }

/* Pixel frame: sampling keeps a band only if it is at least one cell wide, so bevels and the
   glass edge are widened to one cell (otherwise they break up into scattered blocks). */

/* Pixel frame keeps its roundings: the radius stays and the grid filter steps it into
   voxel stairs. (The generic "square corners" rule must not flatten the frame pieces.) */
html[data-vf-frame-px="on"] body #vf-bezel .vf-fr-hole { border-radius: var(--fr-hole-r) !important; }
html[data-vf-frame-px="on"] body #vf-bezel::before,
html[data-vf-frame-px="on"] body #vf-bezel .vf-bezel-back { border-radius: var(--fr-hole-r) !important; }

/* Pixel frame: the lit/dark bevel plates stay on, one grid cell wide, so the outer edge keeps its
   light (up-left) and shade (down-right) like the smooth frame. The opening's own edge bevel is
   drawn by the hull hole shadow (screen-frame.css). */
html[data-vf-frame-px="on"] .vf-bezel { --fr-bevel: var(--fr-px, 3px); }

/* Pixel frame: the screen opening is rounded by FRAME ROUND cells on every faction; the grid
   filter steps that radius into voxel stairs. */
html[data-vf-frame-px="on"] .vf-bezel,
html[data-vf-frame-px="on"] .vf-bezel[data-faction] {
    --fr-hole-r: var(--fr-rad, 0px);
    --glass-r: var(--fr-rad, 0px);
}

/* Pixel/stepped silhouette: clip the band fill to the same mask as the plates. */
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel .vf-bezel-back {
    clip-path: url(#vfStageClip) !important;
}

/* Pixel frame: outer corners follow FRAME ROUND too. The inner plate (hullB) is cut to a rounded
   rect; it sits inside hullA (faction silhouette), so the visible shape is the intersection. */
html[data-vf-frame-px="on"] #vf-bezel .vf-fr-hullB { clip-path: inset(0 round var(--fr-out, 0px)); }

/* Pixel frame: only the frame plates take the stepped silhouette (built by viewport-fit.js); the stage and the
   bezel's children (pilot thumbnail, screens, tools) are never cut. .vf-fr-p drops its smooth clip so the step shows. */
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel .vf-bezel-deco,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel::after { clip-path: url(#vfStageClip) !important; }
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel .vf-fr-p { clip-path: none; }
/* Voxel frame: viewport-fit.js shades the plate per cell into one small bitmap on .vf-fr (hull, outer
   bevel, opening lip, all on the --fr-px grid). It replaces the smooth offset plates entirely. */
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel .vf-fr {
    background-position: 0 0;
    background-repeat: no-repeat;
    image-rendering: pixelated;
}
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel .vf-fr-p { visibility: hidden; }
/* The bitmap is already transparent outside the outline; the stepped clip on top only added anti-aliased
   (soft) edges where cell borders fall between device pixels. */
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel .vf-fr { clip-path: none !important; }
/* Voidborn vines keep --fr-shape (not #vfStageClip / not the voxel none) so the rim never
   depends on a mask that is briefly empty during silhouette rebuild — that made the bezel vanish. */
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="voidborn"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="voidborn"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="voidborn"]::before {
    clip-path: var(--fr-shape) !important;
}
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="voidborn"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="voidborn"] .vf-fr::after {
    clip-path: var(--fr-shape) !important;
}
/* Metal parted-graphic rims (pirate/terran/kronax/machine): same rule — border-image
   on .vf-fr::after + hull fill on ::before must not wait on #vfStageClip. */
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="pirate"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="pirate"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="pirate"]::before,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="terran"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="terran"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="terran"]::before,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="kronax"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="kronax"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="kronax"]::before,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="machine"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="machine"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-sil] #vf-bezel.vf-bezel[data-faction="machine"]::before {
    clip-path: var(--fr-shape) !important;
}
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="pirate"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="pirate"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="terran"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="terran"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="kronax"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="kronax"] .vf-fr::after,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="machine"] .vf-fr,
html[data-vf-frame-px="on"][data-vf-frame-vox] #vf-bezel.vf-bezel[data-faction="machine"] .vf-fr::after {
    clip-path: var(--fr-shape) !important;
}
/* The stage (body) is a plain rectangle: its fill showed as black squares at the frame's notches and
   rounded corners (smooth and pixel frame alike). The frame plates are opaque over the whole band, so the
   stage only needs its fill behind the opening and the background art shows around the silhouette.
   !important: the palette code writes body.style.background inline. */
html:has(#vf-bezel) body,
html.vf-game-shown:has(#vf-bezel) body {
    /* Black under the whole open+inset glass box (freiraum included). */
    background: #000 !important;
}
/* Faction silhouette on <html> so stage children can clip to the same outline. */
html[data-faction="terran"] { --fr-shape: var(--fr-shape-terran); }
html[data-faction="kronax"] { --fr-shape: var(--fr-shape-kronax); }
html[data-faction="voidborn"] { --fr-shape: var(--fr-shape-voidborn); }
html[data-faction="pirate"] { --fr-shape: var(--fr-shape-pirate); }
html[data-faction="machine"] { --fr-shape: var(--fr-shape-machine); }

/* Stage is a rectangle; bezel silhouette has chamfers/notches. Without this,
   the black body corner peeks past the rounded rim as a square “screen” leak.
   Clip the whole stage (screen + overlays + parallax) to the same outline. */
html:has(#vf-bezel) body {
    clip-path: var(--fr-shape, none);
}
/* Seal subpixel / vine-gap leaks on the outer rim (showed as a 1–2px purple
   sliver past the side vine into the letterbox). */
html:has(#vf-bezel) #vf-bezel {
    box-shadow: 0 0 0 2px var(--fr-band-fill, #000);
}
html[data-faction="voidborn"]:has(#vf-bezel) .vf-bezel-back {
    background: #14041c !important;
}
/* Cables SVG is fixed to the window and draws plugs past the rim — reads as
   screen wings on the sides. Keep them off while the bezel is up. */
html:has(#vf-bezel) :is(#vf-cables, #vf-cables-old) {
    display: none !important;
}

/* Glass opening shape (freiraum stays black via .vf-bezel-back).
   Top has NO glass-inset: bezel ::before already ends at --fr-open-top;
   stacking +inset there left a black/hull gutter under the rim. Side/bottom
   keep the inset so chrome does not eat the opaque band. */
html:has(#vf-bezel) {
    --vf-stage-shape: inset(
        var(--fr-open-top)
        calc(var(--fr-open-side) + var(--vf-glass-inset, 0px))
        calc(var(--fr-open-bottom) + var(--vf-glass-inset, 0px))
        calc(var(--fr-open-side) + var(--vf-glass-inset, 0px))
        round calc(24 * var(--bz-u))
    );
}
html[data-vf-frame-px="on"][data-vf-frame-sil] {
    --vf-stage-shape: inset(
        var(--fr-open-top)
        calc(var(--fr-open-side) + var(--vf-glass-inset, 0px))
        calc(var(--fr-open-bottom) + var(--vf-glass-inset, 0px))
        calc(var(--fr-open-side) + var(--vf-glass-inset, 0px))
        round calc(24 * var(--bz-u))
    );
}
/* Tint/glow that fill the stage box may clip to the silhouette.
   Parallax base/glow are OVERSIZED (-6%/112%) — never clip them with
   --fr-shape (% is relative to their own box and would misalign). They
   are contained by the host overlay / body overflow instead. */
html:has(#vf-bezel) #colorOverlay {
    clip-path: var(--fr-shape, var(--vf-stage-shape, none)) !important;
}
/* Full-stage overlays host overscan parallax. Clip to the GLASS opening
   (--vf-stage-shape), not the outer silhouette — otherwise sky/glow paints
   into the freiraum under the vine and reads as screen-in-bezel bleed.
   Never apply this to .profile-selection-overlay.is-inline: that dialog is a
   small flex child inside the start-screen terminal, and inset(--fr-open-*)
   re-cuts fr-open-top/bottom off ITS own box — wiping CANCEL/NEXT and the
   bottom of the faction cards (and the tops of the faction swatches). */
html:has(#vf-bezel) :is(
    .home-station-overlay,
    .profile-selection-overlay:not(.is-inline):not(.onboarding-overlay),
    .player-selection-overlay
) {
    clip-path: var(--vf-stage-shape, none) !important;
    overflow: hidden !important;
}
/* Shop modals / onboarding are already glass hosts (sized to the opening). Do NOT apply
   --vf-stage-shape — that inset is for full-stage overlays and would wipe them. */
html:has(#vf-bezel) .profile-selection-overlay.is-inline,
html:has(#vf-bezel) .profile-selection-overlay.onboarding-overlay {
    clip-path: none !important;
    overflow: hidden !important;
}
/* Glass hosts: keep overscan parallax inside the glass box itself. */
html:has(#vf-bezel) .vf-glass.vf-bg-parallax-host {
    overflow: hidden !important;
}

/* Empty sub-nav (PROFILES): same bar and frame as the other tabs, nothing inside. */
.home-station-content .hs-subnav.hs-subnav-empty { pointer-events: none; }
.home-station-content .hs-subnav.hs-subnav-empty > * { visibility: hidden; }
html body .home-station-overlay .home-station-content > .hs-subnav.hs-subnav-empty { height: 50px !important; min-height: 50px !important; }

/* Name step: input + GENERATE NAME button side by side. */
.profile-name-row { display: flex; align-items: stretch; justify-content: center; gap: calc(8 * var(--bz-u)); }
.profile-name-row .profile-name-input { flex: 1 1 auto; min-width: 0; }
.profile-name-row .profile-name-gen-wrap { flex: 0 0 auto; margin: 0 !important; padding: 0 !important; width: auto !important; position: static; display: flex; }
.profile-name-row .profile-name-gen { white-space: nowrap; margin: 0; }
.profile-name-row .profile-name-gen { font-size: calc(18 * var(--bz-u)) !important; padding: 0 calc(18 * var(--bz-u)) !important; }

/* Fight HUD follows the per-size font settings (TEXT / SMALL family), not just the global font */
html body .game-container .enemy-vitals-side :is(.enemy-faction, .enemy-name) { font-family: var(--ui-font-text, var(--ui-font-family)); }
html body .game-container .enemy-vitals-side :is(.enemy-hp-text, .enemy-shield-text) { font-family: var(--ui-font-small, var(--ui-font-family)); }
html body .game-container #gameInfoPanel { font-family: var(--ui-font-text, var(--ui-font-family)); }

/* Station: inner pad inside the glass opening; top clears overlapping rim art. */
html body .home-station-overlay .home-station-content {
    padding: calc(40px / var(--hs-z)) calc(12px / var(--hs-z)) calc(10px / var(--hs-z)) !important;
    box-sizing: border-box !important;
}

/* Faction relation tabs: every card is the same size in every state and wears
   its own faction's shape + colour; active / hover only change the frame. */
.home-station-overlay .hs-faction-tabs.hs-faction-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    align-items: stretch;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-tab.hs-faction-card,
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-tab.hs-faction-card:is(:hover, .nav-focused, .active) {
    margin: 0 !important;
    padding: var(--fac-space) !important;
    border: 0 !important;
    clip-path: var(--faction-ctl-clip, none) !important;
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 14%, #05060a) 0%, #020203 85%) !important;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 4px color-mix(in srgb, var(--color-primary) 55%, transparent) !important;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-tab.hs-faction-card:is(:hover, .nav-focused) {
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 4px var(--color-primary),
        inset 0 0 18px color-mix(in srgb, var(--color-primary) 55%, transparent) !important;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-tab.hs-faction-card.active {
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 30%, #05060a) 0%, #020203 85%) !important;
    box-shadow:
        inset 0 0 0 2px #05060a,
        inset 0 0 0 5px var(--color-primary),
        inset 0 0 24px var(--color-primary) !important;
}
/* Same layout in every card: status badge always on its own line. */

html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-status {
    order: 3;
    flex: 0 0 auto;
    margin-left: auto;
}
.home-station-overlay .hs-faction-tabs .hs-faction-head::after { order: 2; flex: 0 0 100%; height: 0;}

/* Relation badge sits in the bottom row between planet count and trade icon:
   fixed layout, nothing wraps or jumps with the card width. */
.home-station-overlay .hs-faction-tabs .hs-faction-head { flex-wrap: nowrap; }
.home-station-overlay .hs-faction-tabs .hs-faction-head::after { content: none; }
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-stats {
    flex-wrap: nowrap;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-stats .hs-faction-status {
    order: 0;
    margin: 0;
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: clip;
    white-space: nowrap;
}

/* Faction tabs: big crest on the left, name + bar to its right, taller cards. */
.home-station-overlay .hs-faction-tabs .hs-faction-top { display: flex; align-items: center; gap: 12px; min-width: 0; }
.home-station-overlay .hs-faction-tabs .hs-faction-main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 8px; }
html body .home-station-overlay .hs-faction-tabs .hs-faction-crest,
html body .home-station-overlay .hs-faction-tabs .hs-faction-crest img {
    width: 56px !important;
    height: 56px !important;
    flex: none;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-tab.hs-faction-card {
    min-height: 120px !important;
    gap: 12px;
}
html body .home-station-overlay .home-station-content .hs-body { padding-left: 0 !important; }
/* The framed body has a 4px left border: pull it out so its content (sections) sits at the same 8px as PLAY */
html body .home-station-overlay .home-station-content .hs-body:not(.hs-body-play) { margin-left: -4px !important; }
/* Sections: inner containers sit flush on the same left line (16px from the bezel opening) */
html body .home-station-overlay .home-station-content .hs-body :is(.hs-section, .hs-panel) { padding-left: 0 !important; }
/* Station storage grid: clear clip-path stairs (~6–10px) AND the inset frame rings
   on .hs-panel (box-shadow inset up to 24px). 14px still sat under the frame. */
