    padding-left: 0 !important;
}
html body .home-station-overlay .home-station-content .hs-body :is(.hs-factions, .hs-faction-tabpanel) { padding-left: 0 !important; }
html body .home-station-overlay .home-station-content .hs-menu-host > .start-screen-content { padding-left: 0 !important; border-left-width: 0 !important; }

/* Fleet preview: taller stage (the canvas is 480x290 now, not just a bigger scale). */
.hs-fd-fleet-stage { min-height: min(680px, 78vh); }

/* Faction colours as a list below the preview; the base (hull) colour is editable. */
.hs-fd-colors { display: flex; flex-direction: column; gap: 6px; }
.hs-fd-color-row { display: flex; align-items: center; gap: 10px; font-size: var(--font-text); letter-spacing: 1px; min-width: 0; }
.hs-fd-color-row em { font-style: normal; opacity: 0.6;}
.hs-fd-color-row.is-editable { cursor: pointer; }
.hs-fd-color-row input[type="color"] { width: 20px; height: 20px; padding: 0; border: var(--ui-border-width, 2px) solid #000; box-shadow: 0 0 0 var(--ui-border-width, 2px) rgba(255,255,255,0.25); background: none; cursor: pointer; }
.hs-fd-color-row .hs-fd-swatch { flex: 1 1 auto; }
.hs-fd-color-row .hs-fd-swatch em { margin-left: auto; }
/* PLAY button on the same left line as the sections */
html body .home-station-overlay .home-station-content .hs-header { padding-left: 0 !important; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block > :is(.hs-fd-colors, .hs-fd-text) {
    padding-inline: 16px !important;
    box-sizing: border-box;
}

/* Hue sliders (lightness / saturation stay as in the faction's default colour). */
.hs-fd-color-chip { flex: none; width: 20px; height: 20px; border: var(--ui-border-width, 2px) solid #000; box-shadow: 0 0 0 var(--ui-border-width, 2px) rgba(255,255,255,0.25); }
.hs-fd-color-label { flex: 0 0 150px; }
.hs-fd-hue { flex: 1 1 auto; min-width: 80px; height: 10px; appearance: none; -webkit-appearance: none; cursor: pointer; border: var(--ui-border-width, 2px) solid #000;
    background: linear-gradient(to right, #f00 0%, #ff0 13.3%, #0f0 26.7%, #0ff 40%, #00f 53.3%, #f0f 66.7%, #f00 79.8%,
        #0c0d12 80% 86.6%, #808890 86.7% 93.3%, #e6eaf0 93.4% 100%); }
.hs-fd-hue::-webkit-slider-thumb { -webkit-appearance: none; width: 8px; height: 20px; background: #fff; border: 2px solid #000; }
.hs-fd-hue::-moz-range-thumb { width: 8px; height: 20px; border-radius: 0; background: #fff; border: 2px solid #000; }
.hs-fd-color-row em { flex: 0 0 76px; margin-left: 0; text-align: right; }

/* The taller fleet stage must push the colour list down, not overlap it. */
.hs-fd .hs-fd-fleet { height: auto; flex: 0 0 auto; }
.hs-fd-colors { position: relative; z-index: 1; flex: 0 0 auto; }

/* COLORS: collapsed to one toggle; open, the list overlays the area above on its own background. */
.hs-fd-colors-wrap { position: relative; flex: 0 0 auto; }
.hs-fd-colors-wrap .hs-fd-colors { display: none; }
.hs-fd-colors-wrap.is-open .hs-fd-colors {
    display: flex;
    position: absolute;
    left: 0;
    right: 0;
    bottom: 100%;
    margin-bottom: 6px;
    padding: 14px 16px;
    z-index: 20;
    background: color-mix(in srgb, #05060a 94%, var(--faction-accent, var(--color-primary)));
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
    box-shadow: 0 0 24px rgba(0, 0, 0, 0.7);
}

/* While a slider is dragged the panel turns see-through, so the live preview behind it is visible. */
.hs-fd-colors-wrap.is-dragging .hs-fd-colors { opacity: 0.18; transition: opacity 0.12s; }

/* Per colour: HUE / SAT / LIGHT sliders (LIGHT: middle = the faction's default). */
.hs-fd-color-block { display: flex;}
.hs-fd-color-block + .hs-fd-color-block { padding-top: 8px; border-top: var(--ui-border-width, 2px) solid rgba(255, 255, 255, 0.08); }
.hs-fd-sliders { display: grid; grid-template-columns: auto minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; padding-left: 30px;}
.hs-fd-slider-tag { font-size: var(--font-small); letter-spacing: 1px; opacity: 0.7; }
.hs-fd-adj { width: 100%; min-width: 0; appearance: none; -webkit-appearance: none; cursor: pointer; border: var(--ui-border-width, 2px) solid #000;}
.hs-fd-adj-h { background: linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); }

.hs-fd-adj::-webkit-slider-thumb { -webkit-appearance: none; background: #fff; border: 2px solid #000;}
.hs-fd-adj::-moz-range-thumb { border-radius: 0; background: #fff; border: 2px solid #000;}
.hs-fd-color-row .hs-fd-color-label { flex: 1 1 auto; }

/* Thicker sliders; SAT / LIGHT are 3-step and narrow, HUE takes the room. */
.hs-fd-sliders { grid-template-columns: auto minmax(0, 1fr) auto 84px auto 84px; gap: 8px 12px; }
.hs-fd-adj { height: 18px; }
.hs-fd-adj::-webkit-slider-thumb { width: 12px; height: 30px; }
.hs-fd-adj::-moz-range-thumb { width: 12px; height: 30px; }

/* SAT / LIGHT: three distinct blocks instead of a gradient. */
.hs-fd-adj-s { background: linear-gradient(to right, #8a7a94 0 32%, #05060a 32% 34%, #b060e0 34% 66%, #05060a 66% 68%, #d040ff 68% 100%); }
.hs-fd-adj-l { background: linear-gradient(to right, #1a1a1e 0 32%, #05060a 32% 34%, #808088 34% 66%, #05060a 66% 68%, #e8e8f0 68% 100%); }
.hs-fd-colors-head { display: flex; align-items: center; justify-content: space-between; font-size: var(--font-text); letter-spacing: 2px; opacity: 0.9; }
.hs-fd-colors-actions { display: flex; justify-content: flex-end; gap: 8px; padding-top: 4px; }

/* Nav cards share PLAY's bottom edge: the card row fills the full height of
   the header (header-main -> topbar -> tabs), so the cards' margins (8px 0 6px)
   resolve against the same box as PLAY's. */
html body .home-station-overlay .home-station-content .hs-header-split > .hs-header-main {
    display: flex !important;
    flex-direction: column;
    align-self: stretch;
    padding: 0 !important;
    margin: 0 !important;
}
html body .home-station-overlay .home-station-content .hs-header-main > .hs-topbar,
html body .home-station-overlay .home-station-content .hs-header-main > .hs-topbar > .hs-tabs {
    display: flex !important;
    flex: 1 1 auto;
    align-self: stretch;
    min-height: 0;
}
.hs-fd-sliders { grid-template-columns: auto minmax(0, 1fr) auto 84px auto 84px auto; }

/* Colour rows: picker chip + label sit to the LEFT of the sliders. */
.hs-fd-color-block { flex-direction: row; align-items: center; gap: 16px; }
.hs-fd-color-block .hs-fd-color-row { flex: 0 0 230px; flex-wrap: wrap; row-gap: 2px; }
.hs-fd-color-block .hs-fd-color-label { flex: 1 1 auto; font-size: var(--font-h2); letter-spacing: 2px; }
.hs-fd-color-block .hs-fd-color-row em { flex: 0 0 100%; text-align: left; padding-left: 30px; font-size: var(--font-small); }
.hs-fd-color-block .hs-fd-sliders { flex: 1 1 auto; min-width: 0; padding-left: 0; }

/* Frame colours in the visual settings plate: same chip + rainbow / stepped sliders as the fleet colours. */
.vf-fr-color { display: flex; flex-direction: column; gap: 6px; padding: 6px 0; }
.vf-fr-color + .vf-fr-color { border-top: var(--ui-border-width, 2px) solid rgba(255, 255, 255, 0.08); }
.vf-fr-sliders { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: center; gap: 8px; padding-left: 0; }
.vf-fr-sliders .hs-fd-slider-tag { display: none; }
.vf-fr-color .hs-fd-color-row { display: flex; align-items: center; gap: 10px; }
.vf-fr-color .hs-fd-color-row em { margin-left: auto; font-style: normal; opacity: 0.6; }
.vf-fx-actions { display: flex; justify-content: flex-end; gap: 8px; }

/* Colour sliders inside the visual-settings plate: same rainbow / stepped tracks as the station. */
.vf-bezel-fx input.hs-fd-adj[type="range"] {
    width: 100%;
    height: 10px;
    min-width: 0;
    border: var(--ui-border-width, 2px) solid #000;
    box-shadow: none;
}
.vf-bezel-fx input.hs-fd-adj-h[type="range"] { background: linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); }
.vf-bezel-fx input.hs-fd-adj-s[type="range"] { background: linear-gradient(to right, #8a7a94 0 32%, #05060a 32% 34%, #b060e0 34% 66%, #05060a 66% 68%, #d040ff 68% 100%); }
.vf-bezel-fx input.hs-fd-adj-l[type="range"] { background: linear-gradient(to right, #1a1a1e 0 32%, #05060a 32% 34%, #808088 34% 66%, #05060a 66% 68%, #e8e8f0 68% 100%); }
.vf-bezel-fx input.hs-fd-adj[type="range"]::-webkit-slider-runnable-track { height: 6px; background: transparent; box-shadow: none; }
.vf-bezel-fx input.hs-fd-adj[type="range"]::-moz-range-track { height: 6px; background: transparent; box-shadow: none; }
.vf-bezel-fx input.hs-fd-adj[type="range"]::-webkit-slider-thumb { width: 10px; height: 20px; margin-top: -7px; background: #fff; border: 2px solid #000; box-shadow: none; }
.vf-bezel-fx input.hs-fd-adj[type="range"]::-moz-range-thumb { width: 6px; height: 16px; border-radius: 0; background: #fff; border: 2px solid #000; box-shadow: none; }
.vf-bezel-fx .vf-fr-sliders { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.vf-fx-title-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.vf-fx-title-row .vf-fx-reset { width: auto; flex: 0 0 auto; padding: 2px 12px; }

/* FACTIONS: the faction tab bar stays pinned while the detail below scrolls. */
html body .home-station-overlay .home-station-content .hs-factions > .hs-faction-tabs {
    position: sticky;
    top: 0;
    z-index: 5;
    background: var(--hs-tabpanel, var(--color-background, #05060a));
}

/* Pixel frame: the BEVEL slider sets the glass-edge band (never thinner than one grid cell). */
html[data-vf-frame-px="on"] #vf-bezel { --fr-bv: max(var(--fr-px, 5px), var(--fr-bevel-set, 0px)); }

/* DECO slider: faction deco animations own `opacity`, so the slider fades the art through a
   mask alpha instead (multiplies with the animation). */
.vf-bezel .vf-bezel-deco {
    -webkit-mask: var(--hole), linear-gradient(rgba(0, 0, 0, var(--fr-deco, 1)) 0 0);
    -webkit-mask-composite: xor;
    mask: var(--hole) exclude, linear-gradient(rgba(0, 0, 0, var(--fr-deco, 1)) 0 0);
}

/* In-game HUD fonts: Fernbedienung TEXT · LG/MD/SM × IN-GAME %. */
.game-container {
    --font-lg: var(--game-font-lg, var(--game-font-h1));
    --font-md: var(--game-font-md, var(--game-font-h2));
    --font-sm: var(--game-font-sm, var(--game-font-small));
    --font-h1: var(--font-lg);
    --font-h2: var(--font-md);
    --font-text: var(--font-md);
    --font-small: var(--font-sm);
    --font-text-small: var(--font-sm);
    --font-base: var(--font-md);
    font-size: var(--font-md);
}
/* LG — titles (mission-start sizes live in part-02; do not clamp them here) */
html body .game-container :is(.gi-head-text h3, .game-info-header h3) {
    font-size: var(--font-lg) !important;
}
/* MD — values & names */
html body .game-container :is(
    .gi-metric-value, .gi-row-value, .gi-loot-count, .gi-chip-count, .gi-stage,
    #currentWeapon, .weapon-display, .weapon-display span, .weapon-selection,
    .enemy-faction, .enemy-name, .enemy-hp-text, .enemy-shield-text
) {
    font-size: var(--font-md) !important;
}
/* SM — labels */
html body .game-container :is(
    .gi-cluster-title, .gi-metric-label, .gi-row-label, .gi-chip-row-label,
    .gi-chip-label, .gi-diff, .level-difficulty, .weapon-info, #weaponInfo,
    .weapon-info .wi-part, .gi-size-btn, .controls-info, .shot-type-display
) {
    font-size: var(--font-sm) !important;
}
html[data-game-font="custom"] .game-container,
html[data-game-font="custom"] .game-container :is(div, span, p, h1, h2, h3, h4, button, label, strong, em, small, b, li) {
    font-family: var(--game-font-family) !important;
}

/* Nav cards sit exactly where PLAY sits: the top bar / tab row around them add no
   padding of their own, so the cards' 8px / 6px margins are the only gaps
   (same distance to the sub-nav below as PLAY). */
html body .home-station-overlay .home-station-content .hs-header-main > .hs-topbar,
html body .home-station-overlay .home-station-content .hs-header-main > .hs-topbar > .hs-tabs,
html body .home-station-overlay .home-station-content .hs-header-split > .hs-header-main {
    padding: 0 !important;
    margin: 0 !important;
}

/* Final say for the nav cards (measured): same height and top/bottom edges as PLAY,
   in every state — PLAY is pinned to 120px, so the area cards match it exactly
   instead of auto-sizing to their (shorter) content. */
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn {
    margin: 8px 0 6px !important;
    min-height: 120px !important;
    height: 120px !important;
    align-self: stretch !important;
}

/* Active nav card = the same card as the others (same clip, same frame layers, same label
   strip); it only lights up: brighter inner glow and an accent label. No open bottom. */
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active {
    box-shadow: none !important;
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 18%, #05060a) 0%, #020203 80%) !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before,
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    display: block !important;
    inset: 0;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 30%, #05060a) 0%, #020203 80%);
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active .hs-tab-label {
    margin: 0 5px 5px !important;
    font-weight: 700 !important;
    letter-spacing: normal;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before {
    background: var(--color-primary) !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--color-primary) 24%, #05060a) 0%, #020203 80%);
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before,
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    z-index: 0 !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-icon {
    position: relative;
    z-index: 1;
    background: none !important;
    box-shadow: none !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-label { position: relative; z-index: 1; }

/* Active nav card: the icon box fills the whole card, so the holo scanline overlay striped the
   entire card and swallowed the icon. The card only lights up; the icon keeps its 64px size. */
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-icon::after {
    content: none !important;
    display: none !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-icon :is(img, canvas, .hs-tab-pixel, .ui-icon-tip) {
    width: 64px !important;
    height: 64px !important;
    max-width: 64px;
    max-height: 64px;
    flex: none;
    /* Cancel the global active tint hack (translateX -200px + drop-shadow):
       filter:none already wins on area-btn icons, so the shifted sprite stays
       clipped by overflow:hidden and the icon vanishes. */
    transform: none !important;
    translate: none !important;
    filter: none !important;
    opacity: 1 !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-icon {
    overflow: visible !important;
}
/* Active/hover corner deco + PLAY planets: SVG tint filter draws orange blobs
   on the card frame. Keep the cards clean. */
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn .hs-area-deco,
html body .home-station-overlay .home-station-content .hs-header-split > .hs-play-launch .hs-play-launch-planets {
    display: none !important;
}

/* Active nav card: open at the bottom, its body runs down into the sub-nav panel below. No glow on the
   card; only the icon gets brighter. Frame (::before) and fill (::after) reach 12-14px past the card. */
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active {
    clip-path: none !important;
    overflow: visible !important;
    position: relative;
    z-index: 3;
    filter: none !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before {
    border-radius: 18px 18px 0 0 / 6px 6px 0 0;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    border-radius: 15px 15px 0 0 / 3px 3px 0 0;
    background: var(--hs-tabpanel);
    box-shadow: none;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.active .hs-tab-icon {
    filter: none !important;
    opacity: 1 !important;
    overflow: visible !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before,
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after {
    position: absolute !important;
    width: auto !important;
    height: auto !important;
    margin: 0 !important;
}

/* Fixed gap between the nav cards and the sub-nav bar below (14px, same in every state);
   the active card's bridge spans exactly that gap. */
html body .home-station-overlay .home-station-content .hs-subnav {
    margin-top: 10px !important;
}
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before { inset: 0 0 -14px 0 !important; }
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after { inset: 3px 3px -16px 3px !important; }
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::before,
html body .home-station-overlay .home-station-content .hs-header-main .hs-tabs .hs-tab.hs-area-btn.hs-area-btn.hs-area-btn.hs-area-btn.active::after { clip-path: none !important; }

/* Sub-nav tabs: only the active tab (and hover / keyboard focus) carries the frame;
   idle tabs are bare label + icon. The frame is the tab's own inset shadow. */
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-subnav-tab, .hs-menu-tab-btn) {
    box-shadow: none !important;
    background: transparent !important;
}
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-subnav-tab, .hs-menu-tab-btn):is(.active, :hover, :focus-visible, .nav-focused) {
    background: color-mix(in srgb, var(--color-primary) 14%, #05060a) !important;
    box-shadow:
        inset 0 0 0 2px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 80%, transparent),
        inset 0 0 0 4px #05060a,
        inset 0 0 0 5px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent) !important;
}

/* Remote parked on the left: it slides out / in on the left edge. */
.vf-bezel-fx.is-left { translate: -100vw 0; rotate: -5deg; transform-origin: 0 100%; }
.vf-bezel-fx.is-left.is-in { translate: 0 0; rotate: 0deg; }

/* Sub-nav (STORAGE / SHIPYARD / …): larger labels and icons (icons on the 2× pixel grid). */
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-tab, .hs-menu-tab-btn) {
    height: 46px !important;
    min-height: 46px !important;
    max-height: 46px !important;
    gap: 10px;
}
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-tab, .hs-menu-tab-btn) :is(.hs-tab-icon, .hs-menu-tab-icon, .hs-tab-icon img, .hs-menu-tab-icon img, .hs-tab-pixel),
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-tab-icon, .hs-tab-pixel) {
    width: 32px !important;
    height: 32px !important;
    flex: 0 0 32px;
}
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-tab, .hs-menu-tab-btn) :is(.hs-tab-label, .hs-menu-tab-label),
html body .home-station-overlay .home-station-content .hs-subnav :is(.hs-tab, .hs-menu-tab-btn):is(.active, .nav-focused, :hover) :is(.hs-tab-label, .hs-menu-tab-label) {
    font-size: calc(var(--font-h2) * 1.3) !important;
}

/* Map bar: ANDROMEDA / INVASION stack on the left, the planet card next to it. */
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-stack { order: 1; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-seg.is-planet { order: 2; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-seg.is-actions { order: 3; }

/* Ruler card (ANDROMEDA / CONTESTED): the faction emblem sits on the left of the name. */
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-card {
    flex-direction: row;
    justify-content: flex-start;
}

/* Invasion card: a mission-button icon in front of the title; it animates when the card is hovered. */
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-situation-go {
    display: inline-flex;
    align-items: center;
