.gm-edge.gm-pxline.lit .gm-pxline-glow { opacity: 0.35; }
.gm-edge.gm-pxline.lit .gm-pxline-halo { opacity: 0.12; }
.gm-edge.gm-pxline.lit.next { opacity: 1; }
.gm-edge.gm-pxline.lit.next .gm-pxline-core { filter: brightness(1.9) saturate(1.2); }
.gm-edge.gm-pxline.lit.next .gm-pxline-glow { opacity: 0.85; }
.gm-edge.gm-pxline.lit.next .gm-pxline-halo { opacity: 0.4; }

/* PERF switches from the remote's PERF tab */
html[data-vf-perf-heavy="off"] .vf-fx-chroma,
html[data-vf-perf-heavy="off"] .vf-fx-bloom,
html[data-vf-perf-heavy="off"] .vf-fx-crt { display: none; }
