html[data-vf-performance] .vf-fx-bloom,
html[data-vf-performance] .vf-fx-crt,
html[data-vf-performance] .vf-fx-scanwarp,
html[data-vf-performance] .vf-fx-hdr,
html[data-vf-performance] .vf-fx-hdr-shadow { display: none !important; }
html[data-vf-performance] .vf-fx-scanlines,
html[data-vf-performance] .vf-fx-noise,
html[data-vf-performance] .vf-fx-flicker,
html[data-vf-performance] .menu-item.selected,
