.vf-bezel-fx .vf-fx-fps { font-variant-numeric: tabular-nums; }

/* Faction trait hover modal: all traits stacked, icon container left, info right */
.hs-trait-modal { position: fixed; inset: 0; z-index: 9000; display: grid; place-items: center; pointer-events: none; background: rgba(2, 4, 8, 0.55); animation: hs-trait-fade 0.16s ease-out both; }
.hs-trait-modal.is-out { animation: hs-trait-fade-out 0.16s ease-in both; }
.hs-trait-modal-card { display: flex; flex-direction: column; gap: 12px; width: min(560px, 86vw); padding: 20px 24px; background: #05060a; border: 3px solid var(--trait-accent); box-shadow: 0 0 0 3px #05060a, 0 0 28px color-mix(in srgb, var(--trait-accent) 55%, transparent); animation: hs-trait-pop 0.32s cubic-bezier(.2, 1.4, .4, 1) both; }
.hs-trait-modal-fac { font-size: var(--font-text); letter-spacing: 3px; color: var(--trait-accent); padding-bottom: 8px; border-bottom: 2px solid color-mix(in srgb, var(--trait-accent) 35%, transparent); }
.hs-trait-modal-row { display: flex; align-items: center; gap: 18px; padding: 8px; border: 2px solid transparent; opacity: 0.55; animation: hs-trait-row 0.3s ease-out both; }
.hs-trait-modal-row.is-hot { opacity: 1; border-color: color-mix(in srgb, var(--trait-accent) 60%, transparent); background: color-mix(in srgb, var(--trait-accent) 10%, transparent); }
.hs-trait-modal-ico { flex: 0 0 auto; display: grid; place-items: center; width: 88px; height: 88px; background: #05060a; border: 3px solid var(--trait-accent); box-shadow: 0 0 14px color-mix(in srgb, var(--trait-accent) 45%, transparent); }
.hs-trait-modal-ico img { width: 64px !important; height: 64px !important; image-rendering: pixelated; filter: drop-shadow(0 0 8px color-mix(in srgb, var(--trait-accent) 70%, transparent)); }
.hs-trait-modal-txt { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.hs-trait-modal-txt b { letter-spacing: 2px; color: var(--color-text, #fff);}
.hs-trait-modal-txt em { font-style: normal; color: color-mix(in srgb, var(--color-text, #fff) 75%, transparent);}
@keyframes hs-trait-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes hs-trait-fade-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes hs-trait-pop { 0% { transform: scale(0.6); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
@keyframes hs-trait-row { from { transform: translateX(-24px); opacity: 0; } to { transform: translateX(0); } }
.hs-fd-trait[data-trait-key] { cursor: help; }

/* The icons animate themselves, per trait, in stepped (pixel) motion. The hovered row runs faster. */
.hs-trait-modal-ico img { animation-duration: 1.6s; animation-iteration-count: infinite; animation-timing-function: steps(8, end); transform-origin: 50% 50%; }
.hs-trait-modal-row.is-hot .hs-trait-modal-ico img { animation-duration: 0.9s; }
.hs-trait-modal-ico[data-ico="navCoin"] img { animation-name: hs-ti-spin; }
.hs-trait-modal-ico[data-ico="navSkull"] img { animation-name: hs-ti-twitch; animation-timing-function: steps(1, end); }
.hs-trait-modal-ico[data-ico="navFlag"] img { animation-name: hs-ti-wave; transform-origin: 20% 50%; }
.hs-trait-modal-ico[data-ico="navGear"] img { animation-name: hs-ti-rot; animation-timing-function: steps(8, end); }
.hs-trait-modal-ico[data-ico="navAtom"] img { animation-name: hs-ti-rot; animation-timing-function: steps(12, end); animation-duration: 3.2s; }
.hs-trait-modal-ico[data-ico="navPlanet"] img { animation-name: hs-ti-glow; }
.hs-trait-modal-ico[data-ico="navFactory"] img { animation-name: hs-ti-pump; }
.hs-trait-modal-ico[data-ico="navLock"] img { animation-name: hs-ti-shake; animation-timing-function: steps(1, end); }
.hs-trait-modal-ico[data-ico="navTrophy"] img { animation-name: hs-ti-glow; }
.hs-trait-modal-ico[data-ico="navSword"] img { animation-name: hs-ti-swing; animation-timing-function: steps(6, end); }
.hs-trait-modal-ico[data-ico="navCrosshair"] img { animation-name: hs-ti-lock; }
.hs-trait-modal-ico[data-ico="navStar"] img { animation-name: hs-ti-twinkle; animation-timing-function: steps(1, end); }
.hs-trait-modal-ico[data-ico="navChart"] img { animation-name: hs-ti-grow; transform-origin: 50% 100%; }
.hs-trait-modal-ico[data-ico="navScroll"] img { animation-name: hs-ti-wave; transform-origin: 50% 0%; }
.hs-trait-modal-ico[data-ico="navQuestion"] img { animation-name: hs-ti-twitch; animation-timing-function: steps(1, end); }
@keyframes hs-ti-spin { 0% { transform: scaleX(1); } 25% { transform: scaleX(0.5); } 50% { transform: scaleX(0.08); } 75% { transform: scaleX(0.5); } 100% { transform: scaleX(1); } }
@keyframes hs-ti-twitch { 0%, 60%, 100% { transform: translate(0, 0); } 65% { transform: translate(-3px, 1px) rotate(-4deg); } 75% { transform: translate(3px, -1px) rotate(4deg); } 85% { transform: translate(-2px, 0); } }
@keyframes hs-ti-wave { 0% { transform: skewY(0); } 25% { transform: skewY(-8deg); } 50% { transform: skewY(0); } 75% { transform: skewY(8deg); } 100% { transform: skewY(0); } }
@keyframes hs-ti-rot { to { transform: rotate(360deg); } }
@keyframes hs-ti-glow { 0%, 100% { filter: brightness(1); } 50% { filter: brightness(1.6) drop-shadow(0 0 6px var(--trait-accent)); } }
@keyframes hs-ti-pump { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.14, 0.9); } }
@keyframes hs-ti-shake { 0%, 70%, 100% { transform: translateX(0); } 75% { transform: translateX(-3px); } 85% { transform: translateX(3px); } 95% { transform: translateX(-2px); } }
@keyframes hs-ti-swing { 0%, 100% { transform: rotate(-18deg); } 50% { transform: rotate(18deg); } }
@keyframes hs-ti-lock { 0% { transform: rotate(0) scale(1.15); } 50% { transform: rotate(45deg) scale(0.9); } 100% { transform: rotate(90deg) scale(1.15); } }
@keyframes hs-ti-twinkle { 0%, 100% { transform: scale(1); filter: brightness(1); } 40% { transform: scale(1.2); filter: brightness(1.7); } 55% { transform: scale(0.9); } }
@keyframes hs-ti-grow { 0%, 100% { transform: scaleY(0.75); } 50% { transform: scaleY(1.1); } }
html[data-vf-perf-anim="off"] .hs-trait-modal-card, html[data-vf-perf-anim="off"] .hs-trait-modal-row, html[data-vf-perf-anim="off"] .hs-trait-modal-ico img { animation: none; }

/* MISSION BOARD rows: four columns (name | difficulty + stage progress | bounty | actions) so the width is used
   and the text is large enough to read. Scoped to the board, contracts reuse .hs-mission with their own layout. */
html body .hs-missions-root .hs-mission {
    grid-template-columns: minmax(180px, 1.1fr) minmax(150px, 0.9fr) auto auto;
    gap: 20px;
    padding: 12px 18px;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
}
html body .hs-missions-root .hs-mission .hs-mission-type { font-size: var(--font-text); }
html body .hs-missions-root .hs-mission .hs-line-name strong { font-size: 24px; color: var(--color-text, #fff); }
.hs-mission-info { display: flex; flex-direction: column; gap: 8px; min-width: 0; padding-left: 20px; border-left: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 30%, transparent); }
html body .hs-missions-root .hs-mission-diff { font-size: var(--font-h2); letter-spacing: 2px; color: var(--color-text, #fff); }
.hs-mission-stages { display: flex; align-items: center; gap: 10px; font-size: var(--font-h2); }
.hs-mission-stages b { color: var(--color-text, #fff); }
.hs-mission-stages small { font-size: var(--font-text); letter-spacing: 2px; color: color-mix(in srgb, var(--color-text, #fff) 70%, transparent); }
.hs-mission-pips { display: inline-flex; gap: 4px; }
.hs-mission-pips i { width: 18px; height: 10px; border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent); background: transparent; box-sizing: border-box; }
.hs-mission-pips i.on { background: var(--faction-accent, var(--color-primary)); }
html body .hs-missions-root .hs-mission .hs-line-action { min-width: 150px; }

/* Mission board: faction lane (issuer > target) and action-style buttons */
.hs-mission-lane { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
.hs-mission-fac { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px 3px 4px; border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--fac) 65%, transparent); background: color-mix(in srgb, var(--fac) 12%, #05060a); }
.hs-mission-fac b { font-size: var(--font-text); letter-spacing: 1px; color: var(--fac); }
.hs-mission-fac img { width: 24px; height: 24px; image-rendering: pixelated; }
.hs-mission-fac.is-target { background: color-mix(in srgb, var(--fac) 24%, #05060a); box-shadow: 0 0 10px color-mix(in srgb, var(--fac) 40%, transparent); }
.hs-mission-arrow { font-size: var(--font-text); color: var(--color-text, #fff); opacity: 0.75; }
html body .hs-missions-root .hs-mission .hs-mission-go,
html body .hs-missions-root .hs-mission .hs-mission-abort { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-weight: bold; letter-spacing: 2px; }
html body .hs-missions-root .hs-mission .hs-mission-go {
    min-width: 230px;
    color: #05060a;
    background: linear-gradient(180deg, color-mix(in srgb, var(--faction-accent, var(--color-primary)) 100%, #fff 18%), var(--faction-accent, var(--color-primary)));
    border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 100%, #fff 30%);
    box-shadow: 0 0 14px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent), inset 0 -4px 0 rgba(0, 0, 0, 0.28);
    transition: transform 0.08s steps(2), filter 0.1s;
}
html body .hs-missions-root .hs-mission .hs-mission-go:hover:not(:disabled) { filter: brightness(1.18); transform: translateY(-2px); }
html body .hs-missions-root .hs-mission .hs-mission-go:active:not(:disabled) { transform: translateY(2px); box-shadow: inset 0 2px 0 rgba(0, 0, 0, 0.3); }
html body .hs-missions-root .hs-mission .hs-mission-go:disabled, html body .hs-missions-root .hs-mission .hs-mission-go.is-locked { color: color-mix(in srgb, var(--color-text, #fff) 55%, transparent); background: #0a0c10; box-shadow: none; border-color: color-mix(in srgb, var(--color-text, #fff) 25%, transparent); }
.hs-go-ico { display: inline-grid; place-items: center; }
.hs-go-ico img { width: 24px; height: 24px; image-rendering: pixelated; filter: brightness(0) drop-shadow(0 0 0 transparent); }
.hs-mission-go:disabled .hs-go-ico img, .hs-mission-go.is-locked .hs-go-ico img { filter: brightness(0.8); }
.hs-mission-abort .hs-go-ico img { filter: none; }
html body .hs-missions-root .hs-mission { grid-template-columns: minmax(170px, 0.9fr) minmax(260px, 1.4fr) auto auto; }

/* Mission board bounty: one row of chips, icon exactly as tall as the (larger) amount text. */
html body .hs-body .hs-panel.hs-missions-root .hs-mission-reward { justify-self: end; align-self: center; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-bounty { display: flex; flex-wrap: nowrap; align-items: center; justify-content: flex-end; gap: 10px; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-bounty .hs-cost-cell { display: inline-flex; align-items: center; gap: 8px; padding: 6px 12px; min-height: 0; width: auto; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-reward * { font-size: 24px !important; line-height: 24px; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-bounty .hs-cost-icon { width: 24px; height: 24px; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-reward img { width: 24px !important; height: 24px !important; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission-bounty .hs-cost-amt { min-height: 0; min-width: 0; padding: 0; }

/* Mission board buttons: text must read on the bright fill (the theme's thin, glowing, wide-spaced button text did not). */
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-go,
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-go span {
    color: #02040a !important;
    text-shadow: none !important;
    font-size: var(--font-h2) !important;
    font-weight: 900;
    letter-spacing: 1px !important;
    opacity: 1;
}
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-go:disabled,
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-go:disabled span,
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-go.is-locked span { color: color-mix(in srgb, #fff 70%, transparent) !important; }
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-abort,
html body .hs-body .hs-panel.hs-missions-root .hs-mission .hs-mission-abort span { font-size: var(--font-h2) !important; letter-spacing: 1px !important; font-weight: bold; }

/* MISSION LOG: main quest chain + sidequests + location offers. */
.hs-mission-log .hs-log-body { display: flex; flex-direction: column; gap: 16px; min-height: 0; overflow: auto; }
.hs-log-block {
    display: flex; flex-direction: column; gap: 10px;
    padding: 14px 16px;
    border: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    background: color-mix(in srgb, var(--color-surface, #0b0b10) 88%, transparent);
}
.hs-log-main { border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 65%, transparent); }
.hs-log-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.hs-log-badge {
    font-size: var(--font-h2); letter-spacing: 0.14em; padding: 4px 10px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent);
    color: var(--faction-accent, var(--color-primary));
}
.hs-log-title { font-size: 22px; letter-spacing: 0.08em; color: var(--color-text, #fff); }
.hs-log-blurb, .hs-log-hint { margin: 0; font-size: var(--font-h2); line-height: 1.4; }
.hs-log-objective { margin: 0; font-size: var(--font-h2); letter-spacing: 0.06em; color: var(--color-text, #fff); }
.hs-log-objective b { color: var(--faction-accent, var(--color-primary)); margin-right: 8px; }
.hs-log-steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 8px; }
.hs-log-step {
    display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; align-items: center;
    padding: 10px 12px;
    border: 1px solid color-mix(in srgb, var(--color-primary) 22%, transparent);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
    opacity: 0.55;
}
.hs-log-step.is-active, .hs-log-step.is-focus { opacity: 1; border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent); background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 12%, transparent); }
.hs-log-step.is-done { opacity: 0.75; }
.hs-log-step-idx {
    width: 26px; height: 26px; display: inline-flex; align-items: center; justify-content: center;
    font-size: var(--font-h2); font-weight: bold;
    border: 1px solid color-mix(in srgb, var(--color-primary) 45%, transparent);
}
.hs-log-step-body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.hs-log-step-body b { font-size: var(--font-h2); letter-spacing: 0.08em; }
.hs-log-step-body small { font-size: var(--font-text); opacity: 0.8; letter-spacing: 0.06em; }
.hs-log-step-diff { font-size: var(--font-text); opacity: 0.85; letter-spacing: 0.08em; }
html body .hs-mission-log .hs-log-side,
html body .hs-mission-log .hs-log-offer {
    grid-template-columns: minmax(200px, 1.4fr) auto auto;
    gap: 16px; padding: 12px 14px;
}
html body .hs-mission-log .hs-line-name { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
html body .hs-mission-log .hs-line-name small { font-size: var(--font-text); letter-spacing: 0.06em; }

.hs-trait-modal-row { transition: opacity 0.12s, background-color 0.12s, border-color 0.12s; }
.hs-fd-col[data-im-name] { cursor: help; }
.hs-trait-modal-ico[data-ico="emblem"] img { animation-name: hs-ti-glow; }
.hs-trait-modal-ico img { animation-name: hs-ti-glow; }

/* FACTION OVERVIEW: two wide columns instead of four narrow ones, large type, an icon on every label. The blocks also
   get extra left padding: the faction corner cut was clipping the first letters of titles and labels. */
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-cols { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px !important; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block { padding: 18px 24px 18px 30px !important; gap: 10px !important; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block h4 { font-size: 22px; letter-spacing: 3px; padding-bottom: 8px; margin-bottom: 4px;}
.hs-fd-row-ico { flex: 0 0 auto; display: inline-grid; place-items: center; font-style: normal;}
.hs-fd-row-ico img { width: 24px; height: 24px; image-rendering: pixelated; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row { gap: 14px !important; font-size: 21px; line-height: 1.3; border-bottom: var(--ui-border-width, 2px) dashed color-mix(in srgb, var(--faction-accent, var(--color-primary)) 18%, transparent);}
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row:last-child { border-bottom: 0; }
.hs-fd-row-label { color: color-mix(in srgb, var(--color-text, #fff) 80%, transparent); letter-spacing: 1px;}

.hs-fd-resval img { width: 24px; height: 24px; image-rendering: pixelated; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row b { font-size: 21px; display: inline-flex; align-items: center;}
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-chips { gap: 10px !important; padding-top: 4px; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-chip { font-size: 20px;}
.hs-fd-weapon img { width: 24px; height: 24px; image-rendering: pixelated; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-text { font-size: 20px; line-height: 1.5; color: color-mix(in srgb, var(--color-text, #fff) 88%, transparent); }

/* More air between icon and label in the faction overview. */
.hs-fd-row-ico { margin-right: 6px;}
.hs-fd-row-label { gap: 18px; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block h4 { gap: 18px; }
.hs-fd-resval { gap: 14px; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row b { gap: 14px; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-chip { gap: 14px; padding: 8px 18px; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row { padding: 10px 0; }

/* Alignment: rows are a two-column grid (icon + label | value), icons sit in fixed boxes so every label starts at the
   same x, and everything is centred on one line. */
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row { display: grid; grid-template-columns: minmax(0, auto) minmax(0, 1fr); align-items: center; column-gap: 20px !important; }
.hs-fd-row-label { display: grid; grid-template-columns: 34px auto; align-items: center; column-gap: 16px; white-space: nowrap; line-height: 1; }
.hs-fd-row-ico { margin: 0; width: 34px; height: 34px; line-height: 0; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block .hs-fd-row b { justify-self: end; justify-content: flex-end; text-align: right; line-height: 1.2; }
html body .home-station-overlay .home-station-content .hs-factions .hs-fd-block h4 { display: grid; grid-template-columns: 34px auto; align-items: center; column-gap: 16px; line-height: 1; }
