/* Remote control: plastic depth — curved hull, glossy top edge, domed keys. */
.vf-bezel-fx {
    background:
        radial-gradient(ellipse 120% 40% at 50% 0, rgba(255, 255, 255, 0.10), transparent 70%),
        linear-gradient(90deg, color-mix(in srgb, var(--rc-hull) 70%, #000) 0, var(--rc-lit) 8%, var(--rc-hull) 28%, color-mix(in srgb, var(--rc-hull) 90%, #fff) 50%, var(--rc-hull) 72%, color-mix(in srgb, var(--rc-hull) 60%, #000) 100%);
    box-shadow:
        inset 4px 4px 0 var(--rc-lit),
        inset -4px -4px 0 var(--rc-dark),
        inset 0 0 0 8px color-mix(in srgb, var(--rc-hull) 85%, #000),
        inset 0 14px 18px -8px rgba(255, 255, 255, 0.16),
        inset 0 -22px 26px -10px rgba(0, 0, 0, 0.6),
        -8px 8px 0 rgba(0, 0, 0, 0.5);
}
.vf-bezel-fx .vf-fx-tabs button {
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.22) 0, rgba(255, 255, 255, 0.04) 38%, transparent 50%, rgba(0, 0, 0, 0.35) 100%),
        radial-gradient(ellipse at 50% 12%, color-mix(in srgb, var(--rc-lit) 90%, #fff) 0, transparent 65%),
        linear-gradient(180deg, var(--rc-hull), color-mix(in srgb, var(--rc-hull) 60%, #000));
    box-shadow:
        inset 0 3px 0 rgba(255, 255, 255, 0.28),
        inset 3px 0 0 var(--rc-lit),
        inset -3px 0 0 var(--rc-dark),
        inset 0 -5px 0 var(--rc-dark),
        inset 0 -9px 8px -4px rgba(0, 0, 0, 0.55);
}
.vf-bezel-fx .vf-fx-tabs button.on {
    background:
        linear-gradient(180deg, rgba(0, 0, 0, 0.45) 0, transparent 40%, rgba(255, 255, 255, 0.08) 100%),
        color-mix(in srgb, var(--rc-acc) 16%, var(--rc-hull));
    box-shadow:
        inset 0 4px 6px rgba(0, 0, 0, 0.7),
        inset 3px 0 0 var(--rc-dark),
        inset -3px 0 0 var(--rc-lit),
        inset 0 -2px 0 var(--rc-lit),
        inset 0 0 14px color-mix(in srgb, var(--rc-acc) 35%, transparent);
}
.vf-bezel-fx .vf-fx-head {
    box-shadow: inset 3px 3px 0 #000, inset -3px -3px 0 color-mix(in srgb, var(--rc-acc) 25%, #000), inset 0 8px 10px rgba(0, 0, 0, 0.6), inset 0 -2px 0 rgba(255, 255, 255, 0.12);
}

/* Remote control: embossed Meierdesigns brand mark above the speaker grill. */
.vf-bezel-fx::after {
    flex: 0 0 62px;
    background:
        repeating-linear-gradient(90deg, var(--rc-dark) 0 4px, transparent 4px 8px) 0 100% / 100% 14px no-repeat,
        url("../../assets/brand/meierdesigns-logo-dark.svg") 50% 2px / auto 38px no-repeat,
        url("../../assets/brand/meierdesigns-logo-light.svg") calc(50% + 1px) 3px / auto 38px no-repeat;
    box-shadow: none;
    opacity: 1;
}

/* Remote control: Meierdesigns mark as a glowing neon emblem (dark outline, then glow). */
.vf-bezel-fx {
    padding-bottom: 26px;
    background:
        repeating-linear-gradient(90deg, var(--rc-dark) 0 4px, transparent 4px 8px) 12px calc(100% - 8px) / calc(100% - 24px) 14px no-repeat,
        radial-gradient(ellipse 120% 40% at 50% 0, rgba(255, 255, 255, 0.10), transparent 70%),
        linear-gradient(90deg, color-mix(in srgb, var(--rc-hull) 70%, #000) 0, var(--rc-lit) 8%, var(--rc-hull) 28%, color-mix(in srgb, var(--rc-hull) 90%, #fff) 50%, var(--rc-hull) 72%, color-mix(in srgb, var(--rc-hull) 60%, #000) 100%);
}
.vf-bezel-fx::after {
    flex: 0 0 56px;
    background: radial-gradient(circle at 50% 62%, #ffffa0 0, #ffd070 32%, #ff8a2a 62%, #ff5a14 100%);
    -webkit-mask: url("../../assets/brand/meierdesigns-logo.svg") 50% 50% / auto 46px no-repeat;
    mask: url("../../assets/brand/meierdesigns-logo.svg") 50% 50% / auto 46px no-repeat;
    filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 1px #05060a) drop-shadow(0 0 4px #ff7a1a) drop-shadow(0 0 10px rgba(255, 90, 0, 0.65));
    box-shadow: none;
    opacity: 1;
}

/* Logo: orange body, bright only where the shapes are large (heat map baked into the SVG). */
.vf-bezel-fx::after {
    background: url("../../assets/brand/meierdesigns-logo-glow.svg") 50% 50% / auto 46px no-repeat;
    -webkit-mask: none;
    mask: none;
    filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 1px #05060a) drop-shadow(0 0 3px #ff6a14) drop-shadow(0 0 9px rgba(255, 80, 0, 0.6));
}

/* Remote control: resize handles on all four corners, shown on hover only. */
.vf-bezel-fx .vf-fx-grip {
    width: 22px; height: 22px; right: auto; bottom: auto; background: none; opacity: 0;
    transition: opacity 0.15s; z-index: 3;
}
.vf-bezel-fx:hover .vf-fx-grip, .vf-bezel-fx.is-dragging .vf-fx-grip { opacity: 1; }
.vf-bezel-fx .vf-fx-grip::before {
    content: ""; position: absolute; width: 12px; height: 12px;
    border: 0 solid var(--rc-acc); filter: drop-shadow(0 0 3px var(--rc-acc));
}
.vf-bezel-fx .vf-fx-grip[data-corner="nw"] { left: 6px; top: 6px; cursor: nwse-resize; }
.vf-bezel-fx .vf-fx-grip[data-corner="ne"] { right: 6px; top: 6px; cursor: nesw-resize; }
.vf-bezel-fx .vf-fx-grip[data-corner="sw"] { left: 6px; bottom: 6px; cursor: nesw-resize; }
.vf-bezel-fx .vf-fx-grip[data-corner="se"] { right: 6px; bottom: 6px; cursor: nwse-resize; }
.vf-bezel-fx .vf-fx-grip[data-corner="nw"]::before { left: 2px; top: 2px; border-width: 3px 0 0 3px; }
.vf-bezel-fx .vf-fx-grip[data-corner="ne"]::before { right: 2px; top: 2px; border-width: 3px 3px 0 0; }
.vf-bezel-fx .vf-fx-grip[data-corner="sw"]::before { left: 2px; bottom: 2px; border-width: 0 0 3px 3px; }
.vf-bezel-fx .vf-fx-grip[data-corner="se"]::before { right: 2px; bottom: 2px; border-width: 0 3px 3px 0; }

/* Each corner handle shows only while hovering that corner (or while it is being dragged). */
.vf-bezel-fx:hover .vf-fx-grip { opacity: 0; }
.vf-bezel-fx .vf-fx-grip:hover, .vf-bezel-fx.is-dragging .vf-fx-grip:active { opacity: 1; }

/* Remote scale slider: right of the logo, visible on hover. */
.vf-bezel-fx .vf-fx-zoom {
    position: absolute; left: calc(50% + 36px); bottom: 34px; width: 84px; z-index: 3;
    opacity: 0; transition: opacity 0.15s;
}
.vf-bezel-fx:hover .vf-fx-zoom, .vf-bezel-fx.is-dragging .vf-fx-zoom { opacity: 1; }
.vf-bezel-fx .vf-fx-zoom input[type="range"] { width: 100%; min-width: 0; height: 18px; }

/* No scrollbar in the remote: arrows appear only where scrolling is possible. */
.vf-bezel-fx .vf-fx-body { scrollbar-width: none; -ms-overflow-style: none; }
.vf-bezel-fx .vf-fx-body::-webkit-scrollbar { display: none; width: 0; height: 0; }
.vf-bezel-fx .vf-fx-more {
    position: absolute; z-index: 4; width: 24px; height: 20px; padding: 0; border: 0; cursor: pointer;
    background: linear-gradient(180deg, var(--rc-hull), color-mix(in srgb, var(--rc-hull) 60%, #000));
    box-shadow: inset 2px 2px 0 var(--rc-lit), inset -2px -2px 0 var(--rc-dark);
    color: var(--rc-acc); display: flex; align-items: center; justify-content: center;
}
.vf-bezel-fx .vf-fx-more[hidden] { display: none; }
.vf-bezel-fx .vf-fx-more::before {
    content: ""; width: 0; height: 0; border-left: 6px solid transparent; border-right: 6px solid transparent;
    filter: drop-shadow(0 0 3px var(--rc-acc));
}
.vf-bezel-fx .vf-fx-more-up::before { border-bottom: 7px solid currentColor; }
.vf-bezel-fx .vf-fx-more-down::before { border-top: 7px solid currentColor; }

/* Scroll arrow bars: solid, flush with the body edge so no content peeks past them. */
.vf-bezel-fx .vf-fx-more { height: 22px; background: #0a0c11; box-shadow: inset 0 0 0 2px var(--rc-dark), inset 2px 2px 0 var(--rc-lit); }
.vf-bezel-fx .vf-fx-more-up { box-shadow: inset 0 -2px 0 var(--rc-lit), inset 0 2px 0 var(--rc-dark); }
.vf-bezel-fx .vf-fx-more-down { box-shadow: inset 0 2px 0 var(--rc-lit), inset 0 -2px 0 var(--rc-dark); }

/* Remote keys grouped in captioned clusters, two clusters per row. */
.vf-bezel-fx .vf-fx-tabs { gap: 6px 8px; align-items: stretch; }
.vf-bezel-fx .vf-fx-tabs-break { flex: 0 0 100%; height: 0; }
.vf-bezel-fx .vf-fx-cluster {
    flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 3px;
    padding: 3px 4px 4px; background: rgba(0, 0, 0, 0.28);
    box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit);
}
.vf-bezel-fx .vf-fx-cluster-cap {
    font-size: 8px; letter-spacing: 0.18em; line-height: 1; opacity: 0.6; text-align: center; color: var(--rc-acc);
}
.vf-bezel-fx .vf-fx-cluster-keys { display: flex; gap: 4px; }
.vf-bezel-fx .vf-fx-cluster-keys button { flex: 1 1 0; min-width: 0; }

/* Compact, colour-coded keys: one hue per cluster (display / layout / game / system). */
.vf-bezel-fx .vf-fx-tabs { gap: 4px 6px; padding: 2px 0; }
.vf-bezel-fx .vf-fx-cluster { --cl: #4fd8ff; padding: 2px 3px 3px; gap: 2px; box-shadow: inset 2px 2px 0 var(--rc-dark), inset -2px -2px 0 var(--rc-lit), inset 0 2px 0 var(--cl); }
.vf-bezel-fx .vf-fx-cluster:nth-of-type(2) { --cl: #6dff7a; }
.vf-bezel-fx .vf-fx-cluster:nth-of-type(3) { --cl: #ff5a3c; }
.vf-bezel-fx .vf-fx-cluster:nth-of-type(4) { --cl: #ffd23c; }
.vf-bezel-fx .vf-fx-cluster-cap { font-size: 7px; opacity: 1; color: var(--cl); text-shadow: 0 0 4px color-mix(in srgb, var(--cl) 60%, transparent); }
.vf-bezel-fx .vf-fx-cluster-keys { gap: 3px; }
.vf-bezel-fx .vf-fx-cluster .vf-fx-cluster-keys button { min-height: 34px; padding: 5px 0 4px; gap: 0; }
.vf-bezel-fx .vf-fx-cluster .vf-fx-cluster-keys button svg { width: 20px; height: 20px; color: var(--cl); }
.vf-bezel-fx .vf-fx-cluster .vf-fx-cluster-keys button.on { box-shadow: inset 0 4px 6px rgba(0, 0, 0, 0.7), inset 3px 0 0 var(--rc-dark), inset -3px 0 0 var(--rc-lit), inset 0 -2px 0 var(--cl), inset 0 0 12px color-mix(in srgb, var(--cl) 40%, transparent); background-color: color-mix(in srgb, var(--cl) 14%, var(--rc-hull)); }
.vf-bezel-fx .vf-fx-cluster .vf-fx-cluster-keys button.on svg { color: #fff; filter: drop-shadow(0 0 3px var(--cl)); }

/* DIFFICULTY rows: icon + short label, value readout always visible. */
.vf-bezel-fx .vf-fx-row > span:first-child:has(.vf-fx-ico) { flex: 0 0 88px; display: flex; align-items: center; gap: 5px; min-width: 0; }
.vf-bezel-fx .vf-fx-row > span:first-child .vf-fx-ico { width: 16px; height: 16px; flex: none; color: var(--rc-acc); filter: drop-shadow(0 0 2px var(--rc-acc)); }
.vf-bezel-fx .vf-fx-row > span:first-child em { font-style: normal; font-size: 9px; line-height: 1.1; min-width: 0; overflow-wrap: anywhere; }
.vf-bezel-fx .vf-fx-row:has(.vf-fx-ico) input[type="range"] { min-width: 40px; }
.vf-bezel-fx .vf-fx-row:has(.vf-fx-ico) output { flex: 0 0 auto; min-width: 3em; color: #fff; }

/* MUSIC VOICES: label | volume | dropdown | style pick (% overlays volume on hover).
   Dropdown sits immediately left of the style fader. */
.vf-bezel-fx .vf-fx-voice-row {
    display: grid;
    grid-template-columns: 48px minmax(48px, 1.15fr) minmax(5.5em, 7.5ch) minmax(40px, 0.85fr);
    grid-template-rows: auto;
    grid-auto-flow: dense;
    align-items: center;
    gap: 5px;
    width: 100%;
    min-width: 0;
}
/* STYLE pick: same fixed value column as MUSIC BPM / STRENGTH. */
.vf-bezel-fx .vf-fx-style-pick-row > output {
    flex: 0 0 7.5em;
    width: 7.5em;
    min-width: 7.5em;
    max-width: 7.5em;
}
/* Legacy STYLE row (dropdown + amount) — keep grid if old HTML is cached. */
.vf-bezel-fx .vf-fx-voice-row.vf-fx-style-row {
    grid-template-columns: 48px minmax(5.5em, 8ch) minmax(0, 1fr);
}
.vf-bezel-fx .vf-fx-voice-row > span:first-child {
    grid-column: 1;
    grid-row: 1;
    flex: none;
    width: auto;
    min-width: 0;
    max-width: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.vf-bezel-fx .vf-fx-voice-row input.vf-fx-voice-pick,
.vf-bezel-fx .vf-fx-voice-row input.vf-fx-voice-vol,
.vf-bezel-fx .vf-fx-voice-row input[type="range"] {
    flex: none;
    width: 100%;
    min-width: 0 !important;
    max-width: none;
}
.vf-bezel-fx .vf-fx-voice-row > select.vf-fx-voice {
    grid-column: 3;
    grid-row: 1;
    width: 100%;
    min-width: 0;
    max-width: none;
}
.vf-bezel-fx .vf-fx-voice-row input.vf-fx-voice-vol {
    grid-column: 2;
    grid-row: 1;
}
.vf-bezel-fx .vf-fx-voice-row input.vf-fx-voice-pick {
    grid-column: 4;
    grid-row: 1;
}
.vf-bezel-fx .vf-fx-voice-row.vf-fx-style-row > select.vf-fx-voice {
    grid-column: 2;
    grid-row: 1;
}
.vf-bezel-fx .vf-fx-voice-row.vf-fx-style-row input.vf-fx-voice-pick {
    grid-column: 3;
    grid-row: 1;
}
/* Style / voice-pick: diagonal hatch fill (distinct from solid volume). */
.vf-bezel-fx input.vf-fx-voice-pick[type="range"] {
    background:
        linear-gradient(90deg, transparent var(--look-fill, 0%), color-mix(in srgb, var(--rc-acc) 8%, #02070a) 0) 0 0 / 100% 100% no-repeat,
        repeating-linear-gradient(-45deg,
            color-mix(in srgb, var(--rc-acc) 78%, #000) 0 2px,
            color-mix(in srgb, var(--rc-acc) 22%, #05080a) 2px 5px
        );
}
.vf-bezel-fx .vf-fx-voice-row > output {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
    align-self: center;
    z-index: 2;
    width: auto;
    min-width: 0;
    max-width: 4.5em;
    margin: 0;
    padding: 0 3px;
    text-align: right;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    color: #fff;
    background: color-mix(in srgb, var(--rc-hull) 88%, #000);
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--rc-acc) 35%, transparent);
    transition: opacity 0.12s;
}
.vf-bezel-fx .vf-fx-voice-row.vf-fx-style-row > output {
    grid-column: 3;
    grid-row: 1;
}
.vf-bezel-fx .vf-fx-voice-row:hover > output,
.vf-bezel-fx .vf-fx-voice-row:focus-within > output {
    opacity: 1;
}
.vf-bezel-fx .vf-fx-row > output {
    flex: 0 0 7.5em;
    width: 7.5em;
    min-width: 7.5em;
    max-width: 7.5em;
    box-sizing: border-box;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: right;
}
.vf-bezel-fx .vf-fx-row > input[data-sl="au:bpm"] + output {
    flex: 0 0 7.5em;
    width: 7.5em;
    min-width: 7.5em;
    max-width: 7.5em;
}
.vf-bezel-fx select.vf-fx-voice,
.vf-bezel-fx select.vf-fx-style {
    flex: none;
    width: 100%;
    max-width: none;
    min-width: 0;
    box-sizing: border-box;
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    padding: 2px 4px;
    border: 2px solid var(--rc-acc);
    border-radius: 0;
    background-color: var(--rc-acc);
    background-image: none;
    color: #0c0e12;
    font: inherit;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
    cursor: pointer;
}
.vf-bezel-fx select.vf-fx-voice:focus,
.vf-bezel-fx select.vf-fx-style:focus {
    outline: 2px solid #fff;
    outline-offset: 1px;
}
.vf-bezel-fx select.vf-fx-voice option,
.vf-bezel-fx select.vf-fx-style option {
    background: #0c0e12;
    color: var(--rc-acc);
    font-size: 11px;
}

/* Planets a cleared run just unlocked: drawn locked until the camera arrives, then a scan lights them up. */
.gm-unlock-fx { pointer-events: none; }
.gm-unlock-flash { fill: #fff; opacity: 0; animation: gm-unlock-flash 0.9s ease-out; }
.gm-unlock-ring { fill: none; stroke: #7fe8ff; stroke-width: 2; opacity: 0; transform-box: fill-box; transform-origin: center; animation: gm-unlock-ring 1.2s ease-out; }
.gm-unlock-scan { fill: #7fe8ff; opacity: 0; animation: gm-unlock-scan 0.8s linear; }
.gm-locked-icon.is-breaking { animation: gm-lock-break 0.45s ease-in forwards; }
@keyframes gm-unlock-flash { 0% { opacity: 0.85; } 100% { opacity: 0; } }
@keyframes gm-unlock-ring { 0% { opacity: 1; transform: scale(0.7); } 100% { opacity: 0; transform: scale(2); } }
@keyframes gm-unlock-scan { 0% { opacity: 0.9; transform: translateY(0); } 90% { opacity: 0.9; } 100% { opacity: 0; transform: translateY(var(--scan, 48px)); } }
@keyframes gm-lock-break { to { opacity: 0; } }

/* Scan tooltip with the new planet's stats. */
.gm-unlock-tip {
    position: fixed; z-index: 9000; transform: translateY(-50%);
    min-width: 150px; padding: 6px 8px 7px;
    background: rgba(5, 6, 10, 0.92); border: 2px solid #7fe8ff;
    box-shadow: 0 0 0 2px #05060a, 0 0 12px rgba(127, 232, 255, 0.35);
    color: #cfefff; font: 10px/1.35 monospace; letter-spacing: 1px;
    pointer-events: none; overflow: hidden;
    animation: gm-tip-in 0.5s steps(10, end) both;
}
.gm-unlock-tip.is-leaving { animation: gm-tip-out 0.25s ease-in forwards; }
.gm-unlock-tip-head { color: #7fe8ff; font-size: 8px; opacity: 0.85; }
.gm-unlock-tip-name { color: #fff; font-weight: bold; font-size: 12px; margin: 1px 0 4px; }
.gm-unlock-tip-row { display: flex; justify-content: space-between; gap: 12px; opacity: 0; animation: gm-tip-row 0.2s steps(2, end) forwards; animation-delay: calc(0.45s + var(--i, 0) * 0.16s); }
.gm-unlock-tip-row b { color: #fff; }
.gm-unlock-tip-scan {
    position: absolute; left: 0; right: 0; top: 0; height: 2px;
    background: #7fe8ff; box-shadow: 0 0 6px #7fe8ff;
    animation: gm-tip-scan 1.1s linear 0.1s both;
}
@keyframes gm-tip-in { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes gm-tip-out { to { opacity: 0; } }
@keyframes gm-tip-row { to { opacity: 1; } }
@keyframes gm-tip-scan { 0% { top: 0; opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
    .gm-unlock-flash, .gm-unlock-ring, .gm-unlock-scan, .gm-unlock-tip, .gm-unlock-tip-scan { animation: none; }
    .gm-unlock-tip-row { animation: none; opacity: 1; }
}


/* --- css/styles/part-21.css --- */
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-score { font-size: var(--font-h2); }
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-status-ico { display: inline-flex; align-items: center; padding: 0; border: 0; background: transparent; }
.hs-faction-status-ico img { width: 24px; height: 24px; image-rendering: pixelated; }

/* Faction cards v2: bigger names, stronger faction identity (accent tint, frame, name glow, accent meter edge). */
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card .hs-faction-name {
    letter-spacing: 2px;
    color: var(--faction-accent) !important;
    text-shadow: 0 0 10px color-mix(in srgb, var(--faction-accent) 60%, transparent);
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card .hs-faction-score { font-size: 22px !important; }
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card {
    --frame-color: color-mix(in srgb, var(--faction-accent) 75%, transparent);
    background: linear-gradient(135deg, color-mix(in srgb, var(--faction-accent) 26%, #05060a), color-mix(in srgb, var(--faction-accent) 8%, #05060a) 70%) !important;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card:not(.active) { opacity: 0.92; }
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card.active {
    --frame-color: var(--faction-accent);
    background: linear-gradient(135deg, color-mix(in srgb, var(--faction-accent) 42%, #05060a), color-mix(in srgb, var(--faction-accent) 16%, #05060a) 70%) !important;
}

/* Faction cards: each faction's own (larger) panel silhouette, clipped on the card itself so the gradient follows the shape. */
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card {
    --faction-ctl-clip: var(--faction-panel-clip);
    clip-path: var(--faction-panel-clip);
    box-shadow: none;
}
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card.active { box-shadow: none; }

/* Faction card v3: slightly smaller names, relation as plus / minus icon. */
html body .home-station-overlay .home-station-content .hs-factions .hs-faction-tabs .hs-faction-card .hs-faction-name { font-size: 22px !important; line-height: 28px; }
.hs-faction-score { display: inline-flex; align-items: center; line-height: 0; }
.hs-faction-score.is-pos { color: #3dff9a; }
.hs-faction-score.is-neg { color: #ff5a5a; }
.hs-faction-score.is-zero { color: color-mix(in srgb, var(--color-text, #fff) 55%, transparent); }

/* Voxel bezel perf: the #vfFramePx filter (tile + dilate + 4 offsets) is expensive on full-screen layers.
   Keep each filtered layer on its own compositor layer so the result is cached instead of re-run every frame,
   and drop the looping deco animations while the pixel frame is on (they invalidate the filtered layer).
   Skip Voidborn: its bezel is border-image vines only — will-change/translateZ/contain culled them. */
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"]) .vf-fr,
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"]) .vf-bezel-deco,
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"])::before,
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"])::after,
html[data-vf-frame-px="on"] #vf-cables {
    will-change: transform;
    transform: translateZ(0);
    backface-visibility: hidden;
}
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"]),
html[data-vf-frame-px="on"] .vf-bezel[data-faction]:not([data-faction="voidborn"]) .vf-bezel-deco,
html[data-vf-frame-px="on"] .vf-bezel[data-faction]:not([data-faction="voidborn"])::before,
html[data-vf-frame-px="on"] .vf-bezel[data-faction]:not([data-faction="voidborn"])::after { animation: none !important; }
html[data-vf-frame-px="on"] #vf-bezel:not([data-faction="voidborn"]) { contain: layout style; }

/* Faction detail uses the full height: chain of flex children down to the cards, rows spread evenly inside them. */
html body .home-station-overlay .home-station-content .hs-factions.hs-faction-detail { height: 100%; min-height: 0; box-sizing: border-box; }
html body .home-station-overlay .hs-fd[data-faction] > .hs-fd-main { min-height: 0; height: 100%; }
html body .home-station-overlay .hs-fd[data-faction] > .hs-fd-main > .hs-fd-section > .hs-fd-cols { flex: 1 1 auto; min-height: 0; }
html body .home-station-overlay .hs-fd-section > .hs-fd-cols > .hs-fd-block { display: flex; flex-direction: column; justify-content: space-between; }
html body .home-station-overlay .hs-fd-section > .hs-fd-cols > .hs-fd-block .hs-fd-row { flex: 1 1 0; min-height: 56px; }
html body .home-station-overlay .hs-fd[data-faction] > .hs-fd-main > .hs-faction-actions { margin-top: auto !important; }

/* Faction section tabs: always one row, sharing the width equally. */
