    /* Top-align so every stat icon/value shares one baseline, even when
       some columns stack multiple slot bars underneath. */
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    max-width: 100%;
    /* Room for the filled-dot outer rim (box-shadow 4px). */
    padding: 6px 4px 8px;
    overflow: visible;
    box-sizing: border-box;
}
html body .hs-ship-table .hs-ship-meta-col {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 12px;
    min-width: 2.6em;
    flex: 1 1 0;
}
html body .hs-ship-table .hs-ship-meta-col .hs-ship-stat {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 4px;
    width: 100%;
    min-width: 0;
    white-space: nowrap;
    text-align: center;
}
html body .hs-ship-table .hs-ship-meta-col .hs-ship-stat-ico {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: auto;
    flex: 0 0 auto;
}
html body .hs-ship-table .hs-ship-meta-col .hs-ship-stat-ico img {
    width: 1.35em !important;
    height: 1.35em !important;
    image-rendering: pixelated;
}
html body .hs-ship-table .hs-ship-meta-col .hs-ship-stat b {
    display: block;
    margin: 0;
    font-size: var(--font-text);
    line-height: 1.15;
    color: var(--stat, var(--color-text, #fff));
    text-shadow: 0 0 6px color-mix(in srgb, var(--stat, #fff) 45%, transparent);
}
html body .hs-ship-table .hs-ship-table-name strong {
    display: block;
    line-height: 1.15;
}
html body .hs-ship-table .hs-ship-tier-stars {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    margin-left: 0.35em;
    vertical-align: middle;
}
html body .hs-ship-table .hs-ship-tier-star {
    display: inline-flex;
    align-items: center;
    line-height: 0;
}
html body .hs-ship-table .hs-ship-tier-star img {
    width: 1em !important;
    height: 1em !important;
    image-rendering: pixelated;
}
html body .hs-ship-table .hs-ship-table-name > span {
    display: block;
    line-height: 1.15;
}
html body .hs-ship-table .hs-ship-slot-dots {
    display: flex !important;
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: center;
    justify-content: flex-start;
    gap: 6px;
    width: 100%;
    min-height: 14px;
    margin: 10px 0 0;
    /* Keep the 4px hard rim (and hover scale) inside the scrollport. */
    padding: 4px 0;
    box-sizing: content-box;
    overflow: visible;
}
html body .hs-ship-table .hs-ship-slot-dots.is-empty {
    visibility: hidden;
    pointer-events: none;
}
html body .hs-ship-table .hs-ship-meta-note {
    display: block;
    flex: 1 1 100%;
    width: 100%;
    line-height: 1.15;
}
html body .hs-ship-table .hs-ship-slot-dot {
    --slot-color: var(--color-primary);
    /* Same bar size for every mount — do not stretch with the stat column. */
    flex: 0 0 auto;
    width: 28px !important;
    min-width: 28px;
    height: 14px;
    border-radius: 0 !important;
    background: color-mix(in srgb, var(--slot-color) 12%, transparent);
    border: 2px dashed color-mix(in srgb, var(--slot-color) 85%, #fff 10%);
    box-sizing: border-box;
    cursor: default;
    position: relative;
    overflow: hidden;
}
/* The dot carries a hidden casing icon purely so ui-tooltip.js can read its
   artwork for the tooltip head — never shown on the dot itself. */
html body .hs-ship-table .hs-ship-slot-dot > .hs-item-body {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}
html body .hs-ship-table .hs-ship-slot-dot.is-filled {
    background-color: var(--slot-color-light, var(--slot-color)) !important;
    background-image: none;
    /* Hard pixel rim — no soft blur glow (looked round under browser AA). */
    box-shadow: 0 0 0 2px #05060a, 0 0 0 4px var(--slot-color) !important;
    border: 2px solid var(--slot-color) !important;
}
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="weapon"] { --slot-color-light: #ff7c5c; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="defense"] { --slot-color-light: #5ce1ff; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="ability"] { --slot-color-light: #c58bff; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="energy"] { --slot-color-light: #ffd24a; }
/* Split weapon mount (mirrored L/R pair): hard centre seam — also on empty
   slots, where a background-image divider was invisible on the dashed shell. */
html body .hs-ship-table .hs-ship-slot-dot.is-split::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
    width: 2px;
    margin-left: -1px;
    background: #05060a;
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--slot-color) 70%, #fff);
    z-index: 2;
    pointer-events: none;
}
html body .hs-ship-table .hs-ship-slot-dot.is-split:not(.is-filled)::after {
    background: var(--slot-color);
    box-shadow: none;
    opacity: 0.95;
}
/* Slot size (S/M/L): tooltip only — every bar stays the same pixel size. */
html body .hs-ship-table .hs-ship-slot-dots .hs-ship-slot-dot-size-0,
html body .hs-ship-table .hs-ship-slot-dots .hs-ship-slot-dot-size-1,
html body .hs-ship-table .hs-ship-slot-dots .hs-ship-slot-dot-size-2 {
    width: 28px !important;
    min-width: 28px;
    height: 14px;
}
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="weapon"] { --slot-color: #ff5a3c; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="defense"] { --slot-color: #5ce1ff; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="ability"] { --slot-color: #c58bff; }
html body .hs-ship-table .hs-ship-slot-dot[data-slot-kind="energy"] { --slot-color: #ffd24a; }

/* Hovering a slot dot highlights its own dot plus the matching module's icon
   wherever else it's shown (storage grid / hangar parts list). */
html body .is-slot-hover-highlight {
    outline: 2px solid #fff;
    outline-offset: 1px;
    filter: brightness(1.35);
}
html body .hs-ship-table .hs-ship-slot-dot.is-slot-hover-highlight {
    outline-offset: 2px;
    animation: hsSlotDotPulse 0.6s ease-in-out infinite;
}
@keyframes hsSlotDotPulse {
    0%, 100% { transform: scale(1.1); }
    50% { transform: scale(1.35); }
}

/* Responsive ship tables: stats stay one row, then hide (values stay in the row tooltip). */
*:has(> .hs-ship-table) { container-type: inline-size; container-name: shiptbl; }
@container shiptbl (max-width: 640px) {
    .hs-ship-table .hs-ship-meta { gap: 10px !important; }
    .hs-ship-table .hs-ship-table-name strong { font-size: 26px !important; }
}
@container shiptbl (max-width: 460px) {
    .hs-ship-table .hs-ship-meta { display: none !important; }
    .hs-ship-table .hs-ship-table-thumb { width: 108px !important; }
    .hs-ship-table .hs-ship-thumb { width: 100px !important; height: 80px !important; }
}

/* Launch / abandon buttons: larger hit area and icon. */
html body .hs-faction-contracts .hs-mission { grid-template-columns: 110px minmax(240px, 1fr) auto auto auto 270px; }
html body .hs-faction-contracts .hs-mission :is(.hs-mission-go, .hs-mission-abort) { width: 128px !important; min-width: 128px !important; height: 76px; }
html body .hs-faction-contracts .hs-mission :is(.hs-mission-go, .hs-mission-abort) .hs-go-ico img { width: 44px; height: 44px; }

/* Scoreboard: emblem column as wide as the emblem, with room before the name. */
.start-screen-retro .start-scoreboard-head,
.start-screen-retro .start-scoreboard-row {
    grid-template-columns: 22px clamp(22px, calc(2.4 * var(--sv-w)), 32px) minmax(0, 1fr) max-content;
    column-gap: clamp(10px, calc(1.6 * var(--sv-w)), 18px);
}

/* Profile list: bigger names, more room between crest and name. */

html body .profile-list-item .profile-list-name { font-size: 24px !important; letter-spacing: 2px;}

/* Profile list v2: stronger horizontal gap between crest and name, and inner side padding. */
html body .profile-selection-overlay .profile-list-item, html body .profile-selection-floating .profile-list-item { justify-content: flex-start; gap: 36px !important; padding-inline: 24px !important; }
html body .profile-list-item .profile-list-emblem { margin-right: 0 !important; flex: 0 0 auto; }
html body .profile-list-item .profile-list-name { padding-left: 16px !important; }

.hs-menu-panel-section .hs-menu-profile-row .hs-menu-profile-name { font-size: var(--font-h2); }

/* Profile rows: faction background like the faction cards (accent gradient, accent underline). */
html body .hs-menu-profile-row {
    background: linear-gradient(135deg, color-mix(in srgb, var(--row-accent, var(--color-primary)) 26%, #05060a), color-mix(in srgb, var(--row-accent, var(--color-primary)) 8%, #05060a) 70%);
    box-shadow: inset 0 -4px 0 color-mix(in srgb, var(--row-accent, var(--color-primary)) 70%, transparent);
}
html body .hs-menu-profile-row:hover,
html body .hs-menu-profile-row.is-active {
    background: linear-gradient(135deg, color-mix(in srgb, var(--row-accent, var(--color-primary)) 42%, #05060a), color-mix(in srgb, var(--row-accent, var(--color-primary)) 16%, #05060a) 70%);
    box-shadow: inset 0 -4px 0 var(--row-accent, var(--color-primary)), 0 0 14px color-mix(in srgb, var(--row-accent, var(--color-primary)) 40%, transparent);
}

/* GLOW slider (--vf-glow, 0..2.2) also drives the home-station UI, which had no glow rules of its own.
   :where() keeps these weak, so deliberate per-element glows elsewhere still win. */
:where(html[data-vf-glow]:not([data-vf-glow="off"])) .home-station-overlay :where(.hs-tab, .hs-area-btn, .action-button, .hs-shop-cat, h4, strong, .hs-panel-label, .hs-mi-val, .hs-cost-amt, .hs-line-meta) {
    text-shadow: 0 0 calc(var(--vf-glow, 0) * 5px) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 80%, transparent), 0 0 calc(var(--vf-glow, 0) * 12px) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
}
:where(html[data-vf-glow]:not([data-vf-glow="off"])) .home-station-overlay :where(.hs-tab.active, .hs-area-btn.active, .action-button, .hs-panel, .hs-mi, .hs-line, .hs-cost-cell) {
    box-shadow: 0 0 calc(var(--vf-glow, 0) * 8px) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 45%, transparent);
}
:where(html[data-vf-glow]:not([data-vf-glow="off"])) .home-station-overlay :where(img.hs-pixel, .hs-galaxy-ico img, .hs-faction-crest img) {
    filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 min(calc(var(--vf-glow, 0) * 1.5px), 2px) color-mix(in srgb, var(--faction-accent, var(--color-primary)) 85%, transparent));
}

/* Explorations cluster labels (ARCHIVE / ARSENAL): larger. */

html body .hs-explore-cluster-title { font-size: 28px !important; letter-spacing: 5px; padding-left: 24px !important; padding-bottom: 10px; }

/* Ship table rows flow instead of switching layouts: thumb | name | stats | buttons wrap one after another as the panel narrows. */
.hs-ship-table { display: block; width: 100%; }
.hs-ship-table tbody:not(.hs-ship-card) { display: block; width: 100%; }
.hs-ship-table thead { display: none; }
.hs-ship-table tr { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; padding: 12px 8px; border-bottom: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--color-primary) 18%, transparent); }
.hs-ship-table td { display: block; padding: 0 !important; height: auto !important; border: 0 !important; min-width: 0; }
.hs-ship-table td.hs-ship-table-thumb { flex: 0 0 auto; width: auto !important; }
.hs-ship-table td.hs-ship-table-name { flex: 1 1 150px; }
.hs-ship-table td.hs-ship-table-action { flex: 0 0 auto; margin-left: auto; display: flex; gap: 8px; }
.hs-ship-table .hs-ship-icon-btn { width: 48px !important; height: 48px !important; margin-left: 0 !important; }

/* Owned-ship card: info | storage side-by-side; stack when the ships panel is tight. */
.hs-ship-table tbody.hs-ship-card {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) max-content;
    align-items: stretch;
    gap: 0 18px;
    width: 100%;
    padding: 6px 10px;
    box-sizing: border-box;
}
.hs-ship-table tbody.hs-ship-card > .hs-ship-id-row {
    grid-column: 1;
    grid-row: 1;
    padding: 4px 4px 8px !important;
    border-bottom: 0 !important;
    min-width: 0;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb {
    position: relative;
    overflow: visible;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb-action {
    position: absolute;
    right: -4px;
    bottom: -4px;
    z-index: 3;
    opacity: 0;
    pointer-events: none;
    transform: translateY(4px);
    transition: opacity 0.12s ease, transform 0.12s ease;
}
.hs-ship-table tbody.hs-ship-card:hover .hs-ship-thumb-action,
.hs-ship-table tbody.hs-ship-card:focus-within .hs-ship-thumb-action {
    opacity: 1;
