    border: 2px solid var(--faction-accent, var(--color-primary)) !important;
    background: #05060a !important;
    background-image: none !important;
    box-shadow: 0 0 0 2px #05060a !important;
    filter: none !important;
    cursor: pointer;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb-action .hs-ship-hangar-badge::before,
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb-action .hs-ship-hangar-badge::after,
html body .home-station-overlay .hs-ship-thumb-action .hs-ship-hangar-badge::before,
html body .home-station-overlay .hs-ship-thumb-action .hs-ship-hangar-badge::after {
    content: none !important;
    display: none !important;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb-action .hs-ship-hangar-badge .hs-pixel,
html body .home-station-overlay .hs-ship-thumb-action .hs-ship-hangar-badge .hs-pixel {
    width: 18px !important;
    height: 18px !important;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-thumb-action .hs-ship-hangar-badge:is(:hover, .nav-focused),
html body .home-station-overlay .hs-ship-thumb-action .hs-ship-hangar-badge:is(:hover, .nav-focused) {
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 22%, #05060a) !important;
}
.hs-ship-table tbody.hs-ship-card > .hs-ship-storage-row {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    align-self: start;
    grid-column: 2;
    grid-row: 1;
    gap: 0;
    padding: 8px 2px 8px 16px;
    margin: 4px 0;
    border-bottom: 0 !important;
    border-left: 0;
}
.hs-ship-table tbody.hs-ship-card .hs-ship-storage-row td { width: 100%; }
.hs-ship-table tbody.hs-ship-card .hs-ship-storage-caption {
    font-size: var(--font-text);
    letter-spacing: 0.12em;
    opacity: 0.75;
    padding: 0 0 8px;
}
@container shiptbl (max-width: 580px) {
    .hs-ship-table tbody.hs-ship-card {
