/* Locked planet hint: boxed, larger, with a JUMP TO button. */
html body .galaxy-map-panel-select .gm-detail .gm-unlock-hint:not(:empty) { display: flex; flex-direction: column; gap: 12px; align-items: stretch; margin-top: 10px; padding: 14px 16px; border: var(--ui-border-width, 2px) solid color-mix(in srgb, #ff9b54 55%, transparent); background: rgba(255, 155, 84, 0.08); font: bold var(--font-h2, 16px) var(--ui-font-family, monospace); letter-spacing: 2px; }
.gm-unlock-hint .gm-unlock-text { color: #ffb070; line-height: 1.4; }
.gm-unlock-hint .gm-unlock-text b { color: #fff; }
.gm-unlock-hint .gm-unlock-jump { width: 100%; min-height: 44px; font-size: var(--font-text, 14px); letter-spacing: 2px; }

/* JUMP TO button icon: a rocket that pulses forward in hard steps. */
.gm-unlock-jump { display: inline-flex; align-items: center; justify-content: center; gap: 12px; }
.gm-unlock-jump .gm-jump-ico { display: inline-grid; place-items: center; width: 32px; height: 32px; }
.gm-unlock-jump .gm-jump-ico img { width: 32px; height: 32px; image-rendering: pixelated; filter: drop-shadow(0 0 1px #05060a) drop-shadow(0 0 5px #ff9b54); animation: gm-jump-go 1s steps(2, end) infinite; }
@keyframes gm-jump-go { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.3); } }
html[data-vf-perf-anim="off"] .gm-unlock-jump .gm-jump-ico img { animation: none; }

/* Planet info cells: icon left of the value; label only on hover. */
html body .galaxy-map-panel-select .gm-detail .stat-row {
    position: relative;
    flex-direction: row !important;
    align-items: center;
    gap: 8px;
}
.galaxy-map-panel-select .gm-detail .stat-row::before {
    content: '';
    flex: 0 0 auto;
    width: 16px;
    height: 16px;
    background: var(--color-primary);
    -webkit-mask: var(--gm-ico) center / contain no-repeat;
    mask: var(--gm-ico) center / contain no-repeat;
    filter: drop-shadow(0 0 0 #05060a);
