}
.profile-faction-ship-wrap .profile-faction-ship-badge,
.profile-faction-ship-wrap .profile-faction-preview-emblem {
    --pfc-crest-size: clamp(40px, calc(7 * var(--sv-h)), 64px);
    position: absolute;
    right: 2%;
    bottom: 4%;
    z-index: 2;
    display: flex !important;
    align-items: center;
    justify-content: center;
    width: var(--pfc-crest-size) !important;
    height: var(--pfc-crest-size) !important;
