    height: 100% !important;
}
.profile-faction-ship-wrap .profile-faction-ship-badge img,
.profile-faction-ship-wrap .profile-faction-preview-emblem img {
    max-width: 100% !important;
    max-height: 100% !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain;
    image-rendering: auto !important;
}
html body .profile-faction-info-row .profile-faction-preview > .profile-faction-preview-text {
    box-sizing: border-box;
    padding: 10px 14px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 8%, #050508);
}

/* Under lore: rough stat focuses + preferred / affinity weapons. */
.profile-faction-focus {
    box-sizing: border-box;
    width: 100%;
    padding: 12px 16px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 8%, #050508);
