    flex-direction: column;
    gap: 10px;
}
.profile-faction-focus .pff-style {
    margin: 0;
    color: color-mix(in srgb, #fff 88%, var(--faction-accent, var(--color-primary)));
    line-height: 1.35;
}
.profile-faction-focus .pff-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}
.profile-faction-focus .pff-label {
    flex: 0 0 auto;
    min-width: 7.5em;
    font-size: var(--font-small, 12px);
    letter-spacing: 2px;
    color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 75%, #fff);
    opacity: 0.85;
}
/* Preferred + bonus share one bordered cluster with a fixed 2-row height so
   every faction's focus strip stays the same tall (no jump when chip counts differ). */
.profile-faction-focus .pff-weapons-cluster {
    display: grid;
    grid-template-rows: 36px 36px auto;
    gap: 6px;
    padding: 8px;
    box-sizing: border-box;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 35%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 8%, #05060a);
}
.profile-faction-focus .pff-unlock-row {
    height: auto;
    min-height: 36px;
    align-items: flex-start;
}
.profile-faction-focus .pff-unlock {
    display: inline-flex;
    flex-direction: column;
    gap: 2px;
    padding: 5px 9px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 16%, #05060a);
    box-shadow: 0 0 8px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 22%, transparent);
    max-width: 100%;
}
.profile-faction-focus .pff-unlock b {
    font-size: var(--font-small, 12px);
    letter-spacing: 2px;
    color: var(--faction-accent, var(--color-primary));
}
.profile-faction-focus .pff-unlock em {
    font-style: normal;
    font-size: 11px;
    letter-spacing: 1px;
    color: #fff;
}
.profile-faction-focus .pff-unlock small {
    font-size: 10px;
    letter-spacing: 0.5px;
    color: color-mix(in srgb, #fff 75%, var(--faction-accent, var(--color-primary)));
    line-height: 1.3;
}
.profile-faction-focus .pff-unlocks {
    height: auto !important;
    flex-wrap: wrap !important;
    overflow: visible !important;
}
.pfx-unlocks {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 12px;
    padding-top: 10px;
    border-top: 1px solid color-mix(in srgb, var(--color-primary) 30%, transparent);
}
.pfx-unlock-card {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 8px 10px;
    border: 1px solid color-mix(in srgb, var(--color-primary) 45%, transparent);
    background: color-mix(in srgb, var(--color-primary) 12%, #05060a);
}
.pfx-unlock-card .pfx-unlock-label,
.pfx-unlocks .pfx-group-label {
    font-size: var(--font-small, 12px);
    letter-spacing: 2px;
    color: var(--color-primary);
}
.pfx-unlock-card b { color: #fff; letter-spacing: 1.5px; }
.pfx-unlock-card small { color: color-mix(in srgb, #fff 75%, var(--color-primary)); }
.profile-faction-focus .pff-weapons-row {
    display: grid;
    grid-template-columns: 7.5em minmax(0, 1fr);
    align-items: center;
    gap: 12px;
    flex-wrap: nowrap;
    min-height: 36px;
    height: 36px;
}
.profile-faction-focus .pff-weapons-row .pff-label {
    min-width: 0;
}
.profile-faction-focus .pff-chips,
.profile-faction-focus .pff-weapons {
    display: flex;
    flex-wrap: nowrap;
    gap: 6px;
    align-items: center;
    min-width: 0;
    flex: 1 1 auto;
}
.profile-faction-focus .pff-weapons {
    height: 36px;
    overflow: hidden;
}
.profile-faction-focus .pff-chip,
.profile-faction-focus .pff-level {
    padding: 3px 8px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 50%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 14%, #05060a);
    letter-spacing: 1.5px;
    font-size: var(--font-small, 12px);
    color: #fff;
}
.profile-faction-focus .pff-level {
    margin-left: auto;
    opacity: 0.9;
}
.profile-faction-focus .pff-bars {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 6px 12px;
}
.profile-faction-focus .pff-stat {
    display: grid;
    grid-template-columns: 32px 1fr;
    align-items: center;
    gap: 10px;
    opacity: 0.55;
    transition: opacity 0.15s ease;
}
.profile-faction-focus .pff-stat.is-focus {
    opacity: 1;
}
.profile-faction-focus .pff-stat-ico-wrap {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    flex: 0 0 auto;
    filter: grayscale(0.35) brightness(0.85);
}
.profile-faction-focus .pff-stat.is-focus .pff-stat-ico-wrap {
    filter: drop-shadow(0 0 4px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, transparent));
}
.profile-faction-focus .pff-stat-ico-wrap :is(img, canvas, svg, .ui-icon-tip, .pff-stat-ico) {
    width: 28px;
    height: 28px;
    display: block;
    image-rendering: pixelated;
}
.profile-faction-focus .pff-stat b {
    font-size: var(--font-small, 12px);
    letter-spacing: 1.5px;
    color: color-mix(in srgb, #fff 80%, var(--faction-accent, var(--color-primary)));
}
.profile-faction-focus .pff-cells {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: 1fr;
    gap: 3px;
}
.profile-faction-focus .pff-cells i {
    height: 14px;
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 12%, #05060a);
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 28%, transparent);
    box-sizing: border-box;
}
.profile-faction-focus .pff-stat.is-focus .pff-cells i {
    height: 18px;
    border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent);
}
.profile-faction-focus .pff-cells i.on {
    background: var(--faction-accent, var(--color-primary));
    box-shadow: 0 0 5px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 60%, transparent);
}
.profile-faction-focus .pff-stat.is-focus .pff-cells i.on {
    box-shadow:
        0 0 8px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 80%, transparent),
        0 0 2px #fff;
}
.profile-faction-focus .pff-weapon {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 36px;
    box-sizing: border-box;
    padding: 0 8px 0 4px;
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, transparent);
    background: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 10%, #05060a);
    flex: 0 0 auto;
}
.profile-faction-focus .pff-weapon.is-bonus {
    border-color: color-mix(in srgb, var(--faction-accent, var(--color-primary)) 70%, transparent);
    box-shadow: 0 0 8px color-mix(in srgb, var(--faction-accent, var(--color-primary)) 25%, transparent);
}
.profile-faction-focus .pff-weapon b {
    font-size: var(--font-small, 12px);
    letter-spacing: 1px;
    color: #fff;
    line-height: 1;
}
.profile-faction-focus .pff-weapon em {
    font-style: normal;
    font-size: 10px;
    letter-spacing: 1px;
    color: var(--faction-accent, var(--color-primary));
    line-height: 1;
}
.profile-faction-focus .pff-weapon :is(img, canvas, svg, .ui-icon-tip) {
    width: 28px;
    height: 28px;
    flex: 0 0 auto;
}
.profile-faction-focus .pff-empty {
    font-size: var(--font-small, 12px);
    letter-spacing: 1.5px;
    opacity: 0.55;
    color: #fff;
}
html body .profile-selection-name-mode:not(.is-name-step) .profile-faction-info-row > .profile-faction-focus {
    flex: 0 0 auto;
    width: 100%;
}


/* --- css/styles/part-22.css --- */
@media (max-width: 720px) {
    html body .start-screen-content:has(> .settings-panel-master) {
        width: 94%;
        height: 88%;
        padding: 10px;
    }
    html body .settings-panel.settings-panel-master {
        grid-template-columns: 1fr;
        gap: 10px;
    }
    html body .settings-panel-master .settings-nav {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        border-right: 0;
        border-bottom: 2px solid color-mix(in srgb, var(--color-primary) 38%, transparent);
        padding-bottom: 10px;
    }
}

/* Start step: use the full height (big ship, tight gaps) and one text size everywhere. */
html body .profile-start-main { --ps-font: var(--font-h2); height: auto !important; align-items: stretch; gap: 10px; margin-top: 4px; }
html body .profile-start-main :is(.profile-kit-item, .profile-kit-text, .profile-kit-text b, .profile-kit-text small, .profile-kit-ship > strong, .profile-kit-stats small, .profile-kit-stats b, .profile-loadout, .profile-loadout-title, .profile-loadout-line, .profile-loadout-line b, .profile-area-row, .profile-area-row small, .profile-area-size, .profile-area-btn, .profile-area-left) { font-size: var(--ps-font) !important; }
html body .profile-start-main .profile-kit-list { gap: 8px; height: 100%; }
html body .profile-start-main .profile-kit-item { flex: 1 1 0; min-height: 52px; padding: 8px 12px; }
html body .profile-start-main .profile-faction-info-row, html body .profile-start-main .profile-faction-preview { height: 100% !important; }
html body .profile-start-main .profile-faction-preview { padding: 8px 14px; gap: 6px; justify-content: space-between; }
html body .profile-start-main .profile-faction-info-row .profile-faction-ship { width: auto !important; height: clamp(150px, 34vh, 340px) !important; max-width: 100%; aspect-ratio: 200 / 140; margin: 0 auto !important; }
html body .profile-start-main .profile-kit-stats { gap: 28px; }
html body .profile-start-main .profile-loadout { padding: 8px 14px; gap: 8px; }
html body .profile-start-main .profile-area-row { grid-template-columns: 90px 40px 48px 40px 1fr; }

/* Keep the narrow visual-settings rail readable at large stage font scales. */
html body .vf-bezel-fx .vf-fx-tabs {
    flex: 0 0 150px;
    min-width: 150px;
}
html body .vf-bezel-fx .vf-fx-tabs button {
    font-size: 11px !important;
    line-height: 1 !important;
    letter-spacing: 0.05em !important;
    white-space: nowrap;
}
html body .profile-start-main .profile-area-btn { min-height: 34px; }

/* Hull editor: two columns of area rows, title and kit line span the full width. */
html body .profile-start-main .profile-loadout { display: grid !important; grid-template-columns: 1fr 1fr; column-gap: 36px; row-gap: 10px; align-items: center; }
html body .profile-start-main .profile-loadout > :is(.profile-loadout-title, .profile-loadout-line) { grid-column: 1 / -1; }
html body .profile-start-main .profile-loadout-title { display: flex; justify-content: space-between; align-items: center; text-align: left; padding-bottom: 6px; border-bottom: 1px solid color-mix(in srgb, var(--faction-accent, currentColor) 40%, transparent); }
html body .profile-start-main .profile-loadout-line { padding-top: 6px; border-top: 1px solid color-mix(in srgb, var(--faction-accent, currentColor) 40%, transparent); }
html body .profile-start-main .profile-area-left { float: none; }
html body .profile-start-main .profile-area-row { grid-template-columns: 80px 40px 1fr 40px auto; gap: 8px; }
html body .profile-start-main .profile-area-row small { text-align: right; white-space: nowrap; }

/* Ship stats: icon + number + label, colour coded. */
html body .profile-start-main .profile-kit-stats .pk-stat { display: grid; grid-template-columns: auto auto; grid-template-areas: "i v" "i l"; column-gap: 8px; align-items: center; justify-items: start; color: var(--pk-c); }
html body .profile-start-main .profile-kit-stats .pk-stat img { grid-area: i; width: 28px; height: 28px; image-rendering: pixelated; }
html body .profile-start-main .profile-kit-stats .pk-stat b { grid-area: v; color: var(--pk-c); text-shadow: 1px 1px 0 #05060a; }
html body .profile-start-main .profile-kit-stats .pk-stat small { grid-area: l; color: var(--pk-c); opacity: .85; letter-spacing: 1px; }
.pk-speed { --pk-c: #5ee7ff; } .pk-hull { --pk-c: #6dff8a; } .pk-armor { --pk-c: #ffc24a; } .pk-damage { --pk-c: #ff6a5e; }

/* Start step order: stats strip on top (full width), then name, big ship, hull editor at the bottom. */
html body .profile-start-main .profile-faction-preview { justify-content: flex-start; gap: 8px; }
html body .profile-start-main .profile-kit-ship { display: contents; }
html body .profile-start-main .profile-kit-stats { order: 0; width: 100%; justify-content: space-between; gap: 12px; padding: 4px 8px 8px; border-bottom: 1px solid color-mix(in srgb, var(--faction-accent, currentColor) 40%, transparent); box-sizing: border-box; }
html body .profile-start-main .profile-kit-ship > strong { order: 1; text-align: center; }
html body .profile-start-main .profile-kit-ship > small { display: none; }
html body .profile-start-main .profile-faction-info-row .profile-faction-ship { order: 2 !important; flex: 1 1 auto !important; min-height: 0; height: auto !important; width: auto !important; max-width: 100% !important; max-height: clamp(220px, 46vh, 460px); margin: auto !important; }
html body .profile-start-main .profile-loadout { order: 3; grid-area: nav; padding-top: 4px; }

/* Start-step ship: plain in-game rendering, no outline filter. */
html body .profile-start-main .profile-faction-info-row .profile-faction-ship { filter: none !important; image-rendering: pixelated; }
html body .profile-start-main .profile-faction-info-row .profile-faction-ship { aspect-ratio: auto !important; image-rendering: pixelated; }
html body .profile-start-main .profile-faction-info-row .profile-faction-ship { flex: 0 0 auto !important; height: clamp(220px, 44vh, 440px) !important; width: auto !important; }

/* Start profile list: compact cards, big icon tile, name over description, packed at the top. */
html body .profile-start-main .profile-kit-list { justify-content: flex-start; align-content: flex-start; height: auto; gap: 8px; }
html body .profile-start-main .profile-kit-item { flex: 0 0 auto; min-height: 76px; padding: 10px 14px; gap: 14px; align-items: center; }
html body .profile-start-main .profile-kit-icon { flex: 0 0 auto; width: 52px; height: 52px; display: inline-flex; align-items: center; justify-content: center; padding: 6px; box-sizing: border-box; }
html body .profile-start-main .profile-kit-item .profile-kit-text { gap: 4px; justify-content: center; }
html body .profile-start-main .profile-kit-item .profile-kit-text b { letter-spacing: 3px; }
html body .profile-start-main .profile-kit-item .profile-kit-text small { line-height: 1.3; text-transform: uppercase; }

/* Stats strip: tinted icon + big number, evenly spread, label only as tooltip. */
html body .profile-start-main .profile-kit-stats { justify-content: space-around; gap: 8px; padding: 6px 8px 10px; }
html body .profile-start-main .profile-kit-stats .pk-stat { display: inline-flex; flex-direction: row; align-items: center; gap: 10px; cursor: help; }
html body .profile-start-main .profile-kit-stats .pk-ico { display: block; width: 40px; height: 40px; background: var(--pk-c); -webkit-mask: var(--pk-img) center / contain no-repeat; mask: var(--pk-img) center / contain no-repeat; image-rendering: pixelated; filter: drop-shadow(1px 1px 0 #05060a); }
html body .profile-start-main .profile-kit-stats .pk-stat b { font-size: calc(var(--font-h2) * 1.8) !important; line-height: 1; }

/* Kit bonus bar: icon + label left, bonus right in accent colour, on a tinted strip. */
html body .profile-start-main .profile-loadout-line.profile-kit-bonus { align-items: center; padding: 8px 12px; margin-top: 2px; border: 1px solid color-mix(in srgb, var(--faction-accent, currentColor) 55%, transparent); background: color-mix(in srgb, var(--faction-accent, #3ad) 12%, #05060a); }
html body .profile-start-main .pkb-label { display: inline-flex; align-items: center; gap: 10px; letter-spacing: 2px; opacity: .85; }
html body .profile-start-main .pkb-label img { width: 24px; height: 24px; image-rendering: pixelated; }
html body .profile-start-main .profile-kit-bonus b { color: var(--faction-accent, #fff); text-align: right; letter-spacing: 1px; }

/* Settings sidebar: smaller labels (tabs, group heads, add button). */
html body .settings-panel-master .settings-nav :is(.settings-nav-item, .settings-nav-item span, .settings-nav-add, .settings-cluster-head, .settings-group-head) {
    font-size: clamp(15px, 1.4vw, 20px);
    letter-spacing: 0.5px;
}
html body .settings-panel-master .settings-nav-item { min-height: 40px; padding: 8px 10px; }

/* Station PROFILES tab: pilot list left, detail view right. Wider detail column, compact detail blocks, no clipping. */
.hs-menu-profile-split { grid-template-columns: minmax(0, 1fr) minmax(340px, 42%); gap: 10px; }
.hs-menu-profile-stats.profile-details {
    padding: 10px 12px !important;
    gap: 8px;
    max-height: calc(66 * var(--sv-h));
    overflow-y: auto;
}
.hs-menu-profile-stats .pd-hero { gap: 12px; padding-bottom: 8px; }
.hs-menu-profile-stats .pd-hero-actions { gap: 6px; }
.hs-menu-profile-stats .pd-hero-btn { padding: 6px 10px; font-size: var(--font-small); }
.hs-menu-profile-stats .pd-hero-face { flex: none; }
.hs-menu-profile-stats .pd-hero-portrait,
.hs-menu-profile-stats .pd-hero-portrait > * { width: 56px !important; height: auto !important; min-height: 56px; flex: none; }
.hs-menu-profile-stats .pd-hero-face.has-portrait :is(.pd-hero-emblem, .pd-hero-emblem *) {
    width: 22px !important; height: 22px !important; flex: none;
}
.hs-menu-profile-stats .pd-hero-face:not(.has-portrait) :is(.pd-hero-emblem, .pd-hero-emblem *) {
    width: 48px !important; height: 48px !important; flex: none;
}
.hs-menu-profile-stats .pd-hero-name { font-size: 18px; letter-spacing: 2px; }
.hs-menu-profile-stats .pd-tile { padding: 6px 8px; gap: 8px; }
.hs-menu-profile-stats :is(.pd-tile-icon, .pd-tile-icon *) { width: 26px !important; height: 26px !important; flex: none; }
.hs-menu-profile-stats .pd-tile-value { font-size: 16px; }
.hs-menu-profile-stats .pd-block-title { font-size: var(--font-text); letter-spacing: 2px; display: flex; align-items: center; gap: 6px; }
.hs-menu-profile-stats .pd-res { grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 6px; }
.hs-menu-profile-stats .pd-res-item { padding: 5px 8px; gap: 6px; }
.hs-menu-profile-stats :is(.pd-res-icon, .pd-res-icon *) { width: 22px !important; height: 22px !important; flex: none; }
.hs-menu-profile-stats .pd-res-value, .hs-menu-profile-stats .pd-ship { font-size: var(--font-text); }
.hs-menu-profile-stats .pd-ship { padding: 5px 10px; }
.hs-menu-profile-stats .pd-galaxies { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 6px; }
.hs-menu-profile-stats .pd-galaxy { padding: 6px 8px; column-gap: 8px; row-gap: 4px; grid-template-columns: 32px minmax(0, 1fr) auto; font-size: var(--font-text); min-height: 44px; }
