.hs-slotview-toggle { display: inline-flex; align-items: center; gap: 6px; margin-left: 8px; color: var(--color-primary); font-size: 10px; letter-spacing: 1px; cursor: pointer; }
.hs-slotview-toggle { appearance: none; border: 0; padding: 0; background: transparent; font: inherit; }
.hs-slotview-switch { position: relative; display: inline-block; width: 32px; height: 20px; border: 2px solid var(--color-primary); background: #160d1d; }
.hs-slotview-switch::after { content: ''; position: absolute; top: 3px; left: 3px; width: 10px; height: 10px; background: var(--color-primary); }
.hs-slotview-switch.is-on { background: var(--color-primary); }
.hs-slotview-switch.is-on::after { background: #09090d; transform: translateX(12px); }
