.hs-slotview-slots { display: flex; flex-wrap: wrap; gap: 4px; align-items: flex-start; justify-content: flex-start; }
.hs-slotview-slots em { font-style: normal; opacity: .5; font-size: var(--font-h3, 12px); letter-spacing: 2px; }
.hs-slotview-cell { display: inline-grid; place-items: center; width: var(--svw, 44px); height: var(--svh, 44px); box-sizing: border-box; background: #05060a; border: 0; outline: 2px dashed color-mix(in srgb, var(--pk-c) 55%, transparent); outline-offset: -2px; }
.hs-slotview-cell.is-filled { outline-style: solid; outline-color: var(--pk-c); }
.hs-slotview-cell img { display: block; width: 28px; height: 28px; image-rendering: pixelated; }

