html body .hs-slot-picker .hs-pick-size { position: absolute; top: 2px; right: 4px; font-size: 11px; opacity: .8; }
html body .hs-slotview-cell[data-slot-pick] { cursor: pointer; }
html body .hs-slot-picker .hs-pick-sortbtn { background: #05060a; color: var(--color-text, #fff); border: 2px solid color-mix(in srgb, var(--color-primary) 55%, transparent); padding: 6px 12px; min-height: 0; }
html body .hs-slot-picker .hs-pick-sortbtn.is-active { background: var(--color-primary); color: #05060a; border-color: var(--color-primary); }

.hs-slotview-ico { width: 18px; height: 18px; flex: 0 0 auto; image-rendering: pixelated; fill: color-mix(in srgb, var(--color-primary) 30%, transparent); }
.hs-slotview-ico g.on { fill: var(--color-primary); }

