.hs-pick-keys-label { letter-spacing: 2px; opacity: .85; margin-bottom: 4px; }
.hs-pick-keyopt { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 48px; padding: 0 12px; cursor: pointer; text-align: left; background: #05060a !important; border: 2px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, transparent) !important; clip-path: none !important; box-shadow: none !important; }
.hs-pick-keyopt::before, .hs-pick-keyopt::after { display: none !important; }
