html body .profile-start-main .profile-side-weapons .pk-weapon { display: grid; place-items: center; width: 56px; height: 56px; box-sizing: border-box; background: #05060a; border: 1px solid color-mix(in srgb, var(--pk-c) 40%, transparent); opacity: .8; cursor: help; }
html body .profile-start-main .profile-side-weapons .pk-weapon { position: relative; }
html body .profile-start-main .profile-side-weapons .pk-weapon.is-empty { border-style: dashed; opacity: .6; }
html body .profile-start-main .profile-side-weapons .pk-weapon .pk-wslot,
html body .profile-start-main .profile-side-weapons .pk-weapon .pk-wkey { position: absolute; min-width: 14px; padding: 1px 3px; box-sizing: border-box; font-size: 10px; line-height: 12px; text-align: center; letter-spacing: 1px; background: #05060a; pointer-events: none; }
html body .profile-start-main .profile-side-weapons .pk-weapon .pk-wslot { top: -6px; left: -6px; color: #c8c4d8; border: 1px solid #3a3550; }
html body .profile-start-main .profile-side-weapons .pk-weapon .pk-wkey { bottom: -6px; right: -6px; color: var(--pk-c); border: 1px solid var(--pk-c); }
html body .profile-start-main .profile-side-weapons .pk-weapon img { width: 36px; height: 36px; image-rendering: pixelated; }
html body .profile-start-main .profile-side-weapons .pk-weapon:hover { opacity: 1; }
html body .profile-start-main .profile-side-weapons .pk-weapon.is-focus { width: 76px; height: 76px; opacity: 1; border: 2px solid var(--pk-c); box-shadow: 0 0 0 2px #05060a, 0 0 12px color-mix(in srgb, var(--pk-c) 45%, transparent); }
html body .profile-start-main .profile-side-weapons .pk-weapon.is-focus img { width: 52px; height: 52px; }
/* Inventory items show their size by their footprint in the grid: no S / M / L label. */
html body .hs-bay-inv .hs-pick-size, html body .profile-start-inv .hs-pick-size { display: none !important; }
/* Start step: name bar and kit bonus strip span the full width (over the sidebar); ship and hull sidebar share the row below. */
html body .profile-selection-name-mode .profile-start-main .profile-faction-preview.profile-faction-preview.profile-faction-preview { grid-template-rows: 56px auto minmax(0, 1fr) !important; }
html body .profile-selection-name-mode .profile-start-main .profile-faction-preview.profile-faction-preview.profile-faction-preview > .profile-kit-info {
    grid-column: 1 / -1; grid-row: 2; border-top: 0;
    border-bottom: 2px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 55%, #05060a);
}
html body .profile-selection-name-mode .profile-start-main .profile-faction-preview.profile-faction-preview.profile-faction-preview .profile-kit-ship { grid-column: 1 / -1; }
html body .profile-selection-name-mode .profile-start-main .profile-faction-preview.profile-faction-preview.profile-faction-preview > .profile-loadout { grid-row: 3 / -1; }
/* Start inventory fills the rest of the sidebar as a size container: the grid cells (--cs, core-kits.js) scale to fit instead of scrolling. */
html body .profile-start-main .profile-loadout > .profile-start-inv { container-type: size; flex: 1 1 0; min-height: 0; overflow: hidden; align-self: stretch; width: auto; }
/* Kit strip: label + blurb on the left, icon chips to the right of it (wrap under it only when narrow). */
html body .profile-selection-name-mode .profile-start-main .profile-faction-preview.profile-faction-preview.profile-faction-preview > .profile-kit-info { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 10px 24px; padding: 12px 20px; }
html body .profile-start-main .profile-kit-info .pkb-head { flex: 1 1 280px; flex-wrap: wrap; gap: 4px 16px; }
html body .profile-start-main .profile-kit-info .profile-kit-desc { flex: 1 1 200px; white-space: normal; overflow: visible; }
html body .profile-start-main .profile-kit-info .pkb-chips { flex: 0 1 auto; justify-content: flex-end; gap: 8px; }
html body .profile-start-main .profile-kit-info .pkb-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px 4px 6px; cursor: help; }
html body .profile-start-main .profile-kit-info .pkb-chip b { font-weight: normal; letter-spacing: 1px; }
html body .profile-start-main .profile-kit-info .pkb-ico { display: grid; place-items: center; width: 28px; height: 28px; }
html body .profile-start-main .profile-kit-info .pkb-ico img { width: 24px !important; height: 24px !important; image-rendering: pixelated; }
html body .profile-start-main .profile-kit-info .pkb-ico svg { width: 26px; height: 26px; fill: color-mix(in srgb, currentColor 30%, transparent); filter: drop-shadow(1px 1px 0 #05060a); }
html body .profile-start-main .profile-kit-info .pkb-ico svg .on { fill: currentColor; }
html body .profile-selection-name-mode.is-name-step .profile-start-main .profile-faction-info-row .profile-faction-preview .profile-faction-ship.profile-faction-ship { grid-row: 3; }
/* Start step: the content takes nearly the full width (slim side margins instead of 70 units per side). */
html body .profile-selection-content.profile-selection-floating.profile-selection-name-mode.is-name-step:has(> .profile-start-main) {
    width: calc(100% - 32 * var(--bz-u)) !important; padding-left: 12px !important; padding-right: 12px !important;
}

/* Pilot step: keep portrait + picker fully visible above the bottom bar (no bottom clip).
   Portrait size is capped by remaining height (stepper + bar + name/title chrome), not raw 50vh. */
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step {
    justify-content: flex-start !important;
    min-height: 0 !important;
    overflow: hidden !important;
}
html body .profile-selection-name-mode.is-pilot-step .profile-selection-title,
html body .profile-selection-name-mode.is-pilot-step .profile-faction-picker,
html body .profile-selection-name-mode.is-pilot-step .profile-name-row {
    flex: 0 0 auto;
}
/* Name row: smaller type so the Pilot card gets the height. */
html body .profile-selection-name-mode.is-pilot-step .profile-name-row {
    margin-top: 4px !important;
    margin-bottom: 4px !important;
}
html body .profile-selection-name-mode.is-pilot-step .profile-name-input {
    font-size: 18px !important;
    letter-spacing: 2px !important;
    padding: 6px 12px !important;
}
html body .profile-selection-name-mode.is-pilot-step .profile-name-gen {
    font-size: 14px !important;
    letter-spacing: 1px !important;
    padding: 6px 14px !important;
}
html body .profile-selection-name-mode.is-pilot-step .profile-name-crest {
    width: calc(32 * var(--bz-u));
}
html body .profile-selection-name-mode.is-pilot-step .profile-start-options {
    flex: 1 1 0 !important;
    min-height: 0 !important;
    overflow: hidden;
    justify-content: stretch !important;
    padding-bottom: 0 !important;
    container-type: size;
}
html body .profile-selection-name-mode.is-pilot-step .profile-start-row[data-start-row="pilot"] {
    flex: 1 1 0;
    min-height: 0;
    max-height: 100%;
    display: flex;
    flex-direction: column;
}
/* Portrait uses native 48×54; both panes share the free height and never spill past it. */
html body .profile-selection-name-mode.is-pilot-step .profile-pilot-card {
    --pp-gap: 4px;
    flex: 1 1 0;
    min-height: 0;
    max-height: 100%;
    height: 100%;
    width: 100%;
    box-sizing: border-box;
    gap: 10px;
    padding: 4px;
    align-items: stretch !important;
    grid-template-columns: var(--pp-portrait-w, min(55vw, 640px)) minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr);
    overflow: hidden;
}
html body .profile-selection-name-mode.is-pilot-step .profile-pilot-side {
    min-width: 0;
    min-height: 0;
    max-height: 100%;
    height: 100%;
    width: auto;
    align-self: stretch;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    box-sizing: border-box;
}
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step .profile-pilot-portrait {
    flex: 1 1 auto;
    align-self: center !important;
    min-width: 0;
    min-height: 0 !important;
    height: var(--pp-portrait-h, auto) !important;
    width: var(--pp-portrait-w, auto) !important;
    max-width: min(55vw, 640px) !important;
    max-height: 100% !important;
    aspect-ratio: 48 / 54;
    box-sizing: border-box !important;
    --pk: 3px !important;
    border-width: 3px !important;
    box-shadow: inset 0 0 0 2px #05060a, inset 2px 2px 0 2px color-mix(in srgb, var(--pk-c) 80%, #fff);
}
html body .profile-selection-name-mode.is-pilot-step .profile-pilot-portrait .hero-portrait {
    display: block;
    width: 100% !important;
    height: 100% !important;
    max-width: 100%;
    max-height: 100%;
    object-fit: cover;
    object-position: 50% 0;
    image-rendering: pixelated;
}
html body .profile-selection-name-mode.is-pilot-step .profile-pilot-controls {
    min-width: 0;
    min-height: 0;
    max-height: 100%;
    height: 100%;
    overflow: hidden;
    align-self: stretch !important;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
    gap: 10px;
    box-sizing: border-box;
}
html body .profile-selection-name-mode.is-pilot-step .pp-grid {
    flex: 1 1 auto;
    min-height: 0;
    max-height: none !important;
    max-width: 100%;
    width: auto;
    overflow: visible !important;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
}
/* BACKDROP + ANIMATION on the normal pilot create screen (not only Face Editor). */
html body .profile-selection-name-mode.is-pilot-step .pp-motion {
    flex: 0 0 auto;
    width: 100%;
    max-width: min(100%, calc(6 * var(--pp-tile, 72px) + 5 * var(--pp-gap, 4px)));
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px 10px;
    box-sizing: border-box;
    background: rgba(0, 0, 0, 0.45);
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, #000);
}
html body .profile-selection-name-mode.is-pilot-step .pp-motion .pp-ctl {
    padding: 6px 8px;
}
html body .onboarding-overlay .pp-motion {
    flex: 0 0 auto;
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px 10px;
    box-sizing: border-box;
    background: rgba(0, 0, 0, 0.45);
    border: 1px solid color-mix(in srgb, var(--faction-accent, var(--color-primary)) 40%, #000);
}
/* 6+6+4 square tiles. --pp-tile is set in px by fitPilotPicks() (no cqw/cqh — works in all browsers). */
html body .profile-selection-name-mode.is-pilot-step .pp-picks {
    --pp-gap: 4px;
    --pp-tile: 72px;
    flex: none;
    width: calc(6 * var(--pp-tile) + 5 * var(--pp-gap)) !important;
    height: calc(3 * var(--pp-tile) + 2 * var(--pp-gap)) !important;
    max-width: 100% !important;
    max-height: 100% !important;
    min-height: 0;
    margin: 0 !important;
    display: grid !important;
    grid-template-columns: repeat(6, var(--pp-tile)) !important;
    grid-template-rows: repeat(3, var(--pp-tile));
    gap: var(--pp-gap) !important;
    row-gap: var(--pp-gap) !important;
    align-content: start !important;
    justify-content: start !important;
    box-sizing: border-box;
    overflow: hidden;
}
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step .pp-picks > .pp-pick {
    flex: unset !important;
    flex-basis: auto !important;
    width: var(--pp-tile) !important;
    height: var(--pp-tile) !important;
    min-width: 0 !important;
    min-height: 0 !important;
    aspect-ratio: 1 / 1;
    box-sizing: border-box !important;
    overflow: hidden;
    --pk: 2px !important;
    border-width: 3px !important;
    box-shadow: inset 0 0 0 2px #05060a, inset 2px 2px 0 2px color-mix(in srgb, var(--pk-c) 80%, #fff);
}
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step .pp-picks > .pp-pick canvas,
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step .pp-picks > .pp-pick canvas.hero-portrait.vx-portrait {
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    max-width: 100%;
    max-height: 100%;
    object-fit: contain !important;
    object-position: 50% 50% !important;
    image-rendering: -moz-crisp-edges;
    image-rendering: -webkit-optimize-contrast;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
}
html body .profile-selection-content.profile-selection-name-mode.is-pilot-step .pp-pick.selected {
    box-shadow: inset 0 0 0 2px #fff, inset 2px 2px 0 2px #fff;
}

/* Global Pixel Size: crisp upscaling for every pixel-art surface */
html[data-vf-pixel-size="on"] #gameCanvas,
html[data-vf-pixel-size="on"] .galaxy-map-svg image,
html[data-vf-pixel-size="on"] #ceCanvas {
    image-rendering: pixelated !important;
}
/* Global Pixel Size: a CSS filter on the planet wrapper makes Chromium resample the HTML layer softly. */
html[data-vf-pixel-size="on"] .gm-node .gm-node-icon-wrap:not(.dimmed) { filter: none; }
html[data-vf-pixel-size="on"] .gm-planet-icon-img .gm-planet-img { image-rendering: pixelated !important; }

/* Global Pixel Size: live map + vfMapPx filter (no canvas mirror — that flickered). */
#gmMapArea > .gm-px-raster {
    width: 100%;
    height: 100%;
}
#gmMapArea > .gm-px-raster .galaxy-map-svg {
    width: 100%;
    height: 100%;
    display: block;
}
html[data-vf-pixel-size="on"] #gmMapArea {
    position: relative;
    overflow: hidden;
    filter: url(#vfMapPx) !important;
}
html[data-vf-pixel-size="on"] #gmMapArea > .gm-px-raster {
    width: 100%;
    height: 100%;
    transform: none;
    opacity: 1;
    will-change: auto;
}
html[data-vf-pixel-size="on"] #gmMapArea > .gm-px-raster .galaxy-map-svg {
    width: 100%;
    height: 100%;
    display: block;
    image-rendering: pixelated;
    shape-rendering: crispEdges;
    filter: none !important;
}
html[data-vf-pixel-size="on"] #gmMapArea > canvas.gm-px-canvas {
    display: none !important;
}
html:not([data-vf-pixel-size="on"]) #gmMapArea {
    filter: none;
}
html:not([data-vf-pixel-size="on"]) #gmMapArea > .gm-px-raster {
    width: 100%;
    height: 100%;
    transform: none;
    opacity: 1;
}
html:not([data-vf-pixel-size="on"]) #gmMapArea > .gm-px-raster .galaxy-map-svg {
    width: 100%;
    height: 100%;
    display: block;
}
html[data-vf-pixel-size="on"] .galaxy-map-svg .gm-pxline-flow {
    filter: none !important;
}

/* Map texts: vector text off, cell-built pixel text on while the pixel screen is active. */
html[data-vf-pixel-size="on"] .galaxy-map-svg .gm-vec-text { display: none; }
html:not([data-vf-pixel-size="on"]) .galaxy-map-svg .gm-px-only { display: none; }

/* Pixel screen: crests keep their size (no hover shrink/fade) so they stay readable. */
html[data-vf-pixel-size="on"] .gm-node .gm-node-factions { transform: none; opacity: 1; transition: none; }

/* Station map: galaxy ruler card beside the ship bar, enemy avatar + ship in the bottom bar. */
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-ruler.is-header { display: flex; align-items: stretch; flex: 0 0 auto; }
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-ruler.is-header .galaxy-map-ruler-card {
    flex-direction: row; gap: 12px; padding: 6px 14px; height: 100%; box-sizing: border-box;
    border-right: var(--ui-border-width, 2px) solid color-mix(in srgb, var(--ruler-accent, var(--color-primary)) 45%, transparent);
}
.galaxy-map-embedded .galaxy-map-toolbar .galaxy-map-ruler.is-header .galaxy-map-ruler-text { align-items: flex-start; text-align: left; }
/* Enemy card: avatar and ship are big and cut off by the frame (banner style). */
.galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-stack .gm-enemy-card {
    position: relative; overflow: visible; padding: 0; flex: 1 1 0; min-height: 120px;
}
.gm-enemy-card-in { position: absolute; inset: 0; display: block; }
.gm-enemy-planet { position: absolute; right: -6%; top: 22px; bottom: -30%; width: 62%; overflow: hidden; opacity: .55; z-index: 0; pointer-events: none; }
.gm-enemy-planet > * { position: absolute; inset: 0; width: 100%; height: 100%; max-width: none; object-fit: contain; image-rendering: pixelated; }
/* Poster layout: planet behind, face and ship staggered in front of it, title bar on top. */
.gm-enemy-avatar {
    translate: var(--ec-face-x, 0) var(--ec-face-y, 0);
    position: absolute; left: 12px; top: 76px; bottom: 6px; width: 38%; max-width: 190px; overflow: hidden;
    border: 0; background: none; box-shadow: none; z-index: 4; overflow: visible;
}
.gm-enemy-avatar > * {
    position: absolute; left: 0; top: 0; width: 100%; height: 100%; max-width: none;
    object-fit: contain; object-position: 50% 100%; transform: none;
    image-rendering: pixelated;
}
.gm-enemy-text { translate: var(--ec-bar-x, 0) var(--ec-bar-y, 0); position: absolute; left: 0; right: 0; top: 40px; height: 30px; box-sizing: border-box; padding: 0 12px; display: flex; flex-direction: row; align-items: center; justify-content: flex-start; gap: 10px; z-index: 3; text-align: left; white-space: nowrap; overflow: hidden; background: color-mix(in srgb, var(--ruler-accent, var(--color-primary)) 10%, transparent); border-bottom: 2px solid color-mix(in srgb, var(--ruler-accent, var(--color-primary)) 55%, transparent); }
.gm-enemy-kind { font-size: var(--font-small); letter-spacing: 2px; color: var(--ruler-accent, var(--color-primary)); }
.gm-enemy-name { font-size: var(--font-h2); color: #fff; text-shadow: 0 0 6px #000, 2px 2px 0 #000; }
.gm-enemy-place { margin-left: auto; font-size: var(--font-small); letter-spacing: 2px; color: var(--color-text-secondary); }
.gm-enemy-ship { translate: var(--ec-ship-x, 0) var(--ec-ship-y, 0); position: absolute; left: calc(12px + min(38%, 190px) - 18px); top: auto; bottom: 6px; width: 34%; height: 56%; transform: none; max-width: none; object-fit: contain; object-position: center; image-rendering: pixelated; filter: drop-shadow(3px 4px 0 #000) drop-shadow(0 0 8px #000); border: 0; outline: 0; box-shadow: none; background: none; z-index: 3 }

/* Mission icon right of the navbar. */
.hs-mission-btn { color: var(--mission-accent, var(--color-primary)); border-color: var(--mission-accent, var(--color-primary)); }
.hs-mission-btn.is-calm { opacity: 0.45; }
.hs-mission-btn:hover { opacity: 1; }

/* No frame line on the enemy side of the bottom bar (the card is the last block before the planet). */
.galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-stack:has(.gm-enemy-card) { border-right: 0; }

/* Poster: the planet card's planet is bigger and sits behind the enemy face and ship (covered, not cropped). */
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-stack { position: relative; z-index: 2; overflow: visible; border-right: 0 !important; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .galaxy-map-ruler-seg.is-planet { position: relative; z-index: 1; overflow: visible; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .is-planet .gm-sector-planet-bg { left: -190px; bottom: -20px; width: 280px; height: 280px; }

.gm-enemy-title { text-align: left; translate: var(--ec-title-x, 0) var(--ec-title-y, 0); position: absolute; left: 12px; right: 8px; top: 6px; z-index: 3; font-size: 26px; letter-spacing: 3px; color: #fff; text-shadow: 0 0 6px #000, 2px 2px 0 #000; white-space: nowrap; overflow: hidden; }
.gm-enemy-emblem { display: inline-flex; align-items: center; flex: 0 0 auto; }
.gm-enemy-emblem > * { width: 22px; height: 22px; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar:has(.gm-enemy-card-in) .is-planet .gm-sector-heading { display: none; }

/* Dev: enemy card layout modal (drag title / bar / face / ship). */
.ecl-back { position: fixed; inset: 0; z-index: 100000; display: flex; align-items: center; justify-content: center; background: rgba(0,0,0,.72); }
.ecl-modal { box-sizing: border-box; max-height: 96vh; overflow: auto; display: flex; flex-direction: column; gap: 12px; padding: 16px; background: #05060a; border: 2px solid var(--color-primary); box-shadow: 4px 4px 0 #000; max-width: 96vw; }
.ecl-title { font-size: var(--font-h2); letter-spacing: 2px; color: var(--color-primary); }
.ecl-hint { font-size: var(--font-small); color: var(--color-text-secondary); }
.ecl-stage { position: relative; flex: 0 0 auto; width: 640px; transform-origin: 0 0; height: 220px; overflow: hidden; background: #0b0d14; border: 2px solid color-mix(in srgb, var(--color-primary) 60%, transparent); }
.ecl-stage .gm-enemy-title, .ecl-stage .gm-enemy-text, .ecl-stage .gm-enemy-avatar, .ecl-stage .gm-enemy-ship { cursor: grab; pointer-events: auto; outline: 1px dashed color-mix(in srgb, var(--color-primary) 70%, transparent); touch-action: none; }
.ecl-stage .gm-enemy-avatar > * { pointer-events: none; }
.ecl-actions { display: flex; justify-content: space-between; gap: 8px; }
.ecl-actions .ecl-right { display: flex; gap: 8px; }
body.dev-mode .gm-enemy-card, .gm-enemy-card[data-dev] { cursor: pointer; }
.ecl-planet { translate: var(--ec-planet-x, 0) var(--ec-planet-y, 0); cursor: grab; touch-action: none; outline: 1px dashed color-mix(in srgb, var(--color-primary) 70%, transparent); position: absolute; right: -4%; top: -10px; width: 280px; height: 280px; z-index: 0; pointer-events: auto; }
.ecl-planet > * { width: 100%; height: 100%; }
.ecl-stage .gm-enemy-card-in { z-index: 1; }
.ecl-actions { flex-wrap: wrap; }
.ecl-fit { flex: 0 0 auto; position: relative; overflow: hidden; }
.ecl-stage .gm-enemy-card-in { pointer-events: none; }
.ecl-planet > * { pointer-events: none; }
html body .galaxy-map-embedded .gm-map-stage .galaxy-map-ruler.is-bar .is-planet .gm-sector-planet-bg { translate: var(--ec-planet-x, 0) var(--ec-planet-y, 0); }

/* Face: always whole and in front of the ship; its flat bottom edge fades out instead of ending in a hard cut. */
.gm-enemy-avatar > * { -webkit-mask-image: linear-gradient(to bottom, #000 82%, transparent 100%); mask-image: linear-gradient(to bottom, #000 82%, transparent 100%); }

/* Enemy card layout: size (scale) and layer per element, set by the dev layout modal. */
