.gm-enemy-text { z-index: var(--ec-bar-z, 5); scale: var(--ec-bar-s, 1); transform-origin: 0 50%; }
.gm-enemy-avatar { z-index: var(--ec-face-z, 4); scale: var(--ec-face-s, 1); transform-origin: 50% 100%; }
