.ecl-stage .gm-enemy-card-in { z-index: 1; }
.ecl-ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; }
.ecl-chips, .ecl-row { display: inline-flex; align-items: center; gap: 6px; font-size: var(--font-small); color: var(--color-text-secondary); }
.ecl-chip.is-on { background: var(--color-primary); color: #000; }
.ecl-range { width: 140px; }
.ecl-val { min-width: 3.2em; text-align: center; color: #fff; }
.ecl-stage[data-sel="title"] .gm-enemy-title, .ecl-stage[data-sel="bar"] .gm-enemy-text, .ecl-stage[data-sel="face"] .gm-enemy-avatar,
.ecl-stage[data-sel="ship"] .gm-enemy-ship, .ecl-stage[data-sel="planet"] .ecl-planet { outline: 2px solid var(--color-primary); }

.ecl-stage.is-clone { overflow: visible; background: none; border: 0; }
