.ecl-stage.is-clone :is(.gm-enemy-title, .gm-enemy-text, .gm-enemy-avatar, .gm-enemy-ship, .gm-sector-planet-bg) { pointer-events: auto !important; cursor: grab; outline: 1px dashed color-mix(in srgb, var(--color-primary) 70%, transparent); }
