    animation: none;
}
html[data-faction="pirate"] body .home-station-overlay :is(.hs-panel, .hs-section):not(.hs-hangar-root, .hs-hangar-bay, .hs-shop-root)::before {
    background: none; inset: 0; z-index: 2; border: 16px solid transparent;
    border-image: url('../../assets/ui/pirate-bezel-art.svg?v=17') 16 round;
